(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["nr4"] = [{"id":"nr4-105-1-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"有關婦嬰生命統計資料的敘述，下列何者錯誤？","options":["(A) 總生育率係依當年年齡別生育率，每千位育齡婦女所生育的子女數","(B) 粗出生率係指一年內每千名人口的平均活產嬰兒數","(C) 孕產婦死亡率係指一年內每十萬名活產中，於懷孕期間或懷孕中止42天內之婦女死亡數","(D) 嬰兒死亡率係指每年一千個活產嬰兒中未滿28天的死亡數"],"answer":3,"image":""},{"id":"nr4-105-1-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"下列那些是準父親擬娩症候群（couvade syndrome）的症狀或行為？①焦慮、沮喪 ②食慾不振、噁心、嘔吐 ③疲累、失眠 ④逃避學習父親角色","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":0,"image":""},{"id":"nr4-105-1-3","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"有關治療不孕症藥物的敘述，下列何者錯誤？","options":["(A) Clomiphene Citrate是常使用的口服排卵藥","(B) Human menopausal gonadotropin（HMG）可促進卵泡的發育","(C) Progesterone可促進受精卵著床","(D) hCG注射後12小時內會排卵，此時應進行取卵手術"],"answer":3,"image":""},{"id":"nr4-105-1-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"孕前BMI為24的懷孕婦女，建議其整個孕期體重增加的範圍，下列何者最適當？","options":["(A) 小於7公斤","(B) 7～10公斤","(C) 11～15公斤","(D) 16～18公斤"],"answer":2,"image":""},{"id":"nr4-105-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"懷孕12週婦女，G2P1，前一胎為18週流產，諮詢有關孕期性生活，下列護理師回應，何者最適當？","options":["(A) 沒有性生活禁忌","(B) 性交活動時，避免女性在下平躺姿勢","(C) 出現破水，才需要禁止性交活動","(D) 避免性交活動，但可有擁抱、親吻動作"],"answer":3,"image":""},{"id":"nr4-105-1-6","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"有關卵子形成過程，下列何者正確？","options":["(A) 初級卵母細胞於青春期開始形成","(B) 初級卵母細胞內含有單套染色體","(C) 受精的卵子會經過2次減數分裂","(D) 一個卵細胞可發育成4個成熟的卵子"],"answer":2,"image":""},{"id":"nr4-105-1-7","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"孕婦接受無壓力測試（NST）20分鐘後，胎兒的胎心變異性為3～6 bpm，此時最適當的措施為：","options":["(A) 暫不做任何處置，繼續監測","(B) 輕搖動婦女的腹部","(C) 給予婦女3 L/min氧氣導管使用","(D) 請婦女深呼吸數次"],"answer":1,"image":""},{"id":"nr4-105-1-8","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"李女士，妊娠28週，有1個女兒及1對雙胞胎，曾於妊娠8週自然流產1次，孕產史的紀錄為：","options":["(A) G4P2A1","(B) G3P3A1","(C) G4P3A1","(D) G3P2A1"],"answer":0,"image":""},{"id":"nr4-105-1-9","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"陳女士，G2P 1，妊娠10週，已育有一名2歲的脊髓性肌肉萎縮症患孩，下列敘述何者錯誤？","options":["(A) 脊髓性肌肉萎縮症為體染色體隱性遺傳疾病","(B) 此胎有50%機率為脊髓性肌肉萎縮症患孩","(C) 此胎有25%機率為不具脊髓性肌肉萎縮症基因的健康小孩","(D) 應即刻接受產前胎兒基因診斷"],"answer":1,"image":""},{"id":"nr4-105-1-10","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"有關子宮內膜的敘述，下列何者正確？①子宮內膜的發育受雌性素與黃體素影響 ②懷孕後子宮內膜可發育為底蛻膜、包蛻膜及真蛻膜 ③受精卵著床於真蛻膜 ④受精卵著床後的子宮內膜稱為絨毛膜","options":["(A) ①③","(B) ①②","(C) ③④","(D) ②④"],"answer":1,"image":""},{"id":"nr4-105-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"朱女士採陰道生產，目前已進入第二產程，使用Valsalva長時間閉氣用力技巧，可能出現下列何種生理反應？","options":["(A) 胸內壓降低","(B) 肺部靜脈回流降低","(C) 母血二氧化碳濃度降低","(D) 心輸出量上升"],"answer":1,"image":""},{"id":"nr4-105-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"有關會陰切開術的敘述，下列何者錯誤？","options":["(A) 產婦的會陰部較短，較常使用正中會陰切開術","(B) 正中會陰切開術的失血量較少","(C) 實證不建議例行性施行會陰切開術","(D) 側斜會陰切開術不易縫合，癒合時間長"],"answer":0,"image":""},{"id":"nr4-105-1-13","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"李女士第二胎，胎盤娩出後血壓為170/98 mmHg、脈搏為78次/分、呼吸20次/分，有關促進子宮收縮措施，下列何者不適宜？","options":["(A) 按摩子宮底","(B) 依醫囑肌肉注射Methergine 0.2 mg","(C) 刺激乳房","(D) 確認膀胱不脹"],"answer":1,"image":""},{"id":"nr4-105-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"許女士，G1P0，入院時子宮頸口開4公分，先露部位高度為-1，於待產5小時後，子宮頸口開6公分，先露部位高度仍為-1，護理師發現其子宮收縮開始呈不規則，且恥骨聯合上方呈膨出狀，此時護理師宜優先評估：","options":["(A) 膀胱脹的情形","(B) 子宮收縮的頻率與強度","(C) 腹部觸診確定胎位","(D) 陰道出血量"],"answer":0,"image":""},{"id":"nr4-105-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"有關待產婦施行灌腸的禁忌，下列何者錯誤？","options":["(A) 已破水胎頭未固定","(B) 陰道大量出血","(C) 規則宮縮","(D) 胎兒窘迫"],"answer":2,"image":""},{"id":"nr4-105-1-16","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"下列何者為婦女真陣痛的特徵？","options":["(A) 內診時沒有子宮頸變薄","(B) 走路時肚子緊縮感消失","(C) 胎兒活動時就宮縮","(D) 規則性宮縮且頻率愈來愈密集"],"answer":3,"image":""},{"id":"nr4-105-1-17","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"張女士第二胎，子宮頸開9公分，胎頭高度+1，此時胎頭高度的意義為何？","options":["(A) 坐骨棘連線","(B) 坐骨棘連線上1公分","(C) 坐骨棘連線下1公分","(D) 坐骨棘連線下2公分"],"answer":2,"image":""},{"id":"nr4-105-1-18","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"待產時Pitocin使用之監測，下列何者正確？","options":["(A) 開始用藥的劑量為每分鐘10 IU/c.c.","(B) 2～3分鐘宮縮一次才可使用","(C) 間歇性使用胎兒監測器","(D) 胎心率於100 bpm時應停止給藥"],"answer":3,"image":""},{"id":"nr4-105-1-19","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"有關授乳母親營養需求之敘述，下列何者正確？","options":["(A) 完全素食者，應補充維生素B6","(B) 正常飲食之外，每日增加800大卡的熱量","(C) 增加豆類與堅果類的攝取","(D) 攝取3,500 c.c.以上的水分"],"answer":2,"image":""},{"id":"nr4-105-1-20","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"徐女士產後入住產後護理機構並遵循坐月子習俗，詢問月子餐為何要吃麻油雞？下列何者是護理師最合宜的解釋？","options":["(A) 就中醫的觀點，麻油雞可補氣血","(B) 這是欠缺科學性依據，建議不要吃","(C) 這是月子餐的生意人行銷的方式","(D) 坐月子期間每天進食麻油雞有助身材恢復"],"answer":0,"image":""},{"id":"nr4-105-1-21","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"有關緩解剖腹生產傷口疼痛的護理措施，下列何者適當？","options":["(A) 給予環形中空坐墊，以防傷口受到壓迫","(B) 維持俯臥的姿勢，提供背部按摩","(C) 避免床上擦澡，以防傷口受到牽扯","(D) 教導呼吸放鬆技巧"],"answer":3,"image":""},{"id":"nr4-105-1-22","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"張女士採陰道生產，預計3年後再生育，未母乳哺餵，有子宮外孕的病史，懷孕前月經不規則。下列何種避孕方式較為適當？","options":["(A) 子宮內避孕器","(B) 口服避孕藥","(C) 月經週期法","(D) 結紮"],"answer":1,"image":""},{"id":"nr4-105-1-23","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"產後1週的健康婦女，下列生命徵象何者為正常？","options":["(A) TPR：38.5℃、80次/分、24次/分，BP：118/78 mmHg","(B) TPR：36.8℃、60次/分、18次/分，BP：110/68 mmHg","(C) TPR：37.0℃、78次/分、32次/分，BP：128/80 mmHg","(D) TPR：36.5℃、72次/分、16次/分，BP：150/92 mmHg"],"answer":1,"image":""},{"id":"nr4-105-1-24","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"有關預防產後便秘的護理措施，下列何者最適宜？","options":["(A) 早期下床活動","(B) 建議飲水量每天不超過2,000 c.c.","(C) 持續使用托腹帶以促進腸蠕動","(D) 減少排便次數以防痔瘡產生"],"answer":0,"image":""},{"id":"nr4-105-1-25","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"有關親子同室的注意事項，下列敘述何者不適當？","options":["(A) 早期接觸有助於親子關係的建立","(B) 讓較大的兄姐撫摸新生兒","(C) 可提高母乳哺餵成功率","(D) 餵母奶的媽媽才能執行親子同室"],"answer":3,"image":""},{"id":"nr4-105-1-26","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"吳女士產後第3天，主動學習新生兒沐浴的技術，依據魯賓（Rubin）對產後婦女行為態度之研究結果判斷，她此時的心理狀態是處於：","options":["(A) 接受期（Taking-in phase）","(B) 緊執期（Taking-hold phase）","(C) 放手期（Letting-go phase）","(D) 恢復期（Recovery phase）"],"answer":1,"image":""},{"id":"nr4-105-1-27","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"有關新生兒評估之敘述，下列何者錯誤？","options":["(A) 頭血腫為界線不明顯的腫脹，腫脹通常是單側或雙側","(B) 產瘤為胎頭受壓產生，於出生12小時至數天可被吸收","(C) 新生兒的軀幹長而四肢短","(D) 前囟門較後囟門晚關閉"],"answer":0,"image":""},{"id":"nr4-105-1-28","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"有關新生兒尿布疹之護理措施，下列何者錯誤？","options":["(A) 勤於檢查尿布，如有潮濕應立即更換","(B) 新生兒排便後應以清水清洗臀部","(C) 距離臀部約25～30公分使用烤燈","(D) 擦氧化鋅藥膏減少患部滲液，以保持臀部乾燥"],"answer":2,"image":""},{"id":"nr4-105-1-29","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"有關預防新生兒體熱散失之方法，下列何者錯誤？","options":["(A) 以溫熱過的毛毯包裹新生兒為傳導作用","(B) 勿在新生兒體溫穩定前洗澡為預防對流作用","(C) 避免將嬰兒床置於牆壁附近為預防輻射作用","(D) 立即擦乾身上的羊水為預防蒸發作用"],"answer":1,"image":""},{"id":"nr4-105-1-30","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"下列那一種疫苗不是所有的嬰兒都需要接種？","options":["(A) 卡介苗","(B) B型肝炎免疫球蛋白","(C) 白喉百日咳破傷風混合疫苗","(D) 小兒麻痺口服疫苗"],"answer":1,"image":""},{"id":"nr4-105-1-31","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"有關減緩懷孕期下背痛的運動，下列何者錯誤？","options":["(A) 凱格爾氏運動","(B) 腹肌強化運動","(C) 骨盆傾斜運動","(D) 腰背伸展運動"],"answer":0,"image":""},{"id":"nr4-105-1-32","subject":"nr4","topic":"產科-產後照護","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"有關產後子宮復舊的過程，下列何者正確？","options":["(A) 子宮肌細胞因自體溶解，細胞數目會逐漸減少","(B) 產程延長會加快復舊的速度","(C) 產後1週，子宮重量約1公斤","(D) 產後第10天，無法於腹部觸摸到子宮底"],"answer":3,"image":""},{"id":"nr4-105-1-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"有關心臟病孕婦之生產及產後護理措施，下列何者錯誤？","options":["(A) 產後採半坐臥或左側臥","(B) 產後48小時需密切監測心臟功能","(C) 產後以口服避孕藥避孕","(D) 第二產程避免長時間閉氣用力"],"answer":2,"image":""},{"id":"nr4-105-1-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"林女士，妊娠36週，血壓160/110 mmHg，下列那些徵候及症狀表示可能發展成子癇症之危險？ ①尿量增加 ②深部肌腱反射過度 ③噁心、嘔吐","options":["(A) ①②","(B) ②③","(C) ①③","(D) ①②③"],"answer":1,"image":""},{"id":"nr4-105-1-35","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"某高中學生對於性病有偏差的認知，護理師提供其性病傳染的相關知識，是運用安濃（Annon）的PLISSIT性諮商模式之那一個階段？","options":["(A) 允諾（Permission）","(B) 訊息限制（Limited information）","(C) 特定建議（Specific suggestions）","(D) 加強治療（Intensive therapy）"],"answer":1,"image":""},{"id":"nr4-105-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"有關子宮頸癌之敘述，下列何者正確？","options":["(A) 高社經地位的婦女為罹患子宮頸癌之高危險群","(B) 性交疼痛及陰道異常出血為子宮頸癌的早期病徵","(C) 65歲之後的婦女無需做子宮頸抹片檢查","(D) 人類乳突病毒疫苗建議僅施打於成年女性"],"answer":1,"image":""},{"id":"nr4-105-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"白小姐，25歲，未曾生育，無器質性骨盆腔疾病，因痛經影響生活和工作而就診，下列敘述何者錯誤？","options":["(A) 連續6個月服用口服避孕藥以抑制排卵減輕不適","(B) 建議可以進食溫熱飲品以減輕不適","(C) 鼓勵痛經時可採下腹局部熱敷以減輕不適","(D) 依照醫囑服用前列腺素製劑以減輕不適"],"answer":3,"image":""},{"id":"nr4-105-1-38","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"有關陰道滴蟲感染的敘述，下列何者正確？","options":["(A) 滴蟲只會透過直接接觸而感染","(B) 停經後婦女較少受到感染","(C) Metronidazole（Flagyl）為最有效的治療藥物","(D) 性伴侶不需一起治療，除非有龜頭紅腫或搔癢症狀"],"answer":2,"image":""},{"id":"nr4-105-1-39","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"有關導致經前症候群的可能因素之敘述，下列何者正確？","options":["(A) 缺乏鈉和維生素B6","(B) 缺乏泌乳素","(C) 前列腺素過多","(D) 血管加壓素減少"],"answer":2,"image":""},{"id":"nr4-105-1-40","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"下列何者為罹患骨質疏鬆症的高危險群？","options":["(A) 停經婦女","(B) 不喝酒、咖啡，且不抽菸的婦女","(C) 每日鈣攝取量為1,500毫克者","(D) 運動員"],"answer":0,"image":""},{"id":"nr4-105-1-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"王小弟，7歲，因車禍疑似頸椎損傷而出現心跳停止，有關心肺復甦術（CPR）的敘述，下列何者錯誤？","options":["(A) 立即採壓額抬下巴法，以維持呼吸道的通暢","(B) 在胸部兩乳頭連線中央，執行心外按摩","(C) 按壓深度約1/3～1/2胸廓深","(D) 單人急救時，心外按摩與人工呼吸比率為30：2"],"answer":0,"image":""},{"id":"nr4-105-1-42","subject":"nr4","topic":"兒科-生長發展","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"下列何種行為對促進認知障礙兒童的發展有幫助？","options":["(A) 不需考慮兒童的年齡，而選擇適合兒童認知發展的遊戲及玩具","(B) 不要對兒童的任何行為加以限制，以增加多樣發展的機會","(C) 為減少兒童被歧視的機會，儘量減少其參與社會性的活動","(D) 除非兒童有聽障，否則避免使用非語言的溝通，以增加語言技巧發展的機會"],"answer":0,"image":""},{"id":"nr4-105-1-43","subject":"nr4","topic":"兒科-生長發展","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"有關遊戲發展過程的描述，下列何者正確？","options":["(A) 嬰兒喜歡旁觀者遊戲，從旁觀他人的遊戲中分享到快樂","(B) 幼兒喜歡平行式遊戲，並肩而坐，各自玩著自己的玩具","(C) 學齡前兒童喜歡合作式遊戲，會將玩具拿出來和別人一起玩","(D) 青少年喜歡單獨遊戲，各玩各的，不重視玩伴"],"answer":1,"image":""},{"id":"nr4-105-1-44","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"有關幼兒被熱水燙傷的處置步驟，下列何者正確？","options":["(A) 脫→沖→泡→蓋→送","(B) 沖→脫→泡→蓋→送","(C) 沖→蓋→送→泡→脫","(D) 沖→蓋→泡→脫→送"],"answer":1,"image":""},{"id":"nr4-105-1-45","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"為7個月大嬰兒執行肌肉注射時，下列何者為最適當的處理方式？","options":["(A) 告訴嬰兒可以哭，但不可以亂動","(B) 請母親離開治療室，以避免母親害怕","(C) 握住嬰兒的手，並儘速完成注射過程","(D) 用鼓勵的方式，答應注射後給予牛奶喝"],"answer":2,"image":""},{"id":"nr4-105-1-46","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"有關「以家庭為中心的照護」，下列敘述何者正確？","options":["(A) 為了避免家人過於擔心，與家屬溝通病情時應先過濾訊息","(B) 為了減少交互感染的機率，應儘量避免病童之手足來探病","(C) 為了病房環境管理，應嚴格執行病房會客時間之規定","(D) 為了增強照護能力，鼓勵父母或手足一起參與照護病童的計畫"],"answer":3,"image":""},{"id":"nr4-105-1-47","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"王小弟，2個月大，接受腹部手術，下列敘述何者為手術後第1天進行疼痛評估的指標？","options":["(A) 臉部扭曲、皺眉","(B) 保護疼痛部位","(C) 將疼痛刺激推開","(D) 咬緊牙關、握緊拳頭"],"answer":0,"image":""},{"id":"nr4-105-1-48","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"下列新生兒視覺評估結果，何者為不正常現象？","options":["(A) 出現斜視現象","(B) 對光不會反應","(C) 哭泣時沒有眼淚","(D) 會產生眨眼反射"],"answer":1,"image":""},{"id":"nr4-105-1-49","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"足月男嬰泌尿生殖系統之評估，下列何者為異常？","options":["(A) 兩側睪丸已下降","(B) 陰囊表面光滑少皺褶","(C) 陰莖長度約2～3公分","(D) 出生後24小時內已解尿"],"answer":1,"image":""},{"id":"nr4-105-1-50","subject":"nr4","topic":"兒科-生長發展","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"有關嬰兒脊柱彎曲發展之敘述，下列何者正確？","options":["(A) 新生兒時，薦椎彎曲完成","(B) 3個月時，頸椎續發彎曲完成","(C) 5個月時，腰椎續發彎曲完成","(D) 7個月時，胸椎續發彎曲完成"],"answer":1,"image":""},{"id":"nr4-105-1-51","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"有關4歲兒童對死亡概念的發展，下列敘述何者正確？","options":["(A) 沒有死亡概念，但對「失落」有反應","(B) 死亡被認為是短暫的分離，可以再活過來","(C) 死亡被視為一件遙遠的事，不可逆轉","(D) 將死人擬人化，躲過魔鬼就可以避免死亡"],"answer":1,"image":""},{"id":"nr4-105-1-52","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"謝小弟，妊娠週數41週又1天，出生體重4,600公克，自然產娩出，出生第2天，左手臂活動少，X光顯示鎖骨骨折，有關骨折之生產損傷，下列敘述何者錯誤？","options":["(A) 沿左鎖骨觸摸，會有骨磨擦及裂開的感覺","(B) 驚嚇反射表現不對稱的手臂上舉","(C) 為其執行圍巾徵象（Scarf signs）之評估","(D) 抱起時，支持後背及臀部，避免自手臂處抱起"],"answer":2,"image":""},{"id":"nr4-105-1-53","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"關於末期病童的臨終階段照護，下列敘述何者正確？","options":["(A) 補充營養，按時餵食，以維持體力","(B) 補充液體輸液，以維持其血壓","(C) 持續給予抗生素，以免再次感染","(D) 維持皮膚清潔乾燥，以增進舒適"],"answer":3,"image":""},{"id":"nr4-105-1-54","subject":"nr4","topic":"兒科-高危險新生兒","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"林小弟妊娠42週出生，出生時發現羊水有胎便。有關護理師維持林小弟呼吸道通暢之護理措施，下列敘述何者正確？","options":["(A) 胎頭娩出時即用導管（DeLee’s tube）對新生兒的鼻咽及口腔進行抽吸","(B) 新生兒完全產出時，應立即使用甦醒球（ambu bag）加壓給氧","(C) 到嬰兒室時於鼻咽及口腔注入生理食鹽水清洗","(D) 做完新生兒護理後，插入氣管內管給予正壓氧氣"],"answer":0,"image":""},{"id":"nr4-105-1-55","subject":"nr4","topic":"兒科-高危險新生兒","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"關於新生兒黃疸照光療法的副作用，下列何者錯誤？","options":["(A) 易形成化膿性結膜炎","(B) 皮膚會出現廣泛紅疹","(C) 體溫不穩定","(D) 便秘"],"answer":3,"image":""},{"id":"nr4-105-1-56","subject":"nr4","topic":"兒科-高危險新生兒","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"比較早產兒與足月兒的臨床特徵，下列何者正確？","options":["(A) 抓握反射（grasp reflex）：早產兒比足月兒明顯","(B) 躺姿：早產兒呈放鬆伸展，而足月兒呈彎曲姿勢","(C) 足跟碰觸至耳朵間的測量：早產兒較足月兒不易完成","(D) 肌肉張力評估：早產兒手肘比足月兒不容易越過胸部"],"answer":1,"image":""},{"id":"nr4-105-1-57","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"有關麻疹與德國麻疹的比較，下列何者錯誤？","options":["(A) 麻疹恢復期皮膚不會脫屑","(B) 德國麻疹不會留下色素沉著","(C) 麻疹有結膜炎、鼻炎症狀","(D) 德國麻疹會出現淋巴結腫大"],"answer":0,"image":""},{"id":"nr4-105-1-58","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"下列何者為水痘（Chickenpox; Varicella）之臨床表徵？","options":["(A) 在同一個時間內可以觀察到紅斑、水疱及膿疱疹","(B) 疹子集中在手、腳，軀幹少見，呈離心性的分布","(C) 體溫恢復正常後，出現紅疹，出疹時會感到刺痛","(D) 恢復期疹子消退，皮膚上呈現黑色色素沉著（pigmentation）現象"],"answer":0,"image":""},{"id":"nr4-105-1-59","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"王小弟，9個月，診斷為肺炎，右腋下區聽到有明顯的爆裂音（Crackle），下列姿位何者較能有效引流痰液？","options":["(A) 右側臥，抬高臀部20公分","(B) 左側臥，抬高臀部20公分","(C) 俯臥，頭放低30度","(D) 仰臥，頭抬高30度"],"answer":1,"image":""},{"id":"nr4-105-1-60","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"有關細菌性肺炎（Bacterial pneumonia）之敘述，下列何者錯誤？","options":["(A) 最常見的致病原為黴漿菌","(B) 通常病童會出現高燒（>39℃）情形","(C) 血中顆粒性白血球數值升高","(D) 通常需給予抗生素治療"],"answer":0,"image":""},{"id":"nr4-105-1-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"有關氣喘兒童使用吸入型藥物之說明，下列何者正確？","options":["(A) 短效型氣管擴張劑，是需要每日使用的保養性吸入型藥物","(B) 乾粉吸入劑型不需要手口協調，較適合5歲以下的兒童","(C) 定量噴霧吸入器（Metered dose inhaler）加上吸藥輔助器（spacer），較適用於嬰幼兒","(D) 醫囑早晚各吸2次（2 puffs）時，是指每次用藥須直接連續深吸藥物2次"],"answer":2,"image":""},{"id":"nr4-105-1-62","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"有關兒童細支氣管炎（Bronchiolitis）的敘述，下列何者錯誤？","options":["(A) 呼吸道融合病毒（RSV）是最常見致病因","(B) 是1歲以內嬰兒常見的下呼吸道感染疾病","(C) 臨床典型的症狀是流鼻水、發燒、似狗吠聲的咳嗽","(D) 一般最常發生於冬、春兩季（1～5月）"],"answer":2,"image":""},{"id":"nr4-105-1-63","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"小英，2歲，罹患嚴重主動脈瓣狹窄（Aortic stenosis），下列那個臨床表徵不會發生？","options":["(A) 脈搏微弱、心跳加快","(B) 出現發紺、杵狀指","(C) 出現收縮性心雜音","(D) 血氧不足，容易疲倦"],"answer":1,"image":""},{"id":"nr4-105-1-64","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"1歲的小明診斷為法洛式四重畸形（tetralogy of fallot），因抽血時哭鬧不安，抽血後發紺厲害，且呼吸困難，下列護理措施，何者應優先進行？","options":["(A) 讓小明採膝胸臥姿（Knee-chest position）休息","(B) 測量小明的生命徵象","(C) 以鼻導管給2 L/min氧氣","(D) 請媽媽餵小明喝些牛奶"],"answer":0,"image":""},{"id":"nr4-105-1-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"有關充血性心衰竭（Congestive heart failure）嬰兒的臨床徵象，不包括下列何者？","options":["(A) 心輸出量減少，心跳速率變慢","(B) 周邊靜脈充血，肝腫大，下肢水腫","(C) 肺水腫，咳嗽，呼吸困難，呼吸速率增快","(D) 臉色、指甲蒼白，四肢冰冷，血壓低，經常盜汗"],"answer":0,"image":""},{"id":"nr4-105-1-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"有關特發性血小板減少紫斑症（idiopathic thrombocytopenic purpura, ITP）幼兒的護理指導，下列何者錯誤？","options":["(A) 此類紫斑症的病因可能與自體免疫有關，僅能長期以藥物控制病情","(B) 要非常注意居家活動環境的安全，可於床欄邊與地板上鋪設保護墊","(C) 3當血小板減少至20,000/mm以下時，宜觀察自發性出血現象","(D) 需避免使用含有aspirin的藥物，以預防影響血小板的凝集功能"],"answer":0,"image":""},{"id":"nr4-105-1-67","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"垂直感染AIDS之嬰兒，不可接種下列何種疫苗？","options":["(A) B型肝炎疫苗","(B) 白喉百日咳破傷風三合一疫苗","(C) 沙賓口服小兒麻痺疫苗","(D) b型流行性感冒嗜血桿菌疫苗"],"answer":2,"image":""},{"id":"nr4-105-1-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"有關為嬰兒執行輸血之敘述，下列何者正確？","options":["(A) 全程使用精密點滴輸液套（Microdrip set）","(B) 輸血前須先用生理食鹽水沖洗點滴管道","(C) 開始輸血15分鐘內，輸液速度要快，以觀察是否有過敏反應","(D) 輸血時可將抗生素加入血液中一起滴注"],"answer":1,"image":""},{"id":"nr4-105-1-69","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"有關副甲狀腺功能低下症病童之照護，下列何者錯誤？","options":["(A) 監測抽搐症狀，避免抽搐造成二次傷害","(B) 減少病童周圍環境之聲光刺激","(C) 監測呼吸型態，避免因喉頭痙攣引發呼吸困難","(D) 鼓勵攝取高纖食物，改善便秘症狀"],"answer":3,"image":""},{"id":"nr4-105-1-70","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"有關腸病毒群感染的敘述，下列何者正確？","options":["(A) 其併發症之一的手足口病，主要侵犯5歲以上的孩童","(B) 散播途徑主要是飛沫及接觸傳染","(C) 傳染高峰期在冬末春初","(D) 病毒在40℃以上的溫度，會很快的失去活性及死亡"],"answer":1,"image":""},{"id":"nr4-105-1-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"檢驗結果顯示白血病（Leukemia）病童有貧血現象，護理師解釋此結果最可能的導因為：","options":["(A) 葉酸攝取不足","(B) 紅血球製造減少","(C) 骨髓逐漸由疤痕組織取代","(D) 淋巴細胞對紅血球的破壞增加"],"answer":1,"image":""},{"id":"nr4-105-1-72","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"嘉佳，13歲，被診斷為第1型糖尿病，有關其居家護理指導，下列敘述何者正確？","options":["(A) 正餐以外的時間避免攝取點心","(B) 建議退出學校羽球隊","(C) 最好由嘉佳的媽媽來執行血糖監測及胰島素注射","(D) 上體育課前可以先吃1片花生醬麵包或2、3顆牛奶糖"],"answer":3,"image":""},{"id":"nr4-105-1-73","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"小勇，3週大，因罹患幽門狹窄入院備行幽門切開術（pyloromyotomy），有關幽門狹窄手術前後的護理，下列敘述何者不適當？","options":["(A) 術前記錄輸出入量、嘔吐物的性狀以及尿比重","(B) 術前協助矯正嚴重嘔吐造成的代謝性酸中毒","(C) 術前需協助矯正脫水及電解值不平衡情形","(D) 術後4～8小時即可開始給予少量葡萄糖水"],"answer":1,"image":""},{"id":"nr4-105-1-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"呂小弟因尿量減少診斷為急性腎衰竭，有關急性腎衰竭的照護，下列敘述何者錯誤？","options":["(A) 注射碳酸氫鈉，矯正代謝性鹼中毒","(B) 以少量多次給予水分，控制水分攝取","(C) 聽診呼吸音，以評估肺水腫狀況","(D) 服用Kayexalate，降低鉀離子"],"answer":0,"image":""},{"id":"nr4-105-1-75","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"謝小弟，6個月大，因尿道下裂（hypospadias）接受尿道重建術，有關手術後之護理處置，下列何者不恰當？","options":["(A) 手術後使用床上拱型護架，避免手術部位加壓","(B) 讓病童包雙層尿布，將引流管拉到外層尿布上","(C) 勿限制病童活動，鼓勵照顧者讓病童活動肢體","(D) 監測尿量、顏色、性質及引流管的通暢度"],"answer":2,"image":""},{"id":"nr4-105-1-76","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"小玲，1歲，因頭部外傷自急診入院，依據兒童適用之葛氏昏迷量表（Glasgow coma scale, GCS）評估其意識程度，結果發現其躁動不安無法安撫，對痛有收縮與睜眼反應，其昏迷指數為幾分？","options":["(A) 7分","(B) 8分","(C) 9分","(D) 10分"],"answer":1,"image":""},{"id":"nr4-105-1-77","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"有關橫膈疝氣（Diaphragmatic hernia）臨床表徵與醫療措施之敘述，下列何者錯誤？","options":["(A) 需插入鼻胃管以減輕胃壓力","(B) 胸腔可聽見腸蠕動聲，聽不到呼吸聲","(C) 當嬰兒呈現呼吸窘迫現象時應立即以甦醒球（Ambu bag）擠壓急救","(D) X光片顯示胸腔內有充滿氣體的腸道和塌陷的肺"],"answer":2,"image":""},{"id":"nr4-105-1-78","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"有關學齡兒童罹患癲癇的護理指導，下列運動何者較不適當？","options":["(A) 騎腳踏車","(B) 著救生衣游泳","(C) 打羽毛球","(D) 在操場跑步"],"answer":0,"image":""},{"id":"nr4-105-1-79","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"小莉，1歲，因中耳炎而發高燒40℃，在家時突然兩眼上吊、四肢抽動持續2分鐘，送醫診斷為熱性痙攣，下列出院護理指導何者不恰當？","options":["(A) 高燒時，可提供酒精拭浴以降低體溫","(B) 抽搐時，協助側臥並維持呼吸道通暢","(C) 痙攣時，移除床上易造成傷害的物品","(D) 發作時，不可強將物品塞入口中，以免造成受傷"],"answer":0,"image":""},{"id":"nr4-105-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"陳小弟，5歲，頭部創傷後，合併無菌性腦膜炎（virus meningitis），作腰椎穿刺，有關其腦脊髓液檢查之結果，不會呈現下列何者？","options":["(A) 3壓力為60 mmH2O","(B) 淋巴球100個/mm","(C) 蛋白質50 mg/dL","(D) 葡萄糖30 mg/dL"],"answer":3,"image":""},{"id":"nr4-105-2-1","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"有關妊娠期B群鏈球菌感染之敘述，下列何者正確？","options":["(A) 胎兒若受到垂直感染，多在出生7天內發病","(B) 妊娠20週接受羊膜穿刺術以篩檢孕期婦女是否受感染","(C) 菌種經常存活在婦女的鼻腔及呼吸道","(D) 預防胎兒受到感染，唯有採行剖腹生產"],"answer":0,"image":""},{"id":"nr4-105-2-2","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"當以手指輕觸新生兒嘴角，新生兒會將臉和嘴轉向刺激物並張開嘴是何種反射表現？","options":["(A) 尋乳反射（Rooting reflex）","(B) 吸吮反射（Sucking reflex）","(C) 摩洛反射（Moro reflex）","(D) 巴賓斯基反射（Babinski reflex）"],"answer":0,"image":""},{"id":"nr4-105-2-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"以超音波推估妊娠20週時的胎兒週數，下列何者最適當？","options":["(A) 股骨長度（FL）","(B) 胎兒頭臀長（CRL）","(C) 雙頂徑（BPD）","(D) 頭腹圍比（HC/AC）"],"answer":2,"image":""},{"id":"nr4-105-2-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"有關全民健康保險孕婦產前檢查的服務項目與給付時程之敘述，下列何者正確？","options":["(A) 首次產檢應於妊娠6週以前完成","(B) 妊娠至28週以前，應每隔兩個月檢查一次","(C) 建議在20週進行超音波檢查","(D) 妊娠第二期例行的實驗室檢查項目包括SGOT、SGPT、creatinine與血糖"],"answer":2,"image":""},{"id":"nr4-105-2-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"蔡女士，月經週期規則，最後一次月經的第一天為今年5月10日，則按照內格萊氏法則（Nägele’s rule）推算，蔡女士的預產期應為何時？","options":["(A) 明年1月28日","(B) 明年2月17日","(C) 明年3月12日","(D) 明年4月10日"],"answer":1,"image":""},{"id":"nr4-105-2-6","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"有關唐氏症候群篩檢之敘述，下列何者正確？","options":["(A) 母血篩檢值高於1/270時，則歸為高危險群","(B) 羊膜腔穿刺合適的檢查時間是妊娠10~16週之間","(C) 母血篩檢可作為確立唐氏症候群的診斷方法","(D) 母血唐氏症篩檢加上頸部透明帶的檢測，其假陽性率高"],"answer":0,"image":""},{"id":"nr4-105-2-7","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"有關卵子形成（oogenesis）的敘述，下列何者正確？","options":["(A) 女性在胎兒時期就已經開始有卵原細胞（oogonia）的形成","(B) 卵細胞第一次減數分裂是發生在受精時","(C) 形成一個單套的卵，需經過一次有絲分裂與一次減數分裂","(D) 整個卵母細胞分裂的過程共產生了一個單套的卵及一個極體（polar body）"],"answer":0,"image":""},{"id":"nr4-105-2-8","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"有關胚胎與其附屬器官發育之敘述，下列何者正確？","options":["(A) 胎盤循環始於第6週，故自此後胚胎稱為胎兒","(B) 受精後第3週的胚胎因內胚層形成，遂成為雙板胚胎","(C) 4週大的胚胎身長約3公分，四肢已有芽狀突起","(D) 受精卵以囊胚的型態植入子宮內膜，完成著床"],"answer":3,"image":""},{"id":"nr4-105-2-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"無內外科及產科疾病病史的懷孕36週婦女，平躺於產檢台檢查時，主訴眩暈、虛弱、冒冷汗，測得收縮壓較其原先低30 mmHg，此時最優先的護理措施為：","options":["(A) 給與毛毯和烤燈","(B) 給與氧氣面罩","(C) 協助孕婦坐於床緣","(D) 協助孕婦採左側臥"],"answer":3,"image":""},{"id":"nr4-105-2-10","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"有關產後生殖系統的正常變化，下列敘述何者正確？","options":["(A) 分娩後惡露約持續10天，紅惡露及漿惡露交替出現","(B) 產後3週仍可於腹部摸到子宮底","(C) 產後約12小時，子宮底上升至肚臍的位置或稍高於肚臍之上","(D) 子宮約在產後4週，便可恢復到懷孕前的大小和形狀"],"answer":2,"image":""},{"id":"nr4-105-2-11","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"下列何者為友善生產之概念？①產婦可決定生產陪伴者以獲支持②允許待產婦自由走動以促進舒適③建議使用止痛藥及麻醉劑降低不適④建議待產時禁食以降低生產風險","options":["(A) ①②","(B) ①③","(C) ②③","(D) ②④"],"answer":0,"image":""},{"id":"nr4-105-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"林女士，妊娠38週，因現血及規則宮縮待產，陰道指診結果為子宮頸口開3 cm，變薄40%，高度-1，未破水。詢問護理師：「我現在一定要躺在床上嗎？」，下列何者為最合適的回答？","options":["(A) 是，避免臍帶脫出","(B) 最好一直採左側臥增加胎兒氧氣供應","(C) 僅如廁時下床，其他時間應臥床","(D) 沒有限制，可採您覺得舒適的臥位或下床活動"],"answer":3,"image":""},{"id":"nr4-105-2-13","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"李女士，因超過預產期無產兆而入院，以piton-S引產，子宮頸口開7公分，胎兒監視器顯示有胎心音晚期減速的現象，下列處置何者正確？","options":["(A) 減少液體攝入量與靜脈注射量，以避免胎心音更加緩慢","(B) 為胎兒臍帶受壓迫，可運用膝胸臥位協助改善臍帶受壓","(C) 協助採左側臥、給氧，減少或暫停piton-S的給予","(D) 是胎頭受壓時所呈現的正常反應，故不需特別處理"],"answer":2,"image":""},{"id":"nr4-105-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"產時評估胎頭高度為0，屬於下列何種情況？","options":["(A) 胎頭仍浮動","(B) 胎頭已固定","(C) 胎頭在會陰口","(D) 胎頭位置不確定"],"answer":1,"image":""},{"id":"nr4-105-2-15","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"有關待產婦護理之敘述，下列何者正確？","options":["(A) 鼓勵定時解尿，以利胎兒下降","(B) 維持平躺，可促進血液循環","(C) 預防噁心嘔吐，應該要禁食","(D) 灌腸是避免產時污染的必要護理措施"],"answer":0,"image":""},{"id":"nr4-105-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"下列那項胎心率的週期性變化和子宮收縮無關？","options":["(A) 早期減速","(B) 晚期減速","(C) 變異性減速","(D) 變異性加速"],"answer":2,"image":""},{"id":"nr4-105-2-17","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"王女士，G1P1，產後第1天與護理師分享自己昨夜生產的過程，主訴很累，不想哺餵母乳。依據魯賓對產後母親行為的研究，王女士的行為處於那個時期？","options":["(A) 接受期","(B) 緊執期","(C) 放手期","(D) 獨立期"],"answer":0,"image":""},{"id":"nr4-105-2-18","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"李女士哺餵母乳時很焦急的詢問護理師：「我不知道寶寶吃奶的動作正不正確」，下列回答何者錯誤？","options":["(A) 當嬰兒嘴巴張大，可看到下嘴唇外翻，即為正確含乳姿勢","(B) 含乳正確時，兩頰應該沒有凹陷的現象","(C) 含住乳頭，發出嘖嘖聲，表示正確含乳","(D) 若正確含乳，嘴巴會完全封閉成真空狀態"],"answer":2,"image":""},{"id":"nr4-105-2-19","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"李女士，33歲，G2P2，產後3個月，現純母乳哺餵，月經尚未回復，過去曾使用口服避孕藥，後來用保險套。有關護理師指導產後生育計畫，下列何者較不恰當？","options":["(A) 可續用保險套","(B) 可使用子宮內避孕器","(C) 可口服含雌性素（estrogen）避孕藥","(D) 採用泌乳無月經法"],"answer":2,"image":""},{"id":"nr4-105-2-20","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"有關剖腹產後的護理措施，下列何者正確？","options":["(A) 採硬脊膜外麻醉者，須平躺8小時，避免腦脊髓液流失","(B) 為減輕傷口疼痛，應儘量臥床休息，避免傷口裂開","(C) 因施打麻醉藥物的關係，須延後哺餵母乳的時間","(D) 必要時可於腹部塗抹薄荷油，以促進腸蠕動，避免腹脹"],"answer":3,"image":""},{"id":"nr4-105-2-21","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"有關產後會陰傷口疼痛執行溫水坐浴指導之敘述，下列何者不恰當？","options":["(A) 可促進循環，消除腫脹","(B) 每天坐浴2~4次，每次20分鐘","(C) 在產後24小時內開始","(D) 若有痔瘡也可配合藥物使用"],"answer":2,"image":""},{"id":"nr4-105-2-22","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"有關血栓性栓塞的敘述，下列何者錯誤？","options":["(A) 以霍曼氏徵象（Homan’s sign）評估靜脈血栓","(B) 陽性反應是足部屈曲時，脛骨後肌壓迫深部靜脈而引起疼痛","(C) 常見足踝足背處有凹陷性水腫且合併局部血管紅腫壓痛","(D) 鼓勵並協助下床活動是預防血栓的方法之一"],"answer":1,"image":""},{"id":"nr4-105-2-23","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"黃女士，G1P1，產後第一天哺餵母奶，她告訴護理師：「我很擔心過兩天會有乳房脹痛的情形」，下列護理指導何者最適宜？","options":["(A) 餵完奶後把餘奶擠出","(B) 提醒個案少喝水","(C) 每次餵奶前做乳房按摩與熱敷","(D) 依照嬰兒的需求哺餵母奶"],"answer":3,"image":""},{"id":"nr4-105-2-24","subject":"nr4","topic":"產科-產後照護","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"有關母乳哺餵之敘述，下列何者錯誤？","options":["(A) 乳腺炎時可以繼續餵患側，並不會造成嬰兒感染","(B) 乳頭扁平通常使乳頭伸展性不佳，無法順利分泌乳汁","(C) 乳汁的多少和乳房的大小沒有關係","(D) 不要限制哺乳時間及次數可改善乳汁不足的情形"],"answer":1,"image":""},{"id":"nr4-105-2-25","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"有關足月新生兒泌尿道的特徵，下列何者錯誤？","options":["(A) 腎小管對於水分再吸收能力不足","(B) 腎小管對於電解質排除能力不足","(C) 出生後第1天尿量為25 ml/kg/day","(D) 新生兒腎絲球過濾率較成人為低"],"answer":2,"image":""},{"id":"nr4-105-2-26","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"有關新生兒身體評估的敘述，下列何者錯誤？","options":["(A) 外耳翼頂點低於眼外眥時，可能有染色體異常","(B) 鼻尖的小白點為粟粒疹，出生後3~5天即會消失","(C) 乳頭如有白色分泌物，是受母親雌性素影響之現象","(D) 歐特蘭妮操作法（Ortolani’s maneuver）評估若聽見喀答聲，表示髖關節有脫臼情形"],"answer":1,"image":""},{"id":"nr4-105-2-27","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"有關新生兒出生第5天臍帶尚未掉落的出院護理指導，下列何者正確？","options":["(A) 臍帶出現分泌物，就表示是感染徵象","(B) 洗澡後可以75%酒精消毒，由臍帶根部進行環狀擦拭","(C) 臍帶需用紗布覆蓋，不要讓臍帶暴露在空氣中","(D) 臍帶出現脫落徵象時，用手將其移除，再用75%酒精消毒"],"answer":1,"image":""},{"id":"nr4-105-2-28","subject":"nr4","topic":"產科-新生兒護理","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"以新貝拉德量表（New Ballard Score）執行新生兒的身體成熟度評估時，下列何項結果較不符合妊娠39週男嬰的生理特徵？","options":["(A) 乳暈突起3~4 mm","(B) 皮膚透明、可見靜脈","(C) 耳朵軟成形、可反彈","(D) 陰囊皺摺多，睪丸下降"],"answer":1,"image":""},{"id":"nr4-105-2-29","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"有關懷孕期間貧血的原因與診斷之敘述，下列何者正確？","options":["(A) 當孕婦血紅素低於11 g/dl，血清中鐵蛋白濃度低於12 μg/dl時，即表示有缺鐵性貧血","(B) 海洋性貧血是屬於性染色體遺傳疾病，分為甲型及乙型二類","(C) 缺鐵性貧血是婦女第11對染色體短臂末端上的2個β 血球基因（β-globin gene）突變所造成","(D) 若夫妻為同型海洋性貧血帶因者，其胎兒大多嚴重畸形，建議人工流產終止妊娠"],"answer":0,"image":""},{"id":"nr4-105-2-30","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"謝女士，妊娠23週，過去無糖尿病病史，口服葡萄糖耐受試驗（OGTT）檢查發現1小時後血糖值200 mg%，2小時後為180 mg%。有關謝女士的診斷，下列敘述何者正確？","options":["(A) 其兩次血糖數據均高過標準值，可確立為妊娠糖尿病","(B) 其妊娠週數大於20週，故非妊娠引起的糖尿病，應屬於其他特定型糖尿病","(C) 血糖值均超過160 mg%，是屬於非胰島素依賴型糖尿病（type II diabetes）","(D) 血糖值均超過160 mg%，是屬於胰島素依賴型糖尿病（type I diabetes）"],"answer":0,"image":""},{"id":"nr4-105-2-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"承上題，醫師安排謝女士需接受胰島素治療，她告訴護理師：「我上一胎生的小孩很健康，出生體重還4,100公克，我現在沒什麼不舒服，可不可以不要接受藥物治療？」，護理師的回應，下列何者較合宜？","options":["(A) 「您上一胎生了體重超過4,000公克的小孩，可能與妊娠糖尿病有關，此次應該要接受治療，因血糖不穩，小孩容易產生健康問題」","(B) 「我會提醒醫師說您沒有不舒服，看看是否可以不要接受藥物治療，畢竟，任何藥物對胎兒都不太有利」","(C) 「雖然您沒有不舒服，但您的血糖高於標準值，所以仍須接受治療，您只是口服降血糖藥物，對胎兒與您都沒有什麼影響」","(D) 「通常妊娠糖尿病的症狀會在妊娠25週以後出現，不能以症狀來判斷糖尿病的嚴重度，建議您不要錯過治療時機」"],"answer":0,"image":""},{"id":"nr4-105-2-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"有關妊娠糖尿病可能的合併症，下列何者錯誤？","options":["(A) 巨嬰","(B) 羊水過少","(C) 新生兒低血糖","(D) 妊娠誘發性高血壓"],"answer":1,"image":""},{"id":"nr4-105-2-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"有關胎盤早期剝離婦女產後護理處置之敘述，下列何者正確？","options":["(A) 預防產後大出血及持續觀察凝血機制","(B) 胎盤娩出後不可給予任何子宮收縮劑，以防血壓升高的副作用","(C) 胎盤剝離處接近陰道，產生逆行性感染的機會高","(D) 發生瀰漫性血管內凝血（DIC）症狀的高峰期為產後1星期"],"answer":0,"image":""},{"id":"nr4-105-2-34","subject":"nr4","topic":"產科-待產與分娩","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"有關真空吸引協助胎兒娩出之敘述，下列何者錯誤？","options":["(A) 適用胎頭骨盆不相對稱時","(B) 娩出後胎兒頭部可能會有血腫","(C) 需要由有經驗的醫師執行","(D) 抽吸罩放置於胎頭的枕骨上"],"answer":0,"image":""},{"id":"nr4-105-2-35","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"有關原發性痛經（primary dysmenorrhea）的敘述，下列何者正確﹖①下腹充血性疼痛 ②下腹痙攣性疼痛③發生於月經來潮前1週 ④發生於月經開始前數小時 ⑤經痛持續整個經期 ⑥經痛在月經來潮初期最明顯","options":["(A) ①③⑤","(B) ②④⑥","(C) ①④⑤","(D) ②③⑥"],"answer":1,"image":""},{"id":"nr4-105-2-36","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"有關口服黃體素治療月經量過多的主要目的，下列何者正確？","options":["(A) 增加子宮收縮能力","(B) 抑制前列腺素的形成","(C) 維持卵巢濾泡期功能","(D) 抑制子宮內膜的形成"],"answer":2,"image":""},{"id":"nr4-105-2-37","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"婦女服用混合雌性素與黃體素製劑改善更年期症狀，初期可能出現下列那些副作用？①體重增加 ②膚色變淡 ③乳房腫脹 ④月經出現 ⑤陰道分泌物減少","options":["(A) ①③④","(B) ①②⑤","(C) ②③④","(D) ③④⑤"],"answer":0,"image":""},{"id":"nr4-105-2-38","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"下列何種病源感染與子宮頸癌之形成有關？","options":["(A) 大腸桿菌","(B) 金黃葡萄球菌","(C) 人類乳突病毒","(D) 淋病雙球菌"],"answer":2,"image":""},{"id":"nr4-105-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"李女士，54歲，平日排尿正常，主訴咳嗽或大笑時會有滲尿情況，因而不喜歡外出參加社交活動。李女士可能的問題為下列何者？","options":["(A) 壓力性尿失禁","(B) 滿溢性尿失禁","(C) 急迫性尿失禁","(D) 混合性尿失禁"],"answer":0,"image":""},{"id":"nr4-105-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"承上題，下列護理指導何者最恰當？","options":["(A) 多食含膠質食物","(B) 白天減少喝水量","(C) 骨盆底肌肉運動","(D) 漸進式負重運動"],"answer":2,"image":""},{"id":"nr4-105-2-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"仔仔，5歲，在醫院中午用餐時，突然噎到東西，無法發聲且出現呼吸困難，此時護理師應該如何處理？","options":["(A) 施壓劍突下部位","(B) 進行人工呼吸","(C) 以手掌扣擊背部","(D) 給予心外按摩"],"answer":0,"image":""},{"id":"nr4-105-2-42","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"大明，至溪邊玩，因溺水約5分鐘，送至急診室後，評估其中心體溫33℃，知覺較遲鈍，有關回復體溫的處置，下列何者不適當？","options":["(A) 提供溫熱的毯子","(B) 提供熱湯並協助餵食","(C) 給予加熱的潮濕氧氣","(D) 給予電熱器加溫"],"answer":1,"image":""},{"id":"nr4-105-2-43","subject":"nr4","topic":"兒科-意外事故與急症","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"兒童若長時期接觸玩具上不當的塗料或染料，最容易發生何種物質中毒？","options":["(A) 鐵","(B) 鋰","(C) 鉛","(D) 汞"],"answer":2,"image":""},{"id":"nr4-105-2-44","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"小美，13歲，因脊柱側彎住院接受手術及支架固定，住院已2週，下列護理措施何者較不合適？","options":["(A) 為小美訂定一份生活作息表","(B) 安排醫院課業輔導老師教導","(C) 鼓勵小美參與身體活動之安排","(D) 鼓勵小美打電話邀請同學到醫院探視"],"answer":0,"image":""},{"id":"nr4-105-2-45","subject":"nr4","topic":"兒科-生長發展","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"小樺，18個月，護理師為她做丹佛Ⅱ嬰幼兒發展測驗（DDST-Ⅱ），下列何者是她這個年齡幼兒應通過的項目？","options":["(A) 會向前踢球","(B) 自己走得很穩","(C) 可以疊6塊積木","(D) 會騎三輪車一陣子"],"answer":1,"image":""},{"id":"nr4-105-2-46","subject":"nr4","topic":"兒科-生長發展","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"有關5歲幼兒的生理功能，下列何者尚未達到成人的發展程度？","options":["(A) 腎絲球的過濾率","(B) 骨骼系統的發育","(C) 聽覺與嗅覺功能","(D) 唾液腺的分泌功能"],"answer":1,"image":""},{"id":"nr4-105-2-47","subject":"nr4","topic":"兒科-生長發展","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"有關嬰幼兒氣質評估之敘述，下列何者錯誤？","options":["(A) 氣質評估可協助家長建立親子關係","(B) 嬰幼兒的氣質型態可作為因材施教的依據","(C) 氣質評估可以預估兒童未來的智力發展","(D) 氣質是嬰幼兒先天對內外在刺激的反應方式"],"answer":2,"image":""},{"id":"nr4-105-2-48","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"有關出生的過渡期，下列何者不是胎兒動脈導管的發展變化？","options":["(A) 出生後，肺動脈壓上升導致動脈導管收縮而關閉","(B) 出生後約2~4天，產生功能上的關閉","(C) 出生後約1~3個月，產生解剖上的關閉","(D) 出生3個月後，動脈導管萎縮變成動脈韌帶"],"answer":0,"image":""},{"id":"nr4-105-2-49","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"下列何者是血友病病童關節血腫較少出現的部位？","options":["(A) 膝關節","(B) 踝關節","(C) 肘關節","(D) 肩關節"],"answer":3,"image":""},{"id":"nr4-105-2-50","subject":"nr4","topic":"兒科-高危險新生兒","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"黃小妹，出生48小時即全身黃疸，膽紅素值12 mg/dl，檢驗結果顯示為血型不合造成之溶血性黃疸，有關這種病理性黃疸的原因，下列敘述何者正確？","options":["(A) 母親的血型是A型，胎兒的血型是O型","(B) 母親的血型是O型，胎兒的血型是A或B型","(C) 母親的血型是AB型，胎兒的血型是O型","(D) 母親為Rh(+)，胎兒為Rh(-)"],"answer":1,"image":""},{"id":"nr4-105-2-51","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"婷婷，14歲，罹患急性白血病，經過多次化療，現再度復發，有關青少年對死亡的理解及反應，下列敘述何者錯誤？","options":["(A) 對死亡的概念有成熟的理解，但仍有許多的疑問","(B) 較易認為自己不會在這麼年輕的時候就死亡","(C) 較易與醫護人員表達自己對死亡的看法","(D) 較不能與父母溝通以取得父母的支持"],"answer":2,"image":""},{"id":"nr4-105-2-52","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"榕榕，10歲，為罹患罕見疾病病童的姊姊，為協助其適應病童的疾病及治療的變化，下列護理措施何者最為適當？","options":["(A) 因榕榕對疾病知識或治療缺乏興趣，故無須主動介入","(B) 安撫榕榕，鼓勵其隨時提問或參與病童的照護活動","(C) 建議榕榕少到醫院探望病童，因為會增加病童的困擾","(D) 說服榕榕學習自我照顧，因為爸媽需要全力照顧病童"],"answer":1,"image":""},{"id":"nr4-105-2-53","subject":"nr4","topic":"兒科-高危險新生兒","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"許小妹妊娠週數26週3天，為早產，執行身體檢查與評估時，下列何者為最可能出現的臨床表徵？","options":["(A) 胎毛少，足底皺摺多，皮下脂肪多","(B) 手肘難以越過對側鎖骨中線（scarf sign）","(C) 腳跟難以觸及耳朵（heel to ear）","(D) 四肢肌肉張力無力，難以維持屈曲姿勢"],"answer":3,"image":""},{"id":"nr4-105-2-54","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"小強，於15個月大時被診斷有輕微的腦性麻痺（cerebral palsy），於指導雙親對小強在24個月大時之預期性發展任務，下列何者不適當？","options":["(A) 促進自理能力的掌控","(B) 建立正向的身體心像","(C) 增強對痛覺反應的能力","(D) 提供活動所需之額外熱量"],"answer":2,"image":""},{"id":"nr4-105-2-55","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"有關協助兒童因應親人死亡的哀傷照護方式，下列何者不適當？","options":["(A) 運用適合兒童發展階段能理解的語言，說明親人的死亡","(B) 告訴兒童難過是可以理解的，鼓勵兒童以他們的方式表達感覺","(C) 儘量少與兒童談及死亡的親人，以免造成無法處理的悲慟","(D) 接受兒童在其親人過世後可能有的退化性行為"],"answer":2,"image":""},{"id":"nr4-105-2-56","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"有關兒童罹患麻疹之臨床表徵，下列護理評估何者錯誤？","options":["(A) 前驅期時兒童會有咳嗽、結膜炎及鼻炎等症狀，此時體溫通常維持正常範圍","(B) 病童的下顎黏膜會發現中心藍白色而周圍呈不規則紅斑之科氏斑點（Koplik spots）","(C) 科氏斑點出現後1~2天，在兒童發燒到最高峰時便開始出疹","(D) 發疹的順序為：由上而下，前額、臉部、頸部、上肢、軀幹和下肢"],"answer":0,"image":""},{"id":"nr4-105-2-57","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"下列何種疫苗的接種途徑是肌肉注射，注射部位在嬰幼兒的大腿前外側？","options":["(A) 卡介苗","(B) 日本腦炎疫苗","(C) B型肝炎免疫球蛋白","(D) 麻疹、腮腺炎、德國麻疹混合疫苗"],"answer":2,"image":""},{"id":"nr4-105-2-58","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"小明，3歲，連續多日出現高燒（40~40.6℃）、食慾不振、口腔黏膜多發性潰瘍、牙齦紅腫出血、前頸部淋巴結腫痛、口腔外出現疱疹。醫師診斷為疱疹性口齦炎（Herpetic Gingivostomatitis）。下列護理措施何者不適當？","options":["(A) 協助使用含類固醇的口內膏來減輕炎症反應","(B) 衛教父母以流質及冰涼的食物來餵食","(C) 協助口服acyclovir來減輕疼痛及改善症狀","(D) 衛教父母目前尚無疫苗可預防此病毒感染"],"answer":0,"image":""},{"id":"nr4-105-2-59","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"有關小型噴霧治療（micro-nebulizer therapy）之護理措施，下列敘述何者錯誤？","options":["(A) 將藥物及生理食鹽水混合置入噴霧器之藥杯，氧氣流量需調整至6~8 L/min","(B) 使用時需將噴霧器呈垂直狀，以使氣動將藥物轉換成2~5μm的噴霧粒子","(C) 若病人為嬰兒，可將小型噴霧器架於氧氣頭罩上以增加效果","(D) 限每位病童個人單獨使用，藥杯與噴霧器每天清洗一次"],"answer":3,"image":""},{"id":"nr4-105-2-60","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"小英，7歲，診斷為氣喘，居家長期監測尖峰呼氣流量（peak expiratory flow rate, PEFR），其自我監測的個人最佳值為220 L/min。某日清晨，小英的PEFR為130 L/min，到傍晚上升為170 L/min，護理師判斷小英目前所處的狀態為何？","options":["(A) 呼吸道症狀已有改善，持續維持正常生活作息","(B) 呼吸道症狀逐漸被控制，預期PEFR將會更改善","(C) 呼吸道有發炎及黏膜水腫，小心監測PEFR的變化","(D) 呼吸道出現急性發作的危險，必須立刻緊急就醫治療"],"answer":2,"image":""},{"id":"nr4-105-2-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"下列敘述何者符合兒童呼吸系統的解剖生理特徵？","options":["(A) 鼻腔狹小、鼻黏膜柔軟且微血管豐富","(B) 耳咽管（歐式管）較成人短、窄且水平","(C) 喉頭較窄、較高；約在第4~5頸椎部位","(D) 肺泡表面積相對多，使得呼吸換氣量較多"],"answer":0,"image":""},{"id":"nr4-105-2-62","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"王小妹，足月出生，被診斷罹患開放性動脈導管，為其進行護理評估，下列何項臨床表徵較不會出現？","options":["(A) 餵食時，容易出現發紺的缺氧發作","(B) 觀察呼吸情況，可能發現肺部水腫症狀","(C) 觸診上肢脈搏時，常會出現寬廣的脈搏壓","(D) 聽診時，胸骨左側第二肋間有連續的機械性心雜音"],"answer":0,"image":""},{"id":"nr4-105-2-63","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"法洛氏四重畸形常見的臨床表徵是發紺，下列敘述何者錯誤？","options":["(A) 是血液中含氧量過低的結果","(B) 急性缺氧發作常發生在早晨、餵奶、哭泣或排便時","(C) 主要是血液有由左至右的分流","(D) 主要是肺動脈狹窄所致"],"answer":2,"image":""},{"id":"nr4-105-2-64","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"有關再生不良性貧血病童的臨床症狀與實驗室檢查，下列敘述何者錯誤？","options":["(A) 血容積小於30%時，會有心跳加快、呼吸急促的現象3","(B) 嗜中性白血球數少於1,500/mm時，會容易發生細菌感染現象3","(C) 血小板數小於50,000/mm時，易出現瘀斑及出血現象","(D) 胎兒紅血球降低時，易出現進行性的溶血性貧血"],"answer":3,"image":""},{"id":"nr4-105-2-65","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"協助罹患細小支氣管炎之病童執行姿位引流，下列時間何者較不適當？","options":["(A) 飯後半小時","(B) 睡覺前","(C) 早晨睡醒時","(D) 飯前1小時"],"answer":0,"image":""},{"id":"nr4-105-2-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"琪琪，女嬰，新生兒篩檢診斷為葡萄糖－6－磷酸鹽去氫酶缺乏症（Glucose-6-Phosphate Dehydrogenase Deficiency, G-6-PD Deficiency），下列有關此代謝疾病之敘述，何者錯誤？","options":["(A) 此疾病主要由父親傳給小孩，以女嬰居多","(B) 易發生溶血性貧血及高膽紅素血症","(C) 嬰兒發燒時應避免使用Aspirin","(D) 母親哺乳期間應避免食用蠶豆"],"answer":0,"image":""},{"id":"nr4-105-2-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"有關癌症病童疼痛時止痛劑的使用原則，下列敘述何者錯誤？","options":["(A) 定時給予止痛劑，以維持無痛狀態","(B) 給藥途徑以口服優先選用","(C) 重度疼痛需選擇嗎啡類的止痛劑","(D) 不可併用不同類的止痛劑"],"answer":3,"image":""},{"id":"nr4-105-2-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"有關癌症病童接受化學治療期間的感染預防措施，下列敘述何者錯誤？","options":["(A) 避免接種活性的病毒疫苗","(B) 避免接觸水痘或麻疹病童","(C) 縮短住院時間以防院內感染","(D) 進食的食物需經微波處理"],"answer":3,"image":""},{"id":"nr4-105-2-69","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"小容，17歲，診斷為甲狀腺機能亢進（Hyperthyroidism），下列臨床表徵何者錯誤？","options":["(A) 腸蠕動增快，易腹瀉","(B) 食慾增加，但體重減輕","(C) 皮膚乾燥、頭髮易斷裂","(D) 注意力不集中、情緒不穩"],"answer":2,"image":""},{"id":"nr4-105-2-70","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"急性淋巴性白血病童在接受化學治療多久後，會出現血球低下問題？","options":["(A) 24~72小時","(B) 7~14天","(C) 4~6週","(D) 2~3個月"],"answer":1,"image":""},{"id":"nr4-105-2-71","subject":"nr4","topic":"兒科-高危險新生兒","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"小明，妊娠週數32週出生，體重1,500 gm，將進行口胃管餵食，下列護理措施何者正確？","options":["(A) 測量插入的長度宜由鼻尖經耳垂，連接至劍突和肚臍中點的距離","(B) 插入過程若無咳嗽、嗆到、發紺，表示未插到氣管，可安全地灌食","(C) 灌食速度要緩慢，約5 mL/5~10分鐘，以預防胃部過度膨脹","(D) 餵食後協助左側臥、頭抬高45度約30分鐘，以防吸入性肺炎"],"answer":2,"image":""},{"id":"nr4-105-2-72","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"小美，12個月，診斷為泌尿道感染（urinary tract infection, UTI），有關出院護理指導，下列敘述何者錯誤？","options":["(A) 為避免因包尿布引起感染，立即開始大小便訓練","(B) 避免泡澡，儘量採淋浴的方式清潔身體","(C) 大小便後，會陰部的清潔需由前往後擦拭","(D) 可多攝取蔓越莓汁，以減少重複感染機會"],"answer":0,"image":""},{"id":"nr4-105-2-73","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"有關隱睪症的評估，下列敘述何者錯誤？","options":["(A) 保持檢查環境溫暖，避免提睪肌收縮會將睪丸拉回至腹股溝內","(B) 視診，睪丸未下降側的陰囊縮小，且表皮平滑、缺少摺紋","(C) 6個月大前，可讓嬰兒平躺，以觸診檢查雙側的陰囊","(D) 大於6個月的小孩宜採站姿檢查，以緩和提睪肌"],"answer":3,"image":""},{"id":"nr4-105-2-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"有關尿道下裂病童手術後的護理措施，下列敘述何者不適當？","options":["(A) 限制喝水，以降低尿液滲漏","(B) 導尿管固定於腹部或腿上，以免牽扯傷口","(C) 避免淋浴，直到傷口痊癒為止","(D) 預防便秘，以免影響傷口癒合"],"answer":0,"image":""},{"id":"nr4-105-2-75","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"王小妹，10歲，診斷為急性腎絲球腎炎，每天尿量約250 c.c.，血中尿素氮（BUN）100 mg/dL，下列護理指導何者錯誤？","options":["(A) 攝取生酮飲食，以利腎絲球過濾","(B) 攝取低蛋白質飲食，以保護腎臟功能","(C) 嚴格限水，以控制水腫與高血壓","(D) 避免高鉀食物，以減少水分滯留"],"answer":0,"image":""},{"id":"nr4-105-2-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"小嫻，4歲，預行排尿性膀胱尿道攝影（VCUG），有關檢查前後的護理措施，下列何者正確？","options":["(A) 檢查前，至少禁食（NPO）8小時，以免引起嘔吐","(B) 檢查前，需給予清潔灌腸，以免影響影像判讀","(C) 檢查中，需收集尿液，測量膀胱壓力，以了解排尿功能","(D) 檢查後，需鼓勵多喝水，以利排出顯影劑"],"answer":3,"image":""},{"id":"nr4-105-2-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"王小弟，9歲，診斷為裘馨氏假肥大性肌失養症（Duchenne’s pseudohypertrophic muscular dystrophy），下列護理指導何者不適當？","options":["(A) 鼓勵王小弟進行體能活動，避免肢體攣縮變形","(B) 避免讓王小弟游泳，以防溺水意外之發生","(C) 家中添加輔助性設施，以減少王小弟發生意外","(D) 每日為王小弟執行胸腔物理治療，以預防肺炎"],"answer":1,"image":""},{"id":"nr4-105-2-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"張小弟，就讀小學三年級，罹患強直陣攣型癲癇（tonic-clonic seizure），有關其在學校癲癇發作時的照護，下列敘述何者錯誤？","options":["(A) 協助採取側臥姿勢，以利口鼻分泌物流出","(B) 疏散圍觀人潮維持通風，以免影響呼吸","(C) 移除身旁堅硬及尖銳物，以提供安全環境","(D) 立即進行口對口人工呼吸，以避免缺氧"],"answer":3,"image":""},{"id":"nr4-105-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"曉華，5歲，診斷為重症肌無力（myasthenia gravis），下列護理指導何者錯誤？","options":["(A) 應教導家長注意曉華的呼吸是否順暢、痰液不易咳出","(B) 應鼓勵曉華多進食需咀嚼的食物，以減緩咀嚼功能之退化","(C) 應減少曉華費力的活動，以改善肌肉力量、保留體力","(D) 若仍有眼瞼下垂、視力不佳情形，應注意其活動安全"],"answer":1,"image":""},{"id":"nr4-105-2-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"小華，14歲，疑似腦膜炎，目前有咳嗽、顱內壓升高的症狀，有關小華的照護措施，下列敘述何者正確？","options":["(A) 維持屈膝仰臥，以利靜脈血回流","(B) 給予背部叩擊，以促進痰液排出","(C) 教導深呼吸咳嗽，避免引發肺炎","(D) 攝取高纖維食物，以避免便秘"],"answer":3,"image":""},{"id":"nr4-106-1-1","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"王女士，產後第2天，孕產史為G1P1，為越南籍配偶，由婆婆陪伴照顧，婆婆堅持產後一定要喝生化湯，此時護理師該如何處置？","options":["(A) 接受其傳統習俗，但囑咐其需服藥後1小時再喝","(B) 採不批判的態度，與王女士討論其想法及決定","(C) 為避免衝突，建議等婆婆回去時，再把生化湯倒掉","(D) 尊重其習俗，假裝沒看見"],"answer":1,"image":""},{"id":"nr4-106-1-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"有關現今產科照護發展趨勢的敘述，下列何者正確？","options":["(A) 提升專業人員的衛教能力，並以電腦網絡達成資源共享","(B) 鼓勵女性醫師從事婦產科醫療業務","(C) 應該挑戰各國的傳統習俗","(D) 主張延長住院天數"],"answer":0,"image":""},{"id":"nr4-106-1-3","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"許女士，懷孕30週，這兩週血壓上升，尿液檢查也有異常反應，醫師給予胎兒生理活動評估（BPP），有關此評估之敘述下列何者正確？","options":["(A) 包括胎兒身體張力、胎動與羊膜腔穿刺術等項目","(B) 為自我檢查胎動的紀錄方法","(C) 4～6分表示有胎兒窒息，需立即引產","(D) 包括胎兒呼吸運動、羊水容積與無壓力試驗等項目"],"answer":3,"image":""},{"id":"nr4-106-1-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"下列何者為懷孕之確實徵候？①聽診到胎心音 ②月經未現 ③觸診到胎兒四肢的活動 ④超音波掃描到妊娠囊 ⑤觸摸到胎兒的外形輪廓","options":["(A) ①④⑤","(B) ①③④","(C) ②④⑤","(D) ②③④"],"answer":1,"image":""},{"id":"nr4-106-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"有關妊娠期婦女胃腸系統平滑肌鬆弛所產生之生理變化，下列何者正確？","options":["(A) 胃酸分泌減少","(B) 流涎症","(C) 腸胃蠕動加速","(D) 膽汁排出量減少"],"answer":3,"image":""},{"id":"nr4-106-1-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"有關妊娠期泌尿系統的變化情形之敘述，下列何者正確？","options":["(A) 腎絲球的過濾率增加，使腎臟對糖分吸收閾值升高","(B) 腎小管的再吸收速度增加，以代償腎絲球活動的減少","(C) 腎臟對葡萄糖的再吸收作用速率是不變的","(D) 腎絲球的過濾率增加，使得血液中尿素氮（BUN）含量增加"],"answer":2,"image":""},{"id":"nr4-106-1-7","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"陳女士，妊娠32週，接受腹部超音波掃描發現胎兒身長體重與1個月前相同，估算約為28週，胎盤功能正常，所有檢查數值均在正常範圍，但陳女士體重並未增加。對此結果陳女士因焦慮而哭泣，下列何項敘述正確？","options":["(A) 這是正常的誤差，請陳女士不要著急可不予理會","(B) 鼓勵陳女士正常飲食及充足睡眠，並接受進一步檢查","(C) 只要胎兒沒有外觀上畸形，發育遲滯沒有關係","(D) 胎兒體重小於妊娠週數較有利於自然生產"],"answer":1,"image":""},{"id":"nr4-106-1-8","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"有關胎兒呼吸系統發育之敘述，下列何者正確？","options":["(A) 受孕15至17週已有氣管及支氣管形成","(B) 肺泡管的發育開始於受孕第7個月","(C) 卵磷脂（Lecithin）與抱合髓磷脂（Sphingomyelin）的比值小於1表示肺部已成熟","(D) 胎兒出生前肺臟在子宮內已具有部分呼吸功能"],"answer":0,"image":""},{"id":"nr4-106-1-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"王女士，33歲，目前懷孕9週，有貧血的現象。下列何種食物可幫助鐵質的吸收？","options":["(A) 麥片","(B) 牛奶","(C) 橘子汁","(D) 熱可可"],"answer":2,"image":""},{"id":"nr4-106-1-10","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"陳女士，懷孕26週，下列何項血液變化為正常？","options":["(A) 纖維蛋白原減少","(B) 血比容上升","(C) 白血球減少","(D) 血紅素下降"],"answer":3,"image":""},{"id":"nr4-106-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"一位產婦入院待產，子宮頸口開6公分，因產痛難耐而要求醫護人員提供針灸止痛的措施時，下列有關護理師的反應何者較為合適？","options":["(A) 針灸並無法減輕生產疼痛，建議產婦使用硬腦膜下腔麻醉方式來止痛","(B) 針灸有利減輕生產疼痛，因此可協助產婦照會中醫師","(C) 產房護理師可針對穴位進行針刺以減輕產痛","(D) 針灸只能減輕第二產程的產痛，建議產婦可先行使用其他減痛處置"],"answer":1,"image":""},{"id":"nr4-106-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"蘇女士，G2P1，懷孕39週，因現血與陣痛而入院待產。現子宮頸口開4公分，主訴宮縮時下腹部及下背疼痛難忍，導致其疼痛的原因為何？","options":["(A) 因子宮韌帶伸張、陰道及會陰肌肉伸展所致","(B) 因待產時經常採用同一種臥位而導致背部與腰部神經受壓迫所致","(C) 因子宮體下段伸展、子宮頸擴張與子宮收縮時肌肉細胞缺氧所致","(D) 因子宮收縮，神經衝動由第2～4尾椎神經傳入脊髓所致"],"answer":2,"image":""},{"id":"nr4-106-1-13","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"承上題，護理師提供蘇女士背部按摩以減輕疼痛，此護理措施是根據那一種疼痛理論？","options":["(A) 認知控制理論（cognitive control theory）","(B) 壓力因應理論（stress-coping theory）","(C) 害怕－緊張－疼痛理論（fear-tension-pain theory）","(D) 門閾或路徑控制理論（gate control theory）"],"answer":3,"image":""},{"id":"nr4-106-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"胎兒以面產式，胎頭完全仰伸進入骨盆時，呈現的徑線為下列何者？","options":["(A) 枕額徑（OF）","(B) 頦下前囟徑（SMB）","(C) 枕頦徑（OM）","(D) 枕下前囟徑（SOB）"],"answer":1,"image":""},{"id":"nr4-106-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"張女士待產時胎心率發生變異性減速（variable deceleration），此時護理師應最先執行的護理措施為下列那一項？","options":["(A) 協助張女士左側臥","(B) 測量生命徵象","(C) 觀察陰道有無出血","(D) 抬高張女士頭部"],"answer":0,"image":""},{"id":"nr4-106-1-16","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"王女士，46歲，因子宮肌瘤接受子宮切除手術，有關術後出院照護指導內容，下列何者適當？","options":["(A) 每日執行溫水坐浴，促進分泌物排除","(B) 術後6週內每日做踩單車運動，促進骨盆腔血液循環","(C) 術後6週內應避免性生活，促進傷口癒合","(D) 術後1個月內，陰道持續有中量血色分泌物是正常的"],"answer":2,"image":""},{"id":"nr4-106-1-17","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"林女士因破水進入產房待產，護理師協助陰道內診，摸到胎頭前囟門，胎頭高度在-3。胎頭高度在-3意義為何？","options":["(A) 胎兒頭部尚未固定","(B) 胎兒高度在坐骨棘連線上3公分","(C) 胎兒高度在坐骨棘連線下3公分","(D) 胎兒頭部已逐漸下降接近生產"],"answer":1,"image":""},{"id":"nr4-106-1-18","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"使用Bishop評估引產成功的可能性，須包括之項目為何？①子宮頸擴張 ②懷孕週數 ③子宮頸變薄 ④胎位 ⑤子宮頸位置","options":["(A) ①②③","(B) ②③④","(C) ③④⑤","(D) ①③⑤"],"answer":3,"image":""},{"id":"nr4-106-1-19","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"張女士，產後2小時自恢復室返室，惡露呈鮮紅色，1小時內即浸溼整片產墊，下列敘述何者正確？ ①此為早期出血 ②此為晚期出血 ③可能與子宮收縮不良有關 ④可能與胎盤組織殘留有關","options":["(A) 僅①③","(B) 僅②④","(C) ①③④","(D) ②③④"],"answer":2,"image":""},{"id":"nr4-106-1-20","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"產後純母乳哺餵的婦女，坐月子期間最好的避孕方法為：","options":["(A) 口服避孕藥","(B) 測量基礎體溫","(C) 子宮內避孕器","(D) 保險套"],"answer":3,"image":""},{"id":"nr4-106-1-21","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"黃女士，G2P2，陰道產後6小時尚未排尿，她表示：「我從生產到現在只喝一點水，沒什麼尿液感」，下列護理處置何者最適宜？","options":["(A) 因個案水喝得少，繼續觀察有無尿液感情形","(B) 鼓勵個案多喝水，增加尿液感","(C) 若個案超過8小時仍未排尿，則協助導尿","(D) 評估膀胱，解釋產後膀胱脹滿的敏感度減低，並協助排尿"],"answer":3,"image":""},{"id":"nr4-106-1-22","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"有關奶水不足的主要原因，下列何者錯誤？","options":["(A) 寶寶含乳姿勢不正確","(B) 母親自信不足使催產素反射減弱","(C) 母親身體的疼痛抑制催產素反射","(D) 未限制哺餵的時間及次數"],"answer":3,"image":""},{"id":"nr4-106-1-23","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"黃女士，G1P1，陰道生產，想在寶寶1歲前離奶（斷奶），下列何者錯誤？","options":["(A) 採漸進式的方式以奶瓶餵食來替代母乳哺餵","(B) 排空乳房以減輕乳房腫脹不適","(C) 穿戴合身且具支托性的胸罩","(D) 指導攝取小麥汁或韭菜"],"answer":1,"image":""},{"id":"nr4-106-1-24","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"有關Rubin提出之產後心理適應中的緊執期（Taking-hold phase）之敘述，下列何者正確？","options":["(A) 是產後介於依賴與獨立間的一段時間","(B) 話多，喜歡談論懷孕生產過程，以幫助確認孩子已與她分離","(C) 接受孩子是一獨立個體，也很注重自己的生理需求","(D) 確認孩子的個性及需求，重新設定為人母的角色"],"answer":0,"image":""},{"id":"nr4-106-1-25","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"預防產後血栓靜脈炎發生的護理措施，下列何項錯誤？","options":["(A) 鼓勵產婦產後早期下床活動","(B) 產後第1天即可執行產後運動","(C) 產後每日評估霍曼氏徵象（Homan's sign）","(D) 若有血栓病史者，不宜早期下床活動"],"answer":3,"image":""},{"id":"nr4-106-1-26","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"哺餵母乳使月經較延後之原因為何？","options":["(A) 刺激泌乳激素分泌，抑制動情素與黃體生成激素","(B) 刺激動情素與黃體生成激素，進而刺激泌乳激素","(C) 刺激泌乳激素與動情素分泌，抑制黃體生成激素","(D) 刺激黃體生成激素與泌乳激素，抑制動情素分泌情況題：江女士，G1P1，妊娠40週，以Vacuum協助自然產下一體重3,580公克男嬰。請依上文回答第27題至第29題："],"answer":0,"image":""},{"id":"nr4-106-1-27","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"新生兒出生5分鐘時，護理師評估Apgar score，除評估心跳、呼吸、膚色及刺激反射外，尚須評估新生兒的那一部分？","options":["(A) 外觀是否完整","(B) 大小便有無解出","(C) 肌肉張力是否有力","(D) 身高體重的數值"],"answer":2,"image":""},{"id":"nr4-106-1-28","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"產後第1天，江女士詢問寶寶的胎頭腫塊（Caput），下列何種解釋最適宜？","options":["(A) 這是接生時使用器械產生的，可以去問醫生","(B) 這腫塊出生後數天會自行消失，不用擔心","(C) 這腫塊柔軟、局部，界限清楚，新生兒常發生","(D) 這腫塊可能有顱內出血、黃疸等合併症"],"answer":1,"image":""},{"id":"nr4-106-1-29","subject":"nr4","topic":"產科-產後照護","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"有關江女士的表現，下列何者為潛在適應不良的徵兆？","options":["(A) 看寶寶時皺著眉，哭著對護理師說「他看起來好可怕！」","(B) 與友人談論其生產之過程","(C) 抱在胸前哺餵母乳時，不時的撫摸寶寶有胎頭腫塊的部位","(D) 喜歡觸摸寶寶身體及與之輕聲說話"],"answer":0,"image":""},{"id":"nr4-106-1-30","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"黃小妹採純母乳哺餵，食慾不錯，出生第3天媽媽發現黃小妹臉上膚色黃黃的，測得血清膽紅素為12 mg/dL，護理師的相關解釋何者正確？","options":["(A) 可能是血型不合所導致的病理性黃疸（Pathologic jaundice），要趕快通知醫生做後續治療","(B) 可能是核黃疸（Kernicterus）的前驅表現，容易造成黃小妹腦部損傷及智力傷害，最好先照光治療","(C) 可能是餵母乳造成的母乳性黃疸（Breast milk jaundice），暫時停止哺餵母乳就會改善","(D) 可能是一般的生理性黃疸（Physiologic jaundice），持續注意黃小妹食慾狀況及膚色變化即可"],"answer":3,"image":""},{"id":"nr4-106-1-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"妊娠早期之孕婦若感染下列何種疾病，容易導致胎兒先天性心臟病、耳聾、白內障等不良後果？","options":["(A) 梅毒（syphilis）","(B) 風濕性心臟病（rheumatic heart disease）","(C) 傷寒（typhoid fever）","(D) 德國麻疹（rubella）"],"answer":3,"image":""},{"id":"nr4-106-1-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"沈女士，21歲，懷孕30週產檢時發現血壓150/100 mmHg，經診治與追蹤1個月後，血壓仍維持在150/100～160/110 mmHg之間，34週產檢時血壓160/100 mmHg合併尿蛋白(+)及水腫(+)情形，根據這些臨床徵候，沈女士可能罹患下列何項合併症？","options":["(A) 腎性高血壓","(B) 子癇前症","(C) 妊娠惡化性高血壓","(D) 腦中風前症候群"],"answer":1,"image":""},{"id":"nr4-106-1-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"承上題，沈女士住院安胎，依醫囑予MgSO4 2 gm稀釋於5% D/W 500 c.c.，以5 mL/min靜脈滴注，下列護理措施何者正確？","options":["(A) 注意孕婦是否有MgSO4中毒現象，如深部肌腱反射增強、呼吸受抑制","(B) 50% Calcium gluconate應置於床邊，以備MgSO4中毒時解毒之用","(C) 須監控每小時尿量宜少於25 mL，以避免水分攝取過多導致肺水腫","(D) MgSO4可能造成呼吸抑制現象，應監控呼吸速率，宜大於12次/分"],"answer":3,"image":""},{"id":"nr4-106-1-34","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"形成妊娠中期心灼熱感（heart burn）的荷爾蒙為下列何者？","options":["(A) 人類絨毛膜促性腺激素","(B) 人類胎盤泌乳激素","(C) 黃體素","(D) 雌性素"],"answer":2,"image":""},{"id":"nr4-106-1-35","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"王女士，52歲，最近感到下腹部有沉重感，診斷為第一度的子宮脫垂，此與下列何種骨盆腔韌帶無力有關？","options":["(A) 闊韌帶、圓韌帶","(B) 子宮薦骨韌帶、主韌帶","(C) 圓韌帶、主韌帶","(D) 輸卵管骨盆韌帶、闊韌帶"],"answer":1,"image":""},{"id":"nr4-106-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"服用口服避孕藥的禁忌症，下列何者錯誤？","options":["(A) 有血栓性疾病史者","(B) 已有懷孕可能者","(C) 有高血壓病史者","(D) 有子宮外孕史者"],"answer":3,"image":""},{"id":"nr4-106-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"王先生與太太結婚3年一直沒有孩子，醫師請他接受精液分析檢查，有關收集精液之護理指導，下列何者正確？","options":["(A) 須先禁慾7～10天","(B) 以保險套收集精液","(C) 以手淫方式收集精液","(D) 精液在運送過程需冷藏"],"answer":2,"image":""},{"id":"nr4-106-1-38","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"有關更年期婦女變化之敘述，下列何者正確？","options":["(A) 因雌性素減少，使得體內低密度脂蛋白（LDL）增加，易有心血管疾病","(B) 因黃體素減少，造成骨母細胞活動力減少，而易有骨質疏鬆症","(C) 因雄性素減少，導致陰道容易發炎，而有性交困難","(D) 所有的更年期婦女均可接受荷爾蒙補充療法（HRT）"],"answer":0,"image":""},{"id":"nr4-106-1-39","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"有關經前症候群的敘述，下列何者正確？","options":["(A) 在月經週期的黃體期，產生生理、心理及行為的週期性變化","(B) 子宮內膜分泌之前列腺素、黃體素及留鹽激素過多所導致","(C) 與是否有潛在性婦科疾病有關","(D) 因催乳激素分泌不足所引起"],"answer":0,"image":""},{"id":"nr4-106-1-40","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"下列何者為子宮頸癌的危險因子？","options":["(A) 糖尿病","(B) 單一性伴侶","(C) 未生育","(D) 較早有性經驗"],"answer":3,"image":""},{"id":"nr4-106-1-41","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"下列何者不是16歲青少女神經性厭食症的表徵？","options":["(A) 進食時會玩弄食物","(B) 自覺身體外型太瘦","(C) 超過3個月沒來月經","(D) 四肢冰冷且較怕冷"],"answer":1,"image":""},{"id":"nr4-106-1-42","subject":"nr4","topic":"兒科-生長發展","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"林小弟，1歲6個月，護理師使用丹佛Ⅱ發展篩檢測驗林小弟目前的發展情形，下列那一項測驗結果需懷疑林小弟發展有延遲現象？","options":["(A) 無法通過倒退走路","(B) 無法通過向前踢球","(C) 無法通過單腳平穩站立","(D) 無法通過以腳跟接腳趾行走"],"answer":0,"image":""},{"id":"nr4-106-1-43","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"小明，5歲，因上呼吸道感染住院，基於以家庭為中心的照護理念，下列何者錯誤？","options":["(A) 鼓勵病童其家庭成員，表達對病童罹病的想法","(B) 需要時評估病童家人，不能參與照顧病童的原因","(C) 教導父母，共同參與病童所需的照護知識及技巧","(D) 為賦權父母照顧能力，要求須在院執行病童的照護"],"answer":3,"image":""},{"id":"nr4-106-1-44","subject":"nr4","topic":"兒科-意外事故與急症","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"小亮，8歲，於野外露營時被雨傘節咬傷左小腿，下列何項處置最為適宜？","options":["(A) 以夾板固定患肢且保持低於心臟位置","(B) 建議儘快沖洗傷口並將傷口切開","(C) 可於傷口的遠心端用彈性繃帶綁住","(D) 常因革蘭氏陽性桿菌感染需使用抗生素治療"],"answer":0,"image":""},{"id":"nr4-106-1-45","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"下列何種藥物可能與雷氏症候群（Reye syndrome）有關，不建議兒童使用？","options":["(A) Acetaminophen","(B) Ibuprofen","(C) Ketorolac","(D) Aspirin"],"answer":3,"image":""},{"id":"nr4-106-1-46","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"有關兒童肌肉注射部位的考量，下列敘述何者正確？","options":["(A) 股內側肌神經血管少，適合為0～2歲病童注射","(B) 腹臀肌神經血管少，適合為0～2歲病童注射","(C) 背臀肌吸收最迅速，但6歲以下兒童儘量避免使用","(D) 上臂三角肌吸收最迅速，適合國小學童預防注射"],"answer":3,"image":""},{"id":"nr4-106-1-47","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"下列為2歲幼兒滴耳藥的護理步驟，那一個環節出現錯誤？","options":["(A) 使用耳藥前，先注意藥物溫度，以接近體溫為宜","(B) 協助病童側臥或向健側半側臥，使患耳向上","(C) 將病童耳垂往上往後輕拉，以使耳道拉直","(D) 沿耳壁滴注藥物，以手指輕微按摩耳部"],"answer":2,"image":""},{"id":"nr4-106-1-48","subject":"nr4","topic":"兒科-生長發展","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"小馨，20個月，身體檢查評估時，一般而言，下列那顆乳齒尚未長出？","options":["(A) 犬齒","(B) 側門齒","(C) 第一大臼齒","(D) 第二大臼齒"],"answer":3,"image":""},{"id":"nr4-106-1-49","subject":"nr4","topic":"兒科-意外事故與急症","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"王小弟，10歲，頭部外傷住加護病房治療，因病情穩定轉出至兒科病房，然病童仍躁動不安，欲拔除鼻胃管及靜脈注射留置針，經護理評估為了病人安全需給予約束，下列護理措施何者正確？","options":["(A) 配合翻身，每隔2小時觀察約束肢體的循環狀態","(B) 可採用手臂約束法，將固定帶綁在床欄杆上","(C) 可採用雙套結約束法，用棉墊保護雙手，固定於床架上","(D) 可採用木乃伊約束法，固定雙手雙腳外，維持頭頸部自由活動"],"answer":2,"image":""},{"id":"nr4-106-1-50","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"小強，15個月大，被診斷有輕微的腦性麻痺（cerebral palsy）。小強爸爸是個食品公司全職行銷人員，媽媽則在電腦公司上班，家中有請外傭照顧小強，外傭每週一次帶小強去醫院做復健，下列何者為主要的護理措施？","options":["(A) 盡力保護避免傷害","(B) 解釋腦性麻痺的病因","(C) 改善身體心像","(D) 促進成長及發展"],"answer":3,"image":""},{"id":"nr4-106-1-51","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"小維，足月兒，體重2,800公克。出生後的第3天，血液檢驗報告其總膽紅素值（Total Serum Bilirubin）為16 mg/dL，醫囑照光治療，下列何者是最重要的護理目標？","options":["(A) 準備家屬居家照光療法的護理指導","(B) 提供眼罩及確保小維有足夠的水分攝取","(C) 每小時執行採腳跟血測量小維的膽紅素值","(D) 說明照光療法對小維不會造成任何副作用"],"answer":1,"image":""},{"id":"nr4-106-1-52","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"李太太患有妊娠糖尿病，懷孕38週，自然娩出一女嬰，出生體重3,800公克，有關李小妹出生後的照顧，下列敘述何者錯誤？","options":["(A) 需評估李小妹可能會有盜汗、呼吸喘、嗜睡情形","(B) 出生後4小時應測第一次血糖","(C) 當李小妹血糖低於36 mg/dL應採取措施","(D) 應儘早餵食母奶或配方奶"],"answer":1,"image":""},{"id":"nr4-106-1-53","subject":"nr4","topic":"兒科-高危險新生兒","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"翰翰，剛出生，發現有吸入胎便，有關胎便吸入症候群，下列護理評估與判斷何者正確？","options":["(A) 會導致腸阻塞或腹瀉","(B) 會導致呼吸性鹼中毒","(C) 會導致肺栓塞及肋膜積水","(D) 會導致缺氧及小氣道阻塞"],"answer":3,"image":""},{"id":"nr4-106-1-54","subject":"nr4","topic":"兒科-高危險新生兒","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"劉小妹，妊娠週數25週又5天出生，體重680公克，現住在保溫箱中，目前體溫36℃，有關維持正常體溫之措施，下列敘述何者錯誤？","options":["(A) 維持保溫箱濕度40%，以避免體熱流失","(B) 使用呼吸器加熱潮濕器，以維持氧氣的溫度","(C) 給予乾淨的塑膠膜覆蓋，以免對流熱喪失","(D) 給予頭部戴帽及毛毯包裹，以保持體溫"],"answer":0,"image":""},{"id":"nr4-106-1-55","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"依據娜姬（Nagy）死亡概念理論，下列何者不是6歲兒童對死亡的概念？","options":["(A) 死亡是一種自然現象","(B) 死亡是可以避免的","(C) 只有被抓到的人才會死","(D) 只有老人才會死掉"],"answer":0,"image":""},{"id":"nr4-106-1-56","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"下列何種腸病毒感染的致病原最容易引起神經系統的併發症？","options":["(A) 克沙奇A9型病毒","(B) 克沙奇B5型病毒","(C) 腸病毒70型","(D) 腸病毒71型"],"answer":3,"image":""},{"id":"nr4-106-1-57","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"有關出血性登革熱（dengue hemorrhagic fever）敘述，下列護理措施何者錯誤？","options":["(A) 需小心注意觀察病童可能出現腹水、肋膜積水、低血壓等臨床變化","(B) 病童會發高燒及全身肌肉關節疼痛，建議使用水楊酸類解熱鎮痛","(C) 衛教家人居家預防之道，為撲滅埃及斑蚊及白線斑蚊等病媒蚊","(D) 因其屬於第二類法定傳染疾病，發現新病例需報告當地衛生主管機關"],"answer":1,"image":""},{"id":"nr4-106-1-58","subject":"nr4","topic":"兒科-生長發展","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"小瑛，出生時體重為3 Kg，有關其體重的發展之評估標準，下列何者正確？","options":["(A) 足6個月時，體重約為4.5 Kg","(B) 12個月大時，體重約為6 Kg","(C) 2歲半時，體重約為9 Kg","(D) 4歲時，體重約為15 Kg"],"answer":3,"image":""},{"id":"nr4-106-1-59","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"小華，5歲大，疑似細菌性支氣管炎，使用脈衝式血氧分析法（Pulse Oximetry）偵測脈動血氧，下列敘述何者錯誤？","options":["(A) 為非侵入性偵測血氧的方法，可單次或連續測量血氧飽和度（SpO2）","(B) 可於耳垂、手指或腳趾放置紅外線掃描感應器來監測動脈血流脈動","(C) 感應器的光源探測器位置應固定，避免更換，以增加數值之正確性","(D) 儀器顯示的心跳速率與病童實際的心跳相符時，測得的數值才準確"],"answer":2,"image":""},{"id":"nr4-106-1-60","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"有關嬰兒及兒童接受氧氣治療之相關敘述，下列何者正確？","options":["(A) 使用鼻套管時，氧氣流量不可超過2 L/min，以免黏膜乾燥","(B) 使用氧氣面罩時，氧氣流量不可超過6 L/min，以免氧氣濃度過高","(C) 使用氧氣頭罩時，氧氣流量約調為5 L/min，以免二氧化碳滯留","(D) 使用氧氣帳時，氧氣流量約調為3 L/min，以免發生火花"],"answer":2,"image":""},{"id":"nr4-106-1-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"小英，6歲大，診斷為肺炎，目前痰分泌物黏稠，胸部聽診發現左肺上葉前節有明顯的濕囉音，為小英執行胸腔物理治療，下列護理措施何者正確？","options":["(A) 為有效去除痰分泌物，可先行噴霧治療，再行姿位引流與叩擊","(B) 執行胸部物理治療的時間，最好是在飯前或飯後半小時","(C) 超音波噴霧器底部水槽需加入生理食鹽水，以避免機械受損","(D) 引流左肺上葉前節，最好的姿勢是俯臥及拍背部"],"answer":0,"image":""},{"id":"nr4-106-1-62","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"吳小弟，2歲，因持續發燒5天以上，且出現嘴唇發紅乾裂及草莓樣舌，診斷為川崎氏症，下列何者不屬於川崎氏症兒童的重要症狀觀察項目？","options":["(A) 肛門周圍皮膚脫皮","(B) 呼吸喘促","(C) 眼結膜充血","(D) 四肢末梢紅腫"],"answer":1,"image":""},{"id":"nr4-106-1-63","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"有關大動脈轉位（Transposition of the Great Arteries; TGA）的新生兒之護理評估，下列表徵何者錯誤？","options":["(A) 紅血球增多","(B) 低血氧及發紺症狀","(C) 上下肢血壓相差約20 mmHg","(D) 心臟聽診時，第二心音加重"],"answer":2,"image":""},{"id":"nr4-106-1-64","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"下列何者不是兒童急性風濕熱會出現的臨床表徵？","options":["(A) 心臟炎","(B) 皮下結節","(C) 四肢末梢脫皮","(D) 多發性關節炎"],"answer":2,"image":""},{"id":"nr4-106-1-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"霏霏，2個月，罹患心房中膈缺損（Atrial Septal Defect; ASD），下列護理指導何者不恰當？","options":["(A) 一般不會出現發紺現象","(B) 1歲以內將近一半會自動閉合","(C) 需小心照護，減少呼吸道感染","(D) 按時服用前列腺素E1（Prostaglandin E1）"],"answer":3,"image":""},{"id":"nr4-106-1-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"有關血友病病童的運動建議，下列敘述何者正確？","options":["(A) 籃球","(B) 網球","(C) 游泳","(D) 跳馬"],"answer":2,"image":""},{"id":"nr4-106-1-67","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"有關兒童感染人類免疫缺乏病毒（HIV）的症狀，下列何者錯誤？","options":["(A) 淋巴間質性肺炎（Lymphoid interstitial pneumonitis）","(B) 肝脾腫大（Hepatosplenomegaly）","(C) 慢性便秘（Chronic constipation）","(D) 口腔念珠菌病（Oral candidiasis）"],"answer":2,"image":""},{"id":"nr4-106-1-68","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"有關苯酮尿症（Phenylketonuria）病童飲食指導之敘述，下列何者錯誤？","options":["(A) 於確定診斷後，即開始終身飲食控制","(B) 嬰幼兒時，餵食特殊配方奶Lofenalac和Phenyl-Free","(C) 長大後可以多補充水果、蔬菜、根類或澱粉類食物","(D) 應限制麵粉製品、肉類、魚類、牛奶及豆類等食物"],"answer":0,"image":""},{"id":"nr4-106-1-69","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"小樺，7歲，最近因持續發燒、易流鼻血而求診，診斷疑似急性淋巴性白血病，下列那一項檢查結果可以確定其診斷？33","options":["(A) 周邊血液白血球數量15,000/mm","(B) 周邊血液血小板數量20,000/mm","(C) 腦脊髓液色澄清，葡萄糖減少","(D) 骨髓中未成熟白血球細胞有85%"],"answer":3,"image":""},{"id":"nr4-106-1-70","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"有關化學治療藥物的副作用與護理措施，下列敘述何者正確？","options":["(A) Cyclophosphamide（Cytoxan）易造成聽神經毒性，因此需監測聽覺功能","(B) Cisplatin（Platinol）易造成出血性膀胱炎，應鼓勵病童多喝水","(C) Methotrexate（MTX）易造成心臟毒性，因此需監測心臟功能","(D) Vincristine（Oncovin）易造成便秘，應視需要依醫囑使用軟便劑"],"answer":3,"image":""},{"id":"nr4-106-1-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"有關接受Port-A導管植入病童的護理措施，下列敘述何者錯誤？","options":["(A) 需限制與導管植入處同側的手臂之活動","(B) 定期以含heparin的生理食鹽水沖洗管路","(C) 注射化療藥物前需先反抽，看有無回血","(D) 插入角針不易回血時，可請病童抬高手臂"],"answer":0,"image":""},{"id":"nr4-106-1-72","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"小明，1個月大，罹患膽道閉鎖，因發燒、呼吸喘、脾腫大而住院治療，接受鼻胃管灌食，每餐灌食量為150 mL，護理師灌食前反抽出胃殘餘量50 mL，下列護理措施何者正確？","options":["(A) 應暫時停止餵食，並通知醫師","(B) 倒掉反抽的胃殘餘量，再灌入150 mL","(C) 將反抽的胃殘餘量灌回，再灌入100 mL","(D) 將反抽的胃殘餘量灌回，再灌入150 mL"],"answer":2,"image":""},{"id":"nr4-106-1-73","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"王小弟，9歲，將進行腸道手術前的清潔灌腸（cleansing enema），下列護理技術之執行，何者正確？","options":["(A) 準備蒸餾水600 mL，溶液溫度為40～43℃","(B) 協助兒童安靜平躺床上後，採右側臥、屈曲雙膝姿勢","(C) 將灌腸筒掛於點滴架上，使液面與兒童肛門距離45～60公分","(D) 請兒童張口深呼吸，潤滑14 Fr.肛管後，推入兒童肛門內7.5公分"],"answer":3,"image":""},{"id":"nr4-106-1-74","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"小芸，1歲半，因罹患克隆氏症（Crohn’s disease）而接受人工結腸造瘻口手術。小芸母親第一次參與學習腸造瘻口居家護理技巧，下列護理措施及指導何者錯誤？","options":["(A) 手術後造瘻口會有暫時性腫脹情形，持續約3～6週後，造瘻口會漸漸縮小開口","(B) 好的造瘻口呈紅色，若呈現黑色或深色，表示可能因扭轉、脫出或黏連造成血液循環不佳","(C) 將保護膜剪成如造瘻口大小或比造瘻口大約0.5公分，貼在造瘻口的周圍皮膚上","(D) 造瘻口黏膜需比周圍皮膚低，以保護周圍皮膚及造瘻口的完整，促進傷口癒合"],"answer":3,"image":""},{"id":"nr4-106-1-75","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"有關沙門氏菌（Salmonella）感染引致的兒童急性腸胃炎，其大便型態之敘述，下列何者正確？","options":["(A) 水樣無臭味","(B) 含膿樣分泌物","(C) 含有黏膜","(D) 含有血絲"],"answer":3,"image":""},{"id":"nr4-106-1-76","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"李小妹，9歲，剛被診斷為惡性腦瘤，母親擔心李小妹知道病情之後會傷心，所以不僅隱瞞病情，還整天面帶笑容，而李小妹卻說：「我這麼不舒服，我媽還笑嘻嘻，她有愛我嗎？」下列護理措施何者較適當？","options":["(A) 鼓勵母親將病情告知李小妹，讓李小妹知道母親很愛她","(B) 鼓勵醫師將病情告知李小妹，讓李小妹知道母親很愛她","(C) 鼓勵母親和李小妹分享彼此的感受，共同面對疾病挑戰","(D) 鼓勵母親和李小妹學習病友的經驗，共同面對疾病挑戰"],"answer":2,"image":""},{"id":"nr4-106-1-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"小華，7歲，搭乘母親的摩托車上學途中，被轎車撞傷，頭部嚴重撞傷，轉入兒科加護病房，現昏迷指數3分，給予疼痛刺激時，手臂和腳均呈僵直和內轉的姿勢，有關這些症狀及受傷部位的描述，下列何者正確？","options":["(A) 呈現去皮質僵直姿勢，延腦功能異常","(B) 呈現去皮質僵直姿勢，腦幹功能異常","(C) 呈現去大腦性僵直姿勢，小腦功能異常","(D) 呈現去大腦性僵直姿勢，中腦功能異常"],"answer":3,"image":""},{"id":"nr4-106-1-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"小敏，出生6天，罹患脊髓脊髓膜膨出，有關其手術後的護理措施，下列敘述何者錯誤？","options":["(A) 觀察神經功能的狀態，以評估腦膜炎徵象","(B) 給予被動運動及按摩，以預防肢體攣縮","(C) 提供安靜與昏暗的環境，以減少視聽覺刺激","(D) 監測哭聲與頭圍，以早期發現合併症"],"answer":2,"image":""},{"id":"nr4-106-1-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"張小弟，罹患腦性麻痺，有咀嚼及吞嚥困難問題，有關幫助其吞嚥的護理措施，下列敘述何者正確？","options":["(A) 頭部維持後仰位置","(B) 食物置於舌頭後方","(C) 肩膀稍微向後傾斜","(D) 保持雙腳自然下垂"],"answer":1,"image":""},{"id":"nr4-106-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"小玲，1歲，診斷為單純性熱性痙攣（simple febrile convulsion），小玲的媽媽詢問護理師：「小玲未來是否會再發作？」有關護理師的回答，下列敘述何者較適當？","options":["(A) 小玲的痙攣與發燒有關，只要避免其發燒，就較不會發作","(B) 小玲的痙攣與年齡有關，只要年紀大於2歲，就較不會發作","(C) 小玲的痙攣與腦波有關，只要腦波檢查正常，以後就不會發作","(D) 小玲的痙攣與缺氧有關，只要維持呼吸道通暢，就較不會發作"],"answer":0,"image":""},{"id":"nr4-106-2-1","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"生產是家庭關係重新開始的重要一環，下列何項醫療院所的政策有助於此理念的推展？","options":["(A) 禁止家庭成員參與生產","(B) 若沒有合併症，提倡早期出院","(C) 為避免感染，嬰兒必須待在嬰兒室","(D) 在完成新生兒點眼藥後再進行第一次母乳哺餵"],"answer":1,"image":""},{"id":"nr4-106-2-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"產科護理師針對護理照顧內容進行討論，並發展及驗證合適的護理措施，藉以提升專業之照護品質，是屬於下列何種角色功能？","options":["(A) 支持者","(B) 教育者","(C) 諮詢者","(D) 研究者"],"answer":3,"image":""},{"id":"nr4-106-2-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"姜女士懷孕12週，最後一次月經（LMP）為民國104年2月25日，懷孕前月經週期均約30天左右，其預產期約在何時？","options":["(A) 104年11月1日","(B) 104年12月2日","(C) 104年10月4日","(D) 105年1月2日"],"answer":1,"image":""},{"id":"nr4-106-2-4","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"有關精液分析檢查的說明，下列何者錯誤？①禁慾3～7天再採檢 ②使用保險套和性交中斷法來收集精液 ③留取精液後2～3小時內送至檢查地點 ④精液必須冷凍保存","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第4題除未作答者不給分外，其餘均給分 (原公告答案 D)"},{"id":"nr4-106-2-5","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"孕期婦女需增加碘的攝取，主要促進胎兒何部分的發育？","options":["(A) 腦部神經發育","(B) 肺泡細胞發育","(C) 腎上腺發育","(D) 腸道細菌叢發育"],"answer":0,"image":""},{"id":"nr4-106-2-6","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"有關胚胎與胎兒的發育，下列敘述何者正確？","options":["(A) 細胞分裂最繁忙、快速的時期為胚胎期","(B) 胚胎發育最容易受外在刺激，而導致畸型的時期為12～16週","(C) 胎兒愈成熟，皮下脂肪和胎毛愈多","(D) 胎兒發育在第6個月開始有吞嚥能力，同時也開始產生胎便"],"answer":0,"image":""},{"id":"nr4-106-2-7","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"胎兒生理活動評估（Biophysical profile）測試內容中以超音波評估的項目包括那些？","options":["(A) 胎兒呼吸、胎動、胎兒身體張力、羊水容積","(B) 胎兒呼吸、臍帶血流量、胎兒體重、羊水容積","(C) 胎兒心跳、胎動、臍帶血流量、胎兒體重","(D) 胎兒心跳、胎動、臍帶血流量、胎兒身體張力"],"answer":0,"image":""},{"id":"nr4-106-2-8","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"有關無壓力試驗（Non-stress test）的敘述，下列何者正確？","options":["(A) 胎心音維持在140下／分、變異性＜5bpm，表示胎心音穩定，為反應型","(B) 若出現20分鐘沒有胎動，則應馬上報告，緊急處理","(C) 若20分鐘有2次以上胎動，胎動時心跳上升15bpm持續15秒，為反應型","(D) 試驗期間約20～30分鐘，孕婦必須平躺以確保紀錄正確"],"answer":2,"image":""},{"id":"nr4-106-2-9","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"有關海洋性貧血的敘述，下列何者錯誤？","options":["(A) 是一種體染色體顯性遺傳疾病","(B) α 型海洋性貧血是第16對染色體控制α 型血球素製造的基因缺損","(C) β 型海洋性貧血是第11對染色體控制β 型血球素製造的基因缺損","(D) 要根治β 型海洋性貧血的唯一方法是骨髓移植"],"answer":0,"image":""},{"id":"nr4-106-2-10","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"5歲小美詢問媽媽：「為什麼妹妹會住在媽媽的肚子裡面，妹妹可以出來和我見面嗎？」護理師給予母親的建議，下列何者最適當？","options":["(A) 小美目前對懷孕尚無法理解，可等她上小學後再給予說明","(B) 小美可能很焦慮，需要媽媽多陪伴她","(C) 小美可能想知道生產過程，可帶她參觀產房","(D) 小美可能對懷孕過程好奇，可用圖畫書說明懷孕過程"],"answer":3,"image":""},{"id":"nr4-106-2-11","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"有關護理師進行新生兒抽吸之敘述，下列何者正確？","options":["(A) 新生兒維持仰臥，頭部抬頭15度","(B) 抽吸管放入口腔時，持續保持壓力抽吸","(C) 抽吸壓力為150～200 mmHg","(D) 過度抽吸會造成新生兒心跳速率減低"],"answer":3,"image":""},{"id":"nr4-106-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"有關生產時會陰消毒原則，下列何者錯誤？","options":["(A) 由陰阜開始往上至下腹部","(B) 由腹股溝內側至大腿前半段","(C) 由肛門口開始至尿道口","(D) 通常採用水溶性優碘"],"answer":2,"image":""},{"id":"nr4-106-2-13","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"下列何者為運用門閾理論來緩解宮縮疼痛不適的措施？","options":["(A) 聽音樂","(B) 溫水淋浴","(C) 尾骶骨按摩","(D) 注意力集中法"],"answer":2,"image":""},{"id":"nr4-106-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"高女士第一胎，待產時子宮收縮每5～7分鐘一次，持續時間30～40秒，強度為輕微～中度，子宮頸口為2～3公分，少許陰道出血，尚未破水，神情顯得愉快。此時適宜的護理指導為何？","options":["(A) 教導經常記得排空膀胱","(B) 教導禁食以防嘔吐","(C) 建議絕對臥床休息，禁止下床走動","(D) 建議施行人工破水以助於胎頭下降"],"answer":0,"image":""},{"id":"nr4-106-2-15","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"高女士已超過預產期3天，醫師建議入院引產，下列敘述何者正確？","options":["(A) 比夏計分（Bishop score）≧6分，引產較可能成功","(B) 使用催產素（oxytocin）會增加排尿量，需觀察輸出入液量","(C) 前列腺素主要是刺激血管平滑肌，促使子宮規律收縮","(D) 若胎位不正時建議採人工破水引產"],"answer":0,"image":""},{"id":"nr4-106-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"產婦於第三產程後，依醫囑施打宮縮藥物（Methergine○R , Ergonovine）。護理師於下列何種情況需停止給藥？","options":["(A) 主訴全身發熱","(B) 血壓150/100 mmHg","(C) 呼吸不規則","(D) 脈搏68～72次／分"],"answer":1,"image":""},{"id":"nr4-106-2-17","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"胎兒預估體重3200公克，胎位（Fetal Position）為枕後位（OP），下列敘述何者正確？①子宮收縮力比較弱 ②第一產程時間較長 ③先露部下降較快 ④子宮頸擴張較慢","options":["(A) ①②","(B) ①③","(C) ②③","(D) ②④"],"answer":3,"image":""},{"id":"nr4-106-2-18","subject":"nr4","topic":"產科-待產與分娩","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"李女士G3P0，已入院待產12小時。她說：「我好想用力哦！」，此時護理師最佳的評估是下列何者？","options":["(A) 先幫妳內診，了解目前狀況是否適合用力","(B) 這是待產正常的感覺，可以側躺比較舒服","(C) 這表示即將要生產了，現在立刻送妳進產房","(D) 現在深吸一口氣，朝著陰道方向用力10秒鐘"],"answer":0,"image":""},{"id":"nr4-106-2-19","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"黃女士G1P1，陰道生產，第一天親子同室時，仔細的觀察新生兒並詢問其外觀特性，此時護理師的反應何者最為適當？","options":["(A) 詢問她對親子同室的看法及新生兒像誰","(B) 儘快教導她如何照顧新生兒及哺餵母乳","(C) 讓她有充分的時間認識及熟悉新生兒","(D) 建議她避免抱新生兒，以免子宮下垂"],"answer":2,"image":""},{"id":"nr4-106-2-20","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"有關母乳哺育的護理指導，下列何者正確？","options":["(A) 成熟乳的後奶較前奶含較多的脂肪內容物","(B) 生理性黃疸是哺乳的禁忌","(C) 初乳含有很多的脂肪，所以熱量很高","(D) 母乳中酪蛋白與乳清蛋白的比例較牛乳高"],"answer":0,"image":""},{"id":"nr4-106-2-21","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"協助產婦產後第一次下床活動，須優先進行何項護理評估？","options":["(A) 生命徵象","(B) 子宮收縮","(C) 小便自解","(D) 乳汁分泌"],"answer":0,"image":""},{"id":"nr4-106-2-22","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"王女士採陰道生產，問護理師：「我什麼時候可以裝子宮內避孕器？」下列回答何者正確？","options":["(A) 產後隨時可以","(B) 產後4～6週","(C) 月經來潮時","(D) 月經來前1週"],"answer":1,"image":""},{"id":"nr4-106-2-23","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"有關產後腸蠕動功能的評估，下列何者錯誤？","options":["(A) 以聽診器在腹部的四個象限評估","(B) 正常的腸蠕動音為每分鐘5至34次","(C) 叩診時出現鼓音表示腸蠕動良好","(D) 產後腹壓減少會減緩腸蠕動"],"answer":2,"image":""},{"id":"nr4-106-2-24","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"林女士採陰道生產，會陰四度裂傷。在產後第2天可以教導她執行何項產後運動？","options":["(A) 膝胸臥式運動","(B) 乳（胸）部運動","(C) 抬腿運動","(D) 仰臥起坐"],"answer":1,"image":""},{"id":"nr4-106-2-25","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"王女士為第二胎，採陰道生產，新生兒體重3980公克，抱怨子宮收縮痛，護理師評估子宮收縮呈堅硬狀態。有關產後痛的說明，下列何者錯誤？","options":["(A) 疼痛是因子宮產生間歇性收縮所致","(B) 經產婦會較初產婦子宮收縮疼痛明顯","(C) 新生兒較大者子宮收縮痛會較明顯","(D) 子宮收縮疼痛感通常會持續3週"],"answer":3,"image":""},{"id":"nr4-106-2-26","subject":"nr4","topic":"產科-產後照護","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"承上題，提供王女士產後痛的護理措施，下列何者為宜？","options":["(A) 教導持續按摩子宮","(B) 下腹部冰敷","(C) 教導深呼吸","(D) 依醫囑給與子宮收縮劑"],"answer":2,"image":""},{"id":"nr4-106-2-27","subject":"nr4","topic":"兒科-生長發展","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"林小妹，出生2個月，體重5公斤，每4小時餵食配方奶一次，請問每次應餵食多少c.c.？","options":["(A) 120","(B) 150","(C) 180","(D) 210"],"answer":1,"image":""},{"id":"nr4-106-2-28","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"有關新生兒呼吸系統之敘述，下列何者錯誤？","options":["(A) 因內在刺激影響主動脈與頸動脈之接受器傳導到呼吸中樞引發呼吸","(B) 陰道生產較剖腹生產的新生兒易發生短暫的呼吸窘迫","(C) 因外在環境溫度刺激傳導到呼吸中樞引發呼吸","(D) 表面張力素可預防肺部塌陷"],"answer":1,"image":""},{"id":"nr4-106-2-29","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"有關女性新生兒生殖器之成熟度評估，下列何者最成熟？","options":["(A) 大陰唇覆蓋陰蒂及小陰唇","(B) 陰蒂及小陰唇均突出","(C) 大陰唇變大及小陰唇變小","(D) 陰蒂突出及小陰唇平坦"],"answer":0,"image":""},{"id":"nr4-106-2-30","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"有關新生兒黃疸的敘述，下列何者正確？","options":["(A) 生理性黃疸於出生24小時內出現，1週左右達到高峰，然後逐漸下降","(B) 多數新生兒黃疸是屬於母乳性黃疸，建議應停餵母奶，改用母乳代用品","(C) 足月兒生理性黃疸發生率低於早產兒發生率","(D) 因Rh或ABO血型不合所發生的溶血，是導致生理性黃疸的主因"],"answer":2,"image":""},{"id":"nr4-106-2-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"有關糖尿病婦女於妊娠期間護理措施之敘述，下列何者正確？","options":["(A) 監測胰島素的需要量，若需要量未隨孕程增加，表示飲食計畫成效佳","(B) 避免夜裡發生高血糖症，睡前點心不可含碳水化合物","(C) 妊娠末期可藉由每週一次無壓力試驗，來確認胎盤功能","(D) 由羊水中卵磷脂與抱合髓磷脂之比值，確認胎兒有無神經管缺損問題"],"answer":2,"image":""},{"id":"nr4-106-2-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"有關孕婦缺鐵性貧血之敘述，下列何者錯誤？","options":["(A) 新生兒出生後採延遲斷臍","(B) 補充鐵劑應於飯前服用以利吸收","(C) 鐵劑可與維生素C同時服用以利吸收","(D) 鼓勵多攝取紅色肉類及深綠色蔬菜"],"answer":1,"image":""},{"id":"nr4-106-2-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"有關妊娠糖尿病的敘述，下列何者錯誤？","options":["(A) 採飲食控制或合併insulin使用","(B) 易發生胎兒畸形或巨嬰","(C) 宜控制糖化血色素在7.5%以下","(D) 孕期高血糖常導致酮酸中毒症"],"answer":2,"image":""},{"id":"nr4-106-2-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"下列何者為嚴重產後出血的徵象？","options":["(A) 收縮壓與舒張壓均下降15 mmHg","(B) 心跳次數為60次／分","(C) 失血超過1000 c.c.","(D) 體溫為100.6℉"],"answer":2,"image":""},{"id":"nr4-106-2-35","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"下列何者為罹患乳癌的高危險群？①長期使用雌激素及黃體激素 ②母乳親餵 ③維持身體質量指數（BMI）於23 ④從未懷孕","options":["(A) ①②","(B) ③④","(C) ①④","(D) ②③"],"answer":2,"image":""},{"id":"nr4-106-2-36","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"有關子宮移位之敘述，下列何者錯誤？","options":["(A) 最常見為前傾","(B) 因骨盆支持結構無力所致","(C) 鼓勵採膝胸臥式","(D) 比較不容易受孕"],"answer":0,"image":""},{"id":"nr4-106-2-37","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"最常導致婦女泌尿道感染的病原體為何？","options":["(A) 大腸桿菌","(B) 白色念珠菌","(C) 梅毒螺旋體","(D) 陰道鞭毛滴蟲"],"answer":0,"image":""},{"id":"nr4-106-2-38","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"有關生殖器疱疹之敘述，下列何者正確？","options":["(A) 大多為第一型單純疱疹病毒","(B) 可以哺餵母奶","(C) 懷孕20週以後感染會造成畸胎","(D) 宜採陰道生產"],"answer":1,"image":""},{"id":"nr4-106-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"晚期子宮頸癌病人接受放射線治療及Cisplatin化學治療後感覺耳鳴及聽力喪失，下列敘述何者錯誤？","options":["(A) 教導病人使用手套或圍巾避免冷的刺激","(B) 嚴重時需降低化學治療藥物劑量","(C) 此症狀為放射線治療導致細胞DNA鍵斷裂","(D) 此症狀為因化學治療而引起的周邊神經性病變"],"answer":2,"image":""},{"id":"nr4-106-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"有關陰道正常分泌物的敘述，下列何者錯誤？","options":["(A) 主要功能是濕潤陰道","(B) 反應陰道生態環境平衡的指標","(C) 又稱為白帶（leukorrhea）","(D) 經期前或孕期時量會減少"],"answer":3,"image":""},{"id":"nr4-106-2-41","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"兒科護理師的角色和功能，下列敘述何者錯誤？","options":["(A) 了解各年齡層兒童的正常生長發育過程","(B) 了解國家對嬰幼兒保健的政策發展","(C) 促進12歲以下兒童的身體健康為主","(D) 依據研究實證結果改善兒童與家庭的照護"],"answer":2,"image":""},{"id":"nr4-106-2-42","subject":"nr4","topic":"兒科-意外事故與急症","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"衛生福利部國民健康署，2013年提倡嬰幼兒健康促進及保護計畫目標，針對1～14歲兒童之目標，期望減少那一項之死亡率？","options":["(A) 兒童重症腸病毒","(B) 先天代謝性異常","(C) 意外事故及傷害","(D) 呼吸系統疾病"],"answer":2,"image":""},{"id":"nr4-106-2-43","subject":"nr4","topic":"兒科-意外事故與急症","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"幼兒長期大量接觸鉛，導致鉛中毒所產生的合併症，下列那一項最為嚴重且會造成不可逆的傷害？","options":["(A) 中樞神經系統病變","(B) 吞嚥困難、腹瀉","(C) 紅血球過多","(D) 呼吸衰竭"],"answer":0,"image":""},{"id":"nr4-106-2-44","subject":"nr4","topic":"兒科-意外事故與急症","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"執行嬰兒心肺復甦術時，下列何者錯誤？","options":["(A) 於兩乳頭連線中央按壓","(B) 使用兩手指進行按壓","(C) 按壓深度約4 cm","(D) 按壓速率約每分鐘100次"],"answer":0,"image":""},{"id":"nr4-106-2-45","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"廷廷，4歲，自前年冬天開始時常出現流鼻血現象，有關流鼻血時的護理指導，下列何者不適合？","options":["(A) 協助維持頭向前傾的姿勢","(B) 鼓勵將鼻血吞下而不要擤出","(C) 捏緊鼻樑加壓約10分鐘","(D) 用冷毛巾敷於鼻樑上協助止血"],"answer":1,"image":""},{"id":"nr4-106-2-46","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"小傑，9歲，罹患先天性心室中膈缺損（VSD），此次利用暑假期間安排到醫院做心導管檢查，檢查後下列何項是小傑最大的壓力源？","options":["(A) 擔心暑假作業寫不完","(B) 擔心不能跟朋友一起玩","(C) 擔心身體受傷及疼痛","(D) 擔心禁食及身體活動受限"],"answer":2,"image":""},{"id":"nr4-106-2-47","subject":"nr4","topic":"兒科-生長發展","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"小銘，2歲6個月，在接受丹佛Ⅱ發展測驗（DDST-Ⅱ）前，護理師向母親解釋進行此測驗的主要目的，除精細及粗動作的評估之外，還包含下列何者？","options":["(A) 氣質及認知發展程度","(B) 記憶及環境適應能力","(C) 性別及自我概念的發展","(D) 社會適應及語言的發展"],"answer":3,"image":""},{"id":"nr4-106-2-48","subject":"nr4","topic":"兒科-生長發展","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"筱華，5歲，在幼兒園吃完午餐時，會模仿老師收拾餐盒，此行為表現依據艾瑞克森（Erikson）的理論，她的發展屬於何階段？","options":["(A) 自主性（autonomy）","(B) 主動進取（initiative）","(C) 勤勉感（industry）","(D) 認同感（identity）"],"answer":1,"image":""},{"id":"nr4-106-2-49","subject":"nr4","topic":"兒科-生長發展","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"李小妹，4歲，在幼兒園上課時，經常是笑口常開，對於新同學與老師、玩具或活動均可以很快地接受，此行為表現為嬰幼兒氣質評估中的那一種項目？","options":["(A) 趨避性","(B) 反應閾","(C) 堅持度","(D) 反應強度"],"answer":0,"image":""},{"id":"nr4-106-2-50","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"為學齡前期兒童執行侵入性治療時，下列護理措施何者錯誤？","options":["(A) 先讓病童認識給予治療的醫護人員","(B) 詳細解釋治療措施或解釋身體功能","(C) 在注射後以膠帶貼住注射部位","(D) 讓病童參與治療措施，給予選擇機會，以增加其自我控制感"],"answer":1,"image":""},{"id":"nr4-106-2-51","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"嬰幼兒疼痛評估，不包括下列那一項？","options":["(A) 臉部表情","(B) 呼吸型態","(C) 肢體動作","(D) 意識程度"],"answer":3,"image":""},{"id":"nr4-106-2-52","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"小維，自然產出生的足月兒。出生後的第二天，小維媽媽親餵母乳時發現小維皮膚呈現深黃色，血液檢驗報告其總膽紅素值（Total Serum Bilirubin）為12 mg/dL。護理師初步的護理評估及判斷為何？","options":["(A) 小維為嚴重的病理性黃疸，需換血治療","(B) 小維可能會有不可逆的核黃疸腦部疾病","(C) 小維有母奶性黃疸，建議停止哺餵母奶","(D) 小維有生理性黃疸，為新生兒常見的問題"],"answer":3,"image":""},{"id":"nr4-106-2-53","subject":"nr4","topic":"兒科-高危險新生兒","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"小萱，出生兩天的早產兒，曾有幾次呼吸暫停的現象，現在小萱的呼吸暫停警鈴響了，下列護理措施何者正確？","options":["(A) 以手掌輕揉背部","(B) 抽吸小萱的口鼻","(C) 提供高濃度氧氣","(D) 直接讓小萱俯臥"],"answer":0,"image":""},{"id":"nr4-106-2-54","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"文華，9歲，罹患淋巴癌末期，目前已轉移至骨頭，主訴右髖骨處很痛，經評估疼痛強度為八分，有關疼痛的護理措施，下列何者較為適當？","options":["(A) 依醫囑給予口服Tinten，並使用冰枕冰敷右髖骨處","(B) 依醫囑給予口服Ibuprofen，並使用熱水袋熱敷右髖骨處","(C) 依醫囑給予肌肉注射Demeral，並按摩右髖骨處","(D) 依醫囑給予靜脈注射Morphine，並以枕頭支托右髖骨處"],"answer":3,"image":""},{"id":"nr4-106-2-55","subject":"nr4","topic":"兒科-高危險新生兒","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"有關協助雙親面對新生兒死亡，下列護理措施何者最適當？","options":["(A) 為避免雙親與新生兒有過度依附，建議雙親在新生兒瀕死前，減少跟新生兒相處時間","(B) 向雙親解釋新生兒如果還活著，可能會有發展遲緩的問題，死亡對新生兒而言比較不受苦","(C) 確保雙親一定要在新生兒死後看他一眼，以減少父母親否認的情緒","(D) 在新生兒瀕死前後，提供雙親機會抱抱自己的新生兒及鼓勵雙親與新生兒說話"],"answer":3,"image":""},{"id":"nr4-106-2-56","subject":"nr4","topic":"兒科-高危險新生兒","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"鐘小弟，妊娠週數31週又5天出生，體重1560公克，現出生後第三天開始由口餵食，下列何者不是他在進食過程中的壓力性行為線索（feeding stress cues）？","options":["(A) 吸不到5分鐘就不吸奶，睡著了","(B) 呼吸喘，且鼻翼煽動，心跳變慢","(C) 嗆奶，咳嗽，膚色改變","(D) 會因為呼吸而中止吞嚥"],"answer":3,"image":""},{"id":"nr4-106-2-57","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"小明為小一學生，日前罹患水痘，校護對於小明返校上課的建議，下列何者適當？","options":["(A) 出疹後5～6天","(B) 疹子化膿後5～6天","(C) 疹子結疤乾燥後7～8天","(D) 使用抗生素後7～8天"],"answer":2,"image":""},{"id":"nr4-106-2-58","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"小明，1歲半，診斷為川崎氏症而住院治療。醫囑給予小明高劑量Aspirin 100 mg/kg/day，及靜脈注射免疫球蛋白（intravenous immune globulin）2g/kg。下列護理指導內容，何者不適當？","options":["(A) 小明目前服用Aspirin為高劑量，目的為抗發炎與抑制血小板凝集","(B) 給予病童換上透氣涼爽衣物，保護下肢水腫處，維持皮膚清潔、乾燥","(C) 注射免疫球蛋白之後3個月，小明就可以接種任何疫苗","(D) 小明半年內至少每個月一次宜接受心電圖檢查，以早期發現心臟合併症"],"answer":2,"image":""},{"id":"nr4-106-2-59","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"下列那一種對象是接種麻疹、腮腺炎、德國麻疹混合疫苗（MMR）的禁忌者？","options":["(A) 1年前曾輸過血者","(B) 靜脈注射高劑量免疫球蛋白11個月以上者","(C) 4個月前肌肉注射B型肝炎免疫球蛋白者","(D) 預備3個月內懷孕的婦女"],"answer":3,"image":""},{"id":"nr4-106-2-60","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"小明，3歲，發燒38.5℃，哭鬧不安，胃口不好，活動力差，至小兒急診求治，診斷為急性鼻咽炎，有關小明的照護措施，何者較不適當？","options":["(A) 鼓勵病童多喝水或果汁及臥床休息","(B) 鼻塞引起的呼吸費力是正常現象，請父母不必擔心","(C) 教導父母注意室內環境的通風，避免飛沫傳染","(D) 教導兒童少用手摸鼻子、嘴巴、眼睛，以降低感染風險"],"answer":1,"image":""},{"id":"nr4-106-2-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"有關兒童罹患黴漿菌性肺炎（mycoplasma pneumonia）的臨床表徵，下列敘述何者正確？","options":["(A) 病程進展非常快速，易出現39℃以上高溫","(B) 常侵犯肺葉及肺小葉，聽診時會有呼氣末期囉音","(C) 咳嗽明顯，痰液黏稠、量多，宜儘速痰液培養","(D) 血清檢查可發現特定的抗體濃度升高，白血球數值可能正常"],"answer":3,"image":""},{"id":"nr4-106-2-62","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"有關學童發生氣喘會出現病理生理上的變化，下列敘述何者錯誤？","options":["(A) 血管通透性下降、細胞浸潤、呼吸道水腫","(B) 顆粒性白血球、淋巴球、單核球細胞增加","(C) 呼吸急促、新陳代謝增加、呼吸性酸中毒","(D) 咳嗽、吐氣時間延長、呼氣末期喘鳴聲"],"answer":0,"image":""},{"id":"nr4-106-2-63","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"廖小妹，2個月，罹患心室中膈缺損，因肺炎引發鬱血性心衰竭（congestive heart failure）而入院，下列那一項不屬於鬱血性心衰竭的臨床表徵？","options":["(A) 心跳過慢","(B) 大量流汗","(C) 四肢冰冷","(D) 呼吸過速"],"answer":0,"image":""},{"id":"nr4-106-2-64","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"凱凱，5歲，罹患法洛氏四重畸形（tetralogy of fallot;TOF），常出現有缺氧發作（blue spells），有關缺氧發作的臨床表徵，不包括下列何者？","options":["(A) 哭泣後出現發紺","(B) 皮膚彈性減少呈黃色","(C) 鞏膜因血管之鼓大呈灰色","(D) 嘴唇口腔黏膜呈現暗藍色"],"answer":1,"image":""},{"id":"nr4-106-2-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"小華，5歲，罹患大血管轉位（transposition of the great arteries;TGA），此次入院準備接受完全矯正手術。基於小華在心臟方面的認知，護理師應採取以下何種解釋方式較為適當？","options":["(A) 因小華對心臟認知不足，主要以父母親對心臟的認知為護理指導的範疇","(B) 畫出人形和心臟的位置，說明手術後心臟會發出較規律清晰的蹦蹦聲","(C) 畫出心臟四個腔室的外形，並解釋手術後心臟會如何把血打出去","(D) 採開放式問題，並儘量口語化來討論靜脈、動脈及血液循環的功能"],"answer":1,"image":""},{"id":"nr4-106-2-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"盼盼，6歲，罹患先天性心臟病，依醫囑服用毛地黃，下列何者不是毛地黃中毒的症狀？","options":["(A) 心跳變慢","(B) 噁心、嘔吐","(C) 頭痛、嗜睡","(D) 抽搐、痙攣"],"answer":3,"image":""},{"id":"nr4-106-2-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"小華，7歲，罹患重度型β-海洋性貧血，定期接受輸血治療，有關其外觀的視診結果，下列敘述何者錯誤？","options":["(A) 體型矮瘦","(B) 膚色蒼白","(C) 塌鼻、頭大","(D) 腹部腫大"],"answer":1,"image":""},{"id":"nr4-106-2-68","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"有關兒童感染人類免疫缺乏病毒（HIV）的途徑，下列何者錯誤？","options":["(A) 由產道接觸到HIV帶原母親的血液及分泌物","(B) 產後經由HIV帶原母親的哺乳","(C) 經由HIV帶原者親吻兒童的臉頰","(D) 輸入被HIV感染的凝血因子"],"answer":2,"image":""},{"id":"nr4-106-2-69","subject":"nr4","topic":"產科-新生兒護理","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"郭小妹，妊娠週數39週又4天，自然產娩出，有關健康新生兒篩檢之時間安排，下列敘述何者正確？","options":["(A) 於出生滿24小時，或已完全由腸道進食12小時後","(B) 於出生滿36小時，或已完全由腸道進食24小時後","(C) 於出生滿48小時，或已完全由腸道進食24小時後","(D) 於出生滿72小時，或已完全由腸道進食12小時後"],"answer":2,"image":""},{"id":"nr4-106-2-70","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"新生兒篩檢之代謝性異常疾病，若未及時治療，下列何者較不會影響智力的發展？","options":["(A) 苯酮尿症","(B) G-6-PD缺乏症（Glucose-6-Phosphate Dehydrogenase）","(C) 半乳糖血症","(D) 先天性甲狀腺功能低下症"],"answer":1,"image":""},{"id":"nr4-106-2-71","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"章小妹，出生3天的足月兒，疑似罹患先天性腎上腺增生症，下列敘述何者錯誤？","options":["(A) 由檢查血中19-KS（19-ketosteroids）的含量做診斷","(B) 從外生殖器的觀察，不易分辨性別","(C) 在早上補充皮質酮治療，以維持正常分泌","(D) 皮質酮治療期間容易出現感染之副作用"],"answer":0,"image":""},{"id":"nr4-106-2-72","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"罹患胰島素依賴型糖尿病（IDDM）的12歲病童，參加營養衛教課，當病童能說出下列何者，表示護理師此次衛教已經成功？","options":["(A) 如果正餐時我不餓，我可以稍後再吃點心","(B) 如果我正餐沒吃完，我就必須馬上補充些醣類的食物","(C) 如果我正餐沒吃完，我需要注射多一點胰島素","(D) 如果我正餐沒吃完，我可以在下一餐時增加些醣類的食物"],"answer":1,"image":""},{"id":"nr4-106-2-73","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"有關嬰兒吞嚥攝食的生理特性，下列敘述何者錯誤？","options":["(A) 新生兒是藉由吸吮反射及吞嚥反射來攝食乳汁","(B) 嬰兒3～4週大時即會嘗試自主控制吞嚥動作","(C) 嬰兒的下食道括約肌較為鬆弛故易有溢奶情形","(D) 嬰兒4個月大時，自發性吸吮反射會消失"],"answer":1,"image":""},{"id":"nr4-106-2-74","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"林小妹，9歲，診斷為闌尾炎（Appendicitis）預進行盲腸切除手術。有關手術前後的護理措施，下列何者正確？","options":["(A) 術前持續評估疼痛型態，必要時給予口服非類固醇止痛劑（NSAID）","(B) 持續腹部評估，若腹部肌肉有不自主收縮而僵硬如木板，疑有腹膜炎的危險","(C) 術前宜禁食由靜脈點滴維持體液，術後試喝水無不適即可恢復進食","(D) 術後若有引流管留置，需採平躺姿位，以利引流及防止感染逆行向上擴散"],"answer":1,"image":""},{"id":"nr4-106-2-75","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"有關先天性的氣管食道瘻管（Tracheoesophageal fistula）嬰兒，進行瘻管關閉及食道吻合術後之照護重點，下列敘述何者錯誤？","options":["(A) 需將嬰兒頭部抬高45～60度，以避免胃容物逆流","(B) 使用安撫奶嘴，以免嬰兒哭泣造成胃腸壓力上升","(C) 若鼻胃管滑脫應立即重新放置，以免胃液損及傷口","(D) 抽吸管的長度不可超越傷口吻合處，避免吻合部位受傷"],"answer":2,"image":""},{"id":"nr4-106-2-76","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"有關輪狀病毒（rotavirus）感染引起的兒童急性腸胃炎，下列敘述何者正確？","options":["(A) 主要藉由飛沫傳染","(B) 糞便棄置前需經漂白水消毒","(C) 需使用抗生素治療","(D) 常併有上呼吸道感染"],"answer":[1,3],"image":"","answer_note":"更正:第76題答Ｂ或Ｄ或BD者均給分。"},{"id":"nr4-106-2-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"有關水腦病嬰接受腦室－腹膜分流術（V-P shunt）後的各項護理，下列敘述何者正確？","options":["(A) 頭圍測量方式：自枕部隆經耳垂至額頭上方","(B) 觀察是否有噴射狀嘔吐或尖銳哭聲的發生","(C) 協助病嬰採水平俯臥，以避免傷口受壓","(D) 避免抱起病嬰餵奶，以防脊髓液引流過快"],"answer":1,"image":""},{"id":"nr4-106-2-78","subject":"nr4","topic":"兒科-意外事故與急症","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"小明，7歲，在練習游泳時，被同學推入泳池中，因溺水而窒息，經救生員急救後，送醫院治療，目前懷疑腦幹及延髓受損，有關小明的呼吸型態，下列何者較可能出現？","options":["(A) 呼吸深且快速（過度換氣型態）","(B) 喘息呼吸與暫停呼吸交替出現（陳施氏呼吸）","(C) 呼吸偶而會出現深且聽得到嘆息聲（喟嘆式呼吸）","(D) 呼吸會出現不規則的穿插呼吸暫停（運動式呼吸）"],"answer":1,"image":""},{"id":"nr4-106-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"小玲，出生3天，診斷為脊髓之脊髓膜膨出且合併有水腦症，有關其手術前的護理措施，下列敘述何者錯誤？","options":["(A) 維持垂頭俯臥姿勢，以利脊髓液回流","(B) 協助其腿部呈外展，以預防髖關節脫位","(C) 選擇質軟小孔的奶嘴餵食，以預防吞食過量空氣","(D) 維持臀部及會陰部乾淨，以減少糞便污染膨出的囊"],"answer":0,"image":""},{"id":"nr4-106-2-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"雷氏症候群（Reye’s syndrome）早期病變的主要徵象為何？","options":["(A) 嘔吐","(B) 去大腦髓質僵直","(C) 反射消失","(D) 過度換氣"],"answer":0,"image":""},{"id":"nr4-107-1-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"有關我國婦嬰生命統計之概況，下列何者正確？","options":["(A) 「粗出生率」是指一年內每千位年中人口數的平均活產數","(B) 「孕產婦死亡率」是指一年內每一萬名婦女中，所有懷孕及生產婦女的死亡人數","(C) 「新生兒死亡率」是以小於一年內的嬰兒死亡人數來估計","(D) 「周產期死亡率」中的周產期，是指生產當日到產後一年內的這段期間"],"answer":0,"image":""},{"id":"nr4-107-1-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"有關臺灣產科護理現況之敘述，下列何者正確？","options":["(A) 「母嬰親善醫院」政策已列入醫院評鑑項目之一","(B) 擁有助產師執照的護理師僅能以單一證照執業登錄","(C) 目前政府有多項鼓勵生育措施，促使產科醫師年輕化且為熱門科別","(D) 孕產婦死亡率有增加的趨勢，主要死因為妊娠糖尿病與多胞胎妊娠"],"answer":0,"image":""},{"id":"nr4-107-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"計算預產期的方法，下列何者正確？","options":["(A) 以LMP估算預產期適用於所有的孕婦","(B) 以超音波估算妊娠週數可得知預產期","(C) 以「腹圍（公分）× 8/7 = 懷孕週數」估算預產期","(D) 以受孕日加上280天估算預產期"],"answer":1,"image":""},{"id":"nr4-107-1-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"有關孕期婦女之生理變化，下列何者為異常？","options":["(A) 臉頰及鼻子產生黃褐斑（chloasma）","(B) 胸部、頸部出現放射狀小紅點，即血管蜘蛛痣（vascular spider nevi）","(C) 心跳速率平均每分鐘增加10～15次","(D) 陰道分泌物量增加，顏色由白色轉為黃綠色"],"answer":3,"image":""},{"id":"nr4-107-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"王女士，孕前BMI值為24，目前懷孕25週，體重較孕前增加3公斤，有關護理師的回應，下列何者較為適當？","options":["(A) 「您體重增加不足，對小孩不好」","(B) 「第二孕期要增加5公斤較適當」","(C) 「您體重增加不足，要增加蛋白質攝取」","(D) 「您體重增加不足，您目前吃的如何？」"],"answer":3,"image":""},{"id":"nr4-107-1-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"有關妊娠期的營養評估與指導，下列何者錯誤？","options":["(A) 國人膳食營養素參考攝取量建議，妊娠期的蛋白質攝取較哺乳期為多","(B) 妊娠期體重過重可能誘發妊娠高血壓或糖尿病","(C) 第一妊娠期每日熱量可不需特別增加","(D) 在妊娠期可不需特別增加維生素K"],"answer":0,"image":""},{"id":"nr4-107-1-7","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"有關拉梅茲生產預備與訓練之原理，下列何者錯誤？","options":["(A) 分散注意之焦點為條件反射訓練","(B) 呼吸技巧反覆訓練以達條件反射之效果","(C) 孕婦具備陣痛因應技巧，可免於害怕、緊張、疼痛的循環","(D) 腹部按摩法利用門閾理論"],"answer":0,"image":""},{"id":"nr4-107-1-8","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"王女士於醫師建議下，於妊娠7週進行超音波檢查，護理師的說明，下列何者不適當？","options":["(A) 妊娠初期的超音波可觀察胚胎個數與著床位置","(B) 妊娠初期做超音波宜喝水脹滿膀胱","(C) 高層次超音波可檢測胎兒妊娠囊","(D) 一般超音波可檢測胎兒心臟的構造與血流"],"answer":3,"image":""},{"id":"nr4-107-1-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"有關妊娠9週的超音波檢查評估項目，下列何者錯誤？","options":["(A) 股骨長度（femur length, FL）","(B) 妊娠囊（gestational sac）","(C) 雙頂徑（biparietal diameter, BPD）","(D) 頭臀長（crown-rump length, CRL）"],"answer":[0,2],"image":"","answer_note":"更正:第9題答Ａ或Ｃ或ＡＣ者均給分。"},{"id":"nr4-107-1-10","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"有關生產過程中子宮肌肉活動的敘述，下列何者錯誤？","options":["(A) 胎兒先露部位壓迫子宮頸口會促進其變薄的程度","(B) 子宮出現生理性收縮環，上段肌肉會變薄","(C) 羊膜腔形成的靜水壓會促進子宮頸口的擴張程度","(D) 宮縮時胎兒軸壓力的形成會促進子宮頸口擴張"],"answer":1,"image":""},{"id":"nr4-107-1-11","subject":"nr4","topic":"產科-產後照護","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"王女士以陰道產娩出一足月男嬰，其第一、五分鐘的Apgar scores分別為7分和8分，新生兒即刻護理已完成，王女士正在進行會陰縫合，有關首次親子互動之時機，下列何者最適當？","options":["(A) 向王女士說明新生兒狀態不穩定，須延後親子接觸時間","(B) 先送新生兒至嬰兒室仔細檢查後，再決定親子接觸時間","(C) 等王女士會陰縫合後，再進行親子接觸","(D) 立即將新生兒放到王女士胸腹部，進行親子接觸 +3"],"answer":3,"image":""},{"id":"nr4-107-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"王女士，懷孕38週，因破水，規則陣痛而入院，子宮頸口開5 cm，先露部位胎頭已固定，下列照護措施何者不適當﹖","options":["(A) 建議可以攝取易消化食物","(B) 臥床時，將床尾抬高","(C) 解尿後，給予會陰沖洗","(D) 可下床活動，無活動禁忌"],"answer":1,"image":""},{"id":"nr4-107-1-13","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"有關硬腦膜外減痛分娩的使用機轉與時間之敘述，下列何者正確？","options":["(A) 麻醉劑需同時注射於硬膜外腔與蜘蛛膜外腔","(B) 進行減痛分娩最佳時機是子宮頸口開1公分時","(C) 減痛分娩主要是阻斷腰部的交感神經","(D) 感覺神經和運動神經皆被阻斷"],"answer":2,"image":""},{"id":"nr4-107-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"下列何者為宮縮時胎心率加速之臨床意義？","options":["(A) 正常現象","(B) 胎頭受壓迫","(C) 胎盤功能不良","(D) 臍帶受壓迫"],"answer":0,"image":""},{"id":"nr4-107-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"下列何者是子宮頸擴張最快的時期？","options":["(A) 減速期","(B) 潛伏期","(C) 過渡期","(D) 最大斜率期"],"answer":3,"image":""},{"id":"nr4-107-1-16","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"有關產婦第二產程之護理措施，下列何者正確？","options":["(A) 抬高腿部以預防血栓靜脈炎","(B) 抬高頭部10至20度以利向下用力","(C) 宮縮間歇期間，提醒產婦放鬆休息","(D) 教導產婦使用肩頸及腹部肌肉力量向下用力"],"answer":2,"image":""},{"id":"nr4-107-1-17","subject":"nr4","topic":"產科-產後照護","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"林女士，29歲，大陸瀋陽人，G1P1，先生為臺商，結婚後來臺居住，產後第一天她抱怨沒有奶水無法餵奶，懷孕生產讓自己變胖變醜，先生過兩天後要回大陸工作，必須獨自一人照顧新生兒而顯擔憂。護理師對其產後調適的評估，下列護理問題何者較不恰當？","options":["(A) 低自尊","(B) 缺乏社會支持","(C) 身體心像改變","(D) 照顧新生兒壓力"],"answer":0,"image":""},{"id":"nr4-107-1-18","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"有關母乳與配方奶差異的敘述，下列何者正確？","options":["(A) 母乳中的乳糖含量較低，嬰兒較不易肥胖","(B) 母乳的鐵質含量比配方奶高，有助嬰兒發育","(C) 母乳的熱量較高，嬰兒較容易有飽足感","(D) 母乳中富含IgA，可增強嬰兒免疫力"],"answer":3,"image":""},{"id":"nr4-107-1-19","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"有關避孕方法原理的敘述，下列何者錯誤？","options":["(A) 保險套能阻止精子進入陰道，而達到避孕效果","(B) 子宮內避孕器會刺激局部產生前列腺素複合物，干擾受精卵著床","(C) 口服避孕藥可使子宮頸黏液變稀，使精子無法順利進入","(D) 男性行輸精管結紮手術後初期，仍需採其他避孕措施"],"answer":2,"image":""},{"id":"nr4-107-1-20","subject":"nr4","topic":"產科-產後照護","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"林女士G2P2，剛餵完奶，皺眉以手扶著腹部，對護理師抱怨較前次產後不舒服，下列回應何者錯誤？","options":["(A) 餵母奶有助惡露排出，且會減輕產後痛","(B) 產後痛在產後初期發生，可能影響睡眠","(C) 經產婦產後痛較初產婦常發生","(D) 適當活動與放鬆技巧可改善"],"answer":0,"image":""},{"id":"nr4-107-1-21","subject":"nr4","topic":"產科-產後照護","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"楊女士剖腹產後第二天開始進食，主訴腹脹不舒服，下列措施何者不恰當？","options":["(A) 鼓勵進食奶製品","(B) 於腹部擦拭薄荷油","(C) 協助產婦下床活動","(D) 依醫囑使用肛門栓劑"],"answer":0,"image":""},{"id":"nr4-107-1-22","subject":"nr4","topic":"產科-產後照護","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"有關陰道生產後評估結果的敘述，下列何者為異常現象？","options":["(A) 產墊上的惡露量少，呈紅色，有血腥味","(B) 會陰傷口輕微紅腫，切開傷口邊緣無分泌物","(C) 在右側可摸到鬆軟且位置偏高的子宮底","(D) 檢查下肢的霍曼式徵象（Homan’s sign）為陰性反應"],"answer":2,"image":""},{"id":"nr4-107-1-23","subject":"nr4","topic":"產科-產後照護","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"黃女士G1P1，產後第三天，主訴乳房觸痛、發熱、變硬且有硬塊，下列護理指導何項正確？","options":["(A) 不用擔心，在24小時內會覺得比較好些","(B) 讓寶寶多吸奶，若吸的不好，應每2～3小時擠奶","(C) 教導餵奶時使用乳頭罩，以減輕乳房觸痛","(D) 儘量減少液體的攝取，以防增加乳房脹痛"],"answer":1,"image":""},{"id":"nr4-107-1-24","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"避孕針劑是利用何種高濃度的荷爾蒙干擾精卵運送及子宮內膜發育？","options":["(A) 動情素","(B) 黃體素","(C) 黃體生成素","(D) 濾泡刺激素"],"answer":1,"image":""},{"id":"nr4-107-1-25","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"新生兒經產道出生，首次呼吸產生之機轉過程，下列敘述何者正確？","options":["(A) 出生時斷臍造成血中二氧化碳分壓降低","(B) 呼吸道的液體受到產道擠壓而全部排出","(C) 當新生兒身體娩出後，胸部反彈形成胸部正壓","(D) 出生後，肺擴張促使呼吸道液體進入微血管"],"answer":3,"image":""},{"id":"nr4-107-1-26","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"出生3天的足月新生兒，出生體重為3,000公克，採純母乳哺餵，下列何項營養評估的結果為異常﹖","options":["(A) 體重為2,500公克","(B) 大便呈現鬆軟、黃綠色","(C) 一天更換三次厚重尿片","(D) 吃飽後，尋乳反射變弱"],"answer":0,"image":""},{"id":"nr4-107-1-27","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"有關新貝拉德（New Ballard Score）新生兒神經肌肉成熟度的評估方法，下列何者正確？","options":["(A) 評估姿勢時，將新生兒採平躺，觀察哭泣時四肢伸展程度","(B) 評估方形窗，將新生兒手腕朝前臂外側屈曲，觀察手腕與前臂之角度","(C) 評估手臂反彈力，將新生兒雙手肘彎曲5秒後，再讓兩手臂伸展放鬆，觀察反彈後肘部角度","(D) 評估圍巾現象，將新生兒手臂儘量拉向對側肩膀到有阻力，觀察手肘與乳頭中線位置關係"],"answer":2,"image":""},{"id":"nr4-107-1-28","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"新生兒先天性代謝異常疾病中，下列何者不是屬於體染色體隱性遺傳疾病？","options":["(A) 苯酮尿症","(B) 楓糖漿尿症","(C) 先天性甲狀腺功能低下症","(D) 先天性腎上腺增生症"],"answer":2,"image":""},{"id":"nr4-107-1-29","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"謝女士懷孕39週，入院待產中，產程進度情形為：子宮頸擴張8 cm，變薄80%，高度為+2，已破水。胎兒監測器圖形顯示胎心率下降至100 bpm，減速的時間與子宮收縮沒一定關係，下列何者為最有可能的情形？","options":["(A) 正常情形","(B) 早期減速","(C) 晚期減速","(D) 變異性減速"],"answer":3,"image":""},{"id":"nr4-107-1-30","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"承上題，下列何者可能為造成上述情形的原因？","options":["(A) 胎頭受壓","(B) 胎盤功能不良","(C) 臍帶受壓","(D) 胎兒感染"],"answer":2,"image":""},{"id":"nr4-107-1-31","subject":"nr4","topic":"產科-產後照護","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"產後婦女使用子宮收縮劑Methergine時，須特別留意下列何項生命徵象？","options":["(A) 體溫","(B) 脈搏","(C) 呼吸","(D) 血壓"],"answer":3,"image":""},{"id":"nr4-107-1-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"楊女士，懷孕8週，陰道點狀出血、腹部微痛，子宮頸口未擴張，其最有可能為下列何種情形？","options":["(A) 脅迫性流產（Imminent abortion）","(B) 先兆性流產（Threatened abortion）","(C) 不完全流產（Incomplete abortion）","(D) 敗血性流產（Septic abortion）"],"answer":1,"image":""},{"id":"nr4-107-1-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"何女士，妊娠29週，突然感到腹部劇烈疼痛，檢查結果為TPR：36.6℃，90次/分，16次/分，BP：140/90 mmHg，胎心音難測得，子宮硬且有壓痛，宮縮60～80 mmHg，無陰道出血或羊水流出。根據何女士的臨床狀況，其可能有下列何項問題？","options":["(A) 急性腹膜炎","(B) 前置胎盤","(C) 胎盤早期剝離","(D) 脅迫性流產"],"answer":2,"image":""},{"id":"nr4-107-1-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"承上題，針對何女士的狀況，下列措施何者較適當？","options":["(A) 依醫囑使用抗生素，以預防感染","(B) 依醫囑提供個案腹部熱敷，以緩解腹部疼痛不適","(C) 依醫囑執行凝血篩檢試驗，以避免產時及產後出血合併症","(D) 依醫囑給予降血壓劑與強心利尿劑，以穩定血液動力"],"answer":2,"image":""},{"id":"nr4-107-1-35","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"下列那些生殖道感染疾病，容易造成女性骨盆腔感染？①披衣菌感染 ②淋病 ③梅毒 ④生殖器疱疹","options":["(A) ①③","(B) ①②","(C) ②③","(D) ②④"],"answer":1,"image":""},{"id":"nr4-107-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"有關以腹腔鏡進行子宮肌瘤切除前後的照護措施，下列何者錯誤﹖","options":["(A) 手術前皮膚準備應清洗肚臍","(B) 手術中應維持頭高腳低臥式","(C) 術後禁食6～8小時即可進食","(D) 術後肩背部疼痛，可給局部按摩"],"answer":1,"image":""},{"id":"nr4-107-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"有關子宮肌瘤處置之敘述，下列何者正確？","options":["(A) 肌瘤切除術後不會有月經","(B) 可服用口服避孕藥以抑制及平衡女性荷爾蒙","(C) 肌瘤切除術後需補充女性荷爾蒙","(D) 全子宮切除術是最好的處置"],"answer":1,"image":""},{"id":"nr4-107-1-38","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"全子宮切除手術之術前腸道準備，下列何者不恰當？","options":["(A) 前三天採低渣飲食","(B) 使用抗生素","(C) 使用瀉劑","(D) 溫水灌腸"],"answer":0,"image":""},{"id":"nr4-107-1-39","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"有關婦女腹部超音波檢查的護理指導，下列何者正確？","options":["(A) 簽署同意書","(B) 服用鎮靜劑","(C) 需排空膀胱","(D) 喝水脹膀胱"],"answer":3,"image":""},{"id":"nr4-107-1-40","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"有關急性骨盆腔炎婦女的照護措施，下列何者錯誤？","options":["(A) 教導應暫停性生活","(B) 大小便後執行會陰灌洗","(C) 協助下床活動","(D) 依醫囑靜脈滴注抗生素"],"answer":1,"image":""},{"id":"nr4-107-1-41","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"依據民國104年修正之「兒童及少年福利與權益保障法」，此法所稱之兒童及少年是指未滿幾歲之人？","options":["(A) 12歲","(B) 14歲","(C) 15歲","(D) 18歲"],"answer":3,"image":""},{"id":"nr4-107-1-42","subject":"nr4","topic":"兒科-意外事故與急症","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"有關燒燙傷之敘述，下列何者錯誤？","options":["(A) 72小時內為急救期，需預防休克","(B) 以大量水沖洗，並除去未沾黏之衣物","(C) 優先給予的輸液為乳酸林格氏液","(D) 若三度燒傷面積大於10%，則為中度燒傷"],"answer":3,"image":""},{"id":"nr4-107-1-43","subject":"nr4","topic":"兒科-生長發展","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"陳小妹，2歲半，在保母家吃飯時，即使弄得到處亂七八糟，仍堅持要自己吃，不要給保母餵，根據艾瑞克森（Erikson）的理論，這個行為表現屬於何種發展任務？","options":["(A) 認同感（identity）","(B) 勤勉感（industry）","(C) 進取心（initiative）","(D) 自主性（autonomy）"],"answer":3,"image":""},{"id":"nr4-107-1-44","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"李小弟，6個月大，醫師開立醫囑為Gentamycin 4.8mg I.V. drip q8h，每毫升（mL）含Gentamycin 40mg，請問護理師每次給藥應該抽多少藥量？","options":["(A) 0.12毫升（mL）","(B) 0.24毫升（mL）","(C) 0.36毫升（mL）","(D) 0.48毫升（mL）"],"answer":0,"image":""},{"id":"nr4-107-1-45","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"兒童的復發性腹痛（recurrent abdominal pain）會具有下列何項特徵？①腹痛會出現在肚臍周圍 ②是一種轉移性的腹痛 ③解出鬆軟的大便 ④腹痛時間是不規律的 ⑤會伴隨體溫升高","options":["(A) ①③④","(B) ①④⑤","(C) ②③⑤","(D) ②④⑤"],"answer":0,"image":""},{"id":"nr4-107-1-46","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"林小弟，出生時，哭聲宏亮大聲，心跳速率：170次/分，軀幹顏色粉紅手腳微發紫，四肢屈曲彈性好，吸取鼻腔黏液時，臉部扭曲，其Apgar score的評估數值何者正確？","options":["(A) 10分","(B) 9分","(C) 8分","(D) 7分"],"answer":2,"image":""},{"id":"nr4-107-1-47","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"陳小妹，妊娠週數39週又5天，自然產及使用真空吸引娩出，頭部受到擠壓而嚴重變形，出生體重3,890公克，在執行身體評估時觸摸其頭部，發現整個頭皮邊緣有水腫且越過骨縫中線，生命徵象穩定，瞳孔大小及對光反射正常，有關陳小妹頭部的創傷問題，下列何者正確？","options":["(A) 產瘤（Caput succedaneum）","(B) 水腦（Hydrocephalus）","(C) 硬腦膜下腔血腫（Subdura hematoma）","(D) 顱內出血（Intracranial hematoma）"],"answer":0,"image":""},{"id":"nr4-107-1-48","subject":"nr4","topic":"兒科-高危險新生兒","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"有關早產兒的臨床表徵，下列何者正確？","options":["(A) 陰囊皺摺多","(B) 腳跟無法觸及耳朵","(C) 手腕彎曲度（方形窗）呈90度","(D) 手肘無法越過對側的鎖骨中線"],"answer":2,"image":""},{"id":"nr4-107-1-49","subject":"nr4","topic":"兒科-意外事故與急症","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"有關誤食毒物對兒童身體器官功能損傷的描述，下列何者正確？","options":["(A) 鉛中毒以肝臟功能受損最嚴重","(B) 鐵劑中毒以泌尿系統受損最嚴重","(C) 碳氫化合物中毒會造成心律不整","(D) 乙醯氨基酚中毒會造成肝、腎衰竭"],"answer":3,"image":""},{"id":"nr4-107-1-50","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"有關為白血病病童輸注紅血球濃縮液（packed RBC）的護理敘述，下列何者錯誤？","options":["(A) 需評估病童在輸血前、輸血開始後15分鐘、輸血完成後之生命徵象","(B) 不可使用生理食鹽水之外的大量點滴來作為輸血管路排氣及沖洗之用","(C) 運用微凝集血液過濾器（micro-aggregatefilter）及輸注幫浦，以維持輸血量5 mL/kg/hr為宜","(D) 輸血時若出現寒顫、心跳過速、不安及發燒等反應，可使用溫血器維持血液溫度在30℃～34℃"],"answer":3,"image":""},{"id":"nr4-107-1-51","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"有關第一型糖尿病（type I diabetes mellitus）的初期臨床表徵，下列敘述何者正確？","options":["(A) 陳施式呼吸","(B) 體重增加","(C) 高血糖及酮酸中毒","(D) 口渴、少尿症狀"],"answer":2,"image":""},{"id":"nr4-107-1-52","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"有關先天性甲狀腺功能低下症（Congenital Hypothyroidism）之敘述，下列何者錯誤？","options":["(A) 是一種自體隱性遺傳的疾病","(B) 早期症狀為新生兒黃疸、生長緩慢、明顯矮小及餵食困難","(C) 若無法及時提供適當甲狀腺素，則可能導致病童心智遲緩","(D) 好發於男性"],"answer":3,"image":""},{"id":"nr4-107-1-53","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"王小弟，10歲，長期服用抗癲癇藥物，應定期檢查的項目，下列何者除外？","options":["(A) 血中藥物濃度","(B) 肝臟功能檢查","(C) 血球數量檢查","(D) 心肺功能檢查"],"answer":3,"image":""},{"id":"nr4-107-1-54","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"有關雷氏症候群（Reye’s syndrome）病童的臨床症狀，下列敘述何者正確？","options":["(A) 血清中的氨濃度降低","(B) 血糖濃度增加","(C) 易形成血栓","(D) 肝功能障礙（SGOT、SGPT高）"],"answer":3,"image":""},{"id":"nr4-107-1-55","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"醫護人員藉由評估嬰幼兒的精細動作，肌肉張力及平衡感等活動，可判斷下列何者之功能？","options":["(A) 脊髓","(B) 延髓","(C) 小腦","(D) 中腦"],"answer":2,"image":""},{"id":"nr4-107-1-56","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"臺灣少子化問題日趨嚴重，因此提升出生率及降低嬰兒死亡率為政府的重要目標，下列那項措施無助於達到上述目標？","options":["(A) 降低法定結婚的年齡","(B) 分析嬰兒死因及死亡率","(C) 提升孕產期醫療照護的品質","(D) 提供優質的托育計畫及補助"],"answer":0,"image":""},{"id":"nr4-107-1-57","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"有關自閉症兒童的特徵，下列敘述何者錯誤？","options":["(A) 語言發展與溝通障礙","(B) 喜歡變化多端的環境","(C) 對感覺刺激有過度或不及的反應","(D) 不易建立親密的人際關係"],"answer":1,"image":""},{"id":"nr4-107-1-58","subject":"nr4","topic":"兒科-意外事故與急症","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"強強，1歲，熟睡時，頭部不慎被熱湯燙傷，以嬰兒九分法計算其燙傷範圍為何？","options":["(A) 9 %","(B) 14 %","(C) 18 %","(D) 27 %"],"answer":2,"image":""},{"id":"nr4-107-1-59","subject":"nr4","topic":"兒科-意外事故與急症","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"小玲，7個月大，因大口吃蒟蒻而噎到，有關其急救處置，下列敘述何者正確？","options":["(A) 於胸部兩乳頭連線中央之下方重擊，執行心外按摩","(B) 採俯臥，跨於施救者手背上，頭低於軀幹，以手掌在嬰兒背後肩胛骨間叩擊5下","(C) 將雙手圍繞嬰兒腰部，以拳頭拇指側向劍突下部位，快速向上重壓","(D) 使平躺，壓額提下巴，罩住其口鼻進行人工呼吸2下後，以手掌進行壓胸15次"],"answer":1,"image":""},{"id":"nr4-107-1-60","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"有關嬰幼兒生命徵象測量的順序，下列何者正確？","options":["(A) 呼吸→脈搏→體溫","(B) 脈搏→呼吸→體溫","(C) 脈搏→體溫→呼吸","(D) 體溫→呼吸→脈搏"],"answer":0,"image":""},{"id":"nr4-107-1-61","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"小玲，5歲，因疝氣預定接受手術治療，為了減輕其手術的焦慮，下列護理措施何者最適宜？","options":["(A) 告訴小玲，另一個女孩與她接受同樣手術的勇敢經過","(B) 說明手術切開的目的，給小玲幾天的時間，好說出她的感受","(C) 拿繃帶、紗布、安全剪刀、膠布與洋娃娃，引導小玲了解治療過程","(D) 請母親避免在小玲面前討論手術事宜，並在醫院寸步不離地陪伴"],"answer":2,"image":""},{"id":"nr4-107-1-62","subject":"nr4","topic":"兒科-高危險新生兒","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"早產兒出生後通常會接受呼吸治療，有關動脈血液氣體數值分析，下列何者屬於正常範圍？","options":["(A) PaO2：70 mmHg，PaCO2：70 mmHg","(B) PaO2：70 mmHg，PaCO2：40 mmHg","(C) PaO2：40 mmHg，PaCO2：70 mmHg","(D) PaO2：40 mmHg，PaCO2：40 mmHg"],"answer":1,"image":""},{"id":"nr4-107-1-63","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"有關罹患甲基丙二酸血症（Methylmalonic Acidemia）的患童，下列敘述何者錯誤？","options":["(A) 是一種有機酸代謝異常的體染色體隱性遺傳疾病","(B) 適時補充葡萄糖靜脈輸液及碳酸鈉，避免酸中毒症狀","(C) 大量甲基丙二酸、丙酸等有機酸堆積會造成楓糖漿尿症","(D) 未治療會造成嚴重的代謝性酸血症、酮酸血症、昏迷"],"answer":2,"image":""},{"id":"nr4-107-1-64","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"小芳，3歲，腦瘤手術住院，媽媽對於小芳7歲的哥哥在學校變得易怒、打同學感到煩心，下列措施何者不適當？","options":["(A) 鼓勵父母觀察小芳的哥哥是否可能承受學校友伴關係的壓力","(B) 與父母討論小芳的哥哥至醫院探訪小芳的可能性","(C) 建議父母直接糾正並處罰小芳哥哥的不當行為","(D) 以玩偶設計引導小芳的哥哥了解小芳住院的原因"],"answer":2,"image":""},{"id":"nr4-107-1-65","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"有關病童死亡的護理措施，下列何者正確？","options":["(A) 給予家屬死亡通知時，避免使用死亡的字眼","(B) 對於病童沾有血跡的衣物留給家屬做紀念","(C) 提供病童資訊時，避免使用醫學術語與家屬溝通","(D) 建議家屬暫時不與病童接觸，以避免家屬過度哀傷"],"answer":2,"image":""},{"id":"nr4-107-1-66","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"有關我國小兒麻痺的傳染及預防方法，下列敘述何者正確？","options":["(A) 臺灣為小兒麻痺流行地區，需常規接種不活化小兒麻痺疫苗（IPV）","(B) 臺灣為小兒麻痺根除地區，2000年之後已不需全面接種小兒麻痺疫苗","(C) 主要藉由糞口途徑傳染，需注意由糞便排出而感染未接種疫苗者","(D) 主要藉由飛沫（口咽）途徑傳染，透過明顯症狀病人之咽喉分泌物傳播"],"answer":2,"image":""},{"id":"nr4-107-1-67","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"罹患中耳炎病童的臨床表徵，下列敘述何者錯誤？","options":["(A) 會有搖頭躁動不安，不斷拉扯耳朵的動作","(B) 長期反覆感染，可能會引起乳突炎（mastoiditis）","(C) 會有狗吠式（barking）咳嗽、哽噎、發紺等現象","(D) 一旦鼓膜破裂，分泌物流出時，疼痛隨即改善"],"answer":2,"image":""},{"id":"nr4-107-1-68","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"有關兒童會厭炎（epiglottitis）的敘述，下列何者錯誤？","options":["(A) 最常見的致病菌是B型流行性感冒嗜血桿菌","(B) 病童會無法平躺，會自動採坐姿，身體呈三腳架姿勢","(C) 協助醫師執行喉頭檢查時，宜備妥經鼻氣管插管的急救設備","(D) 做喉頭細菌培養檢查時，先以壓舌板壓住舌後根，便於採集檢體"],"answer":3,"image":""},{"id":"nr4-107-1-69","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"造成嬰幼兒上呼吸道感染及合併中耳炎的原因，下列敘述何者正確？","options":["(A) 鼻腔狹小","(B) 歐氏管較短，寬且呈水平","(C) 喉頭位於頸部較高處","(D) 舌頭在口腔內所占比例較大"],"answer":1,"image":""},{"id":"nr4-107-1-70","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"小虹，1歲2個月，因細支氣管發炎住院，聽診下肺葉痰音重，醫師囑予combivent蒸氣吸入，及執行胸腔物理治療（CPT）。有關胸腔物理治療注意事項，下列何者正確？","options":["(A) 採用頭低腳高的姿位，進行叩擊","(B) 宜在飯前或飯後30分鐘執行","(C) 每次執行時間約5分鐘","(D) 脊椎突出處宜加強叩擊，以利痰液流出"],"answer":0,"image":""},{"id":"nr4-107-1-71","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"有關胎血循環的血流方向，下列敘述何者正確？","options":["(A) 臍動脈血液流入靜脈導管","(B) 動脈導管血液流入主動脈","(C) 肺靜脈血液流入肺臟","(D) 左心室的血液經卵圓孔流入右心室"],"answer":1,"image":""},{"id":"nr4-107-1-72","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"先天性心臟病的嬰兒常因餵食困難而造成營養攝取不足。有關嬰兒餵食的護理措施，下列敘述何者錯誤？","options":["(A) 選擇小一點的奶嘴洞餵食，避免嗆奶","(B) 可3小時餵食一次，每次不超過30分鐘","(C) 吸吮力欠佳的嬰兒，以奶瓶餵食比親餵母奶佳","(D) 吸吮力欠佳的嬰兒，需要時可以鼻胃管灌食"],"answer":0,"image":""},{"id":"nr4-107-1-73","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"有關心臟病童的藥物使用，下列敘述何者正確？","options":["(A) 應補充鈣片，以增加血紅素載氧量","(B) 使用毛地黃應與食物併用，避免腸胃刺激","(C) 使用PGE1靜脈滴注，要注意呼吸窘迫的問題","(D) 使用Propranolol（Inderal），可能會心跳過速，需監測心跳"],"answer":2,"image":""},{"id":"nr4-107-1-74","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"若注射化學藥物出現紅腫、疼痛及水泡時，有關下列照護及處理步驟，其順序何者正確？①每日追蹤滲漏部位變化 ②以空針反抽滲漏部位的藥物 ③在滲漏部位局部冰敷或熱敷或塗抹藥物 ④停止注射","options":["(A) ④②③①","(B) ④③②①","(C) ②③④①","(D) ③②④①"],"answer":0,"image":""},{"id":"nr4-107-1-75","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"林小弟，5歲，接受化學治療後出現食慾下降、噁心嘔吐且體重減輕。有關護理措施之敘述，下列何者錯誤？","options":["(A) 鼓勵林小弟可共同選擇或準備餐點","(B) 林小弟想吃鮮奶、奶昔，也可以讓他吃","(C) 以卡通樣式作為食物擺盤的依據","(D) 每天都須請林小弟一起測量體重"],"answer":1,"image":""},{"id":"nr4-107-1-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"有關膀胱輸尿管逆流（Vesicoureteral Reflux, VUR），下列敘述何者錯誤？","options":["(A) 膀胱輸尿管逆流易導致腎病症候群","(B) 排尿性膀胱尿道攝影可用來評估膀胱輸尿管逆流等級","(C) 膀胱輸尿管逆流分為五等級，等級愈高，逆流程度愈嚴重","(D) 輕微膀胱輸尿管逆流可使用預防性抗生素治療"],"answer":0,"image":""},{"id":"nr4-107-1-77","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"有關唇裂（cleft lip）與腭裂（cleft palate）之手術後護理，下列敘述何者正確？","options":["(A) 出現不停的吞嚥動作，應評估傷口處是否出血","(B) 採俯臥姿勢，利分泌物流出，避免吸入性肺炎","(C) 啼哭時，以奶嘴安撫，避免縫合處裂開","(D) 拆除縫線前應禁食，避免傷口感染"],"answer":0,"image":""},{"id":"nr4-107-1-78","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"張小妹，9個月大，體重原為9公斤，因腹瀉入院治療。臨床表徵，體重現為8.3公斤、囟門凹陷、皮膚及黏膜乾燥、脈搏增加、少尿，有關脫水程度之評估，下列何者正確？","options":["(A) 輕度脫水","(B) 中度脫水","(C) 重度脫水","(D) 極重度脫水"],"answer":1,"image":""},{"id":"nr4-107-1-79","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"王小弟，4週大，因幽門狹窄（pyloric stenosis）接受幽門切開術（pyloromyotomy）。下列有關護理措施之敘述，何者錯誤？","options":["(A) 術前監測嘔吐物質與量、輸出入量、尿比重","(B) 術前協助矯正嘔吐造成的代謝性鹼中毒","(C) 術後避免餵食過快，常予拍背排氣","(D) 術後餵食，宜採左側平躺方式"],"answer":3,"image":""},{"id":"nr4-107-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"有關妥瑞氏症候群（Tourette's syndrome），下列敘述何者正確？","options":["(A) 發病年齡多在幼兒期","(B) 會出現重複不自主的肢體動作","(C) 易造成腦部傷害及學習困難","(D) 因興奮劑及腦炎而引發症狀"],"answer":1,"image":""},{"id":"nr4-107-2-1","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"依我國「人工生殖法」規定，下列何者錯誤？","options":["(A) 禁止從事代理孕母行為","(B) 未婚者可為受術者","(C) 精卵捐贈不得為四等親內之旁系血親","(D) 男性捐贈生殖細胞者應介於20～49歲之間"],"answer":1,"image":""},{"id":"nr4-107-2-2","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"有關臺灣家庭結構改變的敘述，下列何者錯誤？","options":["(A) 晚婚晚育造成高齡產婦的問題日增","(B) 女性在兼顧家庭與職場的衝突下，易延後適婚年齡","(C) 雙薪家庭的增加及經濟能力的提升，因而提升我國目前的生育率","(D) 離婚造成單親家庭日增，對家庭結構與性別角色造成衝擊"],"answer":2,"image":""},{"id":"nr4-107-2-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"懷孕8週的婦女，經常反覆思考「繼續工作」或「擔任專職母親」，此種心境較屬於下列何種孕期心理反應？","options":["(A) 接受懷孕事實","(B) 注意力集中在自己","(C) 不切實際的幻想","(D) 矛盾心理"],"answer":3,"image":""},{"id":"nr4-107-2-4","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"潛伏期待產婦最可能有的行為反應為何？","options":["(A) 會不自主想要向下用力","(B) 將注意力及能量集中在產痛上","(C) 顯得疲累失去自我控制感","(D) 精力充沛、興奮、有信心接受分娩挑戰"],"answer":3,"image":""},{"id":"nr4-107-2-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"有關雌性素（estrogen）對懷孕早期生殖系統所造成的變化，下列何者錯誤？","options":["(A) 子宮頸長度增加","(B) 產生黏液塞","(C) 陰道黏膜變厚","(D) 子宮壁厚度增加"],"answer":0,"image":""},{"id":"nr4-107-2-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"採全素食之孕婦，容易缺少下列何種營養素？","options":["(A) 維生素B12、鋅、維生素D","(B) 維生素B12、鐵、鋅","(C) 維生素C、維生素B12、鐵","(D) 維生素C、鈣、維生素D"],"answer":1,"image":""},{"id":"nr4-107-2-7","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"針對胎兒胚胎發育成身體各器官及構造中，下列何者是由中胚層發育而來？","options":["(A) 皮膚上表皮","(B) 心臟","(C) 肝臟","(D) 神經組織"],"answer":1,"image":""},{"id":"nr4-107-2-8","subject":"nr4","topic":"產科-高危險妊娠","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"下列何種情況最常利用超音波偵測胎兒臍帶動脈血流，以評估胎兒之生長發育？","options":["(A) 妊娠糖尿病","(B) 妊娠高血壓","(C) 過期妊娠","(D) 紅斑性狼瘡"],"answer":1,"image":""},{"id":"nr4-107-2-9","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"有關海洋性貧血之敘述，下列何者錯誤？","options":["(A) 海洋性貧血屬於體染色體顯性遺傳","(B) 監測平均紅血球體積（MCV）為海洋性貧血篩檢的第一步驟","(C) 若夫妻為同一型的帶因者，則孕婦可接受羊膜穿刺以利產前診斷","(D) 若夫妻為同一型的帶因者，胎兒可能罹患重型海洋性貧血的機會是1/4"],"answer":0,"image":""},{"id":"nr4-107-2-10","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"有關第一孕期唐氏症篩檢的敘述，下列何者錯誤？","options":["(A) 檢測項目包括母血的β-hCG與妊娠關聯之血漿蛋白A（PAPP-A）以及超音波掃描測量胎兒頸部透明帶厚度","(B) 若胎兒頸部透明帶厚度大於6毫米，則可懷疑唐氏症或其他染色體異常","(C) 此項母血篩檢可提早至妊娠11～14週左右執行","(D) 唐氏症四指標篩檢的正確偵測率為50%"],"answer":3,"image":""},{"id":"nr4-107-2-11","subject":"nr4","topic":"產科-孕期生理與評估","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"有關妊娠期婦女甲狀腺分泌功能變化的敘述，下列何者正確？","options":["(A) 妊娠期婦女基礎代謝率增加，甲狀腺素（thyroxine, T4）的分泌會受到抑制","(B) 妊娠期甲狀腺功能亢進的婦女，易發生自發性流產","(C) 甲狀腺結合血清蛋白平均值在第二妊娠期達到最高","(D) 妊娠期甲狀腺素值會升高，但三碘甲狀腺素（triiodothyronine, T3）值則下降"],"answer":2,"image":""},{"id":"nr4-107-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"子宮生理性收縮環在肌肉上的變化為何？","options":["(A) 子宮上段變薄，下段變厚","(B) 子宮上段變薄，下段沒有變化","(C) 子宮上段變厚，下段變薄","(D) 子宮上段沒變化，下段變薄"],"answer":2,"image":""},{"id":"nr4-107-2-13","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"王女士G2P1，在待產活動期時接受腰椎硬膜外麻醉，護理師發現王女士的血壓突然降低，下列護理措施何者最不適宜？","options":["(A) 增加靜脈輸液輸入量","(B) 協助採左側躺","(C) 評估胎心率狀況","(D) 評估子宮收縮情況"],"answer":3,"image":""},{"id":"nr4-107-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"楊女士目前子宮頸口全開且完全變薄，當子宮收縮時感到非常疼痛。有關此時生產疼痛的主要來源，下列何者正確？","options":["(A) 疼痛來自於子宮韌帶的伸張，陰道及會陰肌肉的伸展","(B) 疼痛位置主要在下腹部及下背部","(C) 疼痛來自於子宮體下段伸展及宮縮肌肉細胞缺氧","(D) 疼痛的神經衝動由T10～L1傳導進入脊髓"],"answer":0,"image":""},{"id":"nr4-107-2-15","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"陳女士待產時感到疼痛不安並要求止痛藥物，護理師依醫囑給與meperidine（demerol）50mg肌肉注射，下列護理措施何者較不適宜？","options":["(A) 告知產婦藥物的常見副作用，包括尿滯留、噁心、嘔吐等","(B) 觀察產婦的頭暈嗜睡狀況，確保使用床欄","(C) 每小時監測陰道出血情形","(D) 密切監測胎心率的變異性"],"answer":2,"image":""},{"id":"nr4-107-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"自然產的胎頭娩出後將進入下列何項分娩機轉？","options":["(A) 下降（decent）","(B) 外迴轉（external rotation）","(C) 屈曲（flexion）","(D) 伸展（extension）"],"answer":1,"image":""},{"id":"nr4-107-2-17","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"陳女士G2P0獨自來待產，下列何種情況需立即通知醫師？","options":["(A) 主訴先生在外島工作，一直哭泣","(B) 宮縮時胎心率為110～120 bpm","(C) 破水2小時內，無規則性宮縮","(D) 宮縮間歇時的壓力為50 mmHg"],"answer":3,"image":""},{"id":"nr4-107-2-18","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"王女士第一胎，目前子宮頸開6公分，當宮縮時，閉眼睛不理人，下列何種護理措施較不適當？","options":["(A) 引導放鬆呼吸技巧","(B) 提供音樂分散注意力","(C) 手握產婦雙手陪伴在旁","(D) 提供止痛藥或麻醉劑訊息以供選擇"],"answer":3,"image":""},{"id":"nr4-107-2-19","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"當待產婦使用PGE2陰道栓劑後，護理師需要監測下列何種變化？","options":["(A) 子宮頸平滑肌收縮","(B) 胎兒肺部成熟","(C) 子宮頸軟化成熟","(D) 子宮頸水腫"],"answer":2,"image":""},{"id":"nr4-107-2-20","subject":"nr4","topic":"產科-產後照護","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"張女士G2P2，陰道生產後第2天，向護理師表示：「餵母奶時，我的肚子會痛！」。下列護理指導何者適宜？","options":["(A) 2星期後疼痛情況就會改善","(B) 因母乳哺餵造成泌乳激素分泌而引起","(C) 適當活動可以改善疼痛","(D) 先停止母乳哺餵以緩解疼痛"],"answer":2,"image":""},{"id":"nr4-107-2-21","subject":"nr4","topic":"產科-產後照護","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"陰道生產剛結束的婦女若有尿瀦留的現象，最主要的原因為何？","options":["(A) 膀胱內括約肌收縮","(B) 胎兒通過產道時壓迫膀胱","(C) 產後雌性素濃度增加所致","(D) 第一節薦椎神經受損"],"answer":1,"image":""},{"id":"nr4-107-2-22","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"有關結紮手術之敘述，下列何者正確？","options":["(A) 女性結紮可於產後24～48小時內實施","(B) 女性結紮後不會再製造卵子","(C) 男性結紮後立即有避孕效果","(D) 男性結紮後容易有腹腔沾黏的情形"],"answer":0,"image":""},{"id":"nr4-107-2-23","subject":"nr4","topic":"產科-產後照護","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"楊女士產後第10天，仍有輕微足踝水腫情形，其他的生理徵象均正常，護理師給予的指導何者最適宜？","options":["(A) 採低鹽飲食","(B) 穿緊縮的襪子促進血液回流","(C) 坐著時不要交叉雙腿","(D) 多臥床休息，並減少活動"],"answer":2,"image":""},{"id":"nr4-107-2-24","subject":"nr4","topic":"產科-產後照護","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"有關產後性行為（sexual intercourse）的護理指導，下列敘述何者最適當？","options":["(A) 建議惡露乾淨與會陰傷口癒合後才有性行為","(B) 母乳哺餵的母親因泌乳激素較高易導致陰道乾燥","(C) 產後陰道潤滑性減少，可用脂溶性潤滑劑促進潤滑","(D) 因會陰傷口復原之需要，故產後八週後才能有性行為"],"answer":0,"image":""},{"id":"nr4-107-2-25","subject":"nr4","topic":"產科-產後照護","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"有關REEDA評估會陰切開傷口的內容，下列何者正確？","options":["(A) R為Redness，發紅","(B) E為Edege，邊緣","(C) D為Drain，引流","(D) A為Abscess，膿瘍"],"answer":0,"image":""},{"id":"nr4-107-2-26","subject":"nr4","topic":"產科-產後照護","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"下列何者為產後霍曼氏徵象（Homan’s sign）的評估方式？","options":["(A) 以兩手食指水平對稱下壓乳房，從乳暈處向上、下牽拉，再向左、右牽拉，檢查乳頭是否突出","(B) 一手支托膝膕，另一手置於腳掌將其足部向背側屈曲，腓腸肌有無疼痛感","(C) 將大腿靠近腹部，足底靠近臀部，伸直後再放回床面，大腿前側有無疼痛感","(D) 雙膝彎曲，雙腳平放，兩手支托雙膝移向左側，再向右側，腰部是否疼痛"],"answer":1,"image":""},{"id":"nr4-107-2-27","subject":"nr4","topic":"產科-產後照護","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"劉女士第一胎，依據魯賓（Rubin）對產後婦女行為態度之研究結果判斷，下列敘述何者表示劉女士處於接受期（taking-in phase）？","options":["(A) 寶寶為什麼一直睡覺？","(B) 我要怎麼樣才能讓奶水量增加？","(C) 生小孩好痛，下次再也不要生了","(D) 我的先生晚上照顧寶寶，現在他很累"],"answer":2,"image":""},{"id":"nr4-107-2-28","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"有關新生兒出生2～6小時過渡期常出現的生理現象，下列何者異常？","options":["(A) 心跳及呼吸速率變化大","(B) 腸蠕動增加","(C) 解胎便","(D) 黃疸出現"],"answer":3,"image":""},{"id":"nr4-107-2-29","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"有關新生兒黃疸之敘述，下列何者正確？①黃疸最先出現於額頭 ②黃疸症狀漸漸由頭往下，由身體中心向外發展至四肢 ③新生兒出生第3天血中膽紅素大於14 mg/dL，不需處理 ④可輕壓鼻尖觀察皮膚黃疸的情形 ⑤新生兒黃疸照光應保護眼睛與生殖器","options":["(A) ①②⑤","(B) ②③⑤","(C) ①④⑤","(D) ②④⑤"],"answer":3,"image":""},{"id":"nr4-107-2-30","subject":"nr4","topic":"兒科-高危險新生兒","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"有關新生兒神經成熟度評估之描述，下列何者是早產兒的特徵？","options":["(A) 四肢表現出高張性屈曲","(B) 方形窗徵象角度為0度","(C) 腳跟無法拉到耳朵","(D) 手肘可以超過身體中線"],"answer":3,"image":""},{"id":"nr4-107-2-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"有關子宮外孕之敘述，下列何者錯誤？","options":["(A) 血中hCG濃度有上升情形","(B) 臨床處置只能採腹腔鏡手術","(C) 出血時易有腹痛情形","(D) 主要好發於輸卵管壺腹部"],"answer":1,"image":""},{"id":"nr4-107-2-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"有關硫酸鎂（MgSO4）在安胎使用的敘述，下列何者錯誤？","options":["(A) 需監測尿量","(B) 用藥過量時可能抑制深部肌腱反射","(C) 可利用生化檢驗監測血中濃度","(D) 血中濃度過高可使用halothan拮抗"],"answer":3,"image":""},{"id":"nr4-107-2-33","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"以比夏計分法（Bishop’s score）評估產婦引產的難易度，下列何者錯誤？","options":["(A) 子宮頸擴張","(B) 胎兒體重","(C) 胎頭位置","(D) 子宮頸堅硬度"],"answer":1,"image":""},{"id":"nr4-107-2-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"有關評估32週妊娠糖尿病孕婦過去一個月間血糖控制之成效，下列何項檢測最佳？","options":["(A) 飯前空腹血糖值是否均在正常範圍內","(B) 飯後一小時之血糖值是否均在正常範圍內","(C) 糖化血色素值是否均在正常範圍內","(D) 胎兒體重的變化，是否能維持在妊娠週數之50百分位"],"answer":2,"image":""},{"id":"nr4-107-2-35","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"正在接受第2次腹腔內化學治療的卵巢癌病人，主訴一直覺得噁心，下列回應何者最適當？","options":["(A) 「噁心是化學治療副作用之一，過幾天就會好了」","(B) 「我了解您的心情，聽說吃人蔘可緩解噁心，您要不要試試看」","(C) 「噁心是最輕微的副作用之一，接下來還有其他的副作用會出現」","(D) 「少量多餐，攝取高熱量、高蛋白質飲食可逐漸減緩噁心的現象」"],"answer":3,"image":""},{"id":"nr4-107-2-36","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"有關女陰癌之敘述，下列何者正確？","options":["(A) 是臺灣女性較常見之生殖器官惡性腫瘤之一","(B) 早期病變不明顯常被忽略","(C) 第一期以放射線治療為主","(D) 以基底細胞癌居多"],"answer":1,"image":""},{"id":"nr4-107-2-37","subject":"nr4","topic":"產科-待產與分娩","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"王女士第一胎，目前在第一產程的過渡期，隨著越來越密集的字宮收縮，王女士顯得很焦慮不安。在床邊陪伴的王先生詢問護理師：「我的太太很不舒服，我也不知道怎麼幫忙，我最好到產房外面等待？」，此時護理師最適當的回答為何？","options":["(A) 「這個時候王太太最需要你，你怎麼可以離開呢？」","(B) 「因為你的擔心會干擾生產，你最好到外面休息。」","(C) 「我知道你的壓力很大，我們一起來幫忙王太太好嗎？」","(D) 「我知道陪產很辛苦，你確實需要好好休息，寶寶出生後再告訴你。」"],"answer":2,"image":""},{"id":"nr4-107-2-38","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"常導致愛滋病患肺部感染的病原體為何？","options":["(A) 肺炎鏈球菌","(B) 黴漿菌","(C) 結核桿菌","(D) 肺囊蟲"],"answer":3,"image":""},{"id":"nr4-107-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"朱女士，29歲，主訴上週做過流產手術，因發燒和下腹部壓痛前來就診，內診時見子宮頸有膿狀分泌物，細菌培養結果為淋病雙球菌、披衣菌和黴漿菌感染，最有可能的診斷為何？","options":["(A) 子宮外孕","(B) 巴氏腺囊腫","(C) 卵巢囊腫","(D) 骨盆腔炎"],"answer":3,"image":""},{"id":"nr4-107-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"下列何種治療方式，最常用在子宮頸糜爛時的治療？","options":["(A) 電燒灼術","(B) 冷凍治療","(C) 雷射手術","(D) 子宮內膜破壞術"],"answer":1,"image":""},{"id":"nr4-107-2-41","subject":"nr4","topic":"兒科-生長發展","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"下列何者是丹佛嬰幼兒發展篩檢測驗II ( DDST II )的評估項目之一？","options":["(A) 對於新事物的趨避性","(B) 對物體恆存的概念","(C) 遇到挫折的容忍度","(D) 語言與社會適應力"],"answer":3,"image":""},{"id":"nr4-107-2-42","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"有關瀕死兒童的呼吸與心臟血管生理反應，下列敘述何者錯誤？","options":["(A) 會出現陳施式呼吸或喟嘆式呼吸","(B) 喉頭肌肉緊縮，可自行將分泌物咳出","(C) 四肢末梢脈搏變弱且不易觸診","(D) 皮膚濕冷、蒼白、四肢發紺"],"answer":1,"image":""},{"id":"nr4-107-2-43","subject":"nr4","topic":"產科-新生兒護理","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"張太太懷孕30週，因早期破水產下重2,400公克女嬰，其體重與妊娠週數的關係屬於：","options":["(A) LGA：大於妊娠週數應有體重","(B) AGA：體重符合妊娠週數","(C) SGA：小於妊娠週數應有體重","(D) VLBW：非常低出生體重"],"answer":0,"image":""},{"id":"nr4-107-2-44","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"琳琳，9個月大，因細支氣管合併肺炎再度住院，醫囑需要胸腔物理治療，有關協助家屬進行出院準備，下列護理指導何者正確？","options":["(A) 示範家人如何確認痰堆積部位，先進行姿位引流再行噴霧治療","(B) 確定痰液堆積部位後，每個姿位宜連續姿位引流約15〜30分鐘","(C) 過程中若琳琳出現呼吸窘迫、躁動不安等現象，仍可繼續執行","(D) 最佳的姿位引流時間，宜安排在飯前1小時或飯後2小時執行"],"answer":3,"image":""},{"id":"nr4-107-2-45","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"為嬰幼兒進行胸腔物理治療的叩擊（percussion）時，下列何項步驟不適當？","options":["(A) 叩擊宜在姿位引流後執行，以達更佳效果","(B) 以手指併攏、弓為杯狀，規律地叩擊胸壁","(C) 為達鬆動痰液的較佳效果，可直接拍擊病童裸露的皮膚","(D) 每部位的叩擊時間建議約為1～2分鐘，可視病童情況而增減"],"answer":2,"image":""},{"id":"nr4-107-2-46","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"鐮狀細胞貧血（sickle cell anemia）病童不會出現下列何項臨床表徵？","options":["(A) 顱骨變大、顴骨隆起","(B) 末端肢體腫脹與疼痛","(C) 視網膜病變以致失明","(D) 肝、脾腫大"],"answer":0,"image":""},{"id":"nr4-107-2-47","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"小玉，罹患先天性甲狀腺功能低下（congenital hypothyroidism），長期服用甲狀腺藥物，下列何者不是甲狀腺毒性反應之症狀？","options":["(A) 心跳減緩","(B) 腹瀉","(C) 呼吸困難","(D) 痙攣"],"answer":0,"image":""},{"id":"nr4-107-2-48","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"協助罹患腦瘤病童之家庭正向因應疾病時，下列護理照護何者較不適當？","options":["(A) 評估病童及家屬對診斷治療及預後的了解程度","(B) 教導病童及家屬評估病童的神經功能、腦壓上升及感染之徵象","(C) 教導家屬評估病童在生長發展技能上的情形","(D) 避免讓病童知道疾病情況，以免焦慮與緊張"],"answer":3,"image":""},{"id":"nr4-107-2-49","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"婷婷，9個月大，體重9公斤，母親主訴最近一天解水便數次，現體重為8公斤，此屬於下列何種情況？","options":["(A) 正常體液流失","(B) 輕度脫水","(C) 中度脫水","(D) 重度脫水"],"answer":3,"image":""},{"id":"nr4-107-2-50","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"小珊，10個月大，因中耳炎合併熱性痙攣住院治療，下列護理措施何者正確？","options":["(A) 定時給與退燒劑，將體溫控制於攝氏38度即可","(B) 小珊發作後有嗜睡情形，故應協助其適當休息","(C) 必須終身服用抗痙攣藥物，以免造成腦部傷害","(D) 小珊並非全身性發作，所以不必使用床欄護墊"],"answer":1,"image":""},{"id":"nr4-107-2-51","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"10歲的阿偉出現發燒、頭痛、頸背僵硬等症狀，經評估有腦膜炎徵象，下列何者不是腦膜炎的徵象？","options":["(A) 歐氏徵象（Ortolani’s sign）","(B) 柯林氏徵象（Kernig’s sign）","(C) 布魯辛斯基氏徵象（Brudzinski’s sign）","(D) 角弓反張（opisthotonic）"],"answer":0,"image":""},{"id":"nr4-107-2-52","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"幼年型類風濕性關節炎兒童的護理措施，下列敘述何者正確？","options":["(A) 評估身體外觀有無異常出血點、關節皮膚冰冷蒼白情形","(B) 清晨易有關節僵硬疼痛，可以熱敷及止痛藥減輕不適","(C) 宜鼓勵多臥床休息，以改善肌無力、預防關節攣縮情形","(D) 類固醇及免疫抑制劑為最常用的長期治療藥物"],"answer":1,"image":""},{"id":"nr4-107-2-53","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"在嬰幼兒期自閉症的症狀表現，易與下列何種障礙混淆？","options":["(A) 味覺障礙","(B) 肢體障礙","(C) 聽覺障礙","(D) 觸覺障礙"],"answer":2,"image":""},{"id":"nr4-107-2-54","subject":"nr4","topic":"兒科-意外事故與急症","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"根據兒童及少年福利與權益保障法（2015），醫事人員發現兒童遭受猥褻行為或性交，需於多久時間內通報主管機關？","options":["(A) 24小時內","(B) 48小時內","(C) 72小時內","(D) 一週內"],"answer":0,"image":""},{"id":"nr4-107-2-55","subject":"nr4","topic":"兒科-意外事故與急症","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"陳小妹，2歲，12公斤，被人從火場中救出，全身30%的部分皮層燒傷，至今已過1小時，現以靜脈輸液幫浦提供輸液，輸液的速度每小時應為幾mL？","options":["(A) 60 mL","(B) 69 mL","(C) 90 mL","(D) 103 mL"],"answer":3,"image":""},{"id":"nr4-107-2-56","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"小倫，1個月大，接種B型肝炎疫苗。下列何者是適合肌肉注射的部位？","options":["(A) 左上臂三角肌中央","(B) 腹直肌","(C) 股外側肌","(D) 腹臀肌"],"answer":2,"image":""},{"id":"nr4-107-2-57","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"小華，2歲，護理師在給與左耳用藥時，下列護理措施何者正確？","options":["(A) 給藥前向右側呈半側臥姿","(B) 給藥前將耳垂往上往後輕拉","(C) 給藥時直接滴於鼓膜上","(D) 給藥後以棉棒塞住小華耳道"],"answer":0,"image":""},{"id":"nr4-107-2-58","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"惠惠，4歲，護理師預計在30分鐘內完成2c.c.的抗生素靜脈滴注，目前以每小時60c.c.的速度接受靜脈輸液，應該如何處置？","options":["(A) 加在58 c.c.輸液中維持60 gtt./min","(B) 加在28 c.c.輸液中維持60 gtt./min","(C) 加在38 c.c.輸液中維持40 gtt./min","(D) 加在58 c.c.輸液中維持30 gtt./min"],"answer":1,"image":""},{"id":"nr4-107-2-59","subject":"nr4","topic":"兒科-生長發展","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"運用感官對事物所得的心像來了解世界，但卻仍不能以質量保留以及長度保留來認知事物，此兒童之認知發展處於：","options":["(A) 感覺動作期","(B) 運思前期","(C) 具體運思期","(D) 形式運思期"],"answer":0,"image":""},{"id":"nr4-107-2-60","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"為1歲兒童測量生命徵象，下列敘述何者正確？","options":["(A) 呼吸、脈搏均需測量完整一分鐘","(B) 體溫測量以量口溫為佳","(C) 壓脈帶的寬度應為上臂的1/3長度","(D) 橈動脈是測量脈搏常使用的部位"],"answer":0,"image":""},{"id":"nr4-107-2-61","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"小美，6個月大，由媽媽抱來接種五合一疫苗，下列護理措施何者適當？","options":["(A) 利用布偶及空針，說明即將注射的程序","(B) 注射後請媽媽擁抱，並提供安撫奶嘴","(C) 注射時盡可能的緩慢推注藥劑","(D) 注射後，部位貼上小膠布"],"answer":1,"image":""},{"id":"nr4-107-2-62","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"兒童在瀕死過程中，出現呼吸逐漸由深變淺時，下列護理措施何者正確？","options":["(A) 避免給與止痛藥，以防呼吸抑制","(B) 出現臨終嘎聲時可抬高頭部或採側臥","(C) 提供昏暗的環境，以減少光線刺激","(D) 嚴格限制絕對臥床休息，避免任何活動"],"answer":1,"image":""},{"id":"nr4-107-2-63","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"有關罹患先天性梅毒的嬰兒皮膚丘疹及脫屑的護理措施，下列何者不適當？","options":["(A) 接觸個案時需穿著隔離衣及戴手套","(B) 鼓勵家人探視，但避免觸摸或擁抱","(C) 皮膚丘疹及脫屑部位可予以嬰兒油塗敷","(D) 評估是否有皮膚丘疹造成的不適或乾燥"],"answer":1,"image":""},{"id":"nr4-107-2-64","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"小鳴，6個月大，腋下、鼠蹊、頸部長出膿皰後結痂脫屑，求醫確診為膿皰病，下列處置何者不適當？","options":["(A) 因膿皰病具高度傳染力，避免清洗患部及引流膿皰","(B) 依醫囑局部塗抹新黴素（neomycin）抗生素藥膏","(C) 協助患嬰清潔及剪短指甲，以保護患處被抓破","(D) 指導照顧者適當隔離、維持清潔，預防感染"],"answer":0,"image":""},{"id":"nr4-107-2-65","subject":"nr4","topic":"兒科-高危險新生兒","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"高危險新生兒常易出現呼吸窘迫症候群（RDS），下列敘述何者錯誤？","options":["(A) 呼氣時出現咕嚕聲（expiratory grunting）","(B) 肺泡缺乏表面張力素，而使肺泡塌陷","(C) 嚴重者兩側肺部X-ray檢查呈現出毛玻璃樣之影像","(D) 容易有呼吸性鹼中毒"],"answer":3,"image":""},{"id":"nr4-107-2-66","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"綺綺，3歲，罹患急性白血病，近日因出現疼痛問題而住院，有關疼痛評估的敘述，下列何者正確？","options":["(A) 以0～10分的數字量表，使其選擇疼痛分數","(B) 表達疼痛常見的敘述字句，如刺痛、鈍痛、悶痛等，給予選擇","(C) 以哭泣到高興的臉譜量表，使其挑選能代表自己疼痛的臉譜","(D) 以簡單描述量表，使其選擇最適合他感覺疼痛狀態的字詞"],"answer":2,"image":""},{"id":"nr4-107-2-67","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"有關德國麻疹（German measles）的護理指導及處置，下列何者正確？","options":["(A) 體溫及症狀變化於年紀愈小兒童愈明顯","(B) 粉紅色斑丘疹通常由四肢開始出現","(C) 出疹後即不需採接觸防護隔離","(D) 第一孕期婦女應與德國麻疹隔離"],"answer":3,"image":""},{"id":"nr4-107-2-68","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"有關嬰兒玫瑰疹（roseola infantum），下列何者錯誤？","options":["(A) 熱痙攣是常見合併症","(B) 常在退燒後開始發疹，由軀幹開始擴散至四肢","(C) 需要呼吸道隔離至出疹後四天","(D) 感染後可終身免疫"],"answer":2,"image":""},{"id":"nr4-107-2-69","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"有關急性細支氣管炎的敘述，下列何者正確？","options":["(A) 是學齡期兒童常見的上呼吸道感染","(B) 最常見的致病因是細菌感染","(C) 主要傳染途徑為接觸傳染，需採取隔離措施","(D) 呼吸困難嚴重之病童，會出現呼吸性酸中毒現象"],"answer":3,"image":""},{"id":"nr4-107-2-70","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"兒童的呼吸道系統由於尚未完全發展成熟，而與成人有差異，下列何者正確？","options":["(A) 嬰兒喉頭在頭部較低處，約在第5～6頸椎處，易造成吸入性肺炎","(B) 嬰兒會厭軟骨較成人短且有彈性，較不易嗆到","(C) 嬰兒肋骨位置較成人垂直，穩定性小，故較少利用腹式呼吸","(D) 嬰幼兒的歐氏管（耳咽管）較成人短、寬且直，呈水平位置，較易使致病菌或異物入侵"],"answer":3,"image":""},{"id":"nr4-107-2-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"持續靜脈灌注前列腺素E1（PGE1）可維持動脈導管開放，增加肺動脈血流。下列何種先天性心臟病，不適合使用PGE1治療？","options":["(A) 肺動脈瓣狹窄","(B) 主動脈狹窄","(C) 三尖瓣閉鎖","(D) 大血管轉位"],"answer":1,"image":""},{"id":"nr4-107-2-72","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"有關罹患心臟病嬰兒服用毛地黃的護理指導，下列何者正確？","options":["(A) 家中應備聽診器，服用前量心尖脈，至少測量30秒","(B) 心跳如果高於120下/分鐘，可能是毛地黃中毒的症狀，需盡速就醫","(C) 發生噁心嘔吐時，可能是中毒症狀，需盡速就醫","(D) 毛地黃要與牛奶或食物併用，以減少腸胃刺激"],"answer":2,"image":""},{"id":"nr4-107-2-73","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"陳小弟，8個月大，體重7公斤。心臟手術後第一天，下列何者為異常表徵？","options":["(A) 肛溫37.2℃","(B) 24小時尿量60 c.c.","(C) 動脈血氧分壓PaO2 95 mmHg","(D) 兒童葛氏昏迷量表（PGCS）13分"],"answer":1,"image":""},{"id":"nr4-107-2-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"有關先天性甲狀腺功能低下嬰幼兒之症狀處理，下列何者錯誤？","options":["(A) 嬰兒出生24小時內抽血驗TSH值以確立診斷","(B) 嬰兒需暫停母乳哺餵以正確測得甲狀腺素濃度","(C) 治療目標之一為維持T4濃度在10～16 μg/dL","(D) 需定期注意新生兒聽力檢查及發展評估"],"answer":0,"image":""},{"id":"nr4-107-2-75","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"有關性早熟（precocious puberty）的敘述，下列何者錯誤？","options":["(A) 通常男孩子發生率較高，較女孩高出2～3倍","(B) 血清中LH, FSH, estrogen, testosterone皆上升","(C) 可用X光檢查骨骺板癒合情況以確認骨齡","(D) 可以腦部掃描確認是否有中樞神經性早熟"],"answer":0,"image":""},{"id":"nr4-107-2-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"有關腎病症候群（nephrotic syndrome）與急性腎絲球腎炎（acute glomerulonephritis）之比較，下列何者正確？","options":["(A) 兩者皆受到A群β 型溶血性鏈球菌感染所致","(B) 兩者檢驗值皆呈現C-反應性蛋白質（CRP）增加","(C) 兩者皆會出現蛋白尿臨床表徵","(D) 兩者皆會出現高血脂現象"],"answer":2,"image":""},{"id":"nr4-107-2-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"王小弟，診斷為急性腎衰竭（acute renal failure），下列敘述何者正確？","options":["(A) 腎臟排出過多氫離子與鉀離子，造成代謝性酸中毒","(B) 依醫囑給與口服kayexalate，增加鉀離子的吸收","(C) 少尿期，體液容積過多，宜限制水分攝入","(D) 少尿期應攝入高鉀、高鈉飲食，矯正電解質不平衡"],"answer":2,"image":""},{"id":"nr4-107-2-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"小美，14歲，診斷為泌尿道感染（urinary tract infection），有關出院護理指導，下列何者錯誤？","options":["(A) 依醫囑服用抗生素，返院追蹤複檢尿液","(B) 多攝取碳酸飲料，酸化尿液，減少重複感染機會","(C) 如廁後，由前往後擦拭清潔會陰處","(D) 排空膀胱，減少重複感染機會"],"answer":1,"image":""},{"id":"nr4-107-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"有關重症肌無力（myasthenia gravis）病童的臨床症狀，下列何者錯誤？","options":["(A) 眼球肌肉受到侵犯而有複視","(B) 出現吸吮及吞嚥困難","(C) 顏面神經出現麻痺","(D) 活動之後症狀會改善"],"answer":3,"image":""},{"id":"nr4-107-2-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"陳小弟，因腦瘤（brain tumor）接受手術，下列護理措施何者錯誤？","options":["(A) 抬高床尾，增加腦部組織灌流","(B) 監測生命徵象及意識狀況","(C) 觀察傷口紅、腫、熱、痛現象","(D) 教導避免用力咳嗽或解便"],"answer":0,"image":""},{"id":"nr4-108-1-1","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"王女士想了解溫柔生產的照護方式，下列護理指導何者錯誤？","options":["(A) 待產期間可以自由走動","(B) 常規執行會陰部剃毛","(C) 生產時先生可以陪產","(D) 產後立即進行產檯肌膚接觸"],"answer":1,"image":""},{"id":"nr4-108-1-2","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"有關衛生福利部推動的母嬰親善醫院十大措施，下列何者錯誤？","options":["(A) 提倡產後儘早哺餵母乳","(B) 依嬰兒的需求哺餵母乳","(C) 提供嬰兒安撫奶嘴","(D) 實施24小時親子同室"],"answer":2,"image":""},{"id":"nr4-108-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"王女士，G1P0，懷孕16週，為增進母親與胎兒的情感連結，下列護理措施何者最適當？","options":["(A) 討論增加孕期舒適方法","(B) 教導婦女監測胎動出現頻率","(C) 鼓勵婦女與胎兒說話","(D) 安排她參觀產房設備"],"answer":2,"image":""},{"id":"nr4-108-1-4","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"懷孕24週婦女接受產檢，血壓值：124/80 mmHg、未有水腫，尿液試紙的白蛋白顯現痕跡（trace），下列解釋何者最適當？","options":["(A) 子癇前症早期徵象","(B) 腎微血管充血所致","(C) 腎小管對蛋白質吸收增加所致","(D) 攝取過多水分所致"],"answer":1,"image":""},{"id":"nr4-108-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"一位單胞胎孕前BMI為30的孕婦，其飲食與體重的護理指導，下列何者最適當？","options":["(A) 第一孕期可採用極低熱量飲食","(B) 整個孕期體重宜增加5～9公斤","(C) 第二孕期開始，可執行減重計畫","(D) 宜在第三孕期再開始增加體重"],"answer":1,"image":""},{"id":"nr4-108-1-6","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"有關胚胎附屬器官發育的敘述，下列何者正確？","options":["(A) 絨毛膜是由囊胚滋養層細胞發育而來","(B) 羊膜是胚胎膜最外層","(C) 羊水因含有胎兒尿液，故呈弱酸性","(D) 羊水量會隨著妊娠週數的增加而遞增，於懷孕40週達最高峰"],"answer":0,"image":""},{"id":"nr4-108-1-7","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"有關絨毛膜取樣（Chorionic Villus Sampling）之敘述，下列何者錯誤？","options":["(A) 可檢測胎兒神經管發育缺陷","(B) 可檢測胎兒染色體缺陷","(C) 建議妊娠10～12週執行","(D) 易出現胎兒四肢缺損"],"answer":0,"image":""},{"id":"nr4-108-1-8","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"一般建議孕期無壓力試驗（NST）開始測試的時間點和目的之敘述，下列何者正確？","options":["(A) 24週，檢測胎兒呼吸成熟度","(B) 24週，檢測胎兒神經成熟度","(C) 32週，檢測胎兒呼吸成熟度","(D) 32週，檢測胎兒神經成熟度"],"answer":3,"image":""},{"id":"nr4-108-1-9","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"有關以羊水評估胎兒成熟度之敘述，下列何者正確？","options":["(A) 檢查合宜時機為妊娠16～18週","(B) 卵磷脂與抱合髓磷脂（L/S Ratio）之比值≧2表示肺部已經成熟","(C) 羊水中雌三醇（Estriol）值＜10 mg表示胎兒肺泡成熟","(D) 羊水中膽紅素值降至0，表示胎兒肝臟發育有問題"],"answer":1,"image":""},{"id":"nr4-108-1-10","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"有關胎血循環，下列何者正確？","options":["(A) 臍帶內含二條靜脈、一條動脈","(B) 臍靜脈血在進入右心房之前為充氧血","(C) 臍動脈內含缺氧血","(D) 卵圓孔是連接左右心室之間的開口"],"answer":2,"image":""},{"id":"nr4-108-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"丁女士使用催產素催生，胎兒監視器顯示胎心音早期減速，此時最合宜之措施為何？","options":["(A) 立即停止催產素","(B) 密切觀察，不需特殊處理","(C) 馬上給予氧氣","(D) 即刻準備剖腹產"],"answer":1,"image":""},{"id":"nr4-108-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"江女士待產中出現換氣過度現象，抱怨暈眩、嘴唇、手指有麻刺感，下列何者為優先護理措施？","options":["(A) 以鼻導管提供氧氣2 L/min","(B) 加快靜脈輸液","(C) 鼓勵採取左側臥","(D) 教導減慢呼吸速率"],"answer":3,"image":""},{"id":"nr4-108-1-13","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"蔡女士第一胎，因待產緊急狀況需進行剖腹產，醫師採用吸入性麻醉藥物進行全身麻醉，下列何者錯誤？","options":["(A) 一般以吸入性麻醉藥物作為麻醉誘導用藥","(B) 使用吸入性麻醉藥物會影響子宮收縮，需注意產婦出血情況","(C) 全身麻醉法容易影響心血管系統，常發生低血壓情況","(D) 吸入性麻醉藥物為脂溶性易通過胎盤，可能抑制新生兒的神經行為"],"answer":2,"image":""},{"id":"nr4-108-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"胡女士子宮頸口全開，護理師協助產婦躺上產檯並準備生產，下列護理措施何者不合適？","options":["(A) 把手擋在會陰部禁止胎兒娩出","(B) 請準父親穿上隔離衣、帽子、口罩在產房陪產","(C) 監測胎心率變化","(D) 確認預先加熱新生兒處理檯"],"answer":0,"image":""},{"id":"nr4-108-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"王女士，待產期間為右枕前位，進行內迴轉時，下列何者正確？","options":["(A) 自ROA旋轉45度至OA","(B) 自ROA旋轉135度至OA","(C) 自ROP旋轉45度至OA","(D) 自ROP旋轉135度至OA"],"answer":0,"image":""},{"id":"nr4-108-1-16","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"有關剖腹產的敘述，下列何項錯誤？","options":["(A) 經由腹壁及子宮切口將胎兒取出的手術","(B) 剖腹產後，下一次生產一定要採剖腹生產","(C) 胎兒窘迫是緊急剖腹產的適應症","(D) 子宮下段橫式切開法，手術出血量較少"],"answer":1,"image":""},{"id":"nr4-108-1-17","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"有關待產與生產時姿勢的敘述，下列何者錯誤？","options":["(A) 待產過程中應允許婦女自由活動或變換姿勢","(B) 生產時採膀胱截石臥位姿勢，婦女較能有效用力及減少疲勞","(C) 生產時採背部直立姿勢有利於胎兒下降","(D) 生產時採背部直立姿勢可減少下腔靜脈壓迫，較少發生胎心音異常"],"answer":1,"image":""},{"id":"nr4-108-1-18","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"陳女士陰道檢查結果子宮頸擴張9公分，變薄程度80%，高度+2，此時胎頭最有可能在下列那個位置？","options":["(A) 骨盆入口","(B) 坐骨棘上","(C) 坐骨棘下","(D) 陰道出口"],"answer":2,"image":""},{"id":"nr4-108-1-19","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"下列何者為母乳哺餵的禁忌？","options":["(A) 乳腺炎","(B) 嬰兒膽紅素低於15 mg/dL","(C) 藥物濫用","(D) 母親為A型肝炎"],"answer":2,"image":""},{"id":"nr4-108-1-20","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"下列那項父親行為最無助於與新生兒建立依附關係？","options":["(A) 陪伴太太哺餵母乳","(B) 對新生兒說話","(C) 協助換尿布","(D) 詢問新生兒血型"],"answer":3,"image":""},{"id":"nr4-108-1-21","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"李女士剖腹生產後第1天，生命徵象正常，尚未排氣，惡露為少量的深紅色，下列護理指導何者適當？","options":["(A) 避免下床活動以免傷口疼痛影響腸蠕動","(B) 因乳汁尚未分泌暫不進行母乳餵食","(C) 惡露量為異常應注意有內出血情形","(D) 教導腿部運動以防血栓靜脈炎"],"answer":3,"image":""},{"id":"nr4-108-1-22","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"吳女士產後第2天於餵母奶時表示：「妹妹跟爸爸長得好像！」此時產婦的行為屬於下列何者？","options":["(A) 分極作用","(B) 提出所有權","(C) 分離個別化行為","(D) 認同行為"],"answer":3,"image":""},{"id":"nr4-108-1-23","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"有關產後正常紅惡露（lochia rubra）的護理指導，下列何者正確？","options":["(A) 含大量血塊","(B) 惡臭味","(C) 活動時流量會增加","(D) 持續至產後6週"],"answer":2,"image":""},{"id":"nr4-108-1-24","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"有關黃體素抑制劑（RU486）阻斷懷孕過程的敘述，下列何者正確？","options":["(A) 能破壞子宮內膜的穩定性","(B) 懷孕10週前服用","(C) 可做為常規的避孕方法","(D) 可在藥房購買自行服用"],"answer":0,"image":""},{"id":"nr4-108-1-25","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"李女士G1P1，2小時前因雙胞胎妊娠採剖腹生產，採硬脊膜外麻醉，剛剛自恢復室轉到產後病房，下列何者不是護理師應優先進行的評估項目？","options":["(A) 子宮收縮","(B) 母乳哺餵","(C) 腸蠕動","(D) 下肢神經肌肉感覺"],"answer":2,"image":""},{"id":"nr4-108-1-26","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"產婦分娩結束其生理變化回復至懷孕前狀態的期間，稱為什麼時期？","options":["(A) 復舊期（Involution Phase）","(B) 惡露期（Lochia Phase）","(C) 霍曼期（Homan Phase）","(D) 產褥期（Puerperium）"],"answer":3,"image":""},{"id":"nr4-108-1-27","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"有關新生兒黃疸之敘述，下列何者錯誤？","options":["(A) 生理性黃疸通常出現於出生後2～3天","(B) 母乳引起的黃疸通常於出生後1個月發生","(C) 增加母乳哺餵次數有助於改善母乳不足性的黃疸","(D) 皮膚發黃的順序為由頭往下，由中心向外發展至四肢"],"answer":1,"image":""},{"id":"nr4-108-1-28","subject":"nr4","topic":"產科-產後照護","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"產後會陰傷口評估所使用的項目縮寫為何？","options":["(A) HELLP","(B) REEDA","(C) Rubin’s test","(D) Kegel’s test"],"answer":1,"image":""},{"id":"nr4-108-1-29","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"有關新生兒皮膚之敘述，下列何者錯誤？","options":["(A) 毛細血管瘤為永久性不會消失","(B) 毒性紅斑1～3週會消失","(C) 蒙古斑大約1～5歲會漸漸消退","(D) 粟粒疹2～4週會消失"],"answer":0,"image":""},{"id":"nr4-108-1-30","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"李小弟出生第2天，無臉部表情與眼睛活動，呼吸規律，偶有驚嚇反應及突發的吸吮動作，此睡眠與活動狀態屬於那一期？","options":["(A) 安靜睡眠期","(B) 半睡半醒期","(C) 安靜清醒期","(D) 活動清醒期"],"answer":0,"image":""},{"id":"nr4-108-1-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"有關孕期心臟病之敘述，下列何者錯誤？","options":["(A) 懷孕38～40週時心臟負荷最大","(B) 孕婦易早產及流產","(C) 懷孕體重增加控制於10公斤左右","(D) 每餐飯後至少半小時躺下休息"],"answer":0,"image":""},{"id":"nr4-108-1-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"有關前置胎盤之敘述，下列何者正確？","options":["(A) 可能造成的原因為多胎妊娠、高齡、前次剖腹產等","(B) 部分性前置胎盤仍可陰道生產","(C) 前置胎盤之診斷在懷孕30週前即可確認","(D) 孕婦若有前置胎盤情形一律採絕對臥床休息"],"answer":0,"image":""},{"id":"nr4-108-1-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"有關安胎藥物之敘述，下列何者正確？","options":["(A) 硫酸鎂（MgSO4）使用需監測呼吸不能少於18次/分","(B) Adalat屬於α 阻斷劑","(C) Yutopar適用於妊娠全期","(D) 硫酸鎂（MgSO4）中毒時可使用10%葡萄糖鈣中和"],"answer":3,"image":""},{"id":"nr4-108-1-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"有關高危險妊娠的敘述，下列何者正確？","options":["(A) 按照古德溫（Goodwin）產前胎兒危險計分法，高危險妊娠因子不包括「年齡」與「產次」","(B) 高危險妊娠不一定會造成不良的妊娠結果，良好的產前醫護措施與胎兒健康評估，可降低其危險性","(C) 相對於高危險妊娠孕婦，一般正常孕婦是屬於零危險妊娠者","(D) 高危險妊娠的定義是「懷孕時因生理或心理因素，導致母體（不包括胎兒）病理性傷害」"],"answer":1,"image":""},{"id":"nr4-108-1-35","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"Tamoxifen（Nolvadex）可抑制內生性雌激素作用，以有效降低乳癌的復發，若長期服用此藥物，護理師需要評估下列那些副作用？①血糖過低 ②鈣離子過低 ③噁心嘔吐 ④更年期症狀 ⑤末梢水腫","options":["(A) ①②④","(B) ③④⑤","(C) ②③④","(D) ①③⑤"],"answer":1,"image":""},{"id":"nr4-108-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"有關子宮肌瘤之敘述，下列何者正確？","options":["(A) 以漿膜下肌瘤為主","(B) 易產生惡性病變","(C) 常有不正常子宮出血","(D) 因黃體素過多所致"],"answer":2,"image":""},{"id":"nr4-108-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"有關生殖器疱疹之敘述，下列何者正確？","options":["(A) 新生兒會經由陰道感染","(B) 為第一型單純疱疹病毒感染","(C) 臨床症狀少有發燒現象","(D) 只要確實服藥都可根治"],"answer":0,"image":""},{"id":"nr4-108-1-38","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"最常導致愛滋病患神經系統感染的病原體為何？","options":["(A) 新形囊球菌","(B) 金黃色葡萄球菌","(C) 大腸桿菌","(D) 肺囊蟲"],"answer":0,"image":""},{"id":"nr4-108-1-39","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"有關骨盆腔炎之敘述，下列何者正確？","options":["(A) 都為單一病原體感染","(B) 常見之合併症為不孕","(C) 治療期間不需禁慾","(D) 少有異常的陰道分泌物"],"answer":1,"image":""},{"id":"nr4-108-1-40","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"下列何者不屬於腦下垂體所分泌之促性腺激素（pituitary gonadotrophic hormones）？","options":["(A) 濾泡刺激素（follicular stimulating hormone, FSH）","(B) 黃體生成素（luteinizing hormone, LH）","(C) 動情激素（estrogen）","(D) 催乳激素（prolactin）"],"answer":2,"image":""},{"id":"nr4-108-1-41","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"有關異物吸入造成兒童輕微支氣管阻塞的症狀描述，下列何者錯誤？","options":["(A) 作嘔","(B) 咳嗽","(C) 無法說話","(D) 哮喘"],"answer":2,"image":""},{"id":"nr4-108-1-42","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"下列何者是2歲幼兒對疼痛最不常採取的反應？","options":["(A) 大聲哭泣、尖叫，有生氣的表情","(B) 抱住父母或他人，尋求情緒上的支持","(C) 出現拖延的行為，如：我要去尿尿","(D) 手腳扭動、踢人，不肯合作"],"answer":2,"image":""},{"id":"nr4-108-1-43","subject":"nr4","topic":"兒科-高危險新生兒","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"林小弟，妊娠週數37週又3天，出生體重2950公克，採純母乳哺餵，今體重2620公克，減少出生體重的10%以上，給予檢測血糖為33 mg/dL，有關低血糖可能造成的影響及處理，下列何者錯誤？","options":["(A) 立即給予口服餵食葡萄糖水、母乳或配方奶","(B) 若餵食不順，則應給予靜脈注射葡萄糖液","(C) 建議每6～8小時監測一次血糖","(D) 治療目標應維持血糖在45 mg/dL以上"],"answer":2,"image":""},{"id":"nr4-108-1-44","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"有關腸病毒傳染途徑的敘述，下列何者錯誤？","options":["(A) 發病前數天在喉嚨及糞便都有病毒存在，但不具傳染力","(B) 腸病毒感染者之傳染力，在發病後1週是高峰","(C) 一般腸病毒在呼吸道口沫中，可存留約1～3週","(D) 可持續經由腸道釋出病毒，時間可達2～3個月"],"answer":0,"image":""},{"id":"nr4-108-1-45","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"有關川崎氏症（Kawasaki Disease）的敘述，下列何者錯誤？","options":["(A) 急性期會持續發燒5天以上，並有草莓狀舌","(B) 急性期給予高劑量阿司匹靈（Aspirin）可抗發炎及抑制血小板凝集","(C) 亞急性期病童的手指、腳趾、肛門會有脫皮現象","(D) 當症狀獲得控制後，仍須長期追蹤其中樞神經系統病變"],"answer":3,"image":""},{"id":"nr4-108-1-46","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"兒童氣喘發作時最容易造成呼吸性酸中毒的原因，下列何者正確？①呼吸過慢 ②新陳代謝率減慢 ③脫水 ④低血氧","options":["(A) ①②","(B) ①③","(C) ②④","(D) ③④"],"answer":3,"image":""},{"id":"nr4-108-1-47","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"有關缺鐵性貧血病童口服鐵劑的注意事項，下列何者錯誤？","options":["(A) 飯前1小時服用，吸收較佳","(B) 合併制酸劑服用，吸收較佳","(C) 宜使用吸管服用液態鐵劑","(D) 口服鐵劑期間，大便呈黑色"],"answer":1,"image":""},{"id":"nr4-108-1-48","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"王小妹，8歲，罹患急性腎絲球腎炎，若出現少尿情形，有關飲食之護理指導，下列何項應避免？","options":["(A) 鳳梨","(B) 木耳","(C) 胡瓜","(D) 香蕉"],"answer":3,"image":""},{"id":"nr4-108-1-49","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"婷婷，14歲，泌尿道感染三度入院，下列護理指導何者較不適當？","options":["(A) 增加運動量","(B) 解便後由前向後擦拭","(C) 多喝水，不憋尿","(D) 穿寬鬆的棉質內褲"],"answer":0,"image":""},{"id":"nr4-108-1-50","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"有關細菌性腦膜炎的護理措施，下列何者錯誤？","options":["(A) 靜脈注射抗生素至少10天","(B) 維持病童的體溫於正常範圍","(C) 增加環境刺激預防病童嗜睡","(D) 運用姿勢的調整以減輕疼痛"],"answer":2,"image":""},{"id":"nr4-108-1-51","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"10歲的大華罹患癲癇（Epilepsy）以口服phenobarbital（luminal）藥物治療，護理人員給予大華母親的護理指導，下列何者正確？","options":["(A) 定時帶大華回診抽血，監測血中藥物濃度","(B) 尿液顏色變紅棕色是正常現象","(C) 服藥6週後未再發生抽搐，即可停藥","(D) 發作後須進食高碳水化合物飲食，以避免低血糖造成抽搐再度發作"],"answer":0,"image":""},{"id":"nr4-108-1-52","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"有關自閉症的護理指導，下列何者最適當？","options":["(A) 教養方式為自閉症之主要導因，持續與父母親討論教養策略","(B) 強調按時服藥的必要性，以能治癒自閉症","(C) 儘速提供多元有變化的新情境刺激，發展其潛能","(D) 提供正向行為治療，以增強建立適當的行為"],"answer":3,"image":""},{"id":"nr4-108-1-53","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"玲玲，14歲，父母親離異後出現進食量少，餐後嘔吐。即使身體質量指數為13，玲玲自覺很胖，故初次診斷厭食症而開始住院接受治療。有關維持營養的護理措施，下列何者最適合？","options":["(A) 監測玲玲的用餐情形，直到願意開始進食為止","(B) 提供玲玲高熱量食物，每週增加3公斤為目標","(C) 建立行為契約，與玲玲討論營養攝取目標","(D) 邀請父母親參與飲食護理指導，不需轉介家庭心理諮商"],"answer":2,"image":""},{"id":"nr4-108-1-54","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"有關青少年憂鬱症的治療與處置，下列何者正確？","options":["(A) 青少年憂鬱症藥物的使用以三環抗鬱劑為首選","(B) 輕度憂鬱症青少年使用電氣痙攣治療效果為佳","(C) 可多攝取多醣類、奶製品、魚油及維生素的食物","(D) 避免聚焦其人際困擾議題，以免加重憂鬱症狀"],"answer":2,"image":""},{"id":"nr4-108-1-55","subject":"nr4","topic":"兒科-意外事故與急症","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"有關嬰兒的心肺復甦術，下列何者正確？","options":["(A) 急救者只有一人時，先趕快打119求救","(B) 先吹兩口氣再壓胸30下","(C) 以口對口人工呼吸，吹氣時需捏住鼻子","(D) 每分鐘壓胸100～120下"],"answer":3,"image":""},{"id":"nr4-108-1-56","subject":"nr4","topic":"兒科-生長發展","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"王小妹，8歲，國小2年級，依據皮亞傑（Piaget）認知發展理論，其處於「具體運思期」階段，有關此階段發展特性，下列何者正確？","options":["(A) 開始學習使用符號、象徵及語言","(B) 較能了解相互間的關係，可將不同事物連接，開始可逆性思考","(C) 能使用抽象的符號，由系列觀察中，導出符合邏輯之結論","(D) 能融合數個觀念形成概念"],"answer":1,"image":""},{"id":"nr4-108-1-57","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"小華，4歲，因急性腸胃炎住院，護理師與其溝通時，下列何者錯誤？","options":["(A) 先讓小華熟悉護理師的存在","(B) 配合小華的高度與他談話","(C) 首次互動宜安排與小華單獨談話","(D) 避免告知小華「打針一點都不痛」"],"answer":2,"image":""},{"id":"nr4-108-1-58","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"有關兒童呼吸與脈搏之測量與評估，下列何者正確？","options":["(A) 新生兒呼吸急促是指呼吸大於40次/分","(B) 1歲以下嬰兒大多數採胸式呼吸","(C) 2歲以下的兒童通常以聽診器測心尖脈","(D) 兒童最常使用的脈搏測量部位為股動脈"],"answer":2,"image":""},{"id":"nr4-108-1-59","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"小文，6個月大，被診斷胃食道逆流（Gastroesophageal reflux），下列護理指導何者正確？","options":["(A) 添加麥粉或米粉，泡製較濃稠的配方奶","(B) 容易溢奶，其嘔吐物含膽汁","(C) 餵食後，宜採仰臥平躺姿勢","(D) 餵食時，避免拍背排氣引起食物逆流"],"answer":0,"image":""},{"id":"nr4-108-1-60","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"宏宏，8個月大，因支氣管炎住院接受治療，服用口服藥物的護理指導，下列何者正確？","options":["(A) 採躺臥的方式餵藥，以能充分吞入","(B) 用姆指壓其下顎（下巴），以便張口","(C) 將藥輕輕由口腔中間滴入，以免嗆到","(D) 滴入時間儘量快速，以免哭泣而吐出"],"answer":1,"image":""},{"id":"nr4-108-1-61","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"小華，4歲，住院接受靜脈輸液導管治療，有關導管拔除前後之護理措施，下列何者正確？","options":["(A) 注射部位的固定，儘量包紮手指末梢，以免鬆脫","(B) 儘量採纏繞方式固定注射部位，以防關節滑動","(C) 拔除後，注射部位乾燥後貼上膠布，以維護身體完整性","(D) 拔除後，給予輸注部位熱敷，以避免產生靜脈炎"],"answer":2,"image":""},{"id":"nr4-108-1-62","subject":"nr4","topic":"兒科-高危險新生兒","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"有關早產兒在保溫箱中的感官刺激，下列護理措施何者正確？","options":["(A) 聽覺刺激應最早開始執行，有助於促進感覺統合","(B) 晚上可在保溫箱上覆蓋布罩，以調節日夜光線變化","(C) 協助四肢伸展的姿勢擺位，以達寧握照護的原則","(D) 採分段式的護理措施，以給予足夠的休息時間"],"answer":1,"image":""},{"id":"nr4-108-1-63","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"有關新生兒罹患先天性梅毒的敘述，下列何者錯誤？","options":["(A) 出現病理性骨折，稱為溫伯格式（Wimberger’s）徵象","(B) 背部、臀部皮膚出現圓形丘疹的病灶，具傳染力","(C) 肝脾腫大、有明顯黃疸，貧血及紅血球母細胞數量增多","(D) 早期症狀會造成軍刀狀脛骨及痙攣性麻痺"],"answer":3,"image":""},{"id":"nr4-108-1-64","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"有關新生兒生產過程造成的鎖骨骨折，下列護理措施何者錯誤？","options":["(A) 協助穿脫衣服時，採患側先穿後脫的原則","(B) 建議採趴睡姿勢，以利患部癒合","(C) 避免測量圍巾徵象，將手肘越過對側鎖骨中線","(D) 抱起時支持後背及臀部，避免自手臂處抱起"],"answer":1,"image":""},{"id":"nr4-108-1-65","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"有關囊性纖維變性（Cystic Fibrosis）之敘述，下列何者錯誤？","options":["(A) 此為體染色體隱性遺傳疾病，提供家庭遺傳諮詢","(B) 止咳劑及抗組織胺藥物可以協助改善呼吸道分泌物排除","(C) 醫療計畫包括胰酵素製劑、補充脂溶性維生素及鐵劑","(D) 應採取高熱量、高蛋白飲食，且攝取大量水分"],"answer":1,"image":""},{"id":"nr4-108-1-66","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"有關以家庭為中心的兒童緩和安寧醫療照護，下列何者錯誤？","options":["(A) 乃為了減輕末期病童之痛苦，施予緩解性、支持性之醫療照護","(B) 強調能免除痛苦，並獲得符合其年齡需求的身心靈安適，安詳離去","(C) 需同時視病童及家屬為一整體，評估病童與家屬在痛失親人前後之哀傷情緒與靈性需求","(D) 孩童年齡滿7歲後，須給予簽署不施行心肺復甦術同意書"],"answer":3,"image":""},{"id":"nr4-108-1-67","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"小瑛，2歲，入院時，護理師在進行呼吸系統評估時，聽到哮鳴音（Stridor），可能的原因為何？","options":["(A) 氣喘即將發作的前兆","(B) 小孩常有的喉部吵雜音，長大會自然改善","(C) 呼吸道中有含水分多的分泌物","(D) 上呼吸道發炎或有異物阻塞的情形"],"answer":3,"image":""},{"id":"nr4-108-1-68","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"有關氧氣治療的敘述，下列何者正確？","options":["(A) 氧氣頭罩具有噴霧效果，可將氧氣濕化，需用生理食鹽水作為噴霧來源","(B) 氧氣面罩濃度最好維持在1～3 L/min使用，以避免二氧化碳滯留","(C) 病童在氧氣帳內易哭鬧，可給予手機或平板電腦，以分散注意力，降低焦慮","(D) 氧氣帳內應以氧氣分析儀在病童口鼻處測試氧氣濃度"],"answer":3,"image":""},{"id":"nr4-108-1-69","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"張小弟，5個月大，至健兒門診接受預防注射，下列何種預防注射疫苗適合張小弟注射？","options":["(A) 日本腦炎疫苗","(B) 水痘疫苗","(C) 卡介苗","(D) 麻疹疫苗"],"answer":2,"image":""},{"id":"nr4-108-1-70","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"王小弟，一出生即被診斷為大血管轉位，合併心室中隔缺損。下列何者錯誤？","options":["(A) 依醫囑靜脈注射前列腺素E1（Prostaglandin E1, PGE1），應注意是否有呼吸窘迫與血管炎的副作用","(B) 合併心室中隔缺損會讓發紺更嚴重，應立即給予100%氧氣","(C) 合併嚴重的中隔缺損，應注意是否有充血性心衰竭症狀","(D) 注意血液檢查是否有紅血球增多症狀"],"answer":1,"image":""},{"id":"nr4-108-1-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"王小弟，3歲，罹患法洛氏四重症。每天早上9點與晚上9點需服用毛地黃。若在早上需服藥時間的3小時後，發現遺漏服用，下列護理措施何者正確？","options":["(A) 立即補服一劑，下一劑延到晚上12點服用","(B) 立即補服一劑，下一劑維持晚上9點服用","(C) 不需補服，下一劑維持晚上9點服用","(D) 不需補服，晚上9點服用兩劑"],"answer":1,"image":""},{"id":"nr4-108-1-72","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"王小弟，5歲，因心臟病需進行胸骨切開式開心手術。有關傷口換藥的術前心理準備，下列護理措施何者合適？","options":["(A) 王小弟年紀還小，不需先提供傷口訊息","(B) 提供真實的傷口換藥影片給王小弟看","(C) 告訴王小弟傷口不會疼痛、不用害怕","(D) 用布偶示範傷口換藥的方式"],"answer":3,"image":""},{"id":"nr4-108-1-73","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"阿明，1歲，因罹患急性淋巴性白血症正接受誘導期化學治療。因發燒而追蹤抽血檢查，白血球33 100/mm，血色素7.6 g/dL，血小板為10000/mm，下列護理措施何者正確？","options":["(A) 依醫囑立即給予廣效性的預防性抗生素","(B) 發燒時，可給予Aspirin藥物協助降溫","(C) 鼓勵阿明沒發燒時可多活動，如走路及玩球","(D) 仍可依其年齡施打水痘疫苗"],"answer":0,"image":""},{"id":"nr4-108-1-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"新生兒篩檢為半乳糖血症陽性之飲食原則，下列何者錯誤？","options":["(A) 禁止餵食市售兒童配方奶","(B) 應避免餵食乳酪製品","(C) 依醫囑建議補充維生素與礦物質","(D) 維持完全母乳哺餵以維持足夠營養"],"answer":3,"image":""},{"id":"nr4-108-1-75","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"小明，15歲，因慢性腎衰竭而引發副甲狀腺功能亢進（Hyperparathyroidism），血鈣質為12 mg/dL，骨骼X光顯示脫鈣現象。相關的護理措施，下列何者錯誤？","options":["(A) 維持足夠的水分攝取，減少腎結石產生","(B) 為預防骨折發生，下床活動必要時可穿硬背心","(C) 心尖脈監測需測滿1分鐘，注意有無心律不整","(D) 建議服用維生素C，以促進鈣質排出"],"answer":3,"image":""},{"id":"nr4-108-1-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"副甲狀腺功能低下（Hypoparathyroidism）的兒童會出現的臨床表徵，下列何者正確？","options":["(A) 血中鈣質為12.0～15.0 mg/dL","(B) 血中磷質為2.5～3.5 mg/dL","(C) 喉部肌肉痙攣及喘鳴現象","(D) 大量鈣流失而骨密度不足"],"answer":2,"image":""},{"id":"nr4-108-1-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"小奇，10個月大，接受尿道下裂（Hypospadias）手術，有關手術後護理措施，下列何者錯誤？","options":["(A) 應臥床休息及限制肢體活動","(B) 可跨坐父母身上，進行靜態活動","(C) 監測尿量、尿液顏色及導尿管的通暢度","(D) 尿液由陰莖以外部位滲出，應通知醫師"],"answer":1,"image":""},{"id":"nr4-108-1-78","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"張小弟，2個月大，經由鼻胃管餵食，下列有關管灌餵食的敘述何者正確？","options":["(A) 總灌入量為胃殘餘量加上該次灌食量","(B) 如出現嘔吐、腹脹、呼吸暫停等徵象應立即停止灌食","(C) 餵食後，採坐姿或左側半坐臥，避免食物逆流","(D) 鼻胃管餵食期間，不應給予安撫奶嘴，以免影響呼吸"],"answer":1,"image":""},{"id":"nr4-108-1-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"協助有吞嚥困難的學齡前腦性麻痺病童進食，下列護理措施何者正確？","options":["(A) 協助病童坐起、身體維持正中位置","(B) 使病童肩膀前屈、膝蓋放鬆低於大腿","(C) 食物位置高於嘴巴，將食物放於舌頭前方","(D) 選擇適當輔具，完全由照顧者餵食"],"answer":0,"image":""},{"id":"nr4-108-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"張小妹，4個月大，被診斷水腦（Hydrocephalus），接受腦室腹膜分流（V-P shunt）手術，有關手術後護理措施，下列何者錯誤？","options":["(A) 記錄頭圍變化，觸診前囟門有無膨出","(B) 觀察意識狀態及顱內壓增高徵象","(C) 植入引流管處，勿碰撞或擠壓，保持傷口乾燥","(D) 觀察引流管阻塞徵象是周圍皮膚出現紅、腫、熱"],"answer":3,"image":""},{"id":"nr4-108-2-1","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"依據世界衛生組織及聯合國兒童基金會推行的政策，要成為母嬰親善醫院需符合下列那一項規定？","options":["(A) 要求所有母親均需在產檯即開始哺餵母乳","(B) 醫院實施每天8小時親子同室","(C) 除非有醫療特殊需要，否則不給嬰兒母奶以外的食物，包括水、葡萄糖水或配方奶","(D) 醫療人員可提供嬰兒人工奶嘴或安撫奶嘴，以緩解哺餵母親乳頭的負擔"],"answer":2,"image":""},{"id":"nr4-108-2-2","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"下列那一種細菌或病毒感染，為罹患子宮頸癌的高危險群？","options":["(A) 梅毒螺旋體","(B) 奈瑟氏淋病雙球菌","(C) 疱疹病毒","(D) 人類乳突狀病毒（HPV）"],"answer":3,"image":""},{"id":"nr4-108-2-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"李女士，G1P0，懷孕25週，請教護理師：「我身體上從肚臍到會陰部有一條褐色的線，這正常嗎？什麼時候會消失？」，護理師的回答，下列何者為宜？","options":["(A) 這是懷孕期荷爾蒙變化造成皮膚色素沈著，約在生產後會逐漸變淡","(B) 這是懷孕常見的妊娠紋，約在生產後2～3個月會消失","(C) 有可能是胎兒異常的徵兆，建議進一步做染色體核型分析","(D) 需儘快到整型外科或皮膚科進行去斑處理，否則容易留下永久的色素沈著"],"answer":0,"image":""},{"id":"nr4-108-2-4","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"有關生產教育的觀念，下列何者正確？①由醫護團隊主導生產過程，減少孕婦生產壓力 ②讓孕婦因應懷孕與分娩照護的過程 ③朝向以家庭為中心的照護 ④強調一定不要使用藥物性減痛方法","options":["(A) ①②","(B) ③④","(C) ②③","(D) ①④"],"answer":2,"image":""},{"id":"nr4-108-2-5","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"有關運用廓清式呼吸之敘述，下列何者錯誤？","options":["(A) 分娩期間每次宮縮開始與結束都應做一次廓清式呼吸","(B) 可做為產婦肺部通氣及放鬆的訊號","(C) 呼吸速率為正常呼吸速率的2倍（約每分鐘24～32次）","(D) 呼吸法的運用須依產婦的需要及放鬆程度來進行調整"],"answer":2,"image":""},{"id":"nr4-108-2-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"羊水指數（AFI）是以超音波觀察羊水量，有關判定之標準，下列何者正確？①小於10 cm為羊水過少 ②大於2000 mL為羊水過多 ③28週可達1000 mL ④約36週羊水增加至最高點","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"image":""},{"id":"nr4-108-2-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"吳女士，育有一子，目前懷孕10週，她曾自然流產一次，也曾因懷孕24週胎死腹中而引產。其生產紀錄史，下列何者正確？","options":["(A) G4P3AA1","(B) G3P3SA1","(C) G4P2SA1","(D) G3P2SA1"],"answer":2,"image":""},{"id":"nr4-108-2-8","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"下列何種方式是依據懷孕婦女子宮底高度位置推估預產期？","options":["(A) 最後一次月經週期（LMP）","(B) 內格萊式法則（Nagel's rule）","(C) 麥當勞法則（McDonald’s rule）","(D) 雙頂徑（BPD）"],"answer":2,"image":""},{"id":"nr4-108-2-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"懷孕11週的黃女士向護理師抱怨有頻尿的現象，可是並無解尿困難的情形，下列何者是較適當的護理指導？","options":["(A) 白天的飲水量應該減少","(B) 仍維持每日適當的飲水量","(C) 要求黃女士馬上接受醫生的問診","(D) 要求黃女士慢慢練習自我控制膀胱，然後將兩次排尿的時間儘量拉長"],"answer":1,"image":""},{"id":"nr4-108-2-10","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"李女士在第一產程中破水，下列何者為最優先的措施？","options":["(A) 給予陰道內診","(B) 評估胎心音1分鐘","(C) 給予腹部觸診","(D) 以石蕊試紙測試羊水"],"answer":1,"image":""},{"id":"nr4-108-2-11","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"王女士待產時，胎心率之變異性為6～10 bpm，下列敘述何者正確？","options":["(A) 胎兒感染","(B) 胎兒缺氧","(C) 胎兒瀕死","(D) 胎兒正常"],"answer":3,"image":""},{"id":"nr4-108-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"陳女士，G1P0，因規則陣痛而入產房待產，胎位為ROA，子宮頸口開1 cm，station=0，下列何者為station 0？","options":["(A) 胎兒的胎頭在骨盆入口上方","(B) 胎兒的雙頂徑通過骨盆入口","(C) 胎兒的雙頂徑通過恥骨聯合","(D) 胎兒的胎頭接近骨盆出口"],"answer":1,"image":""},{"id":"nr4-108-2-13","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"承上題，陳女士裝上胎兒監視器，此時胎兒心跳轉送器放置何處，可聽到最清楚胎心音？","options":["(A) 肚臍上1 cm處","(B) 與肚臍平行右側3 cm處","(C) 肚臍與右髂骨前上棘連線中點","(D) 肚臍與恥骨聯合連線中點"],"answer":2,"image":""},{"id":"nr4-108-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"照顧處於過渡期之待產婦，下列何者為最適當的護理措施？","options":["(A) 減少探視次數","(B) 延長衛教時間","(C) 告知產程進展","(D) 增加環境刺激"],"answer":2,"image":""},{"id":"nr4-108-2-15","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"有關分娩時經產婦的子宮頸變化之敘述，下列何者正確？","options":["(A) 子宮頸變薄與擴張同時進行","(B) 子宮頸先擴張，再變薄","(C) 子宮頸先變薄，再擴張","(D) 潛伏期時，子宮頸變薄變短程度為90～100%"],"answer":0,"image":""},{"id":"nr4-108-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"吳女士G2P1，她希望生產時能免除會陰切開術，以維持會陰的完整性，有關第二產程的護理措施，下列何者錯誤？","options":["(A) 溫和觸壓按摩會陰","(B) 鼓勵產婦溫和向下用力推進","(C) 配合產婦用力衝動向下推擠","(D) 平躺使用腳凳盡力伸展腿部"],"answer":3,"image":""},{"id":"nr4-108-2-17","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"有關基礎體溫的敘述，下列何者正確？","options":["(A) 危險期是排卵前3天及排卵後2天","(B) 依據排卵時體溫上升的原理，以確認危險期","(C) 排卵時體溫上升（高於36.7℃為高溫期）","(D) 排卵後體溫下降（約36.2℃為低溫期）"],"answer":0,"image":""},{"id":"nr4-108-2-18","subject":"nr4","topic":"產科-產後照護","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"下列何者為子宮復舊不全的現象？","options":["(A) 產後18天在腹部觸摸到子宮底","(B) 產後子宮底每天約下降1～2 cm","(C) 產後1週子宮重量下降至500公克","(D) 產後第1天子宮底高度臍平"],"answer":0,"image":""},{"id":"nr4-108-2-19","subject":"nr4","topic":"產科-產後照護","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"有關剖腹產術後照護之敘述，下列何者錯誤？","options":["(A) 平躺時可將頭側一邊，避免分泌物阻塞呼吸道","(B) 產後1小時內每隔15分鐘測量生命徵象","(C) 術後導尿管須留置至少8小時","(D) 等產婦可下床活動時，再哺餵母乳"],"answer":3,"image":""},{"id":"nr4-108-2-20","subject":"nr4","topic":"產科-產後照護","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"有關產後生理變化的敘述，下列何者正確？","options":["(A) 產後24小時內體溫會輕微下降，是因為生產過度用力、脫水的關係","(B) 產後12～24小時內，排尿量增加為正常現象，是為了排除懷孕時滯留多餘的水份","(C) 因為凝血因子增加，可利用霍曼氏試驗評估下肢血栓動脈炎","(D) 產後心輸出量增加，脈搏會增加到80～120次／分"],"answer":1,"image":""},{"id":"nr4-108-2-21","subject":"nr4","topic":"產科-產後照護","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"劉女士G2P2，陰道生產，產後第2天主訴：「我的子宮收縮怎麼這麼痛」，下列何者錯誤？","options":["(A) 經產婦的肌肉張力較鬆弛，故疼痛感更明顯","(B) 這是因為子宮收縮造成的正常現象","(C) 建議熱敷或輕撫按摩緩解疼痛","(D) 此現象稱為產後痛，約持續7天就會減輕"],"answer":3,"image":""},{"id":"nr4-108-2-22","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"有關母嬰親善醫院的10項措施，下列何者可直接促進親子依附關係？","options":["(A) 生產後於產檯立即性肌膚接觸","(B) 除非醫療需求，不提供配方奶","(C) 不使用奶瓶奶嘴餵食","(D) 提供產婦母乳支持團體"],"answer":0,"image":""},{"id":"nr4-108-2-23","subject":"nr4","topic":"產科-產後照護","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"有關霍曼氏試驗（Homan's test）之敘述，下列何者錯誤？","options":["(A) 須讓個案的腳板向背側彎曲","(B) 在縮短腓腸肌以壓迫深部靜脈","(C) 主要測試是否有深層靜脈血栓","(D) 陽性反應為發生疼痛反應"],"answer":1,"image":""},{"id":"nr4-108-2-24","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"新生兒出生後進行口鼻抽吸之目的為何？","options":["(A) 刺激迷走神經","(B) 移除呼吸道分泌物","(C) 引發嘔吐反射","(D) 適度移除二氧化碳"],"answer":1,"image":""},{"id":"nr4-108-2-25","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"有關新生兒囟門的敘述，下列何者正確？①前囟門為菱形，由二塊額骨及二塊頂骨組成 ②後囟門為三角形，約出生後18週關閉 ③囟門若凹陷代表有脫水現象 ④胎頭之塑形現象（molding），1個月後即可恢復","options":["(A) ①②","(B) ③④","(C) ②④","(D) ①③"],"answer":3,"image":""},{"id":"nr4-108-2-26","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"出生第3天的新生兒，出現早發性母乳黃疸，產婦擔心是否可以繼續哺餵母乳，下列護理師的回答何者適當？","options":["(A) 應該繼續哺餵母乳","(B) 暫停哺餵母乳","(C) 減少哺餵母乳次數","(D) 暫停由口進食"],"answer":0,"image":""},{"id":"nr4-108-2-27","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"有關新生兒的暗示行為之敘述，下列何者錯誤？","options":["(A) 投入性暗示行為：注視著照護者，微笑，代表想和人互動","(B) 脫離性暗示行為：手腳屈曲，臉轉向照顧者，表示想睡覺","(C) 飢餓的暗示行為：把手放在嘴裡，哭泣，拱背","(D) 吃飽的暗示行為：睡著，推開照顧者，吸吮動作減少"],"answer":1,"image":""},{"id":"nr4-108-2-28","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"護理師執行產後新生兒立即性護理時，發現劉小弟頭頂部有一局部軟組織腫脹，觸診組織鬆軟且外緣界線不清楚，下列敘述何者正確？","options":["(A) 是胎頭腫塊（產瘤），為骨膜與顱骨間的血液聚集","(B) 是胎頭腫塊，為頭皮上軟組織水腫","(C) 是頭血腫，會逐漸越過縫合線","(D) 是頭血腫，通常於出生後24～48小時消失"],"answer":1,"image":""},{"id":"nr4-108-2-29","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"有關HELLP syndrome的症狀與致病機轉之敘述，下列何者正確？","options":["(A) 為妊娠子癇症，易在懷孕20週以前出現，主要症狀是因血小板增加與溶血所引發","(B) 指溶血、肝功能指數上升、血小板下降的症候群","(C) 是妊娠出血性疾病的一種，包含血液動力失衡、低紅血球症與胎盤功能下降","(D) 致病機轉通常與孕婦對胎兒的ABO血型不合有關"],"answer":1,"image":""},{"id":"nr4-108-2-30","subject":"nr4","topic":"產科-產後照護","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"有關協助子宮復舊的產後運動，下列何者錯誤？","options":["(A) 臀部運動","(B) 抬腿運動","(C) 膝胸臥式","(D) 擴胸運動"],"answer":3,"image":""},{"id":"nr4-108-2-31","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"張女士懷孕39週，入院待產中，產程進度情形為：子宮頸擴張4 cm，變薄40%，高度為0，胎兒監測器顯示如下圖。根據此圖形，下列何者正確？","options":["(A) 胎頭受壓","(B) 胎盤功能不良","(C) 臍帶受壓","(D) 正常情形"],"answer":1,"image":"nr4-108-2-31.jpeg"},{"id":"nr4-108-2-32","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"承上題，護理師的處置下列何者不適當？","options":["(A) 採左側臥","(B) 調快點滴","(C) 調增催產素","(D) 面罩給氧"],"answer":2,"image":""},{"id":"nr4-108-2-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"有關前置胎盤住院治療的護理措施，下列何者錯誤？","options":["(A) 執行陰道檢查","(B) 監測子宮收縮及胎心率","(C) 觀察陰道出血狀況","(D) 測量生命徵象"],"answer":0,"image":""},{"id":"nr4-108-2-34","subject":"nr4","topic":"產科-待產與分娩","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"下列何者不是用來判斷孕婦是否破水的方法？","options":["(A) 黏液塞排出","(B) 陰道窺鏡檢查","(C) 石蕊試紙試驗","(D) 羊齒試驗"],"answer":0,"image":""},{"id":"nr4-108-2-35","subject":"nr4","topic":"產科-產後照護","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"子宮頸於產後多久可以恢復到幾乎完全閉合，且變得較厚？","options":["(A) 產後7天","(B) 產後14天","(C) 產後28天","(D) 產後42天"],"answer":0,"image":""},{"id":"nr4-108-2-36","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"有關心臟病婦女妊娠期護理之敘述，下列何者錯誤？","options":["(A) 每天應有至少10小時以上睡眠，以減少心臟負擔","(B) 採左側臥姿勢休息","(C) 孕期應告知避免服用digitalis，以免致畸胎","(D) 有上呼吸道感染應立即就醫，及早控制感染"],"answer":2,"image":""},{"id":"nr4-108-2-37","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"有關口服metronidazole（flagyl）治療陰道滴蟲感染之護理指導，下列何者正確﹖","options":["(A) 婦女先接受治療，無效後再請性伴侶一起治療","(B) 可進行陰道清水沖洗以加強治療效果","(C) 服藥期間，不可飲用酒精性飲料","(D) 治療期間，應配合採用口服避孕藥"],"answer":2,"image":""},{"id":"nr4-108-2-38","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"有關以子宮托（pessary）減輕子宮脫垂程度，其正確的放置部位為何？","options":["(A) 陰道前穹窿","(B) 陰道後穹窿","(C) 子宮頸外口","(D) 子宮頸內口"],"answer":1,"image":""},{"id":"nr4-108-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"有關精液檢查之護理指導，下列何者正確？","options":["(A) 保險套直接收集精液送檢","(B) 取精後以冰塊維持7℃以下送檢","(C) 取精後保溫42℃送檢","(D) 取精後室溫1～2小時內送檢"],"answer":3,"image":""},{"id":"nr4-108-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"有關更年期婦女的脂質與脂蛋白改變，下列何者錯誤？","options":["(A) 血小板凝集增加","(B) 高密度脂蛋白（HDL）增加","(C) 低密度脂蛋白（LDL）增加","(D) 纖維蛋白原濃度增加"],"answer":1,"image":""},{"id":"nr4-108-2-41","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"有關青少年病人住院的護理，下列何者錯誤？","options":["(A) 鼓勵青少年病人繼續與同儕保持聯絡","(B) 以不批判的態度，接受青少年可能會有的退化性行為","(C) 為維護其自我控制權，由他選擇服藥時間及意願，自行服藥","(D) 討論各種自我照顧的方式，儘量減少依賴"],"answer":2,"image":""},{"id":"nr4-108-2-42","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"護理師幫幼兒觸診頸部時，觸摸到淋巴結，下列對於觸摸到淋巴結特徵的描述，何者屬於異常現象？","options":["(A) 直徑小於1 cm","(B) 界限不清楚","(C) 指下可移動","(D) 不會壓痛"],"answer":1,"image":""},{"id":"nr4-108-2-43","subject":"nr4","topic":"兒科-生長發展","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"依據常見的嬰幼兒發展現象，一般嬰幼兒乳齒的生長順序，下列何者正確？①上排中央門牙 ②下排中央門牙 ③犬齒 ④第一臼齒 ⑤第二臼齒","options":["(A) ①→②→③→④→⑤","(B) ①→②→④→⑤→③","(C) ②→①→③→④→⑤","(D) ②→①→④→③→⑤"],"answer":3,"image":""},{"id":"nr4-108-2-44","subject":"nr4","topic":"兒科-生長發展","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"小妮及小美為幼稚園的玩伴，坐在地板互借遊戲器材或玩具一起玩，她們此時的遊戲特徵為何？","options":["(A) 競爭遊戲","(B) 合作遊戲","(C) 平行遊戲","(D) 聯合遊戲"],"answer":3,"image":""},{"id":"nr4-108-2-45","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"小明，1歲，罹患主動脈狹窄症（coarctation of the aorta）而入院，下列何者不是其症狀？","options":["(A) 上肢血壓比下肢高","(B) 肺血管阻力升高而有發紺現象","(C) 常主訴頭痛、暈眩","(D) 股動脈搏動較弱，甚至摸不到"],"answer":1,"image":""},{"id":"nr4-108-2-46","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"雯雯是法洛氏四重畸形（Tetralogy of Fallot’s）的病嬰，當其出現發紺嚴重時，護理師為其採膝胸臥式姿勢，可使症狀改善的原理為何？","options":["(A) 減少全身血管的阻力，提高血壓","(B) 減少下肢回心血量，增加肺部血流","(C) 減少上肢回心血量，增加腦部的血液供應","(D) 減少血液循環全身的距離，提高全身循環血量"],"answer":1,"image":""},{"id":"nr4-108-2-47","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"葳葳，5歲，剛做完右心導管檢查，返回病房後護理師提供的護理措施，下列何者錯誤？","options":["(A) 臥床6小時，清醒後即可進食","(B) 評估檢查側之肢體循環，並與另一側比較","(C) 砂袋加壓穿刺部位，彎曲肢體防止砂袋掉落","(D) 觸診兩側肢體的脛骨後動脈或足背動脈，做對稱性比較"],"answer":2,"image":""},{"id":"nr4-108-2-48","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"有關胰島素注射的敘述，下列何者錯誤？","options":["(A) 應先抽取短效胰島素RI後，再抽取中效胰島素NPH","(B) 以Z字法做肌肉注射","(C) 注射部位須輪換，以避免注射部位脂質增生，影響胰島素的吸收","(D) 胰島素注射部位吸收速度由快而慢之排列順序為：腹部＞手臂＞大腿＞臀部"],"answer":1,"image":""},{"id":"nr4-108-2-49","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"小明，8個月大，疑似患有胃食道逆流（gastroesophageal reflux, GER）接受多項診斷檢查，下列何者正確？","options":["(A) 食道鏡檢查，可以確認逆流量的多寡","(B) 上腸胃道攝影術，需喝下含顯影劑的牛奶","(C) 腹部超音波掃描，確認食道炎的位置","(D) 24小時食道酸鹼值測定，是最準確的診斷方法"],"answer":3,"image":""},{"id":"nr4-108-2-50","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"兒童接受排空性膀胱尿道攝影（voiding cystouretheography）的主要目的是：","options":["(A) 了解尿路動力學","(B) 了解泌尿道生理結構","(C) 評估輸尿管逆流情形","(D) 評估尿路結石情形"],"answer":2,"image":""},{"id":"nr4-108-2-51","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"病童罹患厭食症，於營養復健期間，因過度餵食、體重快速增加可能造成的問題，下列敘述何者正確？","options":["(A) 心血管負擔過重","(B) 無月經","(C) 胃出血","(D) 暴食症"],"answer":0,"image":""},{"id":"nr4-108-2-52","subject":"nr4","topic":"兒科-意外事故與急症","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"常見的兒童虐待類型包括身體虐待、情緒（精神）虐待、性虐待及疏忽，有關兒童虐待的敘述，下列何者正確？","options":["(A) 多數兒童虐待的施虐者多為認識的人","(B) 大部分兒童性虐待很容易由兒童的舉止發現異常","(C) 其中只有身體虐待會導致兒童死亡","(D) 兒童疏忽主要是來自照顧者的過度保護"],"answer":0,"image":""},{"id":"nr4-108-2-53","subject":"nr4","topic":"兒科-意外事故與急症","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"有關嬰兒急救的程序，下列敘述何者正確？","options":["(A) 可用刺腳跟的方式，檢查嬰兒是否失去意識","(B) 以手捏住嬰兒鼻子，口罩住其嘴巴吹兩口氣，進行人工呼吸","(C) 以5～10秒檢查嬰兒頸動脈的脈搏跳動","(D) 若懷疑嬰兒頸部損傷，應使用壓額抬下巴法"],"answer":0,"image":""},{"id":"nr4-108-2-54","subject":"nr4","topic":"產科-孕期生理與評估","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"根據衛生福利部擬訂「2025年衛生福利政策白皮書」，婦幼健康促進長程指標，下列敘述何者錯誤？","options":["(A) 孕產婦死亡率降至0.016‰","(B) 嬰兒死亡率降至2.0‰","(C) 低出生體重比率降到2.0%","(D) 6個月以下純母乳哺育率提升至50%"],"answer":2,"image":""},{"id":"nr4-108-2-55","subject":"nr4","topic":"兒科-意外事故與急症","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"陳小妹，1歲半，14公斤，從火場中被救出，全身30%的部分皮層燒傷，目前正滴注靜脈輸液，為評估輸液是否適當，陳小妹每小時的尿量應為多少mL較適宜？","options":["(A) 6 mL","(B) 14 mL","(C) 30 mL","(D) 60 mL"],"answer":1,"image":""},{"id":"nr4-108-2-56","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"阿帕嘉評分（Apgar score）是最常用來評估新生兒對子宮外生活立即適應的方法。下列何者不是阿帕嘉評分的計分項目？","options":["(A) 心跳速率","(B) 膚色","(C) 肌肉張力","(D) 排泄情況"],"answer":3,"image":""},{"id":"nr4-108-2-57","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"小英，4歲，因中耳炎需執行耳內給藥，給藥時，應將小英耳朵往那一方向拉？","options":["(A) 往上往後拉","(B) 往下往前拉","(C) 往上往前拉","(D) 往下往後拉"],"answer":0,"image":""},{"id":"nr4-108-2-58","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"小明，9歲，因患白血病被告知需住院至少一個月接受治療，此階段兒童最關心的事為何？","options":["(A) 與父母分離","(B) 活動限制","(C) 閹割焦慮","(D) 學業與同儕關係"],"answer":3,"image":""},{"id":"nr4-108-2-59","subject":"nr4","topic":"兒科-高危險新生兒","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"有關早產兒視網膜病變，下列敘述何者正確？","options":["(A) 主要發生於妊娠35週以上的早產兒","(B) 與過度或長期給高氧、光線刺激有關","(C) 因視網膜血管舒張及發育不良所致","(D) 應於4個月大時，開始接受視網膜檢查及追蹤"],"answer":1,"image":""},{"id":"nr4-108-2-60","subject":"nr4","topic":"產科-新生兒護理","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"有關新生兒各系統生理特徵與調節，下列何者正確？","options":["(A) IgG不會通過母體胎盤到達新生兒體內","(B) 女嬰出生後，陰道出現紅色分泌物，此徵象乃是受母親雌激素中斷所影響","(C) 出生後肺血流增加，肺靜脈血回流至左心房血流量與壓力增加，使靜脈導管關閉","(D) 新生兒黃疸主要是由於體內甲硫胺酸（methionine）量不足或未活化，而導致結合型膽紅素無法排出"],"answer":1,"image":""},{"id":"nr4-108-2-61","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"小健，國中一年級，罹患第一型糖尿病（type 1 diabetes mellitus），有關糖尿病照護，下列敘述何者正確？","options":["(A) 為減少兒童被歧視，儘量減少其參與社會性活動","(B) 避免告知老師及同儕罹患糖尿病，以減少被標籤化","(C) 聯絡老師，允許不參加體育課，以預防疾病惡化","(D) 只要適當控制血糖，也可自我照顧並和同學一起聚餐"],"answer":3,"image":""},{"id":"nr4-108-2-62","subject":"nr4","topic":"兒科-高危險新生兒","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"彤彤，因母親懷孕30週時突然破水致早產，出生體重1020公克，併有腦室內出血（intraventricular hemorrhage, IVH），下列護理措施，何者錯誤？","options":["(A) 抬高床頭15～20度，以減少顱內壓","(B) 密切監測出血徵狀，如血壓降低、血比容下降","(C) 觀察是否出現囪門膨出、頭圍增加等顱內壓升高現象","(D) 限制家屬探訪，避免造成感染"],"answer":3,"image":""},{"id":"nr4-108-2-63","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"有關新生兒壞死性腸炎之敘述，下列何者錯誤？","options":["(A) 因週產期窒息腸道缺氧，引起壞死及細菌侵犯腸黏膜","(B) 常侵犯部位為乙狀結腸及直腸壺腹處","(C) 哺餵母乳為最佳的預防方法，母乳內之IgA能抑制或殺死細菌","(D) 體溫測量時宜避免測量肛溫，以免傷害腸黏膜"],"answer":1,"image":""},{"id":"nr4-108-2-64","subject":"nr4","topic":"兒科-高危險新生兒","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"凱凱，足月產，體重3050公克，出生後24小時抽血呈現血清膽紅素值為27 mg/dL，欲執行換血治療，下列相關描述，何者正確？","options":["(A) 採用之血液，最好為新鮮血液，或不超過72小時之血庫血袋，以防止血袋中鉀離子過高","(B) 為預防血袋內抗凝血劑所含之檸檬酸，與嬰兒血中鈣結合引起高血鈣，需注射抑鈣激素（calcitonin）","(C) 備血之血量為嬰兒全身血量的3倍，約800mL為原則","(D) 如因Rh血型不合而發生溶血者，應備O型且Rh血型為陽性"],"answer":0,"image":""},{"id":"nr4-108-2-65","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"依照衛生福利部疾病管制署106年公布之「我國現行兒童預防接種時程」，卡介苗（BCG）之建議接種時間為：","options":["(A) 出生滿7～21天","(B) 出生滿1～4個月","(C) 出生滿5～8個月","(D) 出生滿9～12個月"],"answer":2,"image":""},{"id":"nr4-108-2-66","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"小冬，5歲半，是一位初診斷後長期需要類固醇治療的腎病症候群的病童，今年秋天母親提出預防接種的問題，下列何種疫苗適用於小冬？","options":["(A) 水痘疫苗（varicella）","(B) 麻疹疫苗（measles）","(C) 流行性感冒病毒（influenza）","(D) 麻疹、腮腺炎、德國麻疹混合疫苗（MMR）"],"answer":2,"image":""},{"id":"nr4-108-2-67","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"有關哮吼（croup）之敘述，下列何者正確？","options":["(A) 最常引起的致病原是A群β 型葡萄球菌","(B) 較易發生在學齡期兒童","(C) 呼氣時會聽見哮喘聲（stridor）","(D) 病童會出現聲音沙啞（hoarseness）、喉嚨緊縮及狗吠式咳嗽（barking cough）"],"answer":3,"image":""},{"id":"nr4-108-2-68","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"有關扁桃腺切除術（tonsillectomy）後的護理措施，下列敘述何者錯誤？","options":["(A) 鼓勵病童常做咳嗽動作，以利肺部擴張","(B) 協助採側臥或俯臥，以利分泌物引流","(C) 觀察嘔吐物是否含血液性質","(D) 開始進食後，可提供冰涼的果凍、布丁、冰淇淋"],"answer":0,"image":""},{"id":"nr4-108-2-69","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"下列那一項胸腔物理治療是利用重力原理，使肺內的分泌物，易流至較大的支氣管，以利痰液排除？","options":["(A) 震顫","(B) 姿位引流","(C) 叩擊","(D) 抽痰"],"answer":1,"image":""},{"id":"nr4-108-2-70","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"小紅，7歲，因發燒、咳嗽、流鼻水症狀而入院。診斷為黴漿菌感染性肺炎（mycoplasma pneumonia），下列敘述何者正確？","options":["(A) 好發於1～3歲兒童","(B) 使用藥物為erythromycin或azithromycin","(C) 傳染途徑主要為接觸傳染，應加強洗手","(D) 主要由腺病毒引起，導致黏膜水腫"],"answer":1,"image":""},{"id":"nr4-108-2-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"疼痛控制為照護兒癌病童之一大挑戰，有關疼痛的評估及處置，下列敘述何者正確？","options":["(A) 若兒童沒有主訴疼痛，表示沒有疼痛","(B) 病童主訴疼痛時再給止痛藥，可減少止痛藥物副作用","(C) 可運用轉移注意力的方式（如看卡通），緩解疼痛","(D) 在給予止痛藥物時，應以針劑止痛藥為優先考量"],"answer":2,"image":""},{"id":"nr4-108-2-72","subject":"nr4","topic":"產科-高危險妊娠","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"根據衛生福利部疾病管制署「愛滋病防治手冊」，有關照顧愛滋病（AIDS）的產婦及新生兒，下列敘述何者正確？","options":["(A) 母親於分娩過程中應停止抗病毒藥物治療","(B) 新生兒出生24小時內通報","(C) 新生兒一週後開始接受抗病毒藥物治療","(D) 建議哺餵母乳增加新生兒抵抗力"],"answer":1,"image":""},{"id":"nr4-108-2-73","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"近年來由於飲食及生活型態的改變，致使那一類型的問題疾病增加？","options":["(A) 第一型糖尿病（type 1 diabetes）","(B) 第二型糖尿病（type 2 diabetes）","(C) 葡萄糖耐受性不良（impaired glucose tolerance）","(D) 糖尿病酮酸症（diabetes ketone acidosis）"],"answer":1,"image":""},{"id":"nr4-108-2-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"有關於先天性腎上腺素增生症（congenital adrenal hyperplasia, CAH），下列敘述何者正確？","options":["(A) 是一種體染色體顯性遺傳疾病","(B) 24小時尿液17-ketosteroids（17-KS）會下降","(C) 夜間服用cortisone，以維持正常皮質類固醇分泌","(D) 注意每日體重、輸入、輸出量及鈉、鉀離子之平衡"],"answer":3,"image":""},{"id":"nr4-108-2-75","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"小鋼，7歲，罹患威廉氏腫瘤（Wilms tumor）第三期，即將接受腎臟切除術。下列敘述何者正確？","options":["(A) 屬無觸痛感之良性腫瘤","(B) 術前可按摩病童腹部，減輕腫脹不適","(C) 第三期腫瘤局限於腎臟及周邊組織，以腎臟切除手術即可完全根除","(D) 需監測腎功能、血壓及輸出入量"],"answer":3,"image":""},{"id":"nr4-108-2-76","subject":"nr4","topic":"兒科-意外事故與急症","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"5歲以下兒童跌倒，容易導致何部位脫臼（dislocation）？","options":["(A) 髖部","(B) 膝部","(C) 手肘","(D) 腕部"],"answer":0,"image":""},{"id":"nr4-108-2-77","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"王小弟，3歲，罹患腎病症候群（nephrotic syndrome），目前服用prednisolone治療。護理師在安排與王小弟同住的病童時，下列何者適宜？","options":["(A) 2歲，張小弟，診斷哮吼（croup）","(B) 3歲，吳小弟，診斷腸病毒（enterovirus）","(C) 3歲，李小妹，診斷水痘（varicella）","(D) 4歲，陳小妹，診斷疝氣（hernia）"],"answer":3,"image":""},{"id":"nr4-108-2-78","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"有關皮肌炎（dermatomyositis）兒童的護理評估，下列何者錯誤？","options":["(A) 視診臉部會有紅斑結節性皮膚疹","(B) 視診關節部有對稱性紅斑","(C) 觸診肌肉時會感到鬆軟無力","(D) 叩診病變處裡的關節反射減低"],"answer":2,"image":""},{"id":"nr4-108-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"王小弟，8歲，罹患細菌性腦膜炎（bacterial meningitis），下列徵象何者正確？","options":["(A) 巴氏徵象（Barlow's sign）陰性","(B) 布魯金斯基氏徵象（Brudzinski's sign）陽性","(C) 克爾尼格氏徵象（Kernig's sign）陰性","(D) 反彈性疼痛（Rebounding pain）陽性"],"answer":1,"image":""},{"id":"nr4-108-2-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"有關腰椎穿刺之敘述，下列何者錯誤？","options":["(A) 可做為檢查、診斷或治療途徑","(B) 採俯臥平躺，以利穿刺針頭插入，避免傷害","(C) 穿刺後宜觀察中樞神經系統感染、脊髓脫出等合併症","(D) 穿刺後應教導平躺4～6小時，避免頭痛等合併症"],"answer":1,"image":""},{"id":"nr4-109-1-1","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"有關「母嬰親善醫院」認證評鑑的標準，下列何者正確？","options":["(A) 每次哺餵後可餵新生兒少許開水，以免奶水殘留口中導致感染","(B) 新生兒若飢餓哭泣會吃入空氣影響母乳哺餵量，應給予奶嘴防止哭泣","(C) 鼓勵母親哺餵母乳，白天每2～3小時哺餵，夜間每3～4小時哺餵","(D) 懷孕時便應知道哺餵母乳的好處，產後安排母嬰立即接觸"],"answer":3,"image":""},{"id":"nr4-109-1-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"具有伸展會陰部肌肉功用的產前運動項目，下列何者最相關？","options":["(A) 扭轉骨盆運動","(B) 大腿伸展運動","(C) 蹲踞運動","(D) 抬腿運動"],"answer":2,"image":""},{"id":"nr4-109-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"孕婦對懷孕產生負向感覺，並隨著妊娠進展會擔心胎兒是否斷手斷腳或是有缺陷，此為那一孕期最常見的心理反應？","options":["(A) 第一妊娠期","(B) 第二妊娠期","(C) 第三妊娠期","(D) 第四妊娠期"],"answer":2,"image":""},{"id":"nr4-109-1-4","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"羊膜穿刺術理想檢測時間為懷孕16～18週，下列何者不是考量此時間點檢測的主要原因？","options":["(A) 此時期足夠羊水量，約200 mL","(B) 此時α 胎兒蛋白（AFP）分泌濃度最高","(C) 子宮已上升至恥骨聯合之上，易操作","(D) 羊水中存活細胞比率最大，易培養"],"answer":1,"image":""},{"id":"nr4-109-1-5","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"有關胎兒發育之敘述，下列何者錯誤？","options":["(A) 懷孕第4週開始有心跳","(B) 懷孕第8週所有器官都形成","(C) 懷孕第16週眼睛可感受到外界光線","(D) 懷孕第20週有規律的睡眠和活動"],"answer":2,"image":""},{"id":"nr4-109-1-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"一位第三孕期婦女，飲食為蛋奶素，有關孕期飲食指導，下列何者錯誤？","options":["(A) 需額外增加維生素E攝取，促進紅血球發育","(B) 應攝取多醣類食物，避免吃單醣類","(C) 此孕期仍應補充葉酸，故應多吃深綠色蔬菜","(D) 比第二孕期鐵劑補充量增加二倍，以助嬰兒出生後使用"],"answer":0,"image":""},{"id":"nr4-109-1-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"懷孕35週婦女，走路時感到鼠蹊部痛，主要是那一條子宮韌帶受影響？","options":["(A) 闊韌帶","(B) 圓韌帶","(C) 主韌帶","(D) 子宮骶骨韌帶"],"answer":1,"image":""},{"id":"nr4-109-1-8","subject":"nr4","topic":"產科-高危險妊娠","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"懷孕28週婦女，羊水指數（AFI）小於5公分，表示胎兒可能出現下列何種情況？","options":["(A) 水腦","(B) 胎兒過重","(C) 食道閉鎖","(D) 子宮內生長遲滯"],"answer":3,"image":""},{"id":"nr4-109-1-9","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"王女士懷孕38週，胎位為左枕前位（LOA），胎心音的測量最合宜的部位為？","options":["(A) 右側臍棘線中點","(B) 左側臍棘線中點","(C) 肚臍與恥骨連合線上中點","(D) 腸骨兩側"],"answer":1,"image":""},{"id":"nr4-109-1-10","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"有關生產疼痛理論，下列描述何者正確？","options":["(A) 待產時腹部輕撫按摩法是利用條件反射理論","(B) Read醫師提出害怕、緊張與疼痛條件反射理論","(C) 呼吸放鬆技巧利用條件反射理論來減輕分娩時的疼痛","(D) 待產時集中注意力與意象法是利用條件反射理論"],"answer":2,"image":""},{"id":"nr4-109-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"待產婦女陰道檢查結果為station +1，表示先露部位位於何處？","options":["(A) 坐骨棘連線上1公分","(B) 會陰部下1公分","(C) 會陰部上1公分","(D) 坐骨棘連線下1公分"],"answer":3,"image":""},{"id":"nr4-109-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"第二產程胎頭娩出時，為了減少會陰部撕裂傷，下列措施何者較不適當？","options":["(A) 請產婦哈氣","(B) 請產婦採喘息呼吸","(C) 讓產婦採側躺","(D) 將產婦臀部墊高"],"answer":3,"image":""},{"id":"nr4-109-1-13","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"下列何者是產婦待產時的危險徵象？","options":["(A) 子宮頸口擴張至4公分破水","(B) 現血增加","(C) 臍繞頸一圈","(D) 羊水中有胎便"],"answer":3,"image":""},{"id":"nr4-109-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"李女士每1分鐘子宮收縮一次，每次持續50秒，子宮頸口全開，變薄程度100%，胎兒先露部位高度為＋2，有強烈想用力的感覺。當子宮收縮時，下列的護理指導何者最恰當？","options":["(A) 告知不要喊叫","(B) 採持續長時間閉氣用力法","(C) 打開聲門用力法","(D) 腹式呼吸"],"answer":2,"image":""},{"id":"nr4-109-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"有關待產時胎心音之監測，下列敘述何者錯誤？","options":["(A) 持續性胎心音監測可大幅降低新生兒周產期死亡率","(B) 持續性胎心音監測可能增加剖腹產率","(C) 低危險妊娠建議採間歇性的胎心音監測","(D) 高危險妊娠第一產程應每15分鐘記錄胎心音一次"],"answer":0,"image":""},{"id":"nr4-109-1-16","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"李女士，子宮頸口開4公分，擬採腰椎硬脊膜外阻斷麻醉。護理師先行給予林格氏液Lactated Ringer’s solution 500 c.c.，其維持靜脈輸液的主要目的是：","options":["(A) 減輕噁心嘔吐","(B) 預防血壓過低","(C) 減輕頭痛現象","(D) 加速產程進展"],"answer":1,"image":""},{"id":"nr4-109-1-17","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"承上題，第二產程用力時，胎心率出現早發性減速的原因為何？","options":["(A) 胎頭受壓","(B) 胎兒缺氧","(C) 臍帶受壓","(D) 子宮缺氧"],"answer":0,"image":""},{"id":"nr4-109-1-18","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"有關WHO的成功母乳哺育十措施中母嬰肌膚接觸之敘述，下列何者錯誤？","options":["(A) 母嬰肌膚接觸時應監測新生兒血氧濃度或膚色情況","(B) 鼓勵母嬰肌膚接觸時間至少1小時","(C) 當出現尋乳徵象時，可嘗試第一次餵奶","(D) 剖腹產後不應進行母嬰肌膚接觸"],"answer":3,"image":""},{"id":"nr4-109-1-19","subject":"nr4","topic":"產科-產後照護","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"林女士G2P2，採陰道分娩，產後第1天，觸診子宮偏軟，位置與肚臍同高並偏向右側，此時優先的護理評估項目為何？","options":["(A) 解尿情形","(B) 大便次數","(C) 進食狀況","(D) 會陰傷口"],"answer":0,"image":""},{"id":"nr4-109-1-20","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"有關待產的麻醉藥物減痛之敘述，下列何者正確？","options":["(A) 目前剖腹產常使用全身麻醉方式","(B) 腰椎硬膜外麻醉法施用於子宮頸口擴張2公分時","(C) 腰椎硬膜外麻醉法需要注意呼吸抑制及高血壓現象","(D) 腰椎硬膜外麻醉法針頭刺入部位為L3-4"],"answer":3,"image":""},{"id":"nr4-109-1-21","subject":"nr4","topic":"產科-產後照護","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"產後6～10天心跳次數較孕前減緩，最可能的原因為何？","options":["(A) 心輸出量增加","(B) 心臟負荷增加","(C) 產後出血","(D) 腹壓增加"],"answer":0,"image":""},{"id":"nr4-109-1-22","subject":"nr4","topic":"產科-產後照護","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"有關哺餵母乳婦女產後排卵與月經之生理變化，下列敘述何者正確？","options":["(A) 泌乳素抑制濾泡刺激素而抑制排卵","(B) 哺餵母乳婦女子宮復舊時，月經也差不多恢復","(C) 月經延後發生，表示排卵也延後","(D) 純哺餵母乳會延後排卵"],"answer":3,"image":""},{"id":"nr4-109-1-23","subject":"nr4","topic":"產科-產後照護","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"有關產後泌尿系統的變化，下列敘述何者錯誤？","options":["(A) 會陰傷口或裂傷使產婦對膀胱漲滿的敏感度減低","(B) 產後12～24小時會藉利尿作用將孕期積聚過多的液體排出","(C) 產後2～3天尿量可高達一天3,000 c.c.","(D) 產後第10天尿量開始恢復正常"],"answer":3,"image":""},{"id":"nr4-109-1-24","subject":"nr4","topic":"產科-產後照護","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"胎盤娩出後，腦下垂體前葉分泌何者使乳房開始分泌乳汁？","options":["(A) 催產素","(B) 泌乳素","(C) 動情素","(D) 黃體素"],"answer":1,"image":""},{"id":"nr4-109-1-25","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"有關RU486（mifepristone）的臨床治療，下列何者錯誤？","options":["(A) 是黃體素的拮抗劑，須由醫師開立處方簽","(B) 在懷孕6週前服用，成功率最高","(C) 可帶藥物回家服用，須於1～2週內回診檢查","(D) 與前列腺素合併使用，成功率可達95%"],"answer":2,"image":""},{"id":"nr4-109-1-26","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"Apgar score計分表的評估項目不包含下列那一項？","options":["(A) 心跳速率","(B) 肌肉張力","(C) 皮膚顏色","(D) 血氧濃度"],"answer":3,"image":""},{"id":"nr4-109-1-27","subject":"nr4","topic":"兒科-高危險新生兒","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"糖尿病孕婦所產下體重過重的嬰兒（出生體重在4,000公克以上）容易在出生後發生低血糖的狀況，主要原因可能是：","options":["(A) 新生兒出生後無法釋放足夠的胰島素，葡萄糖調節失控所致","(B) 新生兒出生後仍保留從母親獲得的大量葡萄糖，胰島素迅速分泌增加所致","(C) 母親供應的葡萄糖出生後中斷，新生兒體內存在過多的胰島素快速消耗葡萄糖所致","(D) 新生兒剛出生，還沒有開始進食大量奶水，體內葡萄糖容量不足所致"],"answer":2,"image":""},{"id":"nr4-109-1-28","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"下列何者為新生兒黃疸照光治療的原理？","options":["(A) 能讓未結合型膽紅素因光之熱能而加速排出體外","(B) 能將未結合型膽紅素異構化使其容易排出體外","(C) 能將未結合型膽紅素在肝臟中解體後排出體外","(D) 能加速肝臟合成尿甘酸轉化酶與未結合型膽紅素結合"],"answer":1,"image":""},{"id":"nr4-109-1-29","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"剛出生的女嬰出現假性月經與母親那一個荷爾蒙中斷有關？","options":["(A) 黃體素","(B) 雌性素","(C) 胰島素","(D) 醛固酮"],"answer":1,"image":""},{"id":"nr4-109-1-30","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"有關新生兒毒性紅斑與膿疱之敘述，下列何者正確？","options":["(A) 毒性紅斑需要注意與治療","(B) 毒性紅斑通常在出生後最初的4天內發生","(C) 膿疱不具傳染性，可能很快就消失","(D) 膿疱通常是感染大腸桿菌所造成"],"answer":1,"image":""},{"id":"nr4-109-1-31","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"張女士目前子宮頸口開6公分，每10分鐘宮縮2次，每次持續20秒，宮縮壓力10mmHg，產程已持續3小時無進展。張女士顯得疲累，胎心音正常，下列臨床處置何者正確？","options":["(A) 準備剖腹產","(B) 給予止痛藥","(C) 輸注Ritodrine（Yutopar）","(D) 輸注催產素"],"answer":3,"image":""},{"id":"nr4-109-1-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"孕婦早期破水的評估與處置，下列何者錯誤？","options":["(A) 觀察陰道分泌物的顏色及味道","(B) 監測白血球及C反應蛋白的變化","(C) 盡量減少陰道內診次數，以降低感染機會","(D) 確認懷孕34～36週者胎兒的成熟度，如已成熟即可剖腹產"],"answer":3,"image":""},{"id":"nr4-109-1-33","subject":"nr4","topic":"產科-產後照護","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"丁女士在產後10天惡露量突然變多且呈紅色，到門診產後檢查後確立為子宮復舊不全，造成子宮復舊不全的主要原因為何？","options":["(A) 胎膜殘留","(B) 胎盤碎片殘留","(C) 子宮張力不全","(D) 骨盆感染"],"answer":1,"image":""},{"id":"nr4-109-1-34","subject":"nr4","topic":"產科-產後照護","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"有關產褥感染，下列何者正確？①其定義是產後任2天體溫在38℃或38℃以上 ②最常見的細菌為陰道內的細菌，例如B群鏈球菌 ③以腸胃道感染最常見 ④每天至少需2,500～3,000毫升的水分攝入","options":["(A) ①②","(B) ②③","(C) ③④","(D) ②④"],"answer":3,"image":""},{"id":"nr4-109-1-35","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"有關萎縮性陰道炎之敘述，下列何者錯誤？","options":["(A) 常見於更年期後或卵巢切除婦女","(B) 因黃體素缺乏使陰道黏膜萎縮、上皮變薄","(C) 陰道酸鹼度增高有利於其他菌種生長","(D) 主要症狀為陰道分泌物、外陰搔癢與刺痛"],"answer":1,"image":""},{"id":"nr4-109-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"有關不孕症夫妻性生活的護理指導，下列敘述何者錯誤？","options":["(A) 排卵期前後每天行房以提高受孕機會","(B) 性交後墊枕頭抬高女性之臀部","(C) 鼓勵夫妻互相溝通彼此的感受與需要","(D) 排卵期黏液會由黏稠變稀薄、由少量變多量"],"answer":0,"image":""},{"id":"nr4-109-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"有關陰道感染的護理措施，下列何者正確？","options":["(A) 念珠菌陰道炎治療需停用口服避孕藥、抗生素與類固醇","(B) 滴蟲陰道炎治療期間完全禁止性行為","(C) 披衣菌陰道炎患者的性伴侶不需特別治療","(D) 依醫囑給予披衣菌陰道炎患者Gentamycin抗生素治療"],"answer":0,"image":""},{"id":"nr4-109-1-38","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"有關子宮內膜癌之敘述，下列何者正確？","options":["(A) 長期使用黃體素是危險因子之一","(B) 常見的症狀表現是下腹疼痛","(C) 治療方式以化學治療為主","(D) 晚停經的婦女較易發生"],"answer":3,"image":""},{"id":"nr4-109-1-39","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"有關子宮頸抹片檢查之敘述，下列何者正確？","options":["(A) 全民健保提供35歲以上婦女1年一次免費檢查","(B) 不論有無性經驗的婦女，每3年至少接受一次子宮頸抹片檢查","(C) 檢查前需先沖洗陰道，以避免分泌物過多，影響結果","(D) 是目前預防子宮頸癌最好方式"],"answer":3,"image":""},{"id":"nr4-109-1-40","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"有關更年期的賀爾蒙變化，下列何者正確？","options":["(A) 濾泡激素（FSH）下降；黃體生成素（LH）下降","(B) 濾泡激素（FSH）下降；黃體生成素（LH）上升","(C) 濾泡激素（FSH）上升；黃體生成素（LH）下降","(D) 濾泡激素（FSH）上升；黃體生成素（LH）上升"],"answer":3,"image":""},{"id":"nr4-109-1-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"下列何種中毒情況適合為兒童進行催吐？","options":["(A) 小於6個月嬰兒口服藥物中毒","(B) 3歲幼兒誤食杜鵑花葉導致昏迷","(C) 4歲兒童誤食有毒磨菇","(D) 5歲兒童誤食廚房清潔劑"],"answer":2,"image":""},{"id":"nr4-109-1-42","subject":"nr4","topic":"兒科-生長發展","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"依據丹佛II嬰幼兒發展篩檢測驗（DDST-II）評估來健兒門診的王小妹，她能自己扣鈕釦、用手指夾葡萄乾、單腳站立5秒鐘，王小妹大約是幾歲？","options":["(A) 1～1.5歲","(B) 2～2.5歲","(C) 3～3.5歲","(D) 4～4.5歲"],"answer":3,"image":""},{"id":"nr4-109-1-43","subject":"nr4","topic":"兒科-生長發展","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"根據羅文費（ViktorLowenfeld）的兒童繪畫發展階段論，一般兒童從幾歲開始對塗鴉的點、線、圈等加上意義或命名？","options":["(A) 2～2.5歲","(B) 3～3.5歲","(C) 5～5.5歲","(D) 6～6.5歲"],"answer":1,"image":""},{"id":"nr4-109-1-44","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"有關護理師在醫院中運用治療性遊戲（Therapeutic play）的敘述，下列何者錯誤？","options":["(A) 透過遊戲以了解兒童內心想法，以治療其心理或行為疾病","(B) 作為溝通橋樑，可以協助了解兒童住院行為反應","(C) 具有指導性質，可協助兒童認識自己的身體或疾病","(D) 藉由角色扮演的遊戲，可同時達到學習及情緒表達的功能"],"answer":0,"image":""},{"id":"nr4-109-1-45","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"李小妹，8歲，因敗血病住進加護病房，很在意父母親是否準時到病房探視，不斷詢問護理師探病時間。李小妹的行為屬於下列何種情況？","options":["(A) 學習認識時間概念","(B) 自我中心","(C) 分離焦慮","(D) 在意身體心像"],"answer":2,"image":""},{"id":"nr4-109-1-46","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"下列何者不是瀕死兒童的生理變化？","options":["(A) 出現陳施氏呼吸型態","(B) 感覺很熱，身體卻很冰冷","(C) 視力模糊，眼睛分泌物增加","(D) 聽覺減少，對疼痛的刺激敏感"],"answer":3,"image":""},{"id":"nr4-109-1-47","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"下列何者不是腮腺炎的臨床典型症狀？","options":["(A) 發燒","(B) 食慾不振","(C) 耳朵痛","(D) 皮疹"],"answer":3,"image":""},{"id":"nr4-109-1-48","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"有關兒童氣喘（Asthma）的敘述，下列何者正確？","options":["(A) 臺灣常見的過敏原是海鮮","(B) 發作時呼吸道平滑肌舒張","(C) 與遺傳體質、環境無關","(D) IgE免疫球蛋白會增加"],"answer":3,"image":""},{"id":"nr4-109-1-49","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"林小弟，13歲，學校體檢時發現上肢血壓高，鼠蹊脈搏較上肢脈搏微弱，主訴頭痛，常常感覺腳部冰冷，林小弟可能罹患下列何種疾病？","options":["(A) 心室中隔缺損","(B) 主動脈狹窄","(C) 肺動脈瓣狹窄","(D) 大血管轉位"],"answer":1,"image":""},{"id":"nr4-109-1-50","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"有關兒童白血病的敘述，下列何者正確？","options":["(A) 兒童最常發生的是慢性骨髓性白血病","(B) 急性淋巴球性白血病好發於2～6歲兒童","(C) 發病年齡與白血病的預後無關","(D) 兒童白血病的確診檢查為腰椎穿刺"],"answer":1,"image":""},{"id":"nr4-109-1-51","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"下列何者是幼兒泌尿道感染常見的致病菌？","options":["(A) 變形桿菌屬（Proteus spp.）","(B) 腸球菌（Enterococcus）","(C) 克雷白氏桿菌屬（Klebsiella spp.）","(D) 大腸桿菌（E. coli）"],"answer":3,"image":""},{"id":"nr4-109-1-52","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"丁丁，2歲，診斷為水腦，並接受腦室－腹膜分流術（V-P shunt），現已術後第5天，今早丁丁哭鬧不喝奶，測得體溫達38.2℃、血壓為100/60 mmHg，有關護理評估，下列何者需優先執行？","options":["(A) 疼痛評估","(B) 意識評估","(C) 感染評估","(D) 營養評估"],"answer":2,"image":""},{"id":"nr4-109-1-53","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"小明，3歲，被機車撞倒，頭部受傷，有關腦壓增高的早期臨床表徵，不包括下列何者？","options":["(A) 痙攣、頭痛","(B) 斜眼、複視","(C) 噴射狀嘔吐","(D) 瞳孔大小不對稱"],"answer":3,"image":""},{"id":"nr4-109-1-54","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"協助病童接受腰椎穿刺檢查過程中，下列護理措施何者不恰當？","options":["(A) 穿刺前應仔細評估病童有無顱內壓升高之徵象","(B) 穿刺時協助病童採半側臥、頭高腳低的舒適臥位","(C) 穿刺前後應監測病童是否有脊髓脫出的症狀產生","(D) 穿刺後教導病童平躺以減少頭痛及穿刺部位出血"],"answer":1,"image":""},{"id":"nr4-109-1-55","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"小美，3歲，因重積癲癇而入住加護病房照護，下列何者不是以家庭為中心的照護？","options":["(A) 評估小美個別需求，提供父母彈性的探訪時間","(B) 在父母有意願的情況下，讓其參與小美侵入性治療及檢查過程","(C) 由於治療的複雜性，應避免父母參與治療計畫與決策","(D) 專業醫護人員隨時跟小美的父母分享資訊，包含相關的科學新知"],"answer":2,"image":""},{"id":"nr4-109-1-56","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"小銘，2歲，罹患典型的異戊酸血症（Isovaleric Acidemia），下列敘述何者正確？","options":["(A) 小銘的疾病是一種有機酸代謝異常的體染色體顯性遺傳疾病","(B) 大量的異戊酸堆積在體內，小銘的尿液會有明顯的臭腳汗味","(C) 小銘急性發作時主要的醫療處置是矯正脫水及呼吸性鹼中毒","(D) 小銘可以攝取特殊配方奶，並逐漸增加肉鹼（carnitine）攝取量"],"answer":1,"image":""},{"id":"nr4-109-1-57","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"小春，國中3年級，1年前被診斷罹患青少年憂鬱症，曾服用fluoxetine及ativan治療。最近因會考在即，課業壓力導致失眠，情緒常常不穩定，今在家忽然情緒失控，故至醫院求治，醫師表示可能憂鬱症再發，需再服藥治療。母親詢問護理師應該要怎麼做對小春最好，下列回答何者為佳？","options":["(A) 多給予小春獨處的空間，及提供獨立思考的時間","(B) 如果服藥後有嗜睡的副作用則可先停藥，避免影響功課","(C) 可幫小春請家教或上補習班，幫助小春成績進步以減少壓力","(D) 可多陪伴小春，鼓勵到戶外曬太陽與進行規律運動"],"answer":3,"image":""},{"id":"nr4-109-1-58","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"有關兒童罹患自閉症會出現的身心表徵，下列何者錯誤？","options":["(A) 出現不理人，不看人等，對人缺乏反應的現象","(B) 出現鸚鵡式仿說或答非所問","(C) 遊戲玩法單調缺變化，出門走一定路線","(D) 身體及眼球經常出現不自主擺動"],"answer":3,"image":""},{"id":"nr4-109-1-59","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"小英，5個月，採心尖脈測量心跳，有關心尖脈位置之敘述，下列何者正確？","options":["(A) 左鎖骨中線與第一、二肋骨的交會處","(B) 左鎖骨中線與第三、四肋骨的交會處","(C) 左鎖骨中線與第五、六肋骨的交會處","(D) 左鎖骨中線與第七、八肋骨的交會處"],"answer":1,"image":""},{"id":"nr4-109-1-60","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"有關兒童住院壓力，下列敘述何者錯誤？","options":["(A) 嬰兒住院，最主要的壓力源是與父母分離","(B) 幼兒會以合理化方式，來因應其住院帶來的限制","(C) 學齡前期兒童常誤解其住院原因，而出現罪惡感","(D) 學齡期兒童可以理解生病的原因是來自外在的"],"answer":1,"image":""},{"id":"nr4-109-1-61","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"護理師為6個月大嬰兒進行肌肉注射，下列處理方式何者最適當？","options":["(A) 告訴他可以哭，不可以亂動","(B) 請母親暫時離開注射環境","(C) 盡速完成治療過程，減少疼痛刺激的時間","(D) 用鼓勵的方式，答應注射後給予獎勵"],"answer":2,"image":""},{"id":"nr4-109-1-62","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"小群目前3個月大，因膽道閉鎖未治療造成肝臟硬化、脾腫大、肝昏迷，有關提供小群的家屬家庭支持，下列敘述何者不適當？","options":["(A) 與小群的家屬溝通時，將會談的焦點放在他們關心的事情上","(B) 主動多次提及並討論未能於小群出生時及早發現膽道閉鎖的原由","(C) 陪伴並鼓勵表達所承受的痛苦，以同理心傾聽家屬的焦慮","(D) 言談中流露對小群的真誠關懷，且願意提供訊息與資源"],"answer":1,"image":""},{"id":"nr4-109-1-63","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"新生兒曾暴露於巨細胞病毒、德國麻疹等感染源中，下列那一種抗體濃度會升高？","options":["(A) γ 球蛋白","(B) IgG","(C) IgA","(D) IgM"],"answer":3,"image":""},{"id":"nr4-109-1-64","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"小明，2個月大，罹患後天免疫缺乏症候群，有關預防接種的敘述，下列何者錯誤？","options":["(A) 小兒麻痺疫苗建議不可口服沙賓疫苗","(B) 終生不可接種b型流行性感冒嗜血桿菌疫苗","(C) B型肝炎、肺炎雙球菌疫苗均可按時接種","(D) 免疫功能低下，則不予接種水痘疫苗"],"answer":1,"image":""},{"id":"nr4-109-1-65","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"臺灣安寧緩和醫療條例保障不可治癒之臨終末期病人的醫療意願，有關兒童安寧緩和醫療照護，下列敘述何者錯誤？","options":["(A) 家屬簽署“不施行心肺復甦術同意書”前，建議能夠和病童充分溝通","(B) 依照病童的年齡可利用繪本故事共同討論他們對死亡的概念","(C) 父母在病童臨終時，依照病童體力可負荷狀況盡力滿足病童的心願","(D) 兒童安寧緩和醫療不宜於兒童癌症診斷確立時即介入"],"answer":3,"image":""},{"id":"nr4-109-1-66","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"小瑋，6歲，罹患膽道閉鎖，多年來等不到肝臟移植，面臨死亡，父母在與小瑋討論死亡時，下列敘述何者錯誤？","options":["(A) 僅提及快樂的事情，避免引發哀傷反應，以減輕小瑋焦慮","(B) 小瑋主動提及死亡時，父母應認真回應，不要虛張聲勢","(C) 問問小瑋：「你的想法呢？」，使小瑋有機會說自己對死亡的想法","(D) 父母與小瑋主動分享自己面對死亡的感受"],"answer":0,"image":""},{"id":"nr4-109-1-67","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"有關兒童疼痛之敘述，下列何者錯誤？","options":["(A) 3～5歲的兒童尚無法以語言表達出疼痛的程度","(B) 護理師可經由觀察或各種疼痛量表來評估兒童疼痛情形","(C) 新生兒會以全身身體活動來反應其疼痛","(D) 兒童疼痛的處理，經評估後，可依照醫囑給予止痛藥物"],"answer":0,"image":""},{"id":"nr4-109-1-68","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"有關4歲兒童使用集尿袋收集常規尿液標本，下列敘述何者正確？","options":["(A) 需以優碘藥水消毒兒童會陰處","(B) 需遵守無菌技術操作原則收集尿液","(C) 女童先黏貼恥骨聯合處，再向下黏至肛門肌肉","(D) 男童盡可能將陰莖與陰囊放入集尿袋"],"answer":3,"image":""},{"id":"nr4-109-1-69","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"王小妹，1歲，因感冒、發燒、左耳痛而就診，被診斷為急性中耳炎，下列護理措施何者較適當？","options":["(A) 避免藥物成癮，衛教少服止痛藥","(B) 清潔耳道時，耳朵宜向下向後拉","(C) 休息時宜採側右臥姿，以免壓迫左耳","(D) 避免產生抗藥性，衛教若無症狀，其抗生素即可自行停藥"],"answer":1,"image":""},{"id":"nr4-109-1-70","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"張小弟，5個月大，因呼吸喘、痰液多而入院，診斷為細支氣管炎（Bronchiolitis），入院後需抽痰，有關抽痰護理的敘述下列何者正確？","options":["(A) 抽痰順序宜先由口腔開始，再到鼻腔","(B) 抽痰前後宜給予適當的氧氣吸入，以避免缺氧情形","(C) 抽吸時間最好維持在12～15秒之間，以預防缺氧情形","(D) 抽吸壓力維持在110～130 mmHg"],"answer":1,"image":""},{"id":"nr4-109-1-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"正常情況下，兒童心臟血管的含氧量下列何處最高？","options":["(A) 肺靜脈","(B) 肺動脈","(C) 上腔靜脈","(D) 右心房"],"answer":0,"image":""},{"id":"nr4-109-1-72","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"王小妹，5歲，罹患心房中隔缺損，進行心導管檢查。有關心導管檢查後的護理措施，下列敘述何者正確？","options":["(A) 右心導管檢查後需臥床4～6小時","(B) 穿刺肢體保持彎曲，有利止血","(C) 檢查後應持續禁食6小時，再開始嘗試液體食物","(D) 返家後應至少3天不要洗澡，避免感染"],"answer":0,"image":""},{"id":"nr4-109-1-73","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"罹患開放性動脈導管的病童，較不會出現下列何種症狀？","options":["(A) 心搏過快","(B) 肺動脈高壓","(C) 紅血球增多症","(D) 餵食困難"],"answer":2,"image":""},{"id":"nr4-109-1-74","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"下列何者血液疾病不屬於體染色體隱性遺傳？","options":["(A) A型血友病（hemophilia）","(B) 范康尼氏症候群（Fanconi’s syndrome）","(C) 鐮狀細胞貧血（sickle cell anemia）","(D) β-海洋性貧血（β-thalassemia）"],"answer":0,"image":""},{"id":"nr4-109-1-75","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"有關威廉氏腫瘤（Wilms tumor）之可能出現的臨床表徵，下列何者錯誤？","options":["(A) 疼痛","(B) 低血壓","(C) 貧血","(D) 疲倦"],"answer":1,"image":""},{"id":"nr4-109-1-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"小珍，8歲，第1型糖尿病病童。幾天來出現噁心、嘔吐、易口渴症狀，現因呼吸、心跳快且深而到 ++ 急診。Blood sugar 780 mg/dL、K：5.0 mEq/L、Na：138 mEq/L、Urine sugar 3+、ketone+。由上述症狀評估小珍可能出現的問題為：","options":["(A) 高滲透壓高血糖狀態","(B) 低滲透壓高血糖狀態","(C) 糖尿病酮酸症","(D) 低血糖性休克反應"],"answer":2,"image":""},{"id":"nr4-109-1-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"王小妹，7歲，被診斷泌尿道感染（UrinaryTractInfection），出院時醫囑開立7天份的口服抗生素amoxicilline，下列護理指導何者適當？","options":["(A) 解尿無疼痛或無灼熱感，即可停藥","(B) 尿量增加，尿液清澈，即可停藥","(C) 藥物吃完，完成治療，即可避免復發","(D) 藥物吃完，需回診追蹤及檢查尿液"],"answer":3,"image":""},{"id":"nr4-109-1-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"有關隱睪症（cryptorchidism），下列敘述何者錯誤？","options":["(A) 胎兒7個月時睪丸應已進入陰囊","(B) 早產兒發生隱睪症的機率高於足月兒","(C) 出生後一年內未下降的睪丸可能會自動下降","(D) 臨床醫療處置以手術或荷爾蒙治療為主"],"answer":0,"image":""},{"id":"nr4-109-1-79","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"有關先天性巨結腸症（congenital megacolon）之臨床表徵，下列敘述何者錯誤？","options":["(A) 新生兒胎便延遲排出","(B) 嘔吐物不含膽汁","(C) 嬰幼兒慢性便秘","(D) 嬰幼兒生長遲滯"],"answer":1,"image":""},{"id":"nr4-109-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"有關腦性麻痺（cerebral palsy）的敘述，下列何者正確？","options":["(A) 由濾過性病毒經由口或飛沫傳染，侵犯脊髓灰白質","(B) 治療目標在增進運動功能和預防殘障加重","(C) 吞嚥困難時，協助頭部維持正中位置，將食物放在舌頭前方，以利吞嚥","(D) 病童主要問題為肢體障礙，大部分兒童的智能是屬於正常的"],"answer":1,"image":""},{"id":"nr4-109-2-1","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"護理師於婦女產後經由電話協助母親解決哺乳問題，屬於下列何種角色？","options":["(A) 照顧者","(B) 管理者","(C) 研究者","(D) 諮詢者"],"answer":3,"image":""},{"id":"nr4-109-2-2","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"有關以家庭為中心的產科照護，下列何者錯誤？","options":["(A) 鼓勵配偶與新生兒手足參與生產過程","(B) 推廣親子同室增加新生兒與家庭成員互動","(C) 鼓勵儘早出院與家人團聚","(D) 提供完全相同的產科常規照護以符合評鑑要求"],"answer":3,"image":""},{"id":"nr4-109-2-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"鄭女士因月經過期8週而至門診驗孕，她已有一對雙胞胎子女，曾於懷孕8週時胚胎因無胎心音而入院接受中止妊娠術，此次門診確認鄭女士已懷孕，因此其孕產史紀錄，下列何項正確？","options":["(A) G4P2","(B) G3P1SA1","(C) G3P1AA1","(D) G4P2AA1"],"answer":2,"image":""},{"id":"nr4-109-2-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"懷孕期間因雌性素（estrogen）所造成的生殖系統變化，下列何者錯誤？","options":["(A) 子宮頸黏液塞形成","(B) 陰道的血管增生、充血","(C) 懷孕初期子宮頸變軟","(D) 懷孕後期子宮壁變薄"],"answer":3,"image":""},{"id":"nr4-109-2-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"一位孕前BMI為23.1 kg/m2的單胞胎孕婦，有關其孕期體重之護理指導，下列何者最適當？","options":["(A) 第一孕期如體重未增加，需要增加熱量攝取","(B) 第二孕期，體重增加每個月應少於1公斤","(C) 第三孕期，每個月體重增加可控制在1. 5～2.0公斤之間","(D) 整個孕期體重需增加控制在7～10公斤範圍內"],"answer":2,"image":""},{"id":"nr4-109-2-6","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"有關生產計畫書，下列敘述何者不適當？","options":["(A) 計畫書可包括待產、分娩和寶寶照護項目之選擇","(B) 計畫書可包括生產流程與常規的說明","(C) 讓婦女和醫護人員討論，兩者共同做決定","(D) 鼓勵婦女表達其擔憂與需要"],"answer":2,"image":""},{"id":"nr4-109-2-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"懷孕28週婦女參加產前媽媽教室，練習母乳哺餵姿勢和嬰兒沐浴，此為下列何種母性認同行為之表現？","options":["(A) 角色扮演","(B) 模仿學習","(C) 內射－接受","(D) 幻想－外射"],"answer":0,"image":""},{"id":"nr4-109-2-8","subject":"nr4","topic":"產科-高危險妊娠","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"林女士28歲，孕前體重56公斤，目前懷孕20週，此次產檢體重為64公斤，血壓為148/94 mmHg，尿蛋白1+，下列護理指導何者最適當？","options":["(A) 增加脂肪攝取","(B) 減少鹽分攝取","(C) 減少蛋白質攝取","(D) 增加鈉攝取"],"answer":1,"image":""},{"id":"nr4-109-2-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"罹患妊娠糖尿病婦女，努力控制飲食，讓飯後血糖值在正常範圍，此為魯賓（Rubin）所提出何種母性任務行為？","options":["(A) 學習貢獻自己","(B) 確保自己和胎兒安全","(C) 使胎兒能被家人和重要他人所接受","(D) 與胎兒產生情感連結"],"answer":1,"image":""},{"id":"nr4-109-2-10","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"下列那個階段是胎兒體重快速增加的時期？","options":["(A) 胚胎前期","(B) 第一孕期","(C) 第二孕期","(D) 第三孕期"],"answer":3,"image":""},{"id":"nr4-109-2-11","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"有關產婦生產用力的描述，下列何者錯誤？","options":["(A) 蹲姿生產是利用地心引力來幫助產婦向下用力","(B) 產婦利用橫膈膜和腹部的肌肉來向下用力，其他肌肉放鬆，以免浪費力氣","(C) 生產閉氣用力太長容易導致產婦肺靜脈回流上升，不利胎兒產出","(D) 側躺姿勢有助於緩解向下用力的感覺，讓產婦較舒適"],"answer":2,"image":""},{"id":"nr4-109-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"有關待產婦之護理，下列敘述何者錯誤？","options":["(A) 待產時如無破水，應鼓勵產婦下床走動，促進有效宮縮","(B) 待產時應常變換姿勢，促進身體舒適與放鬆","(C) 活動期的晚期應教導待產婦開始用力，以促進胎頭下降","(D) 定期排空膀胱，促進胎頭下降"],"answer":2,"image":""},{"id":"nr4-109-2-13","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"初產婦廖女士進入產房待產，足月且孕期無其他併發症，目前每5分鐘子宮收縮一次，每次約收縮30秒，沒有破水，陰道有粉色分泌物，內診發現其子宮頸變薄80%且已擴張3公分，station0。廖女士詢問是否可以下床走動，下列回應何者較適切？","options":["(A) 我沒法做決定，妳最好去問醫師","(B) 只要妳覺得舒服，儘可下床活動","(C) 應躺在床上，以免走路活動影響子宮收縮","(D) 建議妳臥床休息，我們比較容易監測子宮收縮及胎心音"],"answer":1,"image":""},{"id":"nr4-109-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"承上題，廖女士的子宮收縮逐漸增強，陣痛越來越密且痛的持續時間較久，胎膜在此時破裂，護理師立即扶她上床，躺下後最優先執行的措施為：","options":["(A) 通知醫師","(B) 聽胎心音","(C) 計算宮縮的時間與頻率","(D) 測量血壓與脈搏"],"answer":1,"image":""},{"id":"nr4-109-2-15","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"下列何者為胎兒的先露部位和母親骨盆前後左右的關係？","options":["(A) 胎勢","(B) 胎姿","(C) 胎產式","(D) 胎位"],"answer":3,"image":""},{"id":"nr4-109-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"有關胎心率的監測，下列敘述何者錯誤？","options":["(A) 正常足月兒的胎心率範圍介於120～160 bpm","(B) 胎兒受感染時，會導致胎心率過慢","(C) 胎心率基準線指監測10分鐘以上兩次宮縮間的胎心率","(D) 正常足月兒的胎心率變異性約在6～10 bpm"],"answer":1,"image":""},{"id":"nr4-109-2-17","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"下列何者為子宮收縮頻率（frequency）的定義？","options":["(A) 子宮收縮時所持續增加的壓力","(B) 一次子宮收縮開始到下次宮縮開始之時間","(C) 子宮收縮結束之後的平靜期","(D) 每次子宮收縮的開始到結束之時間"],"answer":1,"image":""},{"id":"nr4-109-2-18","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"產婦進入待產過程中，護理師協助陰道內診，無法獲得下列何項資料？","options":["(A) 子宮頸厚薄","(B) 子宮頸擴張","(C) 胎頭下降程度","(D) 胎兒大小"],"answer":3,"image":""},{"id":"nr4-109-2-19","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"陰道生產的產後第二天，評估子宮底呈堅硬狀，位置在肚臍以下2公分，惡露呈紅色且小量，此時最適當的護理指導為何？","options":["(A) 教導按摩子宮底至鬆軟狀","(B) 解釋為子宮復舊正常現象","(C) 給予誘尿","(D) 通知醫師處理"],"answer":1,"image":""},{"id":"nr4-109-2-20","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"有關產後痛（after pain）的護理，下列何者錯誤？","options":["(A) 通常在第三天後疼痛日益嚴重","(B) 臨床常以10分法進行疼痛評估","(C) 鼓勵適度活動","(D) 教導深呼吸緩解"],"answer":0,"image":""},{"id":"nr4-109-2-21","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"王女士剖腹產後第一天，主訴腹部疼痛。評估美容膠覆蓋之傷口無滲液，腹部叩診鼓音，子宮收縮良好，惡露色紅量少無異味，下列何項護理措施最優先？","options":["(A) 因惡露量少，建議洗澡保持會陰清潔即可","(B) 告知傷口美容膠不可弄濕，需每日清潔與更換","(C) 鼓勵多喝水吃高纖維食物，以利腸蠕動","(D) 協助翻身與下床，避免進食產氣食物"],"answer":3,"image":""},{"id":"nr4-109-2-22","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"陳先生初次當爸爸，從未參與新生兒照護，表示：「不要抱妹妹給我，她軟軟的，我不敢抱。」下列敘述何者最適當？","options":["(A) 告知很多爸爸第一次會怕，之後習慣就好了","(B) 鼓勵循序漸進，先撫觸嬰兒後再教導抱嬰兒技巧","(C) 尊重陳先生害怕的感受，改由產婦全權照顧嬰兒","(D) 嬰兒照護為父母雙方責任，衛教陳先生嬰兒照顧技巧"],"answer":1,"image":""},{"id":"nr4-109-2-23","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"劉女士剖腹產後因身體不適，且寶寶黃疸需住院照光治療而無法一同出院，她覺得自己不是好媽媽。下列何項措施對其親子依附關係的建立較不適當？","options":["(A) 評估劉女士對自己身體復原與對寶寶照護的擔心","(B) 為避免感染，新生兒住院期間不鼓勵媽媽探訪","(C) 運用產婦的支持資源，讓產婦能將心力放在新生兒身上","(D) 鼓勵產婦與新生兒有眼對眼及身體上的接觸"],"answer":1,"image":""},{"id":"nr4-109-2-24","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"有關產後婦女生理復舊變化之敘述，下列何者正確？","options":["(A) 產後初期有利尿現象，可將身體組織囤積過多的液體排出體外","(B) 生產過度用力或脫水，產後體溫會上升至38℃，持續約2～3天","(C) 產後脈搏速率會增快至100次／分，於產後3～7天恢復正常","(D) 產後初期腹肌鬆弛，腹壓減少，使得腸蠕動增快，而有輕瀉現象"],"answer":0,"image":""},{"id":"nr4-109-2-25","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"有關母乳之敘述，下列何者正確？","options":["(A) 後奶（hindmilk）較白，富含脂肪，熱量較前奶高","(B) 前奶（foremilk）清淡，富含酪蛋白","(C) 嬰兒吸食前奶才能得到足夠的營養及水分","(D) 母乳哺餵時，仍需補充水分給嬰兒"],"answer":0,"image":""},{"id":"nr4-109-2-26","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"有關產後生殖器官的復舊過程，下列何者正確？","options":["(A) 每天以相同進展恢復","(B) 子宮體積縮小屬於退行性變化","(C) 三種型態的惡露採循環的方式排出","(D) 大約持續6個月完成"],"answer":1,"image":""},{"id":"nr4-109-2-27","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"有關新生兒身體評估結果，下列何者異常？","options":["(A) 出生時，鼻頭有粟粒疹","(B) 出生1～3天左右，身體表面出現毒性紅斑","(C) 頭圍35公分","(D) 舌頭上有凝乳塊狀的白色斑點"],"answer":3,"image":""},{"id":"nr4-109-2-28","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"有關足月新生兒身體成熟度評估，下列特徵何者錯誤？","options":["(A) 皮膚乾裂，且幾乎看不見血管","(B) 乳暈平坦無突起","(C) 耳軟骨堅硬成形，用手彎凹後放開可立即反彈","(D) 眼瞼張開"],"answer":1,"image":""},{"id":"nr4-109-2-29","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"有關神經系統反射的敘述，下列何者正確？①擁抱反射（moro reflex）是將新生兒突然改變姿勢後，四肢對稱性外展且伸直 ②尋乳反射（rootingreflex）是觸碰新生兒嘴角時出現舌頭伸出的現象，表示新生兒飢餓，應該餵食 ③巴賓斯基反射（Babinski reflex）是以手指自新生兒腳跟沿外側朝蹠趾方向刺激，新生兒腳趾會內縮 ④頸部強直反射（tonic neck reflex）是新生兒平躺時，將頭轉向一側，轉向的那一側手腳會伸展，對側會屈曲狀","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":3,"image":""},{"id":"nr4-109-2-30","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"下列何種胎產式之胎頭徑線最短，較能順利分娩？","options":["(A) 面產式","(B) 額產式","(C) 前頂產式","(D) 頭頂產式"],"answer":3,"image":""},{"id":"nr4-109-2-31","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"根據臺灣優生保健法施行細則規定，除醫療行為外，人工流產應於幾週內施行？","options":["(A) 12","(B) 20","(C) 24","(D) 28"],"answer":2,"image":""},{"id":"nr4-109-2-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"子癇前症之症狀，下列何者錯誤？","options":["(A) 高血壓","(B) 痙攣","(C) 蛋白尿","(D) 水腫"],"answer":1,"image":""},{"id":"nr4-109-2-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"有關懷孕期TORCH感染的項目，下列何者錯誤？","options":["(A) 弓形蟲病","(B) 麻疹","(C) 單純疱疹病毒","(D) 巨細胞病毒"],"answer":1,"image":""},{"id":"nr4-109-2-34","subject":"nr4","topic":"產科-孕期生理與評估","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"王女士接受試管嬰兒治療，今日抽血驗孕報告為未懷孕，王女士表示自己懷孕症狀明顯，一定是檢驗錯誤，下列護理措施何者最適當？","options":["(A) 立即連絡施術醫師解釋檢驗報告","(B) 解釋抽血報告最準確，請王女士再接再厲","(C) 衛教懷孕症狀為妊娠的主觀經驗，請王女士要努力接受現實","(D) 鼓勵王女士表達其疑問與擔憂，詢問是否需要協助聯絡配偶到院，與醫療團隊共同討論後續治療規畫"],"answer":3,"image":""},{"id":"nr4-109-2-35","subject":"nr4","topic":"產科-產後照護","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"下列何者為陰道產的產後出血定義？","options":["(A) 產後12小時內，出血超過500 c.c.","(B) 產後24小時內，出血超過500 c.c.","(C) 產後12小時內，出血超過250 c.c.","(D) 產後24小時內，出血超過250 c.c."],"answer":1,"image":""},{"id":"nr4-109-2-36","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"有關陰道瘻管，下列敘述何者正確？","options":["(A) 最常見的原因為手術傷害","(B) 甲基藍試驗是以試紙測試","(C) 治療方式以內科治療為主","(D) 病人身上經常有糞便味"],"answer":0,"image":""},{"id":"nr4-109-2-37","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"下列何者不屬於後天免疫缺乏症候群（AIDS）之伺機性感染？","options":["(A) 口腔念珠球菌感染","(B) 淋巴腺腫大","(C) 肺囊蟲肺炎","(D) 囊球菌腦脊髓膜炎"],"answer":1,"image":""},{"id":"nr4-109-2-38","subject":"nr4","topic":"產科-待產與分娩","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"陳女士G4P3，有急產之經驗，目前子宮頸開7公分，主訴一直有便意感，下列敘述何者錯誤？","options":["(A) 請她先上廁所解便，減緩不適","(B) 聯絡醫師，並準備生產之環境","(C) 陰道內診了解子宮頸口擴張情形","(D) 教導先不要用力，採吹蠟燭式呼吸法"],"answer":0,"image":""},{"id":"nr4-109-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"林女士22歲，因外陰部搔癢並有泡沫狀、黃綠色及有異味的陰道分泌物，內診時可見子宮頸上皮有草莓狀紅點，最有可能是下列何種病原感染？","options":["(A) 砂眼披衣菌","(B) 白色念珠菌","(C) 梅毒螺旋體","(D) 陰道鞭毛滴蟲"],"answer":3,"image":""},{"id":"nr4-109-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"有關毒性休克症候群之敘述，下列何者正確？","options":["(A) 多發生於經期使用衛生棉條的女性","(B) 是受到黴漿菌感染所致","(C) 臨床症狀少有發燒現象","(D) 臨床症狀為單一器官系統異常"],"answer":0,"image":""},{"id":"nr4-109-2-41","subject":"nr4","topic":"兒科-生長發展","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"小畢3歲，因為經常出現咬手、打頭、撞牆行為而就醫，醫師診斷有自閉症，護理師指導父母有關自閉症的兒童照護，下列何者錯誤？","options":["(A) 不要因為孩子診斷有自閉症，而心存罪惡感或愧疚","(B) 公平的對待孩子，不必過度關注病童而忽略其他正常孩子的教養","(C) 可嘗試帶著病童走入人群，讓其也能享有正常的社交活動","(D) 對孩子單調固定的習慣給予改變，儘量每日安排不同活動，使生活多采多姿"],"answer":3,"image":""},{"id":"nr4-109-2-42","subject":"nr4","topic":"兒科-意外事故與急症","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"下列何者較不屬於兒童遭受虐待／疏忽的常見徵象？","options":["(A) 身上有多處瘀傷痕跡","(B) 表現活潑好動行為","(C) 身體髒污發出異味","(D) 寒冬常穿短袖上學"],"answer":1,"image":""},{"id":"nr4-109-2-43","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"臺灣發展遲緩早期療育實施服務的流程，主要負責協調整合與管理的窗口為何？","options":["(A) 兒童早期療育通報轉介中心","(B) 發展遲緩兒童聯合評估中心","(C) 各縣市政府衛生局","(D) 發展遲緩兒童早期療育中心"],"answer":0,"image":""},{"id":"nr4-109-2-44","subject":"nr4","topic":"兒科-意外事故與急症","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"有關預防嬰幼兒鉛中毒，下列可減少鉛的吸收之敘述，何者錯誤？","options":["(A) 進食前應協助嬰幼兒洗手","(B) 選擇不會掉漆的安全玩具","(C) 避免攝入過多罐頭食物","(D) 多攝取富含脂肪酸的食物"],"answer":3,"image":""},{"id":"nr4-109-2-45","subject":"nr4","topic":"兒科-意外事故與急症","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"強強4歲，誤食退燒藥，至急診求治，診斷為乙醯氨基酚（acetaminophen）中毒，下列敘述何者正確？","options":["(A) 誤食後應立即給予naloxone","(B) 誤食二小時內應避免洗胃及催吐","(C) 誤食三天後開始使用活性碳吸附劑","(D) 誤食後常用的解毒劑為N-acetylcysteine（mycomyst）"],"answer":3,"image":""},{"id":"nr4-109-2-46","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"有關嬰幼兒呼吸系統的解剖生理特徵，下列何者正確？","options":["(A) 嬰幼兒舌頭在口腔所占的比例比成人小，鼻腔過濾效果較佳","(B) 嬰幼兒的咽喉較狹窄，會厭軟骨較大，比成人較易造成吸入性肺炎","(C) 嬰幼兒採腹式橫膈膜呼吸，乃因其肋骨位置較成人垂直，胸肋骨支持穩定性較小","(D) 嬰幼兒耳咽管較短、窄，呈垂直，致病菌易進入中耳，易發生感染"],"answer":1,"image":""},{"id":"nr4-109-2-47","subject":"nr4","topic":"兒科-生長發展","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"小宏足月生產，出生體重3公斤，目前3歲，下列敘述何者較不符合此年齡層的生長發展？","options":["(A) 目前體重13公斤","(B) 呼吸以胸壁肌肉為主","(C) 乳齒幾乎全部長出","(D) 大便訓練完成"],"answer":1,"image":""},{"id":"nr4-109-2-48","subject":"nr4","topic":"兒科-生長發展","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"婷婷3歲，喜歡吸吮大拇指，但是擔心被母親發現，所以總是以另一手遮掩，婷婷覺得自己隱藏得很好，別人不會發現。她的行為是下列何種認知思考特性的反應？","options":["(A) 自我為中心","(B) 去集中作用","(C) 保留概念","(D) 可逆性"],"answer":0,"image":""},{"id":"nr4-109-2-49","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"有關生命末期兒童疼痛評估和照護，下列敘述何者最不適當？","options":["(A) 病童喊痛時需給予meperidine進行止痛","(B) 利用QUESTT進行兒童疼痛評估的蒐集","(C) 儘量避免和減少不必要的侵入性治療","(D) 教導家屬利用非藥物方式轉移注意力"],"answer":0,"image":""},{"id":"nr4-109-2-50","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"當護理師為病童點眼藥水時，下列敘述何者較不適宜？","options":["(A) 使病童平躺或半坐臥，頭部後仰","(B) 將病童下眼瞼向下向外拉出成囊狀","(C) 將眼藥水輕輕滴於病童眼球處","(D) 滴藥後，以手指按壓內眥淚點約1分鐘"],"answer":2,"image":""},{"id":"nr4-109-2-51","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"小萱出生第3天，左手手臂活動受限，擁抱反射不對稱，兩肩不等高，局部觸痛及腫脹。依此觀察，小萱可能有下列何種問題？","options":["(A) 鎖骨骨折","(B) 橈骨骨折","(C) 尺骨骨折","(D) 肱骨骨折"],"answer":0,"image":""},{"id":"nr4-109-2-52","subject":"nr4","topic":"產科-新生兒護理","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"下列何者不屬於新生兒篩檢的項目？","options":["(A) 葡萄糖-6-磷酸鹽去氫酵素（G-6-PD）缺乏症","(B) 唐氏症","(C) 苯酮尿症","(D) 甲基丙二酸血症（MMA）"],"answer":1,"image":""},{"id":"nr4-109-2-53","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"王小弟經由母親垂直感染後天免疫缺乏症候群（AIDS），下列敘述何者正確？","options":["(A) 卡氏肺囊蟲肺炎為最常見的死因","(B) 王小弟的大小便會傳染病毒","(C) 王小弟不可以接種B型肝炎疫苗","(D) 王小弟可以接種卡介苗"],"answer":0,"image":""},{"id":"nr4-109-2-54","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"小莉被診斷為血小板無力症（thrombasthenia），此次入院進行首次輸血小板治療，她表示現在最害怕受到懲罰，她的發展最可能屬於下列何階段？","options":["(A) 學步期","(B) 學齡前期","(C) 學齡期","(D) 青少年期"],"answer":1,"image":""},{"id":"nr4-109-2-55","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"小琪2歲，為急性骨髓性白血病（AML）末期。有關瀕死病童的照顧，下列敘述何者較不適當？","options":["(A) 開誠溝通，表露關懷","(B) 害怕失去病童，會積極治療","(C) 症狀控制與維持舒適","(D) 尊重家庭的宗教信仰與信念"],"answer":1,"image":""},{"id":"nr4-109-2-56","subject":"nr4","topic":"兒科-高危險新生兒","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"有關早產兒腸胃系統功能，下列敘述何者不適當？","options":["(A) 早產兒胃容量小且胃腸蠕動弱","(B) 心跳及呼吸速率快，新陳代謝快","(C) 對脂肪消化能力有限","(D) 消化乳糖能力至妊娠32週以後才成熟"],"answer":3,"image":""},{"id":"nr4-109-2-57","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"有關麻疹（measles）的症狀敘述，下列敘述何者正確？","options":["(A) 具高傳染性，必須採腸胃道隔離","(B) 疹子最早會出現在軀幹，再擴散至頸部、臉部和四肢","(C) 紅疹出現前3～5天至出現紅疹後4天，為傳染期","(D) 發燒時使用aspirin退燒"],"answer":2,"image":""},{"id":"nr4-109-2-58","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"有關嬰兒玫瑰疹的敘述，下列何者正確？","options":["(A) 好發的年齡為2～5歲","(B) 當高燒消退後，開始出現疹子","(C) 最常見的合併症為中耳炎","(D) 病原大多是第二型疱疹病毒所引起"],"answer":1,"image":""},{"id":"nr4-109-2-59","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"林小妹4歲，常用手抓屁股，疑有蟯蟲感染，將進行透明膠帶試驗（scotch tape test），最合適的蟲卵採集時間為何？","options":["(A) 清晨尚未起床時","(B) 中午進餐後","(C) 傍晚進餐前","(D) 睡覺前"],"answer":0,"image":""},{"id":"nr4-109-2-60","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"小花6個月，疑似罹患呼吸道融合病毒，有關採檢相關的敘述，下列何者最適當？","options":["(A) 糞便的病毒培養","(B) 鼻內分泌物及血液免疫分析","(C) 鼻內分泌物的細菌培養","(D) 血液厭氧培養"],"answer":1,"image":""},{"id":"nr4-109-2-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"有關病童使用氧氣帳（O2 tent）之照護，下列何者較適當？","options":["(A) 應注意維持帳內高氧、低濕度及低溫的環境","(B) 儘量以集中護理的方式，維持帳內的氧氣濃度","(C) 為避免病童有隔離感，應鼓勵照顧者於帳內陪伴","(D) 讓病童將其心愛的電動玩具帶入，以免病童無聊"],"answer":1,"image":""},{"id":"nr4-109-2-62","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"林小妹6歲，因反覆性氣喘發作入院，現病情已漸趨穩定欲出院，有關出院的居家照顧，下列敘述何者正確？","options":["(A) 家中儘量採用布織的窗簾，以降低過敏","(B) 床單枕頭以30～40℃的熱水每個月清洗一次為宜","(C) 兒童運動種類應以可控制自己呼吸狀況的有氧運動為主，如慢跑、游泳、騎腳踏車","(D) 由於塵蟎易存在木製品或皮革製品上，睡覺時以提供彈簧床或榻榻米為宜"],"answer":2,"image":""},{"id":"nr4-109-2-63","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"有關罹患心臟病嬰兒的護理照護，下列何者最適當？","options":["(A) 少量多餐，奶瓶餵食時間不要少於30分鐘，避免吸得太快太急","(B) 心衰竭的嬰兒以低鈉的配方奶取代母乳，減少鈉的攝取量","(C) 必要時使用鼻（口）胃管餵食，減少心臟負荷","(D) 補充鈣質可增加血紅素的載氧量"],"answer":2,"image":""},{"id":"nr4-109-2-64","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"小東8個月，診斷為法洛氏四重症（Tetralogy of Fallot），哭鬧厲害全身發紺，此時護理師給予氧氣，並將小東擺為膝胸臥式之目的為何？","options":["(A) 減少回流至心臟之血量","(B) 減少全身血管阻力","(C) 減少右心室流向肺動脈之血量","(D) 減少身體耗氧量"],"answer":0,"image":""},{"id":"nr4-109-2-65","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"有關胎血循環的敘述，下列何者錯誤？","options":["(A) 臍靜脈的血液經由靜脈導管流向下腔靜脈","(B) 經過卵圓孔的血液是由左心房流向右心房","(C) 右心室的血液多數由肺動脈幹直接經動脈導管流入主動脈","(D) 臍靜脈的血氧濃度高於臍動脈"],"answer":1,"image":""},{"id":"nr4-109-2-66","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"有關體染色體隱性遺傳之疾病，下列何者錯誤？","options":["(A) 原發性再生不良性貧血（Fanconi’s anemia）","(B) 海洋性貧血","(C) G-6-PD缺乏症","(D) 鐮狀細胞貧血"],"answer":2,"image":""},{"id":"nr4-109-2-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"小漢8歲，罹患血友病（hemophilia），下列護理措施何者最適當？","options":["(A) 關節出血時，加壓並給予熱敷，減輕不適","(B) 鼓勵病童從事適度的活動，以強化其關節肌肉","(C) 刷牙時應選用硬毛刷","(D) 持續疼痛不止，可依醫囑給予止痛藥，如阿斯匹靈（aspirin）"],"answer":1,"image":""},{"id":"nr4-109-2-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"9歲的小君，診斷白血病（leukemia），目前接受化學治療，其血液檢驗數值嗜中性白血球計數為800/mm3，有關護理措施，下列敘述何者不適當？","options":["(A) 接觸病童前後都要洗手","(B) 禁止施打活性疫苗","(C) 發燒時使用肛門塞劑來退燒","(D) 飲食遵守低微生物餐的原則"],"answer":2,"image":""},{"id":"nr4-109-2-69","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"小明3歲，罹患急性淋巴性白血病，有關接受誘導期化學治療的敘述，下列何者錯誤？","options":["(A) 相較於6個月或是12歲罹病的病童，小明有較佳的預後","(B) allopurinol是用來預防腫瘤溶血症候群的藥物","(C) 中樞神經系統和睪丸是急性淋巴性白血病最常復發的地方","(D) MTX、Ara-C、hydrocortisone用來預防中樞神經系統復發"],"answer":1,"image":""},{"id":"nr4-109-2-70","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"小美5歲，出現發燒、臉色蒼白、虛弱、肚子痛，經醫師確診為神經母細胞瘤第三期，下列敘述何者最不適當？","options":["(A) 小美腫瘤已經出現轉移，因此無法完全切除腫瘤","(B) 小美的症狀會依腫瘤位置而出現不同的疾病進展","(C) 可以推測小美已經轉移至骨髓、骨骼、肝臟等處","(D) 如果腫瘤轉移至眼睛，小美會有上眼瞼下垂症狀"],"answer":2,"image":""},{"id":"nr4-109-2-71","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"癌症病童接受治療期間，有關疫苗接種之敘述，下列何者最不適當？","options":["(A) 可以接種流行性感冒疫苗","(B) 可以口服小兒沙賓疫苗","(C) 不可以接觸水痘病人","(D) 不可以接觸麻疹病人"],"answer":1,"image":""},{"id":"nr4-109-2-72","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"小曄3個月大，因為唇裂（cleft lip）而入院，經醫師進行唇裂修補術後返回病室，有關手術後護理，下列敘述何者錯誤？","options":["(A) 協助採取俯臥姿勢，以促進分泌物流出，預防呼吸道阻塞","(B) 須適當約束手肘，避免病童碰觸傷口影響癒合","(C) 儘量避免嬰兒吸吮，安撫奶嘴暫時勿使用","(D) 餵完奶後，應給予清水清洗口腔以預防感染"],"answer":0,"image":""},{"id":"nr4-109-2-73","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"王小弟腹瀉三天，每天高達10次，體重從10公斤降至9.2公斤，尿量也減少。請問王小弟的脫水程度為何？","options":["(A) 沒脫水","(B) 輕度脫水","(C) 中度脫水","(D) 重度脫水"],"answer":2,"image":""},{"id":"nr4-109-2-74","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"有關腸套疊（intussusception）的臨床表徵，下列敘述何者正確？","options":["(A) 常出現咳嗽、梗塞、發紺等症狀","(B) 解草莓果醬般大便","(C) 腹部的左下象限內會觸摸到香腸狀腫塊","(D) 解出暗茶色尿液"],"answer":1,"image":""},{"id":"nr4-109-2-75","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"兒童健康手冊有嬰兒大便卡，請家長比對嬰兒大便的顏色，可早期發現膽道閉鎖兒，主要目的為何？","options":["(A) 預防核黃疸，減少神經損傷","(B) 早期給予特殊奶粉，減少代謝異常","(C) 儘早進行手術，減少肝臟損傷","(D) 儘快給予排膽劑，以利膽汁排出"],"answer":2,"image":""},{"id":"nr4-109-2-76","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"陳小弟11歲，因闌尾炎進行盲腸切除術。有關手術後護理措施，下列敘述何者正確？","options":["(A) 疼痛時少用止痛劑，因易降低腸蠕動，可予腹部熱敷，減輕疼痛","(B) 定時監測傷口有無紅、腫、熱、痛等發炎現象","(C) 鼓勵病童臥床休息，減少下床，以預防傷口縫線滲血，導致影響傷口癒合","(D) 術後如有引流管留置，應採平躺姿勢，以利傷口引流"],"answer":1,"image":""},{"id":"nr4-109-2-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"有關提供癲癇病童長期服用抗癲癇藥物的護理措施，下列何者錯誤？","options":["(A) 需與牛奶一起服用，避免吸收不良","(B) 定時回診監測血中藥物濃度","(C) 即使發作頻率降低，也不可自行停藥","(D) 使用phenytoin（Dilantin）常見副作用是牙齦增生"],"answer":0,"image":""},{"id":"nr4-109-2-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"有關發展性髖關節發育不良病童，使用帕米利克背帶（Pavlik harness）的護理措施，下列敘述何者不適當？","options":["(A) 使用目的是維持髖關節屈曲及外展","(B) 2歲以上的病童，只需穿戴此背帶直到骨盆發育穩定就會痊癒","(C) 建議父母在背帶正確位置做記號，以方便調整回正確位置","(D) 維持背帶下皮膚的清潔及完整性"],"answer":1,"image":""},{"id":"nr4-109-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"當懷疑個案出現腦膜炎時，醫師常會執行柯林氏徵象（Kernig’s sign）之身體評估，此評估正確做法為何？","options":["(A) 以反射鎚柄由足跟沿上經足外緣至大蹠趾，出現腳趾呈扇形張開","(B) 讓兒童平躺，將其頭向上抬時，兒童會不自主的彎曲膝蓋及髖部","(C) 讓兒童以兩腳之腳尖踮起走路，測試走路穩定狀態","(D) 使平躺將小腿托高，使髖及膝關節屈曲成直角，再伸展小腿會產生阻力或疼痛"],"answer":3,"image":""},{"id":"nr4-109-2-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"小英6歲，因扁平足（flat foot）就診，有關護理指導之敘述，下列何者正確？","options":["(A) 建議墊腳尖及跳躍，以加強足背肌腱訓練","(B) 使用矯正鞋墊配合矯正鞋，誘導足弓發育","(C) 使用功能性鞋墊，以預防足弓繼續塌陷","(D) 建議考慮以滑膜切除術，預防阿基氏腱的短縮"],"answer":1,"image":""},{"id":"nr4-110-1-1","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"有關以家庭為中心的照護，下列敘述何者正確？","options":["(A) 家中每位成員的需求皆需要被注意及尊重","(B) 醫療機構只能讓準父親陪產","(C) 因孕產婦的自主權最重要，照護只需考量婦女需求","(D) 婚姻的品質與婦女的支持系統無關"],"answer":0,"image":""},{"id":"nr4-110-1-2","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"有關產婦接受腰椎硬膜外麻醉術可能發生的合併症，下列何者錯誤？","options":["(A) 低血壓","(B) 胎兒心跳變異性增加","(C) 脊髓性頭痛","(D) 排尿困難"],"answer":1,"image":""},{"id":"nr4-110-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"有關妊娠期腸胃系統的變化所造成孕婦不適的現象，下列敘述何項正確？","options":["(A) 噁心與嘔吐是與胃蛋白酶分泌增加有關","(B) 膽囊排空時間延長，膽汁排出量減少","(C) 肝功能改變，如血漿白蛋白和球蛋白值上升","(D) 唾液分泌減少，若口腔衛生不佳者易患齲齒"],"answer":1,"image":""},{"id":"nr4-110-1-4","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"有關常見遺傳疾病之敘述，下列何項正確？","options":["(A) 唐氏症是21號染色體多一條，95%非遺傳所造成","(B) X染色體脆折症為單基因遺傳疾病，女性發生率高於男性","(C) 裘馨氏肌肉萎縮症是為染色體異常遺傳疾病，每胎產下重症寶寶機率為1/4","(D) 海洋性貧血為多基因遺傳疾病，也會受到環境因素共同調控而產生"],"answer":0,"image":""},{"id":"nr4-110-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"第三妊娠期孕婦身體姿勢之敘述，下列何項正確？","options":["(A) 坐姿為挺直背脊，身體的重量壓力應集中在坐骨","(B) 採後傾30度的半坐臥姿，身體的重量壓力應集中在尾骨","(C) 坐時應儘量選擇無靠背椅子，大腿呈外八字可避免重心不穩及下背痛","(D) 坐下時應側身手扶椅面，並先坐椅面前1/3再將臀部挪進中央"],"answer":0,"image":""},{"id":"nr4-110-1-6","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"懷孕32週婦女接受無壓力性試驗（NonstressTest;NST）20分鐘後，未發現胎兒有活動訊號，下列措施何者最適當？","options":["(A) 給予補充含糖電解質飲料，再監測","(B) 立即安排住院密切觀察","(C) 請孕婦返家，等到34週再監測","(D) 鼻吸氧氣2～3 L/min，30分鐘後再監測"],"answer":0,"image":""},{"id":"nr4-110-1-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"懷孕婦女詢問為什麼她臉頰、額頭最近開始出現一些褐色斑點，護理師以下解釋，何者正確？","options":["(A) 這是一種臉部結締組織擴張所致","(B) 這是因臉部的血管擴張、增生所致","(C) 臉部皮下組織代謝增加所致","(D) 因腦下垂體分泌的黑色素刺激素增加"],"answer":3,"image":""},{"id":"nr4-110-1-8","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"有關雷奧波德式操作法（Leopold’s maneuvers）之敘述，下列何者正確？","options":["(A) 在妊娠12週即可操作","(B) 第一段操作法的目的為找出胎兒的那一部位位於子宮底","(C) 檢查前需要先脹膀胱","(D) 第三段操作法的目的之一為找出最適當的胎心音聽診部位"],"answer":1,"image":""},{"id":"nr4-110-1-9","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"有關胎兒呼吸系統發育，下列敘述何者正確？","options":["(A) 胎兒在28週，肺表面張力素開始製造","(B) 胎兒娩出後，才開始有呼吸動作","(C) 胎兒在子宮內有呼吸動作易造成羊水吸入","(D) 肺表面張力素過少易造成新生兒呼吸窘迫症候群"],"answer":3,"image":""},{"id":"nr4-110-1-10","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"有關受精的敘述，下列何者錯誤？","options":["(A) 精子在進入卵子之前，必須穿過卵子外層的放射冠及透明帶","(B) 雙胞胎是指同時有二隻精子進入卵子的細胞核完成受精","(C) 受精最常發生於輸卵管壺腹部","(D) 受精是單套染色體的精子與單套染色體卵子的結合"],"answer":1,"image":""},{"id":"nr4-110-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"有關待產婦之照顧，下列敘述何者正確？","options":["(A) 已破水的個案宜灌腸","(B) 早產安胎的個案便祕宜灌腸","(C) 待產婦不用常規剃除陰毛","(D) 破水後應立即生產"],"answer":2,"image":""},{"id":"nr4-110-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"有關生產疼痛之敘述，下列何者錯誤？","options":["(A) 第一產程疼痛來源主要是子宮收縮與子宮頸變薄及擴張","(B) 第二產程疼痛來源主要是子宮收縮、陰道與會陰肌肉的伸張與伸展","(C) 第三產程疼痛來源主要是胎盤排出時子宮收縮和子宮頸擴張","(D) 生產疼痛是相當主觀而有個別性經驗，與個人過去經驗有關"],"answer":1,"image":""},{"id":"nr4-110-1-13","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"李女士待產時宮縮疼痛非常焦慮不安，下列護理措施何者錯誤？","options":["(A) 換氣過度可給予塑膠袋及O2使用","(B) 利用集中注意力與意象法，減輕疼痛","(C) 利用音樂療法，促進放鬆減輕疼痛","(D) 讓待產婦浸泡於溫水中，達到肌肉鬆弛"],"answer":0,"image":""},{"id":"nr4-110-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"有關脊髓阻斷（Spinal Block）之敘述，下列何者正確？","options":["(A) 常用於減痛分娩，有效緩解第一產程產痛","(B) 在L4-5或L5-S1下針","(C) 麻醉前30分鐘須給予較多的靜脈輸液","(D) 麻醉後須平躺3～4小時，預防頭痛"],"answer":2,"image":""},{"id":"nr4-110-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"以下那些護理評估可以知道待產婦已開始進入第二產程？①破水 ②子宮規則收縮 ③陰道排出粉紅色黏液 ④子宮頸完全擴張 ⑤會陰可見胎頭膨出，個案有不自主用力感","options":["(A) ①②","(B) ②③","(C) ③④","(D) ④⑤"],"answer":3,"image":""},{"id":"nr4-110-1-16","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"入院待產婦裝置體外電子胎兒監測器後，下列何者為第一優先的監測項目？","options":["(A) 辨識出胎心加速的型態","(B) 評估胎心率基準線","(C) 確立子宮收縮強度","(D) 確立子宮收縮的頻率"],"answer":1,"image":""},{"id":"nr4-110-1-17","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"有關正常子宮收縮的特性，下列何者錯誤？","options":["(A) 無法由產婦的意志支配","(B) 以子宮底收縮強度最高","(C) 受腸胃的神經管制","(D) 間歇性的收縮"],"answer":2,"image":""},{"id":"nr4-110-1-18","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"待產婦以催產素（Pitocin）引產時，下列何者最不需要監測？","options":["(A) 血壓與呼吸次數","(B) 輸出入量","(C) 宮縮與胎心率","(D) 血糖"],"answer":3,"image":""},{"id":"nr4-110-1-19","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"林女士，陰道分娩後12小時，主訴會陰傷口疼痛，下列敘述何者適當？","options":["(A) 請產婦採屈膝仰臥式評估會陰傷口","(B) 採REEDA評估時，A是指傷口密合度（Approximation）","(C) 指導如廁後由肛門往陰道口的方向擦拭會陰部","(D) 給予溫水坐浴20分鐘"],"answer":1,"image":""},{"id":"nr4-110-1-20","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"邱女士，產後第三天嚴重脹奶，原想採純母乳哺餵，表示：「昨天都還好，今早突然這樣，實在太痛了，我想打退奶針。」下列何項處置最適當？","options":["(A) 哺餵次數過多會造成乳汁分泌量增多，建議定時餵奶","(B) 協助熱敷與按摩乳房直至乳房呈現柔軟狀態","(C) 刺激噴乳反射，協助擠出乳汁","(D) 建議穿著較緊胸罩、減少刺激與限制水分來退奶"],"answer":2,"image":""},{"id":"nr4-110-1-21","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"下列何者為更年期女性的生理變化？①濾泡刺激素大量增加 ②雌性素分泌增加 ③低密度脂蛋白增加 ④陰道pH值下降","options":["(A) ①③","(B) ②③","(C) ①④","(D) ③④"],"answer":0,"image":""},{"id":"nr4-110-1-22","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"丁女士30歲，第二胎，現為產後第二天，其宮底位於臍下一指，惡露呈紅色量中，主訴昨夜睡眠差且感宮縮疼痛不適，當新生兒推出餵奶時，表示想休息並拒絕餵奶，此行為正確的解釋是：","options":["(A) 此為第二胎，所以對新生兒較不感好奇，也較以自我為中心","(B) 此宮縮痛是不正常之現象，應立即通知醫師","(C) 此時處於接受期，身體仍需調養，所以應主動為她哺餵新生兒","(D) 此時處於接受期，應先滿足她的需求，但同時亦應鼓勵她多接觸新生兒"],"answer":3,"image":""},{"id":"nr4-110-1-23","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"有關母乳哺餵對母親的影響，下列護理指導何者正確？","options":["(A) 刺激腦下垂體前葉分泌催產素","(B) 停經前罹患卵巢癌的機率較低","(C) 因鈣質流失易造成母親中年期骨質疏鬆症","(D) 對月經來潮時間沒有影響"],"answer":1,"image":""},{"id":"nr4-110-1-24","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"王女士G1P1，陰道生產產後第3天，主訴感覺疲倦、失眠、緊張、過於敏感，有時會不由自主的掉眼淚。她目前最可能的情況為何？","options":["(A) 產後的正常現象","(B) 產後情緒低落（postpartum blues）","(C) 產後憂鬱（postpartum depression）","(D) 產後精神病（postpartum psychosis）"],"answer":1,"image":""},{"id":"nr4-110-1-25","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"陳女士產後小便尚未自解，護理師評估結果為尿瀦留，下列敘述何者正確？","options":["(A) 聽診下腹部有囉音","(B) 叩診恥骨聯合上方處有鼓音","(C) 陳女士目前為產後3小時","(D) 觸診腹部子宮底的位置偏向右側"],"answer":3,"image":""},{"id":"nr4-110-1-26","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"承上題，此時護理師需優先注意的現象為何？","options":["(A) 排汗多寡","(B) 子宮收縮狀態","(C) 大便自解情形","(D) 腰酸背痛程度"],"answer":1,"image":""},{"id":"nr4-110-1-27","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"有關新生兒囟門的敘述，下列何者錯誤？","options":["(A) 前囟門為菱形，一般在新生兒出生後12～18週時關閉","(B) 後囟門為三角形，一般在新生兒出生後8～12週時關閉","(C) 當新生兒脫水時，可以觀察到其前囟門凹陷的狀況","(D) 當顱內壓力上升時，可以觀察到新生兒前囟門凸出的狀況"],"answer":0,"image":""},{"id":"nr4-110-1-28","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"下列新生兒的皮膚評估，何者為異常？","options":["(A) 出生時臀部有蒙古斑","(B) 出生後2～3天胸腹部出現毒性紅斑","(C) 出生時先露部位有紅紫色瘀點（Petechiae）","(D) 出生時臉部有葡萄色酒斑"],"answer":3,"image":""},{"id":"nr4-110-1-29","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"有關新生兒免疫系統的敘述，下列何者錯誤？","options":["(A) 新生兒自妊娠20週後即可自行合成少量的免疫球蛋白（IgM，IgG，IgE）","(B) 第三妊娠期中，IgG可通過胎盤，胎兒即可獲得來自母體的被動免疫能力","(C) IgM無法通過胎盤，若新生兒體內IgM值偏高，即可能表示胎兒有感染現象","(D) IgE可自初乳中分泌出來，因此哺餵母乳的新生兒，較易獲得來自母體的IgE"],"answer":3,"image":""},{"id":"nr4-110-1-30","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"有關女陰癌之敘述，下列何者正確？","options":["(A) 早期病變為搔癢、小傷口，但癌症生長快速","(B) 容易因直接接觸至鄰近器官而發生局部轉移","(C) 早期治療以化學治療為主","(D) 術後應採仰臥式，維持大腿45度外張，膝關節90度彎曲之姿勢"],"answer":3,"image":""},{"id":"nr4-110-1-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"王女士，有糖尿病病史，到院進行產前諮詢。醫護人員會建議她在懷孕前最好接受何項檢驗，以了解其血糖控制之狀況？","options":["(A) 50公克口服葡萄糖耐受試驗","(B) 100公克口服葡萄糖耐受試驗","(C) 糖化血色素","(D) 空腹血糖"],"answer":2,"image":""},{"id":"nr4-110-1-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"陳女士妊娠30週，因有早產預兆而入院安胎，依醫囑使用Ritodrine（Yutopar）靜脈點滴注射。有關此藥物的副作用，下列何者錯誤？","options":["(A) 低血糖","(B) 噁心","(C) 頭痛","(D) 胎心率增加"],"answer":0,"image":""},{"id":"nr4-110-1-33","subject":"nr4","topic":"產科-產後照護","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"李女士產後8小時，惡露呈鮮紅色，1小時內即浸溼整片產墊，下列護理措施何者錯誤？","options":["(A) 監測生命徵象及血壓","(B) 評估出血量","(C) 暫停子宮按摩","(D) 依醫囑給予子宮收縮藥物"],"answer":2,"image":""},{"id":"nr4-110-1-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"有關前置胎盤的敘述，下列何者正確？","options":["(A) 生育期婦女發生前置胎盤的機率與年齡無關","(B) 胎盤著床的位置在子宮底部位","(C) 有前置胎盤病史者，再次發生機率較高","(D) 發生的機率與婦女有無多次子宮刮除術經驗無關"],"answer":2,"image":""},{"id":"nr4-110-1-35","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"下列何者不是多囊性卵巢疾病之臨床表徵？","options":["(A) 雌性素分泌過多","(B) 肥胖","(C) 多毛","(D) 月經過少或無月經"],"answer":0,"image":""},{"id":"nr4-110-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"鄭女士53歲，有關更年期之注意事項，下列敘述何者最適當？","options":["(A) 多喝冰涼飲品，可舒緩熱潮紅","(B) 仍需定期做子宮頸抹片檢查","(C) 建議接受民俗療法，以舒緩不適症狀","(D) 因萎縮性陰道炎，不要有性行為"],"answer":1,"image":""},{"id":"nr4-110-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"有關經前症候群的護理措施，下列敘述何者最適當？","options":["(A) 補充高蛋白、高熱量、高鹽分的飲食","(B) 服用雌性素預防不適症狀","(C) 多飲用咖啡、冰涼的手調茶飲","(D) 調整生活作息，良好的睡眠品質"],"answer":3,"image":""},{"id":"nr4-110-1-38","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"有關子宮頸癌的護理措施，下列敘述何者正確？","options":["(A) 根除性子宮切除術後，可能出現排尿問題，病人需接受膀胱訓練","(B) 全子宮切除術後一個月可恢復正常生活，例如爬樓梯、提重物等","(C) 放射線治療的病人，照射部位皮膚容易乾燥搔癢，可自行擦拭乳液","(D) 需先評估白血球在2,000/mm3、血紅素在12gm%以上才可行放射治療"],"answer":0,"image":""},{"id":"nr4-110-1-39","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"體外受精與胚胎植入術（IVF-ET）執行過程中，受精卵分裂數量為多少時即可植入子宮內？","options":["(A) 2～8個細胞","(B) 10～16個細胞","(C) 18～32個細胞","(D) 36～48個細胞"],"answer":0,"image":""},{"id":"nr4-110-1-40","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"有關婦科體外放射治療後產生的腹瀉問題之護理指導，下列何者不適當？","options":["(A) 維持水分平衡","(B) 增加乳製品攝取","(C) 採用低渣飲食","(D) 必要時使用止瀉劑"],"answer":1,"image":""},{"id":"nr4-110-1-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"依據「兒童及少年福利與權益保障法」第53條，當護理師知悉兒童非法施用毒品或管制藥品、遭受虐待或其他傷害，至遲不得超過幾小時，應立即向主管機關通報？","options":["(A) 12小時","(B) 24小時","(C) 36小時","(D) 48小時"],"answer":1,"image":""},{"id":"nr4-110-1-42","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"小方，3歲，因急性腸胃炎住院，下列何種行為反應顯示小方處於分離焦慮的抗議期？","options":["(A) 持續性哭叫","(B) 吸手指頭","(C) 白天尿床","(D) 吃奶嘴"],"answer":0,"image":""},{"id":"nr4-110-1-43","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"有關燒傷病童休克期最初24小時的處置措施，下列敘述何者最適當？","options":["(A) 優先選擇乳酸林格氏液（lactated Ringer solution）補充液體","(B) 以皮下或肌肉注射給予止痛藥物，降低病童疼痛不適","(C) 提供高蛋白、高熱量飲食，以補充熱量與蛋白質耗損","(D) 照護重點是避免燒傷造成關節攣縮或變形後遺症"],"answer":0,"image":""},{"id":"nr4-110-1-44","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"小玉，3歲，體重15公斤，誤食外婆包粽子用的鹼水，就醫時意識清楚，下列處置何者最適當？","options":["(A) 食入後儘快進行催吐延緩吸收","(B) 在食入2小時內喝清水或牛奶中和","(C) 給予灌腸或胃灌洗","(D) 食入後積極投予deferoxamine治療"],"answer":1,"image":""},{"id":"nr4-110-1-45","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"小瑄，1歲1個月，因不明原因發燒而入住兒童病房，測量小瑄的生命徵象時，下列護理措施何者較不適當？","options":["(A) 採肛溫測量以獲得正確體溫","(B) 讓主要照顧者陪伴在身旁","(C) 先量呼吸、心跳再量體溫","(D) 血壓測量部位最常用為右上臂"],"answer":0,"image":""},{"id":"nr4-110-1-46","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"下列何者是造成兒童燒傷急救期（emergent period）休克的主要原因？","options":["(A) 低血量性","(B) 壓力性","(C) 心因性","(D) 敗血性"],"answer":0,"image":""},{"id":"nr4-110-1-47","subject":"nr4","topic":"兒科-高危險新生兒","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"早產兒吸吮力弱，有關使用口胃管灌食的注意事項，下列敘述何者不適當？","options":["(A) 插口胃管時先以無菌蒸餾水潤滑","(B) 每次餵食前應先檢查胃內殘餘量","(C) 灌食時，早產兒頭部抬高大於30度","(D) 每日攝取熱量宜為100～120 Kcal/kg"],"answer":2,"image":""},{"id":"nr4-110-1-48","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"有關兒童疼痛概念與認知的敘述，下列何者錯誤？","options":["(A) 早產兒、新生兒不會覺得疼痛，因為傳導慢","(B) 16個月的小欣，對疼痛有記憶看到針頭就哭","(C) 5歲的小美用語言抗議和肢體活動來表達疼痛","(D) 7歲的阿偉將疼痛視為一種錯誤行為的懲罰"],"answer":0,"image":""},{"id":"nr4-110-1-49","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"有關兒童常用的鴉片類製劑（opioids）疼痛處置，下列敘述何者正確？","options":["(A) 此類藥物適用於兒童中度至重度的疼痛","(B) 主要抑制前列腺素的合成，而有鎮痛效果","(C) 常見副作用包括胃潰瘍、腹瀉、出血性腎炎","(D) Morphine與雷氏症候群有關，不建議兒童使用"],"answer":0,"image":""},{"id":"nr4-110-1-50","subject":"nr4","topic":"兒科-生長發展","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"嬰兒最早發展的知覺為下列何者？","options":["(A) 聽覺","(B) 視覺","(C) 觸覺","(D) 嗅覺"],"answer":2,"image":""},{"id":"nr4-110-1-51","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"小明，3歲半，診斷為會厭炎而住院求治，下列護理措施何者最適當？","options":["(A) 給予小明接種流感嗜血桿菌疫苗","(B) 協助喉嚨採檢時，備好急救用物","(C) 宜給予抽痰以維持呼吸道通暢","(D) 提供冰冷軟質食物，以減少會厭腫脹"],"answer":1,"image":""},{"id":"nr4-110-1-52","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"有關意識不清的嬰幼兒期病童疼痛評估，下列何者最適當？","options":["(A) Poker Chip Scale籌碼片量表","(B) Face Pain Scale臉譜疼痛量表","(C) Face, Legs, Activity, Cry& Consolability量表","(D) Numeric Pain Scale數字疼痛量表"],"answer":2,"image":""},{"id":"nr4-110-1-53","subject":"nr4","topic":"兒科-高危險新生兒","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"張小妹，妊娠28週出生，體重960公克，有關早產兒的特徵及照護，下列敘述何者正確？","options":["(A) 依醫囑由靜脈點滴給予表面張力素（survanta）","(B) 若無吸吮及吞嚥反射，以腸道外營養法提供營養","(C) 四肢屈曲且內縮，呈現子宮內姿勢","(D) 皮膚缺乏皮下脂肪、胎毛少、腳底皺摺多"],"answer":1,"image":""},{"id":"nr4-110-1-54","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"有關兒童事故傷害的預防與處置，下列敘述何者正確？","options":["(A) 誤食漂白水，在2小時內，給予吐根糖漿（ipecac syrup）催吐","(B) 溺水發生時，最優先的緊急處置是恢復體溫","(C) 嬰幼兒乘坐汽車，安全座椅應固定於前座駕駛旁","(D) 處於口腔階段嬰幼兒容易發生異物哽塞或鉛中毒"],"answer":3,"image":""},{"id":"nr4-110-1-55","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"小傑，2歲，罹患重度海洋性貧血（Thalassemia），需反覆入院輸血。母親為印尼裔回教徒的新住民，中文溝通有限，有關以家庭為中心的護理計畫，下列敘述何者最適當？","options":["(A) 提供家庭以臺灣本土文化為主的照護計畫","(B) 完全配合印尼文化，進行所有病童與其家庭對疾病與住院的反應和需求照護","(C) 在住院期間，儘量與家庭的文化習慣和常規保有一致性","(D) 在所有照護決策過程，請小傑母親找尋其他家人幫忙做翻譯"],"answer":2,"image":""},{"id":"nr4-110-1-56","subject":"nr4","topic":"兒科-高危險新生兒","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"早產兒常出現呼吸暫停現象，下列敘述何者正確？","options":["(A) 指呼吸停止連續10～15秒，且併有發紺、心跳變快的現象","(B) 維持俯臥姿勢，可縮短早產兒發生呼吸暫停時的心跳遲緩，或發紺之持續時間","(C) 給予theophylline時，須觀察有無心搏過慢，及嗜睡等中毒的徵象","(D) 出現呼吸暫停，立即執行心外按摩，促進呼吸恢復"],"answer":1,"image":""},{"id":"nr4-110-1-57","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"小花，8歲，罹患神經母細胞瘤末期，問護理師他是否快要死掉了，下列敘述何者較適當？","options":["(A) 沒有啊，是誰告訴你的，不要想那麼多","(B) 為什麼你突然問這個問題，說說看你在擔心什麼","(C) 你聽誰說的？你是不是太累了，會不會聽錯了","(D) 每個人都會死掉，只是早死或晚死罷了"],"answer":1,"image":""},{"id":"nr4-110-1-58","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"協助學齡前期的手足面對病童瀕死的護理措施，下列敘述何者正確？","options":["(A) 為了保護病童之手足，應減少手足與瀕死的病童接觸","(B) 此年齡的孩童對死亡概念模糊，不需與他談到死亡","(C) 當手足出現行為問題時，須予以糾正","(D) 以繪本或遊戲方式，引導病童手足講出其心中想法"],"answer":3,"image":""},{"id":"nr4-110-1-59","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"有關川崎氏症（Kawasaki disease）的臨床表徵，下列敘述何者錯誤？","options":["(A) 急性期會出現持續發燒5天以上","(B) 急性期兩眼結膜充血、草莓樣舌和頸部淋巴結腫大","(C) 亞急性期可能出現腕、膝和踝等關節痛的症狀","(D) 亞急性期紅血球沉降速率和血小板數值降低"],"answer":3,"image":""},{"id":"nr4-110-1-60","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"感染麻疹（measles）在卡他期（catarrhal stage）的病童之3C症狀，下列敘述何者不適當？","options":["(A) 結膜炎（conjunctivitis）","(B) 鼻炎（coryza）","(C) 咳嗽（cough）","(D) 抽搐（convulsion）"],"answer":3,"image":""},{"id":"nr4-110-1-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"小傑，8個月，罹患支氣管肺炎（Bronchopneumonia），需住院治療，下列護理措施何者不適當？","options":["(A) 進行呼吸症狀評估，且依醫囑給予氧氣","(B) 促進小傑休息和節省體力，故採集中護理","(C) 每當小傑看見父母時都會大哭，宜避免父母親參與照顧","(D) 宜抬高床頭給予舒適臥姿，促進肺部擴張"],"answer":2,"image":""},{"id":"nr4-110-1-62","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"有關兒童罹患會厭炎（Epiglottitis）的典型症狀，下列敘述何者最不適當？","options":["(A) 流口水","(B) 吞嚥困難","(C) 發聲困難","(D) 口腔潰瘍"],"answer":3,"image":""},{"id":"nr4-110-1-63","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"王小弟，2歲，因肺部的下葉上節有痰液蓄積，護理師為其執行姿位引流，下列姿勢何者最適當？","options":["(A) 俯臥，頭放低30度","(B) 側臥，頭放低15度","(C) 側臥，頭放低30度","(D) 俯臥，頭放低15度"],"answer":3,"image":""},{"id":"nr4-110-1-64","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"王小妹，6個月大，有關心導管檢查前的準備，下列敘述何者適當？","options":["(A) 避免測量下肢血壓","(B) 確認禁食4～6小時","(C) 確認鼠蹊部脈搏最強處，標示記號","(D) 確認檢查前不宜給鎮靜劑與抗生素"],"answer":1,"image":""},{"id":"nr4-110-1-65","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"有關病毒性腦膜炎（virus meningitis）的護理措施，下列敘述何者錯誤？","options":["(A) 採支持性療法或症狀治療","(B) 大多數病童會出現神經系統障礙的後遺症","(C) 持續監測病童的生命徵象","(D) 若同時發生細菌性感染，則會給予抗生素使用"],"answer":1,"image":""},{"id":"nr4-110-1-66","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"有關胎兒出生後的心臟血管變化，下列敘述何者錯誤？","options":["(A) 左心房壓力大於右心房，導致卵圓孔瓣膜關閉","(B) 臍動脈閉合，形成肝圓韌帶","(C) 左心房與左心室的壓力增加","(D) 動脈導管於出生後1～3個月閉塞，形成動脈韌帶"],"answer":1,"image":""},{"id":"nr4-110-1-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"有關血友病住院病童及其家屬之照顧，下列敘述何者較適當？","options":["(A) 父母為帶因者易對病童有罪惡感，應支持父母對病童的保護行為","(B) 為維護健康手足之生活品質，宜儘量減少其至病房","(C) 為提升病童自我照顧能力，應儘早提供居家照護知識","(D) 為避免受同儕排擠，應鼓勵病童積極參加學校各類活動"],"answer":2,"image":""},{"id":"nr4-110-1-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"小凌，16歲，罹患再生不良性貧血，住院接受抗淋巴球蛋白（ALG）及cyclosporin治療，下列護理措施何者較適當？","options":["(A) 因小凌食慾不振，儘量選擇其愛吃的食物，例如生菜沙拉","(B) 青春期在意身體外觀，先暫不告知藥物有外觀改變之副作用","(C) 為避免社交隔離，鼓勵安排同學到院探訪","(D) 發燒時，避免使用aspirin，以免延長出血時間"],"answer":3,"image":""},{"id":"nr4-110-1-69","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"小青，2歲，罹患先天性甲狀腺功能低下（congenital hypothyroidism），下列敘述何者不適當？","options":["(A) 提供低纖維食物，以預防腹瀉","(B) 增加鐵質的提供，以預防貧血","(C) 給予四肢適當保暖，預防體溫過低","(D) 鼓勵增加日曬時間，以促進骨骼發展"],"answer":0,"image":""},{"id":"nr4-110-1-70","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"有關兒童腫瘤好發部位的敘述，下列何者錯誤？","options":["(A) 骨肉瘤（osteosarcoma）最常發生於肱骨（humerus）","(B) 最常見的原發性腦瘤是膠質瘤（glioma）","(C) 神經母細胞瘤（neuroblastoma）最常發生在腎髓質","(D) 威廉氏腫瘤（Wilm’s tumor）是發生於腎臟的惡性腫瘤"],"answer":0,"image":""},{"id":"nr4-110-1-71","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"林小弟，9歲，因為急性腎絲球腎炎（acute glomerulonephritis）而入院治療，有關此疾病之護理照護，下列敘述何者錯誤？","options":["(A) 急性期階段，儘量鼓勵臥床休息，以減少能量消耗","(B) 須密切監測病童水腫、血壓、尿量等的變化","(C) 鼓勵病童多進食高鉀食物，如香蕉、橘子以預防低血鉀","(D) 每日定時使用同一磅秤與相同穿著測量體重"],"answer":2,"image":""},{"id":"nr4-110-1-72","subject":"nr4","topic":"兒科-高危險新生兒","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"有關早產兒呼吸窘迫症候群的護理措施，下列敘述何者正確？","options":["(A) 胸部X光表現為肺擴張不全，毛玻璃樣的變化","(B) 胎兒在妊娠週數32週大時才開始製造及分泌表面張力素","(C) 早產兒呼吸窘迫症候群的臨床表徵為吸氣出現咕嚕聲","(D) 呼吸性酸中毒為動脈血液氣體分析pH＜7.20、PaO2＞50 mmHg"],"answer":0,"image":""},{"id":"nr4-110-1-73","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"小強，男生，1個月大，因泌尿道感染住院，有關此疾病敘述與照護，下列何者錯誤？","options":["(A) 嬰兒常出現的臨床表徵包括發燒、餵食困難、食慾下降等","(B) 鼓勵給予小強蔓越莓汁，以鹼化尿液，預防感染","(C) 指導母親應給予小強勤換尿布及避免泡澡","(D) 指導母親在小強抗生素服用期間，勿因症狀改善而任意停用抗生素"],"answer":1,"image":""},{"id":"nr4-110-1-74","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"兒童是易受輪狀病毒感染的高危險群，為預防輪狀病毒感染，有關家屬的護理指導，下列敘述何者錯誤？","options":["(A) 鼓勵父母及兒童養成勤洗手習慣","(B) 需注射兩劑輪狀病毒疫苗","(C) 儘量減少出入公共場所","(D) 勿吃生食，保持廚房、器具、食材的清潔"],"answer":1,"image":""},{"id":"nr4-110-1-75","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"罹患腸套疊（intussusception）的病童，接受鋇劑灌腸治療後，下列敘述何者正確？","options":["(A) 腸套疊可完全復原，不需擔心再度復發","(B) 必須配合外科手術使腸道完全復位","(C) 初次解出灰白色糞便代表非正常現象","(D) 解出正常的褐色糞便，表示腸套疊可能復原"],"answer":3,"image":""},{"id":"nr4-110-1-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"有關病童罹患膀胱輸尿管逆流（Vesicoureteral Reflux; VUR）的初期臨床表徵，下列敘述何者正確？","options":["(A) 排尿疼痛有灼熱感","(B) 無尿意感","(C) 出現下肢骨突處凹陷性水腫","(D) 總膽固醇與三酸甘油脂數值上升"],"answer":0,"image":""},{"id":"nr4-110-1-77","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"周小弟，12歲，因打球跌倒導致右側脛腓骨骨折，已上石膏住院治療，下列護理措施何者錯誤？","options":["(A) 不可使用烤燈加速石膏乾燥","(B) 評估右下肢皮膚及指甲床顏色、溫度有無改變","(C) 患肢未被石膏固定的上下關節儘量固定不動，避免疼痛","(D) 抬高敷有石膏的患肢，以促靜脈回流"],"answer":2,"image":""},{"id":"nr4-110-1-78","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"小畢，5歲，因騎腳踏車跌倒，頭撞到地板，出現頭痛、嘔吐的現象，送醫後緊急接受開顱手術，下列有關手術後護理何者不適當？","options":["(A) 密切評估監測意識狀態與生命徵象","(B) 觀察有無顱內壓增高症狀，如頭痛、嘔吐、視力模糊等","(C) 協助小畢採頭低臀高的姿勢，以促進頭部傷口引流","(D) 提供安靜光線柔和的環境，並減少聲光刺激"],"answer":2,"image":""},{"id":"nr4-110-1-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"張小弟，5個月，因水腦症入院，為預防顱內壓升高，下列護理措施何者不適當？","options":["(A) 密切觀察有無囟門鼓脹或噴射狀嘔吐現象","(B) 抬高床頭30～45度，以降低腦內壓","(C) 術後每2小時協助叩擊與抽痰，以預防吸入性肺炎","(D) 給予安撫奶嘴以減少哭泣不安"],"answer":2,"image":""},{"id":"nr4-110-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"有關兒童腦性麻痺的型態及表徵，下列敘述何者不適當？","options":["(A) 運動失調型（ataxic）因小腦功能病變而導致平衡和協調障礙","(B) 痙攣型（spastic）因錐體徑路病變而肌肉持續性出現高張力","(C) 運動困難型（dyskinetic）因錐體外徑路病變而有不自主運動","(D) 徐動型（athetoid）因基底核受損而使雙下肢麻痺"],"answer":3,"image":""},{"id":"nr4-110-2-1","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"王女士30歲，第一次懷孕，詢問有關人性化生產準備，下列護理師的回應何者較不適當？","options":["(A) 與產婦一起討論生產計畫","(B) 多元友善的生產環境，是鼓勵家人參與分娩過程","(C) 提供新生兒於產後立即第一次與產婦接觸","(D) 醫院生產前會有禁食、灌腸、會陰切開等常規處置"],"answer":3,"image":""},{"id":"nr4-110-2-2","subject":"nr4","topic":"產科-產後照護","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"有關嬰兒正確含乳的注意事項，下列護理指導何者正確？","options":["(A) 需下壓乳暈以免乳房壓到嬰兒鼻子造成缺氧","(B) 通常上乳暈露出比下乳暈少","(C) 以乳頭觸動嬰兒的嘴以利張口含乳","(D) 吸吮到乳汁會發出嘖嘖聲"],"answer":2,"image":""},{"id":"nr4-110-2-3","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"有關第二孕期母血唐氏症四指標（quadruple test）之檢測項目，下列何者錯誤？","options":["(A) 胎兒甲型蛋白（AFP）","(B) 非結合性雌三醇（Unconjugated estriol, uE3）","(C) β-人類絨毛膜性腺激素（β-hCG）","(D) 胎盤生長激素（PlGF）"],"answer":3,"image":""},{"id":"nr4-110-2-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"懷孕期間由於生理機能改變，使得藥物在孕婦體內的吸收、分布、代謝與排泄均有改變，下列敘述何者正確？","options":["(A) 潮氣容積量下降，使吸入性藥物的吸收減少","(B) 藥物與白蛋白結合比例降低，肝臟對藥物的代謝能力增加","(C) 腎絲球過濾率增加，藥物的代謝變慢","(D) 胃排空加快胃酸分泌增加，藥物滯留腸胃道時間減少"],"answer":1,"image":""},{"id":"nr4-110-2-5","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"有關產前胎兒生理活動評估，下列敘述何者正確？","options":["(A) 計分方式分為兩種，而滿分標準分為8分和10分","(B) 若總分為6分，表示胎兒狀況良好可每週再重複做一次","(C) 超音波觀察之項目，如呼吸運動、胎動、胎兒身體張力和羊水容積","(D) 正常羊水容積是指兩相互垂直的平面羊水囊，直徑均小於1公分"],"answer":2,"image":""},{"id":"nr4-110-2-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"有關妊娠期會陰按摩，下列敘述何者正確？","options":["(A) 藉由按摩減少會陰肌肉的延展性，以減少會陰撕裂傷","(B) 可在妊娠32～34週開始按摩，每星期至少3～4次","(C) 會陰按摩應是一種無菌措施，以防止胎兒受到感染","(D) 按摩應避免觸及尿道口，過程中若有微熱感是異常現象"],"answer":1,"image":""},{"id":"nr4-110-2-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"妊娠各時期的孕婦心理反應會因生理的改變而產生變化。第一妊娠期婦女的心理反應，下列敘述何者最適當？","options":["(A) 憂喜參半的矛盾心理","(B) 接受懷孕事實","(C) 準備新角色","(D) 身體界限的改變"],"answer":0,"image":""},{"id":"nr4-110-2-8","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"李女士月經週期約28～45天，產前門診剛確定懷孕，最後一次月經來是上個月3號，下列何者為最準確的預產期推估法？","options":["(A) 用最後一次月經（LMP）日期，以內格來氏法推估","(B) 詢問其最可能的排卵受孕日期，再加上266天","(C) 等到第二孕期感受到胎動的日期，再加上20～22週","(D) 以超音波觀察胚胎發育，例如：妊娠囊、胎心音"],"answer":3,"image":""},{"id":"nr4-110-2-9","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"護理師執行腹部四段式操作法之主要目的為何？","options":["(A) 測子宮收縮強度","(B) 測胎兒心跳","(C) 檢查胎產式","(D) 測子宮收縮頻率"],"answer":2,"image":""},{"id":"nr4-110-2-10","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"懷孕30週婦女，主訴想強化骨盆肌肉群，下列產前運動之建議何者正確？①盤腿坐姿運動 ②凱格爾運動 ③蹲踞運動 ④膝胸臥式運動 ⑤腹肌收縮運動","options":["(A) ①②③","(B) ①③④","(C) ②③④","(D) ②④⑤"],"answer":0,"image":""},{"id":"nr4-110-2-11","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"陳女士G2P1待產時發現胎位為枕後位，主訴腰酸疼痛，下列護理措施何者不適當？","options":["(A) 運用生產球膝跪姿有助於胎頭旋轉，減輕疼痛","(B) 採站立弓箭步有助於胎頭旋轉，減輕疼痛","(C) 按摩薦骨處，並請待產婦平躺，減輕疼痛","(D) 冷熱敷骶骨處，減輕疼痛"],"answer":2,"image":""},{"id":"nr4-110-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"有關待產婦呼吸技巧之敘述，下列何者錯誤？","options":["(A) 第一產程時，不須拘泥呼吸形態，只要待產婦覺得舒適即可","(B) 建議呼吸技巧與其他舒適技巧並用","(C) 出現迫切想用力時，可採用哈氣呼吸法","(D) 待產婦若有換氣過度時，常因體內存留太多CO2，導致嘴唇或手指有麻刺感"],"answer":3,"image":""},{"id":"nr4-110-2-13","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"當待產婦有下列何者描述時，可判斷為真陣痛的徵象？","options":["(A) 我剛剛坐著休息一下就好像沒那麼痛了","(B) 我的子宮收縮痛的強度增加且越來越密","(C) 我感覺到下腹部有子宮收縮痛","(D) 我在走動時子宮收縮就沒那麼痛"],"answer":1,"image":""},{"id":"nr4-110-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"有關第二產程的敘述，下列何者錯誤？","options":["(A) 胎頭下降壓迫薦椎和閉孔神經，使產婦有便意感","(B) 建議採超過10秒閉氣用力法","(C) 在第二產程的休息期時，不建議用力","(D) 指子宮頸完全擴張到胎兒完全娩出的過程"],"answer":1,"image":""},{"id":"nr4-110-2-15","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"下列何種胎位之生產時間通常較短？","options":["(A) LOP","(B) LOA","(C) LSA","(D) LMP"],"answer":1,"image":""},{"id":"nr4-110-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"李女士G1P0，子宮收縮每2分鐘一次，子宮頸口開9公分，變薄程度為90%，先露部位高度為0，產婦說：「我很痛，我要用力了」，此時的優先護理措施為何？","options":["(A) 通知麻醉醫師，告知產婦疼痛狀況","(B) 教導平躺休息以避免子宮頸腫脹","(C) 教導吹熄蠟燭式呼吸","(D) 教導閉氣向下用力"],"answer":2,"image":""},{"id":"nr4-110-2-17","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"蔡女士第一胎，子宮收縮每2分鐘一次，每次持續60秒，收縮強度為中度，子宮頸口開8公分，突然自然破水，羊水呈棕綠色，無晚期減速或變異性減速的情形。此時最優先的護理措施為何？","options":["(A) 內診評估子宮頸口變化","(B) 監測子宮收縮","(C) 測量體溫、脈搏、呼吸","(D) 測量胎心率"],"answer":3,"image":""},{"id":"nr4-110-2-18","subject":"nr4","topic":"產科-產後照護","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"有關產婦產後第1天的生理變化，下列敘述何者錯誤？","options":["(A) 白血球增多症（leukocytosis）","(B) 凝血因子（coagulation）減少","(C) 黃體素（progesterone）減少","(D) 雌性素（estrogen）減少"],"answer":1,"image":""},{"id":"nr4-110-2-19","subject":"nr4","topic":"產科-產後照護","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"張女士產後第一天，表示：「初乳黃黃黏黏的，聽說對嬰兒不好，等等我把它擠掉以後再餵奶。」，下列敘述何者正確？","options":["(A) 初乳可以促進胎便排出，減少膽紅素再吸收，所以可以減少黃疸的機率","(B) 初乳因為不含脂肪但含易消化吸收的乳糖，所以有利消化能力弱的新生兒","(C) 初乳含豐富的抗體IgM，可以保護新生兒不受病菌感染","(D) 初乳含的維生素K雖然不如成熟乳多，但仍有防止出血的功用"],"answer":0,"image":""},{"id":"nr4-110-2-20","subject":"nr4","topic":"產科-產後照護","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"李女士，哺餵母乳，產後出院前表示：「我暫時不想懷孕，想跟以前一樣吃避孕藥，可以考慮使用避孕器，其他方法就不用了。」，下列敘述何者最適當？","options":["(A) 餵母奶期間不可以吃口服避孕藥，要改用保險套或是禁慾","(B) 如果要吃避孕藥，需先禁慾，等接著的月經來潮後再開始吃","(C) 如果要吃混合雌性素與黃體素的避孕藥，現在可以開始服用","(D) 如果要用子宮內避孕器，要等4～6週後返診時再置入"],"answer":3,"image":""},{"id":"nr4-110-2-21","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"蔡女士18歲，表示：「我都用保險套避孕，前幾天跟我男友發生關係，忘記要用套子，可是我們不想懷孕。」，下列敘述何者最適當？","options":["(A) 說明墮胎的方式與合併症，建議跟男友商量並繼續懷孕","(B) Mifepristone（RU486）有拮抗黃體素的作用，可以用來避免懷孕","(C) 因為還不確定懷孕，建議繼續觀察，確定懷孕後再決定如何處理","(D) 在72小時內服用高劑量雌性素，12小時後再服第二劑，可以用來避孕"],"answer":1,"image":""},{"id":"nr4-110-2-22","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"有關新生兒飢餓的暗示行為，下列敘述何者錯誤？","options":["(A) 寶寶的手伸向嘴巴並扭動身體","(B) 臉部放鬆","(C) 舌頭伸出來","(D) 寶寶的臉轉向照顧者"],"answer":1,"image":""},{"id":"nr4-110-2-23","subject":"nr4","topic":"產科-產後照護","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"婦女於正常陰道生產後的復舊生理變化，下列何者所需時間最長？","options":["(A) 陰道皺襞","(B) 心輸出量","(C) 排尿量","(D) 月經週期"],"answer":3,"image":""},{"id":"nr4-110-2-24","subject":"nr4","topic":"產科-產後照護","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"白女士G2P2，陰道生產後一週，此時惡露的評估正常為何？①白色 ②粉紅色 ③1小時內產墊上的血液約為5公分 ④30分鐘浸溼整片產墊","options":["(A) ①③","(B) ②④","(C) ①④","(D) ②③"],"answer":3,"image":""},{"id":"nr4-110-2-25","subject":"nr4","topic":"產科-待產與分娩","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"白女士因胎兒窘迫接受剖腹生產，採腰椎硬膜外麻醉，有關於術後姿勢及其護理指導，下列何者最適當？","options":["(A) 採垂頭仰臥式，有助呼吸道分泌物引流","(B) 維持平躺8小時，避免腦脊髓液滲出","(C) 採辛氏臥位頭側向一邊，避免分泌物阻塞呼吸道","(D) 協助左側躺，以增加子宮的血液循環"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第25題一律給分。 (原公告答案 D)"},{"id":"nr4-110-2-26","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"下列那一個新生兒篩檢項目為檢測性聯染色體隱性遺傳疾病？","options":["(A) 半乳糖血症","(B) G-6-PD缺乏症（蠶豆症）","(C) 高胱胺酸尿症","(D) 先天性甲狀腺低能症"],"answer":1,"image":""},{"id":"nr4-110-2-27","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"有關新生兒髖關節脫臼的身體或姿勢表徵，下列何者錯誤？","options":["(A) 大腿與臀部的股縫不對稱","(B) 膝關節屈曲時患部的股骨較長","(C) 歐特蘭尼徵象（Ortolani’s sign）為陽性","(D) 外展患部髖部動作時會受限且有阻力"],"answer":1,"image":""},{"id":"nr4-110-2-28","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"聽診新生兒心跳速率的部位，下列何者正確？","options":["(A) 左鎖骨內側第2至第3肋間交會點","(B) 左鎖骨中線第3至第4肋間交會點","(C) 左鎖骨內側第3至第4肋間交會點","(D) 左鎖骨中線第2至第3肋間交會點"],"answer":1,"image":""},{"id":"nr4-110-2-29","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"有關新生兒腸胃系統及排泄，下列敘述何者錯誤？","options":["(A) 新生兒出生後3～4天，體重會下降5～10%，稱為生理性脫水","(B) 新生兒出生後12小時內未解胎便，應通知小兒科醫師檢查","(C) 出生3～4天後因哺餵母乳或配方奶的關係，會解出過渡便","(D) 因新生兒賁門擴約肌未成熟，應避免餵食太飽"],"answer":1,"image":""},{"id":"nr4-110-2-30","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"張女士，妊娠8週，因陰道斷續性少量出血到門診檢查。主訴有嚴重的噁心和嘔吐，醫師初步評估子宮大小超過懷孕週數，hCG值偏高，超音波掃描未看到胎兒影像。張女士最可能的情況是：","options":["(A) 先兆性流產","(B) 子宮外孕","(C) 雙胞胎","(D) 葡萄胎"],"answer":3,"image":""},{"id":"nr4-110-2-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"王女士，懷孕32週，突然發生陰道出血而入院，醫囑住院安胎。評估個案未覺腹痛，出血呈鮮紅色、量中。護理師的處置與指導，下列何者錯誤？","options":["(A) 密切觀察生命徵象及出血狀況","(B) 若安胎失敗，只能採剖腹生產","(C) 評估與治療前，給予個案和家屬說明程序","(D) 禁止執行陰道檢查"],"answer":1,"image":""},{"id":"nr4-110-2-32","subject":"nr4","topic":"產科-產後照護","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"下列何者不適合使用麥角鹼類藥物（如Ergonovine）來促進產後的子宮收縮？①妊娠糖尿病 ②前置胎盤 ③子癇前症 ④心臟疾病","options":["(A) ①②","(B) ②③","(C) ③④","(D) ②④"],"answer":2,"image":""},{"id":"nr4-110-2-33","subject":"nr4","topic":"產科-孕期生理與評估","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"有關德國麻疹與懷孕關係，下列敘述何者錯誤？","options":["(A) 病毒藉由空氣及飛沫傳染","(B) 德國麻疹疫苗是活的減毒疫苗","(C) 孕婦應接種疫苗以避免感染","(D) 妊娠初期感染會造成胎兒嚴重缺陷"],"answer":2,"image":""},{"id":"nr4-110-2-34","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"陳女士因痛經求診，護理師的回答，下列何者最適當？","options":["(A) 可自行服用止痛藥","(B) 可泡熱水澡以舒緩疼痛","(C) 可多吃巧克力、咖啡等食物","(D) 多休息，局部熱敷下腹部"],"answer":3,"image":""},{"id":"nr4-110-2-35","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"鄭女士因骨盆腔炎症入院治療，下列敘述何者正確？","options":["(A) 護理指導安全性生活","(B) 臥床休息，採側臥以利引流","(C) 執行陰道灌洗，以保持清潔","(D) 每天限液體1,000 c.c.內"],"answer":0,"image":""},{"id":"nr4-110-2-36","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"有關更年期婦女使用荷爾蒙補充療法的禁忌，下列何者錯誤？","options":["(A) 下肢靜脈血栓","(B) 憂鬱症","(C) 高血壓","(D) 子宮頸原位癌"],"answer":1,"image":""},{"id":"nr4-110-2-37","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"有關更年期婦女的護理指導，下列何者不適當？","options":["(A) 定期做子宮頸抹片檢查","(B) 鈣攝取量增加至500 mg/天，以預防骨質疏鬆","(C) 減少高糖高油脂食物","(D) 建議維生素D攝取400 IU/天"],"answer":1,"image":""},{"id":"nr4-110-2-38","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"下列何者不是預防新生兒臍帶感染的護理措施？","options":["(A) 沐浴前先用95%的酒精消毒，再用75%的酒精促進乾燥","(B) 每次更換尿布時應注意臍帶是否有感染徵象","(C) 包尿布時應保持尿布在臍部以下，避免尿液回滲","(D) 臍帶尚未脫落前，應隨時保持臍部清潔乾燥"],"answer":0,"image":""},{"id":"nr4-110-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"下列何者最可能與原發性月經疼痛相關？","options":["(A) 前列腺素","(B) 子宮肌瘤","(C) 卵巢腫瘤","(D) 經血量過多"],"answer":0,"image":""},{"id":"nr4-110-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"王女士26歲，結婚2年，因性交疼痛令其十分困擾而就診，下列護理措施何者錯誤？","options":["(A) 夫婦兩人一起討論以發掘彼此忽略的問題","(B) 為顧及配偶自尊，治療初期以王女士為主","(C) 探討病因期間建議王女士暫時禁慾","(D) 必要時可鼓勵使用無刺激性的潤滑劑"],"answer":1,"image":""},{"id":"nr4-110-2-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"有關3歲兒童的心肺復甦術之敘述，下列何者正確？","options":["(A) 執行心外按摩，以兩根手指按壓胸骨，深度為4公分","(B) 檢查有無脈搏時，以肱動脈為主","(C) 執行人工呼吸時，應同時罩住口、鼻，以防吹氣時漏氣","(D) 胸部按壓與人工呼吸比例，單人施救應30：2，雙人施救應15：2"],"answer":3,"image":""},{"id":"nr4-110-2-42","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"小強，5歲，因溺水急救後送至急診，體溫為29℃，下列處置何者錯誤？","options":["(A) 使用40～45℃加熱潮濕的氧氣","(B) 由靜脈提供40～42℃的溫熱液體","(C) 給予40～45℃電解液行胃灌洗","(D) 給予加溫毯使體溫上升3℃/小時"],"answer":3,"image":""},{"id":"nr4-110-2-43","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"小剛，12歲，國小六年級，因最近走路經常偏斜、跌倒，情緒變得暴躁，且經常遺忘事情而入院，經醫師檢查後，診斷為惡性腦瘤，母親情緒低落的說：「怎麼會這樣呢？小剛這麼乖，為什麼要讓他受這麼多折磨，我到底做錯了什麼？」，護理師最適當的處理為何？","options":["(A) 媽媽別難過，只要配合醫師，醫師一定會把孩子醫好的","(B) 小剛這麼乖，這麼聽話，媽媽要有信心，上帝一定會幫助他的","(C) 媽媽聽了醫師病情解釋後，心理一定非常傷心難過，如果想哭就哭出來","(D) 人生有許多不如意的事，媽媽不要想太多"],"answer":2,"image":""},{"id":"nr4-110-2-44","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"針對注意力不足／過動症（attention deficit hyperactivity disorder, ADHD）的行為表現與診斷之敘述，下列何者錯誤？","options":["(A) 容易分心精神無法集中","(B) 過動及衝動行為持續3個月","(C) 學齡兒童常見的發展性神經行為障礙之一","(D) 重複一些被禁止的行為，企圖引他人注意"],"answer":1,"image":""},{"id":"nr4-110-2-45","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"小莉，3歲，因被熱湯潑及，處於燒燙傷急救期（emergent period），當小莉在低血量休克狀態下時，下列何者為最有效的止痛劑給予途徑？","options":["(A) 鼻部吸入","(B) 皮下注射","(C) 肌肉注射","(D) 靜脈注射"],"answer":3,"image":""},{"id":"nr4-110-2-46","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"美國精神疾病診斷準則手冊第五版（DSM-5）將自閉症、亞斯伯格症及未分類廣泛性發展障礙，統稱為自閉症類群障礙症（autism spectrum disorder, ASD），有關其身心表徵，下列何者錯誤？","options":["(A) 孤立的人際互動","(B) 動作協調困難","(C) 堅持固定的習慣或玩法","(D) 語言和溝通能力障礙"],"answer":1,"image":""},{"id":"nr4-110-2-47","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"有關兒童虐待的敘述，下列何者錯誤？","options":["(A) 遇到可疑的受虐兒，可撥打110或113專線","(B) 1歲以下嬰兒身上有任何的骨折，都須通報","(C) 與受虐兒談話時，需協助指認及責怪施虐者","(D) 施虐者大多是受虐兒熟識的身邊人占最多"],"answer":2,"image":""},{"id":"nr4-110-2-48","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"有關為4歲的兒童進行身體檢查評估時，下列敘述何者最適當？","options":["(A) 測量耳溫時，應將該兒童的耳朵向下向後拉","(B) 測量心尖脈的位置為左鎖骨中線與第五肋間交會點","(C) 進行副鼻竇檢查時，首重出生時即存在且發育的額竇","(D) 進行呼吸速率評估時，應注意該年齡為腹式呼吸"],"answer":3,"image":""},{"id":"nr4-110-2-49","subject":"nr4","topic":"兒科-生長發展","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"護理師為了讓2～6歲病童認為藥杯內藥物減少，將小藥杯改為較大底面積的藥杯，主要是運用兒童尚未發展何種認知概念？","options":["(A) 物體恆存","(B) 質量保留","(C) 象徵符號","(D) 抽象邏輯"],"answer":1,"image":""},{"id":"nr4-110-2-50","subject":"nr4","topic":"兒科-生長發展","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"下列那個年齡層兒童，其繪畫發展已能充分表現創造性、具有平面及空間概念畫法？","options":["(A) 2～4歲","(B) 4～7歲","(C) 7～9歲","(D) 9～12歲"],"answer":2,"image":""},{"id":"nr4-110-2-51","subject":"nr4","topic":"兒科-生長發展","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"依據皮亞傑（Piaget）的認知發展理論，感覺運動期（sensory-motor stage）的孩童，主要在建立何種概念？","options":["(A) 萬物有靈","(B) 時間概念","(C) 物體恆存","(D) 抽象符號"],"answer":2,"image":""},{"id":"nr4-110-2-52","subject":"nr4","topic":"產科-新生兒護理","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"餵食母乳之新生兒，可由母乳得到何種抗體，協助其對抗水痘、單純性疱疹與流行性感冒？","options":["(A) IgA","(B) IgD","(C) IgE","(D) IgG"],"answer":0,"image":""},{"id":"nr4-110-2-53","subject":"nr4","topic":"兒科-高危險新生兒","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"早產兒的體溫調節功能不成熟，下列護理措施何者不適當？","options":["(A) 採集中護理，執行醫療照護時避免早產兒離開保溫箱","(B) 低出生體重早產兒絕對不能執行袋鼠式護理，以免造成低體溫","(C) 使用特殊透明膠膜覆蓋於加熱處理台（warmer），可以減少體熱散失","(D) 早產兒抱出保溫箱時需要提供保暖，例如帽子、包被、手套"],"answer":1,"image":""},{"id":"nr4-110-2-54","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"小衡，7歲，因妥瑞氏症（Tourette’s disorder），在學校常出現搖頭聳肩、發出狗叫聲，導致班上同學嘲笑，下列護理措施何者不適當？","options":["(A) 疾病會影響智能發展，宜提供特殊教育","(B) 評估小衡對疾病的認知程度，給予正向的心理支持","(C) 教導小衡學會放鬆，減少因身體抽動導致疲倦的症狀","(D) 教導家屬發掘小衡潛能或專長，以建立良好的自信心"],"answer":0,"image":""},{"id":"nr4-110-2-55","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"小妮，1歲半，診斷為蠶豆症（G-6-PD），有關此疾病之兒童與家庭壓力反應之護理措施，下列敘述何者最不適當？","options":["(A) 應用聯合性遊戲溝通，以緩解其罪惡感","(B) 儘量減少與父母分離以避免分離焦慮","(C) 儘量維持小妮的日常生活作息與規範","(D) 做任何治療時應使用簡潔的字句與小妮溝通"],"answer":0,"image":""},{"id":"nr4-110-2-56","subject":"nr4","topic":"兒科-意外事故與急症","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"媽媽看到2歲大的小寶喝了一大口漂白水，應該如何立即處置再送醫？","options":["(A) 先給小寶清水漱口","(B) 先給小寶喝一點牛奶","(C) 先幫小寶拍背讓他吐出來","(D) 給予吐根糖漿引發嘔吐"],"answer":1,"image":""},{"id":"nr4-110-2-57","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"有關護理師與癌症末期病童談論有關死亡的溝通方式，下列敘述何者最適當？","options":["(A) 可鼓勵學齡期病童憑空想像死亡的意義","(B) 避免與病童討論死亡議題","(C) 提供病童遊戲和藝術，表達其想法與感受","(D) 給予病童痊癒的希望"],"answer":2,"image":""},{"id":"nr4-110-2-58","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"新生兒經母子垂直感染後天免疫缺乏症候群（AIDS），有關護理措施之敘述，下列何者錯誤？","options":["(A) 執行侵入性治療時採取全面性防護措施","(B) 鼓勵哺餵母乳以提升新生兒免疫能力","(C) 可按時接種B肝疫苗","(D) 不會透過唾液及碰觸帶原者所接觸的物體感染"],"answer":1,"image":""},{"id":"nr4-110-2-59","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"有關麻疹與德國麻疹的臨床表徵之比較，下列何者正確？","options":["(A) 麻疹會在口腔出現科氏斑點（Kopliks’ spots）","(B) 德國麻疹在紅疹消退後留下棕色色素沉著","(C) 德國麻疹會出現咳嗽、結膜炎、鼻炎的症狀","(D) 麻疹的疹子出現在淋巴腺腫大之後"],"answer":0,"image":""},{"id":"nr4-110-2-60","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"幼兒感染腸病毒後的5天內，需要密切注意腸病毒的嚴重合併症狀，下列選項何者除外？","options":["(A) 嗜睡、意識不清、活力不佳、手腳無力","(B) 無故驚嚇或突然間全身肌肉收縮","(C) 呼吸急促或心跳加快","(D) 腸骨疼痛"],"answer":3,"image":""},{"id":"nr4-110-2-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"有關氣喘病童使用吸入型氣喘藥物，下列敘述何者錯誤？","options":["(A) 使用定量噴霧吸入劑（metered dose inhaler）時，應告訴病童閉氣5～10秒鐘","(B) 乾粉吸入劑型（dry powder inhaler），建議適用於5歲以上之氣喘病童","(C) 定量噴霧吸入劑（metered dose inhaler）的優點為劑量及副作用比口服少","(D) 建議小於10歲兒童，使用定量噴霧吸入劑時併用面罩式吸藥輔助器（aerochamber）"],"answer":3,"image":""},{"id":"nr4-110-2-62","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"小玲，9歲，於扁桃腺切除術（tonsillectomy）後，用手指著傷口並抱怨傷口疼痛，下列護理措施何者最適當？","options":["(A) 避免吃冰涼飲食，以免影響傷口癒合","(B) 為緩解疼痛，依醫囑按時服用Acetaminaphen","(C) 建議小玲熱敷傷口，以降低腫脹減輕疼痛","(D) 鼓勵喝檸檬汁或柳橙汁，以加速傷口癒合"],"answer":1,"image":""},{"id":"nr4-110-2-63","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"張小妹，5個月大，因肺部嚴重感染而住院，現有氣管內管留置，呼吸道分泌物黏稠，有關執行抽痰技能與應注意的事項，下列敘述何者正確？","options":["(A) 應每小時執行抽痰，以有效排除呼吸道之分泌物","(B) 抽痰順序：氣管內管→口腔→鼻腔","(C) 抽痰管應在無抽吸壓力狀態下，放置到抽吸部位","(D) 抽吸壓力應調在110～130 mmHg"],"answer":2,"image":""},{"id":"nr4-110-2-64","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"有關兒童毛地黃（Digoxin）給藥之護理指導，下列敘述何者正確？","options":["(A) 給藥前測橈動脈1分鐘，以監測心律不整","(B) 給予口服糖漿時與牛奶併用，增加服藥遵從性","(C) 忘記給藥的時間如未超過6小時，則補服一劑","(D) 長期服用需補充奶類食物，以預防低血鈣"],"answer":2,"image":""},{"id":"nr4-110-2-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"小倫，6個月大，患有法洛氏四重畸形（Tetralogy of Fallot, TOF），為維持心輸出量足夠身體所需之組織灌流的護理目標，下列護理措施何者不適當？","options":["(A) 集中護理、安撫小倫情緒，並減少哭泣","(B) 避免便秘造成閉氣用力，增加心臟負擔","(C) 宜選用柔軟、吸食洞孔稍大的奶嘴餵奶","(D) 每次餵食時間不宜太短，應超過30分鐘"],"answer":3,"image":""},{"id":"nr4-110-2-66","subject":"nr4","topic":"兒科-高危險新生兒","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"30週早產之男嬰，出生體重1,500公克，診斷開放性動脈導管（patent ductus arteriosus），以Indomethacin靜脈注射治療，下列敘述何者正確？","options":["(A) 尿量＜1 mL/kg/hr時應通知醫師調整藥物劑量","(B) 治療前聽診較少出現心雜音","(C) 因肺動脈血流下降易造成發紺","(D) Indomethacin易造成血栓之副作用"],"answer":0,"image":""},{"id":"nr4-110-2-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"阿強，9歲，罹患G-6-PD缺乏症，因全身黃疸住院治療，有關此疾病之誘發因子，下列敘述何者錯誤？","options":["(A) 最近是否吃蠶豆","(B) 最近是否服用Aspirin","(C) 最近是否有使用樟腦丸","(D) 最近是否服用止咳藥"],"answer":3,"image":""},{"id":"nr4-110-2-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"有關鐮狀細胞貧血的敘述，下列何者錯誤？","options":["(A) 紅血球變形呈鐮刀狀","(B) 遺傳因子血紅素S（Hgb S）造成紅血球變形","(C) 疼痛時可用Aspirin止痛","(D) 經由體染色體隱性遺傳而來"],"answer":2,"image":""},{"id":"nr4-110-2-69","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"小明，3歲，罹患神經母細胞瘤，進行第一次化學治療需要裝置人工血管，有關人工血管的敘述，下列何者不適當？","options":["(A) Port-A植入需要由外科醫師於手術室完成","(B) PICC可由特別訓練護理師執行導管插入","(C) Port-A每個月需要沖洗一次10 mL（含Heparine100 U/mL）生理食鹽水","(D) PICC是最適合小明化學治療期間，長期給藥的方式"],"answer":3,"image":""},{"id":"nr4-110-2-70","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"化學治療期間血液檢查結果，絕對嗜中性白血球（absolute neutrophil count, ANC）數目為320/mm3，依據檢查結果，下列護理指導何者較適當？","options":["(A) 教導個案ANC是確立白血病緩解與否的指標","(B) 教導個案ANC的正常值會隨著年齡不同而改變","(C) 教導個案注意預防感染，需採保護性隔離措施","(D) 教導個案可能出現自發性出血，需要限制活動"],"answer":2,"image":""},{"id":"nr4-110-2-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"小名，14歲，因左膝尖銳性疼痛、腫脹入院，醫師診斷為骨肉瘤（osteosarcoma）並進行截肢手術，下列護理措施何者不適當？","options":["(A) 觀察殘肢是否有出血、滲液或發炎","(B) 評估幻肢痛，視需要使用藥物和神經阻斷法改善疼痛","(C) 截肢術後立即以彈性繃帶固定殘肢，以預防攣縮","(D) 截肢術後立即裝置永久性義肢，以減輕殘肢水腫"],"answer":3,"image":""},{"id":"nr4-110-2-72","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"小花，3個月大，診斷為先天性甲狀腺功能低下，有關其疾病之臨床表徵，下列敘述何者正確？","options":["(A) 肌肉張力強","(B) 前囟門未閉合","(C) 常有腹瀉情形","(D) 皮膚乾粗"],"answer":3,"image":""},{"id":"nr4-110-2-73","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"嬰兒唇顎裂手術後的護理照護注意事項，下列敘述何者錯誤？","options":["(A) 需適時約束嬰兒，手臂避免抓到縫線","(B) 避免哭泣影響傷口，可使用安撫奶嘴安撫之","(C) 直立式坐姿是較適合餵食的方式","(D) 可用毛毯限制嬰兒翻身，避免嬰兒碰到傷口"],"answer":1,"image":""},{"id":"nr4-110-2-74","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"王小弟，6週大，每次餵奶後出現噴射式嘔吐，被診斷為幽門狹窄（pyloric stenosis），下列敘述何者正確？","options":["(A) 嘔吐物含膽汁，呈黃褐色","(B) 嘔吐多發生在餵食完後","(C) 上腹部出現由右至左慢慢移動的胃蠕動波","(D) 大便含有血液與黏膜"],"answer":1,"image":""},{"id":"nr4-110-2-75","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"小雄，2歲，因嘔吐、體溫38.6℃而入院，母親主訴小雄昨日就開始嘔吐、解水樣綠色便多次，且進食量、尿量明顯減少，體重由14公斤降到13.1公斤。下列評估何者正確？","options":["(A) 無脫水現象","(B) 輕度脫水現象","(C) 中度脫水現象","(D) 重度脫水現象"],"answer":2,"image":""},{"id":"nr4-110-2-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"張小弟，10歲，診斷為腎病症候群（nephroticsyndrome），目前服用Prednisolone治療，下列護理指導何者最適當？","options":["(A) 常見副作用是掉髮，建議以帽子或假髮修飾","(B) 出現腸胃不適，先自行停藥，待症狀改善後再服用","(C) 避免接觸有傳染病源的人或環境，以預防感染","(D) 解血尿是藥物副作用所致，停藥後會改善"],"answer":2,"image":""},{"id":"nr4-110-2-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"小芳，5歲，罹患腦性麻痺（cerebral palsy），因咀嚼及吞嚥能力較差，導致進食量少，有關協助其進食的護理措施，下列敘述何者正確？","options":["(A) 提供高熱量、高蛋白質的流質食物，以增加進食量","(B) 儘量將食物置放於舌頭後方","(C) 膝蓋放鬆低於大腿，雙腳自然下垂","(D) 不鼓勵小芳使用輔具學習獨立進食能力，以防嗆到"],"answer":1,"image":""},{"id":"nr4-110-2-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"小玉，3歲，因原有腦室-腹膜分流管（V-P shunt）感染，已移除並接受腦室外引流（external ventricular drainage）手術，有關術後護理措施，下列敘述何者正確？","options":["(A) 引流時需完全平躺，以眼睛高度為壓力零點，嚴禁抬高床頭","(B) 此裝置可配合測量顱內壓","(C) 只能採取持續性引流，不可關閉引流管","(D) 將腦脊髓液引流至一個半開放式的無菌收集瓶"],"answer":1,"image":""},{"id":"nr4-110-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"陳小妹，於學校上體育課時，出現強直陣攣型痙攣（tonic-clonic seizure）發作，下列護理措施何者最不適當？","options":["(A) 壓額抬下巴，通暢呼吸道","(B) 移開可能造成損傷的物品","(C) 勿強行放置壓舌板於口內","(D) 觀察並記錄發作型態與時間"],"answer":0,"image":""},{"id":"nr4-110-2-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"王小妹，8個月大，被診斷為熱性痙攣（febrile convulsion），下列敘述何者最適當？","options":["(A) 熱性痙攣通常會續發為癲癇的主要原因","(B) 發作時呈現全身性或局部性痙攣型態","(C) 痙攣發作時間通常持續1小時以上","(D) 熱性痙攣發作後，常造成肢體偏癱或智能障礙等後遺症"],"answer":1,"image":""},{"id":"nr4-111-1-1","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"有關醫療院所提供以家庭為中心照護之策略，下列敘述何者錯誤？","options":["(A) 鼓勵留院直到適應母職","(B) 推動準爸爸陪產制","(C) 提供待產、分娩、恢復室合而為一的樂得兒產房","(D) 協助產檯上母嬰早期肌膚接觸"],"answer":0,"image":""},{"id":"nr4-111-1-2","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"下列何者不是接受產前遺傳諮詢之高危險群孕婦？","options":["(A) 懷孕年齡為34.8歲孕婦","(B) 曾生下先天性心臟病兒之孕婦","(C) 初次被診斷為妊娠糖尿病的經產婦","(D) 孕婦先生是海洋性貧血帶原者"],"answer":2,"image":""},{"id":"nr4-111-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"下列何者不是全民健康保險於第一妊娠期婦女所提供之實驗室檢驗項目？","options":["(A) 乙型鏈球菌篩檢","(B) B型肝炎檢查","(C) 德國麻疹抗體檢驗","(D) 愛滋血清抗體檢驗"],"answer":0,"image":""},{"id":"nr4-111-1-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"有關測量胎心音的敘述，下列何者最正確？","options":["(A) 妊娠6週即可用腹部超音波掃描出胎兒心跳","(B) 妊娠16週可用杜普勒（Doppler）在平臍左右兩側探測胎心音","(C) 妊娠17～20週可用一般聽診器在腹部聽診到胎心音","(D) 妊娠20週可用杜普勒（Doppler）在劍突下1公分探測胎心音"],"answer":2,"image":""},{"id":"nr4-111-1-5","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"蔡女士，懷孕第13週，主訴上週出國到茲卡病毒疫區，她擔心胎兒會受到影響，護理師的回應，下列何者適當？","options":["(A) 解釋胎兒此時腦部已發育完全，病毒造成腦部病變機率低","(B) 返家後2週內密切觀察是否有紅疹、發燒、關節痛等症狀","(C) 建議可立即考慮做羊水茲卡病毒檢驗","(D) 立即做傳染性通報，並抽血檢驗病毒"],"answer":1,"image":""},{"id":"nr4-111-1-6","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"羅女士，因16歲的女兒月經遲遲未來，經醫師診斷為透納式症候群（Turner syndrome），有關透納式症候群之敘述，下列何者正確？","options":["(A) 其造成原因與目前塑化劑及環境荷爾蒙有關","(B) 通常會有身材矮小、第二性徵發育不全與無法生育的問題","(C) 會有月經不規則及智能遲緩的相關處置","(D) 其典型症狀為小頭、手指粗短與蹼狀足"],"answer":1,"image":""},{"id":"nr4-111-1-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"有關妊娠期婦女需增加熱量攝取之敘述，下列何者正確？","options":["(A) 依據母體氧氣消耗增加所需熱量","(B) 第一妊娠期應儲存較多熱量以利胎盤的生長","(C) 應攝取較多來自高醣、高蛋白及高脂肪食物","(D) 孕前BMI為22者，在第一妊娠期應攝取更多熱量"],"answer":0,"image":""},{"id":"nr4-111-1-8","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"在妊娠期間，下列何項腎臟功能是降低的？","options":["(A) 腎血漿流量（RPF）","(B) 腎小管的再吸收速度","(C) 對糖分吸收的閾值","(D) 腎臟的排尿量"],"answer":2,"image":""},{"id":"nr4-111-1-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"陳女士，懷孕28週，有一位4歲的孩子小明。小明對陳女士說：「我討厭媽媽肚子裡面的小妹妹，因為媽媽只關心她，都不和我玩」。下列護理師回應，何者最適當？","options":["(A) 告訴小明，要學習愛妹妹","(B) 讓小明用聽診器聽胎兒心跳","(C) 帶小明參加產前教室","(D) 利用遊戲轉移小明注意力"],"answer":1,"image":""},{"id":"nr4-111-1-10","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"有關胎兒染色體檢查的敘述，下列何者錯誤？","options":["(A) 妊娠5～8週者母血唐氏症篩檢值大於1/720為高危險群","(B) 妊娠10週以前施行絨毛膜取樣有斷肢畸形之風險","(C) 妊娠11～12週是合適進行母血檢測胎兒染色體的時機","(D) 妊娠16～18週是合適進行羊膜穿刺術的時機"],"answer":0,"image":""},{"id":"nr4-111-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"有關待產時陰道內診之敘述，下列何者錯誤？","options":["(A) 陰道內診可評估待產婦的子宮頸擴張、變薄程度及胎膜完整性","(B) 可指導待產婦深呼吸或哈氣以緩解其內診時的不適","(C) 待產婦有前置胎盤為陰道內診的禁忌","(D) 若待產婦已破水，應更密集陰道內診以評估其產程進展"],"answer":3,"image":""},{"id":"nr4-111-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"有關分娩的鎮痛與麻醉藥物之敘述，下列何者錯誤？","options":["(A) marcaine為脊髓麻醉常用藥物，術後無須平躺","(B) meperidine常用於第一產程活動期止痛用，naloxone為解毒劑","(C) meperidine具呼吸抑制之副作用及胎兒心跳變異性減低","(D) fentanyl具呼吸抑制及低血壓之副作用，naloxone為解毒劑"],"answer":0,"image":""},{"id":"nr4-111-1-13","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"有關待產時裝置胎兒監測器的注意事項，下列何者錯誤？","options":["(A) 子宮收縮壓力傳導器置於收縮力最強的子宮底位置","(B) 將胎心率傳導器置於胎心音最清晰處","(C) 應確認傳導器彈性皮帶的鬆緊度約可容納一個指頭為合宜緊度","(D) 偵測到與產婦心跳一致的胎兒臍帶雜音是正常的"],"answer":3,"image":""},{"id":"nr4-111-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"待產婦的護理紀錄記載胎兒先露部位高度是-1。此紀錄結果是指胎兒先露部位為下圖那一個編號的位置？間徑單位為公分","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":"nr4-111-1-14.jpeg"},{"id":"nr4-111-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"有關剖腹產的手術前護理措施，下列何者最適當？","options":["(A) 手術前1天進行腹部劃線作標記","(B) 手術前一晚使用抗焦慮劑","(C) 手術前3天進食低渣飲食","(D) 手術前1天及手術當天應聽診胎心音"],"answer":3,"image":""},{"id":"nr4-111-1-16","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"下列何者為枕後位（OP）第一、二產程延長的主要機轉？","options":["(A) 需要不斷的屈曲成為LOP位","(B) 內迴轉成為枕前位，費時長","(C) 在骨盆入口，不易下降","(D) 實施外部轉向時，費時較長"],"answer":1,"image":""},{"id":"nr4-111-1-17","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"陳女士，待產12小時後生下一位健康新生兒。有關護理師執行的第四產程的護理措施，下列何者不適宜？","options":["(A) 鼓勵產婦與寶寶做眼對眼的接觸","(B) 以包布覆蓋寶寶保暖並鼓勵觸摸寶寶","(C) 延後打維生素K1及先進行肌膚接觸","(D) 將新生兒放置保溫箱讓產婦休息"],"answer":3,"image":""},{"id":"nr4-111-1-18","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"陳女士，產後1週，表示有易怒、失眠、沒有食慾、注意力不集中的情形，其最有可能的情況為何？","options":["(A) 產後情緒低落","(B) 產後憂鬱症","(C) 產後精神病","(D) 產後躁鬱症"],"answer":0,"image":""},{"id":"nr4-111-1-19","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"護理師進行產後子宮復舊評估時，下列何者正確？","options":["(A) 宜先排空膀胱再進行","(B) 維持半坐臥姿勢","(C) 評估時以單手進行","(D) 剖腹產不宜進行觸診"],"answer":0,"image":""},{"id":"nr4-111-1-20","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"下列那種情況容易發生產後痛（after pain）？","options":["(A) 經產婦","(B) 羊水過少","(C) 單胞胎","(D) 剖腹產"],"answer":0,"image":""},{"id":"nr4-111-1-21","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"教導產婦執行產後運動時，膝胸臥式的主要目的為何？","options":["(A) 促進子宮恢復正常位置","(B) 促進傷口癒合","(C) 預防乳房鬆弛","(D) 改善尿失禁"],"answer":0,"image":""},{"id":"nr4-111-1-22","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"王女士，從未避孕，產後出院前表示：「我暫時不想懷孕，可是不想避孕，覺得自然比較好。」下列敘述何者最適當？","options":["(A) 如果可以無論晝夜親餵且月經未恢復，在6個月內可避孕","(B) 從接著的月經來潮第1天開始算，受精的危險期是第11天到第19天","(C) 接著的月經來潮日期不一定，在那之前是安全的，可以不用避孕","(D) 每天量基礎體溫，從體溫降低那天開始連續2天避免性交，其他日子可以性交"],"answer":0,"image":""},{"id":"nr4-111-1-23","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"有關使用荷爾蒙藥物或避孕器的敘述，下列何者正確？","options":["(A) 子宮內避孕器Mirena®在分娩後4～6週置入子宮，效期3年","(B) 混合型避孕藥在月經結束後1週開始吃，可使子宮頸黏液變稠","(C) 迷你丸（mini pills）為單一黃體素製劑，因干擾正常排卵而避孕","(D) Depo-Provera®注射後不會立即有避孕效果，建議先用保險套避孕"],"answer":3,"image":""},{"id":"nr4-111-1-24","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"李女士，採脊髓阻斷麻醉剖腹產，產後第1天主訴噁心感，起床的時候頭很痛，躺下頭痛就好些。下列何項護理指導較適當？","options":["(A) 說明是因為禁食較久，導致胃不適與血糖低，建議進食","(B) 說明是腦脊髓液不平衡，建議暫時頭不抬高平躺並補充水分","(C) 說明是麻醉藥的關係，等藥代謝後會緩解，提供檸檬水緩解噁心感","(D) 評估新生兒照顧能力，可能是擔心能力不足太過焦慮引起"],"answer":1,"image":""},{"id":"nr4-111-1-25","subject":"nr4","topic":"產科-產後照護","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"王女士表示：「我不准我兒子來，他們天天吵，太皮了，萬一妹妹怎樣就麻煩了。」下列敘述何者最適當？","options":["(A) 這樣的考量是正確的，大孩子如果太皮可能讓妹妹受傷","(B) 請其他家人一起照看大孩子，讓他們遠遠看妹妹就沒問題了","(C) 有家人在旁協助，讓大孩子撫摸或擁抱妹妹可以增強依附關係","(D) 跟哥哥們說清楚，且要訂好規則，這樣他們就可以自己抱妹妹"],"answer":2,"image":""},{"id":"nr4-111-1-26","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"新生兒出生後1分鐘，哭聲宏亮，呼吸規則，心跳128次／分，四肢略屈曲，身體呈粉紅色，四肢為藍色，阿帕嘉計分（Apgar score）為幾分？","options":["(A) 7分","(B) 8分","(C) 9分","(D) 10分"],"answer":1,"image":""},{"id":"nr4-111-1-27","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"初產婦照顧新生兒的各項行為，下列何者最不適當？","options":["(A) 洗澡過後全身擦上精油，預防皮膚乾裂","(B) 餵奶時，以搖籃式抱法，以手臂的彎曲處支持新生兒頭部，以另一隻手支撐臀部","(C) 在餵奶前或是餵奶後1小時進行沐浴","(D) 以直立式抱法，讓新生兒靠在肩膀上，一隻手支撐新生兒背臀部，一隻手拍打嗝"],"answer":0,"image":""},{"id":"nr4-111-1-28","subject":"nr4","topic":"兒科-生長發展","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"王小弟，出生1個月，有關評估其生殖器之描述，下列何者最正確？","options":["(A) 睪丸位於腹股溝，陰囊皺摺少","(B) 睪丸已下降，陰囊皺摺多","(C) 睪丸未下降，陰囊無皺摺","(D) 陰囊表面光滑，無皺摺"],"answer":1,"image":""},{"id":"nr4-111-1-29","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"有關新生兒護理之敘述，下列何者正確？①出生後給與抗生素眼藥膏預防淋病性結膜炎 ②以吸球清除分泌物時應先抽吸鼻腔 ③以75%酒精消毒臍斷面 ④頭圍量法為額頭經雙耳中端到枕骨粗隆","options":["(A) ②③","(B) ①④","(C) ②④","(D) ①③"],"answer":3,"image":""},{"id":"nr4-111-1-30","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"子癇前症孕婦以硫酸鎂（MgSO4）治療期間的護理評估重點，下列何者最重要？","options":["(A) 意識狀態之變化","(B) 身體平衡反應","(C) 深部肌腱反射","(D) 指尖再灌流檢測"],"answer":2,"image":""},{"id":"nr4-111-1-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"王女士，Rh(-)，初產下一位Rh(+)的女嬰，母女均安。為了預防下次懷孕時產生胎兒大量溶血，給予母體注射Rh0免疫球蛋白之時機，下列何者最適當？","options":["(A) 此胎產後72小時內","(B) 此胎產後6～8週","(C) 下次懷孕28週時","(D) 下次懷孕產後立即"],"answer":0,"image":""},{"id":"nr4-111-1-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"有關患有心臟病的孕婦最易發生心臟衰竭的時期，下列何者錯誤？","options":["(A) 懷孕22～26週","(B) 懷孕28～32週","(C) 待產陣痛時","(D) 產後48小時內"],"answer":0,"image":""},{"id":"nr4-111-1-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"有關孕婦接受B群（乙型）鏈球菌篩檢之敘述，下列何者錯誤？","options":["(A) 以避免垂直感染新生兒","(B) 建議孕婦在懷孕35～37週間進行篩檢","(C) 陽性者，在分娩前4小時給予抗生素","(D) 陽性者，建議採取剖腹產"],"answer":3,"image":""},{"id":"nr4-111-1-34","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"有關子宮內膜癌之敘述，下列何者錯誤？","options":["(A) 常見症狀為不正常陰道出血","(B) 是發生在子宮內最常見的癌症","(C) 病人出現症狀時多已進入晚期","(D) 診斷檢查以子宮內膜刮搔術（D&C）為主"],"answer":2,"image":""},{"id":"nr4-111-1-35","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"有關卵巢癌的醫療措施，下列敘述何者錯誤？","options":["(A) 以手術治療合併化學治療為主流","(B) 分期手術（staging surgery）前應進行腸道準備","(C) 減積手術（debulking surgery）就是儘可能將所有的卵巢腫瘤或已經擴散之腫瘤切除乾淨","(D) 初診斷之卵巢癌化療藥物以微脂體小紅莓（Lipo-Dox）為首選"],"answer":3,"image":""},{"id":"nr4-111-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"有關HPV疫苗，下列敘述何者正確？","options":["(A) 接種疫苗後，仍需定期的子宮抹片檢查","(B) 注射一劑終生有效","(C) 疫苗針對HPV型別有16、18、30、31","(D) 子宮頸癌有60～70%由HPV第30、31型引起"],"answer":0,"image":""},{"id":"nr4-111-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"陰道鏡檢查的最大優點是可清楚檢測子宮那一個部位之病灶？","options":["(A) 陰道前壁與子宮頸交接處","(B) 陰道後壁與子宮頸交接處","(C) 子宮頸內口與子宮體交接處","(D) 子宮頸轉換區"],"answer":3,"image":""},{"id":"nr4-111-1-38","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"王女士，已婚，疑似有骨盆腔炎，有關評估其臨床徵候的敘述，下列何者正確？","options":["(A) 下腹兩側鈍鈍悶痛","(B) 腹部腫大，腰圍變大","(C) 原發性月經過少","(D) 內診子宮頸有移動性疼痛"],"answer":[0,3],"image":"","answer_note":"更正:第38題答Ａ或Ｄ者均給分。 (原公告答案 C)"},{"id":"nr4-111-1-39","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"容易出現經前症候群的女性生命週期為那一時期？","options":["(A) 輸卵管結紮後的中年時期","(B) 停經前幾年的老年時期","(C) 生產後6個月青年時期","(D) 初經階段年輕時期"],"answer":3,"image":""},{"id":"nr4-111-1-40","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"有關乳房纖維腺瘤之敘述，下列何者正確？","options":["(A) 多發生於30歲以上之婦女","(B) 為最常見的乳房良性腫瘤","(C) 病人常因感到疼痛而就醫","(D) 多為界限不明之腫塊"],"answer":1,"image":""},{"id":"nr4-111-1-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"因應少子化時代來臨，為保護兒童，兒童及少年福利與權益保障法規，下列何者錯誤？","options":["(A) 醫護人員執行業務時知悉兒童及青少年有施用毒品時，應於24小時內通報相關主管機關","(B) 兒童及少年福利與權益保障法主要保護20歲以下之兒童及青少年","(C) 任何人對兒童及少年不得有遺棄、身心虐待、猥褻或性交行為","(D) 孕婦不得吸菸、酗酒、嚼檳榔或施用毒品等有害胎兒發育之行為"],"answer":1,"image":""},{"id":"nr4-111-1-42","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"當發現8個月大的張小弟口中塞有異物，有意識、呼吸困難，下列措施何者最適當？","options":["(A) 挖出異物後，於兩乳頭連線下執行心外按壓","(B) 挖出異物後，蓋住口鼻給予人工呼吸","(C) 張小弟頭低於軀幹，於肩胛骨間叩擊5下，兩乳頭連線下壓胸5下","(D) 雙手環抱張小弟腰部，於劍突下連續向上推擠5下"],"answer":2,"image":""},{"id":"nr4-111-1-43","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"有關遭受性虐待後之兒童可能出現的行為表現，下列敘述何者不適當？","options":["(A) 害怕獨處，討厭他人碰觸身體","(B) 出現複雜或不合宜的性知識概念","(C) 攻擊性強，說謊行為，但無身體發展遲滯","(D) 情緒沮喪退縮，對他人充滿敵意、不信任"],"answer":2,"image":""},{"id":"nr4-111-1-44","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"有關新生兒搖晃症候群（Shaken Baby Syndrome）的敘述，下列何者錯誤？","options":["(A) 屬於兒童虐待行為表現之一，須要通報","(B) 因外力劇烈晃動所造成，是一種可逆的傷害","(C) 初期會有嗜睡或煩躁不安","(D) 抱起新生兒時，應該給予頭頸部適當支撐"],"answer":1,"image":""},{"id":"nr4-111-1-45","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"林小弟，1個月大，剛確診膽道閉鎖，父母正為是否接受手術猶豫不決。根據以家庭為中心的兒科護理特色，下列何者最適當？","options":["(A) 為避免父母擔憂害怕，儘量減少開刀風險相關的訊息提供","(B) 利用圖片、影片與模型向病童父母解說治療的選擇","(C) 病童母親認為因懷孕時動到胎神，護理師應向母親說明絕無此事","(D) 由父母決定選擇，醫護人員不參與，增加父母自主性"],"answer":1,"image":""},{"id":"nr4-111-1-46","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"兒科護理重視以家庭為中心的照護，有關其基本觀念之一「賦權（empowerment）」的定義，下列敘述何者正確？","options":["(A) 治療兒童疾病需考量健康提供者、病童及父母親的相互利益，以滿足家庭成員需求","(B) 醫療人員與家庭互動過程中，讓家庭成員獲得自我控制感，進而增加優勢、能力及行動","(C) 由護理師扮演兒童發言人，讓家庭對兒童的健康需求有所認知","(D) 專業人員使用高科技輔助溝通，使兒童及其家庭減輕其壓力，讓傷害降低"],"answer":1,"image":""},{"id":"nr4-111-1-47","subject":"nr4","topic":"兒科-生長發展","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"一般2歲兒童的生長發育，下列敘述何者錯誤？","options":["(A) 前囟門已閉合，且胸圍大於頭圍","(B) 腹式呼吸，速率約15～20次／分","(C) 腎絲球過濾率約達成人標準","(D) 已長出側門齒和第一大臼齒"],"answer":1,"image":""},{"id":"nr4-111-1-48","subject":"nr4","topic":"兒科-生長發展","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"臨床上可以和嬰幼兒玩躲貓貓遊戲，轉移害怕的注意力，主要是利用其已發展何種概念？","options":["(A) 保留概念（conservation）","(B) 符號功能（symbolic function）","(C) 物體恆存（object permanence）","(D) 視覺暫存（persistence of vision）"],"answer":2,"image":""},{"id":"nr4-111-1-49","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"小苗，5歲，因小腿蜂窩性組織炎住院接受治療，護理師在進行「兒童疼痛概念」發展之評估時，下列敘述何者最適當？","options":["(A) 小苗會擔心自己的腳無法走路且害怕被截肢","(B) 小苗認為，吹吹痛痛的地方，疼痛就會像魔術般的消失","(C) 小苗可以正向應用其生活經驗調適疼痛","(D) 小苗可以說出蜂窩性組織炎造成自己疼痛的原因"],"answer":1,"image":""},{"id":"nr4-111-1-50","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"有關對於兒童疼痛控制的敘述，下列何者正確？","options":["(A) meperidine用於癌末疼痛控制，但不適合人工血管術後病童","(B) naloxone為鴉片類藥物拮抗劑，可緩解呼吸抑制的副作用","(C) morphine為鴉片類製劑，常使用於開刀後病童的疼痛控制","(D) acetaminophen易產生耐受性，故不建議於兒科疼痛的控制"],"answer":1,"image":""},{"id":"nr4-111-1-51","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"正常新生兒消化系統特徵的敘述，下列何者錯誤？","options":["(A) 唾液的分泌量少","(B) 賁門括約肌不成熟","(C) 胃排空時間約6小時","(D) 出生後24小時內排出胎便"],"answer":2,"image":""},{"id":"nr4-111-1-52","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"有關病童約束的原則，下列何者錯誤？","options":["(A) 有醫囑和家屬同意書時，才能執行約束","(B) 須確保約束肢端的皮膚完整性","(C) 每隔2小時要評估約束的狀況","(D) 木乃伊約束是嬰兒常用的約束法之一"],"answer":2,"image":""},{"id":"nr4-111-1-53","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"小方，進入瀕臨死亡狀態，有關瀕死的生命跡象，下列何者最不適當？","options":["(A) 失去理智且意識混亂","(B) 失去大小便的控制能力","(C) 呼吸型態改變（潮式呼吸法：Cheyne-Stokes respiration）","(D) 快速且強而有勁的脈搏"],"answer":3,"image":""},{"id":"nr4-111-1-54","subject":"nr4","topic":"兒科-高危險新生兒","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"早產兒口、鼻、氣管內管分泌物多，必要時應予抽吸，下列敘述何者正確？","options":["(A) 抽吸順序為①鼻 ②口 ③氣管內管","(B) 抽吸管大小為5～8 Fr.","(C) 抽吸壓力不可超過60 mmHg","(D) 氣管內管抽吸一次約20秒"],"answer":1,"image":""},{"id":"nr4-111-1-55","subject":"nr4","topic":"兒科-高危險新生兒","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"有關新生兒胎便吸入症候群的敘述，下列何者錯誤？","options":["(A) 早產兒較常發生，主因是在子宮內缺氧","(B) 黏稠的胎便可能阻塞呼吸道","(C) 可能肺泡過度擴張，甚至破裂造成氣胸","(D) 呼吸窘迫的症狀通常在出生後很快就出現"],"answer":0,"image":""},{"id":"nr4-111-1-56","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"依據娜姬（Nagy）的理論，9歲兒童對死亡的概念為何？","options":["(A) 死亡是暫時的","(B) 會探索死亡的靈性意義","(C) 生物體死亡後無法復活","(D) 相信死亡只會發生在老人身上"],"answer":2,"image":""},{"id":"nr4-111-1-57","subject":"nr4","topic":"兒科-高危險新生兒","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"有關早產兒呼吸窘迫症候群的醫療處置，下列何者錯誤？","options":["(A) 使用氧氣頭罩（O2 hood）時氧氣流量必須大於5 L/min，以避免二氧化碳滯留","(B) 使用持續性呼吸正壓法（CPAP）壓力為8～12 cmH2O，以防止呼氣時肺泡塌陷","(C) 持續性呼吸正壓法（CPAP）使用於有自發性呼吸的早產兒","(D) 使用持續性呼吸正壓法（CPAP）後仍有呼吸窘迫的早產兒，需插入氣管內管使用呼吸器"],"answer":1,"image":""},{"id":"nr4-111-1-58","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"有關嬰兒猝死症候群的預防措施，下列敘述何者最不適當？","options":["(A) 嬰兒睡眠姿勢建議採取仰睡","(B) 嬰兒床應避免放置任何鬆軟物件","(C) 奶嘴不可懸掛在嬰兒頸部或衣物上","(D) 小於3個月的嬰兒，最好與父母同床睡眠"],"answer":3,"image":""},{"id":"nr4-111-1-59","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"有關川崎氏症的護理指導，下列敘述何者不適當？","options":["(A) 注射免疫球蛋白2個月後，要按時接種疫苗","(B) 退燒後仍需依醫囑服用低劑量的Aspirin","(C) 飲食採少量多餐和提供軟質的食物","(D) 出院後需定期回院追蹤檢查心臟功能"],"answer":0,"image":""},{"id":"nr4-111-1-60","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"小雄，9歲，因抽搐發作住院接受檢查，當護理師以腦波檢查的相關圖片及故事，解說檢查的流程及相關注意事項並澄清小雄的錯誤觀念時，此為下列何種治療性遊戲？","options":["(A) 指導性遊戲","(B) 生理健康促進性遊戲","(C) 情緒宣洩性遊戲","(D) 戲劇性遊戲"],"answer":0,"image":""},{"id":"nr4-111-1-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"小凱，5歲，入院診斷為右下肺葉肺炎，急性期發生呼吸窘迫症狀，下列護理措施何者較不適當？","options":["(A) 維持補充體液，且監測及記錄尿量","(B) 維持組織氧合，給予氧氣、擺位、通氣及抽吸","(C) 預防感染，並治療潛在疾病","(D) 協助採左側臥，以緩解疼痛"],"answer":3,"image":""},{"id":"nr4-111-1-62","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"小佩，3歲，因長期出現扁桃腺發炎，此次住院欲進行扁桃腺切除手術，有關手術後護理措施，下列敘述何者正確？","options":["(A) 出現清喉嚨或吞嚥次數增加，應視為早期出血警訊","(B) 鼓勵採平躺姿勢，以利分泌物引流","(C) 鼓勵進食西瓜汁、番茄汁等冰冷飲料，以減輕疼痛","(D) 鼓勵用力擤鼻涕，清除口咽內分泌物"],"answer":0,"image":""},{"id":"nr4-111-1-63","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"陳小弟，7個月大，因高燒、聲音出現狗吠聲而入院，經醫師診斷為哮吼（croup），有關哮吼的護理措施，下列敘述何者錯誤？","options":["(A) 給予充足的水分與適當的營養","(B) 給予抽痰協助分泌物排出","(C) 觀察有無呼吸窘迫現象，如心跳加快、鼻翼搧動、胸骨凹陷等","(D) 如醫師開立Flixotide蒸氣吸入後，應協助病童漱口以預防感染"],"answer":1,"image":""},{"id":"nr4-111-1-64","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"小華，診斷主動脈狹窄（Coarctation of Aorta）入院，有關其身體評估之敘述，下列何者最適當？","options":["(A) 易有暈眩、流鼻血、心搏過速等症狀","(B) 下肢因血流增加，而溫度較高","(C) 頸動脈搏動變弱","(D) 下肢血壓會高於上肢血壓"],"answer":0,"image":""},{"id":"nr4-111-1-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"王小弟，心室中膈缺損（VSD），出現充血性心衰竭的症狀，呼吸喘，費力，請問採那個姿勢較舒適？","options":["(A) 趴睡","(B) 側睡","(C) 垂頭俯臥","(D) 半坐臥"],"answer":3,"image":""},{"id":"nr4-111-1-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"有關兒童心導管檢查的各腔室含氧飽和度，下列敘述何者異常？","options":["(A) 右心房含氧飽和度70～75%","(B) 肺靜脈含氧飽和度70～75%","(C) 主動脈含氧飽和度95～98%","(D) 左心房含氧飽和度95～98%"],"answer":1,"image":""},{"id":"nr4-111-1-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"有關尚未接受治療之缺鐵性貧血（iron deficiency anemia）及地中海型貧血（thalassemia）病童血液檢驗之敘述，下列何者正確？","options":["(A) 缺鐵性貧血病童之平均血球血紅素（MCH）低於正常；地中海型貧血病童則正常","(B) 缺鐵性貧血病童之平均血球容積（MCV）正常；地中海型貧血病童則低於正常","(C) 缺鐵性貧血病童之血清鐵質降低；地中海型貧血病童鐵蛋白（ferritin）則上升","(D) 兩者病童發病時間皆常見於6～24個月大"],"answer":2,"image":""},{"id":"nr4-111-1-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"有關血友病關節血腫的臨床表徵，最常發生於何部位？","options":["(A) 腕關節","(B) 肘關節","(C) 踝關節","(D) 膝關節"],"answer":3,"image":""},{"id":"nr4-111-1-69","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"小良，4歲，身高90公分，患有生長素缺乏（growth hormone deficiency），有關護理措施，下列敘述何者不適當？","options":["(A) 應以小良發展年齡的方式與其互動，以促進正向發展","(B) 建議發掘小良較優勢的能力，而非靠身高取勝的活動","(C) 建議母親在家中須每日早上起床時為小良注射生長素","(D) 生長素的注射部位可以選擇腹部及大腿，採皮下注射"],"answer":2,"image":""},{"id":"nr4-111-1-70","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"小華，11歲，診斷為副甲狀腺功能低下，下列護理照護措施之敘述，何者較不適當？","options":["(A) 身材矮小、圓臉和短脖子會影響小華的身體心像，鼓勵支持小華的興趣發展","(B) 若緊急出現低血鈣時，可以靜脈注射葡萄糖鈣（calcium gluconate）","(C) 發生強直性痙攣時，應維持呼吸道通暢和注意安全","(D) 服用高劑量的維他命A"],"answer":3,"image":""},{"id":"nr4-111-1-71","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"小奇，10歲，診斷為第一型糖尿病，有關運動的護理指導，下列敘述何者較不適當？","options":["(A) 建議運動時隨身攜帶糖果或果汁","(B) 鼓勵進行游泳、慢跑等有氧運動","(C) 建議養成每日睡前運動的習慣","(D) 提醒注射胰島素60～90分鐘後再運動"],"answer":2,"image":""},{"id":"nr4-111-1-72","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"有關新生兒篩檢的敘述，下列何者錯誤？","options":["(A) 透過篩檢可早期發現和治療先天代謝異常的疾病","(B) 採血位置為兩腳後足跟外側","(C) 於新生兒出生滿24小時，或已完全由腸道進食12小時後採檢","(D) 初步報告疑陽性者，由負責採集機構通知家長帶個案進行複檢"],"answer":2,"image":""},{"id":"nr4-111-1-73","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"乳糜瀉（celiac disease）是對蛋白質中的麩質過敏而導致吸收不良的疾病，下列何種食物不適合麩質過敏的兒童食用？","options":["(A) 燕麥片","(B) 玉米","(C) 米飯","(D) 蛋"],"answer":0,"image":""},{"id":"nr4-111-1-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"咚咚，4個月大，疑似泌尿道感染（urinarytractinfection）住院，經排尿性膀胱尿道攝影（Voiding cystourethrogram, VCUG）檢查，確認為第三級，下列敘述何者正確？","options":["(A) 屬輕微的尿液逆流，不需治療會自行痊癒","(B) 出院後每3個月做1次尿液培養至少1年","(C) 宜限制水分攝取，避免發生低血鉀","(D) 安排開刀，避免尿液大量逆流，造成腎臟損傷"],"answer":1,"image":""},{"id":"nr4-111-1-75","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"有關先天性巨結腸症的臨床表徵，下列敘述何者錯誤？","options":["(A) 出生24小時內無法排出胎便","(B) 新生兒時有嘔吐現象且嘔吐物不含膽汁","(C) 嬰兒期時有難以進食及生長遲滯之狀況","(D) 兒童期有慢性便秘且呈現絲帶狀糞便"],"answer":1,"image":""},{"id":"nr4-111-1-76","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"小華，5歲，罹患腎病症候群（nephrotic syndrome），全身出現水腫。為預防因水腫可能產生的皮膚完整性受損，下列護理指導何者不適當？","options":["(A) 選擇寬鬆通風的棉質衣服","(B) 適當地支托身體可減輕水腫及增加舒適感","(C) 避免經常更換姿勢導致皮膚摩擦受損","(D) 保持皮膚及皺摺處的清潔與乾燥"],"answer":2,"image":""},{"id":"nr4-111-1-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"妙妙，5個月大，因發展性髖關節發育不良（developmental dysplasia of the hip）入院，進行髖部人字形石膏固定，有關石膏固定之出院護理，下列敘述何者不適當？","options":["(A) 餵食時，盡可能採用坐姿或仰臥並抬頭抬高，以預防受嗆","(B) 當因石膏內皮膚發癢不適而哭鬧，協助以長竹棍伸入抓癢減輕不適","(C) 多給予撫觸、擁抱，利用玩具分散注意，以減輕不適","(D) 經常更換尿布，以防石膏受糞便污染"],"answer":1,"image":""},{"id":"nr4-111-1-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"小薇，13歲，經檢查發現脊柱側彎角度30度，確診為脊柱側彎，有關醫療及護理措施，下列何者正確？","options":["(A) 除洗澡及睡覺之外，都需穿著背架","(B) 需持續穿著背架直到骨成熟為止","(C) 需同步接受脊柱融合術","(D) 穿著背架時才可進行較劇烈的球類運動"],"answer":1,"image":""},{"id":"nr4-111-1-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"有關成骨不全（osteogenesis imperfecta）病變的護理措施，下列敘述何者錯誤？","options":["(A) 鼓勵儘量固定不動以避免多重骨折","(B) 使用雙磷化合物降低骨折頻率","(C) 固定不動時宜在健側多做運動","(D) 可做骨髓內固定以增強骨的強度"],"answer":0,"image":""},{"id":"nr4-111-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"張小妹，10歲，罹患腦膜炎，出現顱內壓增高（Increased intracranial pressure, IICP），下列護理措施何者不適當？","options":["(A) 監測有無便秘情形","(B) 監測有無噴射式嘔吐、認知改變","(C) 避免執行頭低腳高的姿位引流","(D) 執行背部扣擊或抽痰，以利呼吸道通暢"],"answer":3,"image":""},{"id":"nr4-111-2-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"有關懷孕期正常內分泌變化的敘述，下列何者正確？","options":["(A) 腦下垂體前葉分泌濾泡刺激素及黃體生成素會增加","(B) 甲狀腺所分泌的甲狀腺素會增加","(C) 腎上腺分泌留鹽激素會降低","(D) 胎盤分泌的雌二醇分泌增加取代卵巢分泌的雌三醇"],"answer":1,"image":""},{"id":"nr4-111-2-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"阮女士，目前懷孕30週，飲食偏好辣與冷食，公婆一直抱怨這樣飲食型態對孩子健康不好，下列護理處置，何者較不適當？","options":["(A) 評估孕婦的飲食嗜好及行為","(B) 尊重接受孕婦的看法採不批評的態度","(C) 認同公婆想法，一起說服其改變不健康的飲食","(D) 尊重孕婦最後的信念與決定"],"answer":2,"image":""},{"id":"nr4-111-2-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"有關周產期死亡率的定義，下列何者正確？","options":["(A) 妊娠20週以上之死胎數及出生1週內的嬰兒死亡數÷一年中活產數×1000","(B) 妊娠28週以上之死胎數及出生1週內的嬰兒死亡數÷一年中活產數×1000","(C) 妊娠28週以上之死胎數÷一年中活產數×1000","(D) 妊娠24週以上之死胎數÷一年中活產數×1000"],"answer":1,"image":""},{"id":"nr4-111-2-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"王女士，懷孕10週，有關雌性素（estrogen）增加而發生的子宮頸變化，下列何者錯誤？","options":["(A) 子宮頸血管增生充血","(B) 子宮頸黏液分泌增加","(C) 子宮頸組織變肥厚堅硬","(D) 子宮頸腺體增加腫脹"],"answer":2,"image":""},{"id":"nr4-111-2-5","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"李女士，懷孕11週，第一胎為唐氏症，此胎希望可以提前檢查確診，下列何者為此時較適當的檢查？","options":["(A) 胎兒頸部透明帶","(B) 絨毛膜取樣術","(C) 羊膜腔穿刺術","(D) 唐氏症母血檢驗"],"answer":1,"image":""},{"id":"nr4-111-2-6","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"李女士，懷孕40週尚無產兆，前來進行30分鐘的無壓力試驗，有關無壓力試驗判讀所需的資料，下列何者錯誤？","options":["(A) 宮縮時胎心率出現至少15秒的加速","(B) 胎心率的變異性介於3～6次／分鐘","(C) 前10分鐘無胎動，後10分鐘5次胎動","(D) 胎心率加速通常介於12～15次／分鐘"],"answer":0,"image":""},{"id":"nr4-111-2-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"有關我國全民健康保險給付之產前檢查時間，一般孕婦常規接受妊娠糖尿病篩檢的週數為何？","options":["(A) 18～20週","(B) 24～28週","(C) 30～34週","(D) 35～37週"],"answer":1,"image":""},{"id":"nr4-111-2-8","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"有關懷孕期間血液系統的變化，下列敘述何者錯誤？","options":["(A) 血漿量比未懷孕時增加","(B) 血比容比未懷孕時降低","(C) 纖維蛋白原數目比未懷孕時增加","(D) 血小板數目比未懷孕時增加"],"answer":3,"image":""},{"id":"nr4-111-2-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"懷孕24週婦女，孕前BMI為23，目前體重比孕前增加5公斤，血色素（Hb）＝11.2g/dL，血比容（Hct）＝35%，目前飲食指導內容，下列何者除外？","options":["(A) 每日熱量攝取量較孕前增加300卡","(B) 每日額外增加鐵劑攝取量45 mg","(C) 每日增加蛋白質攝取量10 g","(D) 需攝取足夠含鈣質食物"],"answer":1,"image":""},{"id":"nr4-111-2-10","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"妊娠36週時，腹部四段式觸診觸得胎位是LOA，則評估胎心音時，超音波胎音器（doppler）應放在何處，會聽得最清楚？","options":["(A) 肚臍周圍","(B) 左側肚臍、髖骨前上棘延長線","(C) 右側肚臍與髖骨前上棘連線的中點","(D) 左側肚臍與髖骨前上棘連線的中點"],"answer":3,"image":""},{"id":"nr4-111-2-11","subject":"nr4","topic":"產科-產後照護","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"陳女士，產後1小時後評估發現其子宮位置於臍上2指且偏向右側，其最有可能的原因為何？","options":["(A) 子宮內胎盤殘留","(B) 子宮內積血","(C) 子宮收縮不佳","(D) 膀胱漲滿"],"answer":3,"image":""},{"id":"nr4-111-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"王女士，29歲，G1P0，40週。目前子宮頸擴張4公分，子宮收縮強度達50 mmHg，可自在與護理師交談，下列護理處置何者不適當？","options":["(A) 提供呼吸技巧的訓練及舒適措施指導","(B) 每30分鐘陰道內診一次，以監測產程進展","(C) 協助經常改變姿勢促進舒適與放鬆","(D) 每2小時提醒待產婦解小便排空膀胱"],"answer":1,"image":""},{"id":"nr4-111-2-13","subject":"nr4","topic":"產科-孕期生理與評估","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"王女士，G1P0，懷孕24週，常規的產前檢查正常。詢問護理師：「我有時會覺得肚子繃緊，但不覺得痛。繃緊感有時候幾秒鐘就過去，通常不超過1分鐘，沒有其他不舒服，這樣是正常嗎？」下列的回答，何者最適當？","options":["(A) 這可能是早產的徵兆，需要立即通知醫師，可能需要住院安胎","(B) 雖然目前沒事，但妳可能是早產的高危險群，需要多臥床休息","(C) 這種收縮對子宮頸變薄有幫助，妳的身體開始生產前的準備，不用擔心","(D) 這是懷孕期間一種正常的無痛性子宮收縮，無需太擔心"],"answer":3,"image":""},{"id":"nr4-111-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"有關胎兒娩出的過程，當左枕前位（LOA）的胎兒完成內回轉（internal rotation）。此時胎頭與母體骨盆間的關係，下列敘述何者正確？","options":["(A) 胎頭的矢狀縫合與母體骨盆的前後徑，呈平行狀態","(B) 胎頭的冠狀縫合與母體骨盆的前後徑，呈平行狀態","(C) 胎頭的額縫合與母體骨盆的前後徑，呈垂直狀態","(D) 胎頭的枕下前囟徑與母體骨盆的前後徑，呈垂直狀態"],"answer":0,"image":""},{"id":"nr4-111-2-15","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"根據世界衛生組織（WHO）對無併發症或任何健康問題婦女的待產期照護建議，下列何者正確？","options":["(A) 採間歇性胎心音聽診監測","(B) 例行性灌腸及陰毛剃除","(C) 產程活動期開始禁食","(D) 常規性施打點滴"],"answer":0,"image":""},{"id":"nr4-111-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"王女士，G1P0，子宮頸口開10公分，待產時宮縮疼痛，下列措施何者最適當？","options":["(A) 直接送入分娩室，等醫師來方可用力生產","(B) 可採膀胱截石臥位，此為最有助於產程進展之姿勢","(C) 當進入第二產程每30分鐘監測待產婦的血壓、脈搏和呼吸","(D) 有強烈便意感時，可採緩慢開聲門用力生產"],"answer":3,"image":""},{"id":"nr4-111-2-17","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"使用催產素催生的待產婦女，當發生下列何種情況仍可持續使用催產素促進產程？","options":["(A) 胎頭與骨盆不對稱","(B) 胎兒窘迫","(C) 前置胎盤","(D) 早期破水"],"answer":3,"image":""},{"id":"nr4-111-2-18","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"一位足月懷孕的孕婦，因腹痛來院準備待產，護理師評估其疼痛的性質：子宮收縮壓力在40 mmHg，收縮的頻率不規則，子宮頸沒有變化，疼痛與不適的部位侷限在腹部，協助來回走動時其疼痛可減輕，該產婦的子宮收縮是屬於那一種陣痛？","options":["(A) 真陣痛","(B) 假陣痛","(C) 混合型陣痛","(D) 無法分辨陣痛型態"],"answer":1,"image":""},{"id":"nr4-111-2-19","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"有關新生兒蒙古斑的敘述，下列何者錯誤？","options":["(A) 為新生兒胎記的一種","(B) 多分布於臀部、背部和大腿","(C) 一般於12～18歲會逐漸消失","(D) 邊緣界線不明顯"],"answer":2,"image":""},{"id":"nr4-111-2-20","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"產後第二天純母乳哺餵的母親詢問：「我的寶寶兩餐之間是否需要餵開水？」下列護理指導何者最適當？","options":["(A) 6天內的純母乳寶寶都需要餵開水，避免導致結晶尿","(B) 6天內的純母乳寶寶都需要餵少量開水，避免鵝口瘡","(C) 6個月內的純母乳寶寶皆需要餵開水，避免便秘","(D) 6個月內的純母乳寶寶皆不需要餵開水，避免增加腎臟負荷"],"answer":3,"image":""},{"id":"nr4-111-2-21","subject":"nr4","topic":"產科-產後照護","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"有關產後生命徵象的評估，下列何者正確？","options":["(A) 產後心輸出量增加，不易發生姿位性低血壓","(B) 產後心輸出量增加，最初6～10天常發生心跳過緩","(C) 會陰傷口痛、子宮收縮痛，使呼吸速率下降","(D) 分娩時用力與脫水，會導致體溫升高至39 ℃"],"answer":1,"image":""},{"id":"nr4-111-2-22","subject":"nr4","topic":"產科-產後照護","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"有關泌乳機轉的敘述，下列何者正確？","options":["(A) 乳汁的移出與吸吮次數會影響泌乳量","(B) 吸吮刺激腦下垂體前葉分泌催產素","(C) 泌乳素可作用於肌皮細胞產生排乳反射","(D) 泌乳素夜間分泌較少，母親夜間應有充足睡眠以利奶水分泌"],"answer":0,"image":""},{"id":"nr4-111-2-23","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"有關各種避孕方法作用原理的敘述，下列何者正確？","options":["(A) 迷你丸使子宮內膜產生炎症反應而干擾受精卵著床","(B) 子宮內避孕器使子宮頸黏液變黏稠而產生避孕效果","(C) 避孕貼片使子宮內膜產生前列腺素化學物質而干擾受精卵著床","(D) 陰道避孕環可抑制排卵，使子宮頸黏液變黏稠而產生避孕效果"],"answer":3,"image":""},{"id":"nr4-111-2-24","subject":"nr4","topic":"產科-產後照護","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"有關產後子宮復舊（uterine involution），下列敘述何者正確？","options":["(A) 子宮底每天下降一指寬，約產後5天降至骨盆腔","(B) 除胎盤位置外，子宮內膜復舊約需6週","(C) 蛋白質自體溶解使子宮細胞數目減少而復舊","(D) 胎盤部位是由剝落過程而復舊，所以沒有疤痕形成"],"answer":3,"image":""},{"id":"nr4-111-2-25","subject":"nr4","topic":"產科-產後照護","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"吳女士，G1P1，產後第三天，計畫採純母乳哺育，詢問：「哺乳是否可以避孕？」下列護理指導何者最適當？","options":["(A) 在月經尚未出現之前，不分日夜純母乳哺餵，頻率8～10次以上，6個月內可當作避孕措施","(B) 分娩後42天可能排卵，哺乳避孕只適用於產後1個月內","(C) 哺乳可以抑制排卵，只要純母乳哺餵，月經未恢復即可避孕","(D) 純母乳哺餵是最不安全的避孕方式，不建議產後6個月內使用"],"answer":0,"image":""},{"id":"nr4-111-2-26","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"齊女士，月經週期規律，擬以安全期法避孕，下列護理師的指導何者正確？","options":["(A) 瞭解齊女士記憶中的最長及最短週期","(B) 最長月經週期減10，最短月經週期減18","(C) 卵子排卵後可存活48～72小時","(D) 避孕效果約80%"],"answer":1,"image":""},{"id":"nr4-111-2-27","subject":"nr4","topic":"產科-待產與分娩","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"有關剖腹產後陰道生產（vaginal birth after cesarean, VBAC）的敘述，下列何者正確？","options":["(A) 前胎剖腹生產的次數，不影響VBAC","(B) 前置胎盤者，可以建議行VBAC","(C) 前胎採子宮下段橫切剖腹產，此胎不宜行VBAC","(D) 曾有子宮破裂病史者，此胎不宜行VBAC"],"answer":3,"image":""},{"id":"nr4-111-2-28","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"有關新生兒臍帶的照護措施，下列何者不適當？","options":["(A) 出生24～48小時應去除臍夾避免局部壓迫性傷害","(B) 將尿布反摺避免覆蓋臍帶可促進乾燥與預防感染","(C) 若使用酒精消毒臍根部應以環狀向外消毒直徑約5公分","(D) 酒精性優碘亦可使用於臍帶消毒且乾燥效果較酒精為佳"],"answer":3,"image":""},{"id":"nr4-111-2-29","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"下列何項為新生兒晚期飢餓的暗示行為（late hunger cues）？","options":["(A) 吸吮嘴唇","(B) 不斷哭泣","(C) 將手放進嘴巴","(D) 嘴唇出現尋乳動作"],"answer":1,"image":""},{"id":"nr4-111-2-30","subject":"nr4","topic":"產科-新生兒護理","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"下列何項不是新生兒於睡眠活動週期中「安靜清醒期」（quiet alert state）的行為表徵？","options":["(A) 注意周圍環境","(B) 眼睛張大、明亮、有精神","(C) 對照顧者有反應","(D) 呼吸不規律"],"answer":3,"image":""},{"id":"nr4-111-2-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"有關妊娠合併糖尿病孕婦預後及其相關檢測的敘述，下列何者正確？","options":["(A) 產後血糖值檢測仍超過標準值者，未來一定會罹患第一型糖尿病","(B) 具第二型糖尿病的危險因子，下胎懷孕即在第一次產檢就須進行篩檢","(C) 產後血糖值檢測正常者，在產後6～12週就不需再做糖尿病篩檢","(D) 妊娠期糖尿病與卵巢分泌雌性素有關，與下一胎再度罹患糖尿病的關聯性高"],"answer":1,"image":""},{"id":"nr4-111-2-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"有關孕婦前置胎盤的症狀敘述，下列何者錯誤？","options":["(A) 腹部較少疼痛表現","(B) 常合併有胎位不正的現象","(C) 腹部呈現木板狀的堅硬","(D) 突發性鮮紅色陰道出血"],"answer":2,"image":""},{"id":"nr4-111-2-33","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"臍帶血中可作為胎兒在子宮內感染診斷之免疫球蛋白，下列何者正確？","options":["(A) IgA","(B) IgE","(C) IgG","(D) IgM"],"answer":3,"image":""},{"id":"nr4-111-2-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"王女士，G1P0，過去產檢皆正常，於妊娠32週產檢時主訴胎動有減少情形，感到很擔心，此時何項處置最適當？","options":["(A) 指導個案返家記錄每日胎動","(B) 此為此期常見情形，告知不用擔心","(C) 安排無壓力試驗","(D) 立即安排引產"],"answer":2,"image":""},{"id":"nr4-111-2-35","subject":"nr4","topic":"產科-高危險妊娠","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"有關我國後天免疫缺乏症候群母嬰的照護，下列何者錯誤？①產婦的排泄物以漂白水浸泡1小時後再沖入馬桶 ②新生兒出生7天後即給予預防性投藥 ③可以採取親子同室 ④應鼓勵餵母奶以促進親子關係","options":["(A) ①②","(B) ②③","(C) ②④","(D) ③④"],"answer":2,"image":""},{"id":"nr4-111-2-36","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"有關更年期熱潮紅症狀的敘述，下列何者錯誤？","options":["(A) 與黃體素的減少有關","(B) 起因於血管舒張與收縮之間不穩定","(C) 藉由流汗、發熱來降低體溫","(D) 體重過輕者，熱潮紅症狀更為嚴重"],"answer":0,"image":""},{"id":"nr4-111-2-37","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"女性於經期不適時建議可補充的維生素為何？","options":["(A) 維生素A","(B) 維生素D","(C) 維生素E","(D) 維生素C"],"answer":2,"image":""},{"id":"nr4-111-2-38","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"有關精液檢查的敘述，下列何者錯誤？","options":["(A) 檢查前3～5天需禁慾","(B) 自慰射精並以保險套方式收集精液","(C) 精液收集完成後保存於室溫環境中","(D) 1～2小時內送至醫院檢查"],"answer":1,"image":""},{"id":"nr4-111-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"劉女士，28歲，因外陰部搔癢、排尿時有灼熱感並有濃稠白色的陰道分泌物，內診時可見陰道壁有乳酪狀白色附著物，最有可能是下列何種病原感染？","options":["(A) 砂眼披衣菌","(B) 白色念珠球菌","(C) 梅毒螺旋體","(D) 陰道鞭毛滴蟲"],"answer":1,"image":""},{"id":"nr4-111-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"有關乳癌的護理措施，下列何者正確？","options":["(A) 術後患側手臂易發生腫脹感染，會自然恢復","(B) 術後以PQRST評估患者疼痛，其中R是recovery，評估疼痛恢復的狀況","(C) 外出時，儘量避免陽光直射患側手臂","(D) 術後腋下會出現僵硬、緊繃的感覺是正常的，會慢慢恢復，不需特別注意"],"answer":2,"image":""},{"id":"nr4-111-2-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"依據美國燒傷協會有關兒童重度燒燙傷程度的分類，下列敘述何者正確？","options":["(A) 二度燒燙傷占10～20%體表面積","(B) 二度燒燙傷占<10%體表面積","(C) 三度燒燙傷占2～10%體表面積","(D) 三度燒燙傷占>10%體表面積"],"answer":3,"image":""},{"id":"nr4-111-2-42","subject":"nr4","topic":"兒科-生長發展","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"有關自閉症兒童的敘述，下列何者護理照護較為正確？","options":["(A) 低功能自閉症兒童語言表達與理解能力通常正常","(B) 有自傷行為的自閉兒，必要時可執行適當的約束","(C) 增加身體的碰觸可刺激自閉症兒童的感覺統合","(D) 經常改變生活環境可增加自閉症兒童的學習刺激"],"answer":1,"image":""},{"id":"nr4-111-2-43","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"玲玲，2歲12公斤，媽媽自己開車載她看醫生，玲玲乘坐汽車的方式，下列何者正確？","options":["(A) 坐嬰兒安全座椅，置前座，面向車尾","(B) 坐幼兒安全座椅，置後座，面向車頭","(C) 坐幼兒安全座椅，置前座，面向車頭","(D) 坐嬰兒安全座椅，置後座，面向車尾"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第43題一律給分。 (原公告答案 B)"},{"id":"nr4-111-2-44","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"小奇，2個月大，在吃奶時，突然沒有呼吸、心跳，且嘴唇發紫，保母立即施以心肺復甦術，下列步驟何者錯誤？","options":["(A) 刺激腳跟以評估意識狀態","(B) 以10秒內檢查肱動脈","(C) 心外按摩部位於胸部兩乳頭連線中央下方","(D) 以單手掌根方式進行心外按摩"],"answer":3,"image":""},{"id":"nr4-111-2-45","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"兒童誤食下列那種毒物時，可採用催吐處理？","options":["(A) 清潔劑","(B) 鐵劑","(C) 漂白劑","(D) 洗碗劑"],"answer":1,"image":""},{"id":"nr4-111-2-46","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"丁丁，3歲，被家中養的母貓咬傷手背，傷口流血，疼痛哭泣，送至急診處理，下列處置何者錯誤？","options":["(A) 儘快打破傷風抗毒素","(B) 沖洗傷口，予抗生素藥膏局部塗抹","(C) 指導家長，傷口若發生紅腫須趕快就醫","(D) 指導家長回家應注意體溫及局部淋巴腫脹"],"answer":0,"image":""},{"id":"nr4-111-2-47","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"小玲，8歲，住院期間常抱怨因右手打點滴無法自己吃飯及畫畫、不願意打針及吃藥，護理師協助小玲增進其「自我控制感」的護理措施，下列敘述何者最適當？","options":["(A) 讓小玲表達及討論可以參與治療的方式","(B) 在小玲的同意下讓小玲的同學來院陪伴","(C) 跟小玲聊聊她喜歡的卡通以轉移注意力","(D) 請小玲的主要照顧者留在病房內陪伴"],"answer":0,"image":""},{"id":"nr4-111-2-48","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"有關執行兒童生命徵象的測量，下列敘述何者錯誤？","options":["(A) 幼兒生命徵象測量依序是呼吸、脈搏、體溫和血壓","(B) 呼吸暫停是新生兒常見表徵，僅需持續觀察和記錄","(C) 2歲以下幼兒，需測量心尖脈脈動完整1分鐘","(D) 3歲以下幼兒，測量耳溫時將耳朵向下向後拉"],"answer":1,"image":""},{"id":"nr4-111-2-49","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"有關兒童疼痛的處理，下列何者最不適當？","options":["(A) 使用鴉片類藥物，會合併給予緩瀉藥物以預防合併症發生","(B) 讀故事書是一種分散注意力法，可運用於6歲以上的小孩","(C) EMLA是一種局部麻醉劑，需於侵入性治療前1小時使用","(D) Acetaminophen是一種非類固醇抗發炎藥物，適合輕度疼痛"],"answer":0,"image":""},{"id":"nr4-111-2-50","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"小明，4歲半，入院須接受疝氣手術治療，下列那項護理措施較不適當？","options":["(A) 使用臉譜量表來評估小明術前、術後的疼痛程度","(B) 向小明解說開刀過程，應避免使用「切除」、「切開」等字眼來說明","(C) 注射後用膠布覆蓋注射部位，其目的是要轉移注意力，減輕疼痛","(D) 運用遊戲方式，如：角色扮演等，來表達術前、術後疼痛感受"],"answer":2,"image":""},{"id":"nr4-111-2-51","subject":"nr4","topic":"兒科-生長發展","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"有關兒童遊戲發展的敘述，下列何者錯誤？","options":["(A) 嬰兒期正發展單獨遊戲，如玩填充玩偶","(B) 幼兒期主要發展平行遊戲，如和鄰居一起玩耍，但各玩各的","(C) 合作性遊戲是學齡期的特色，如下棋、玩樸克牌","(D) 聯合遊戲是青春期的特色，如玩家家酒"],"answer":3,"image":""},{"id":"nr4-111-2-52","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"生理徵象的改變為評估疼痛的重要指標之一，下列何種徵象與疼痛較無直接關係？","options":["(A) 尿量","(B) 心跳","(C) 呼吸","(D) 瞳孔"],"answer":0,"image":""},{"id":"nr4-111-2-53","subject":"nr4","topic":"兒科-高危險新生兒","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"有關早產兒安全的擺位，下列敘述何者不適當？","options":["(A) 口胃管灌食後，維持頭部抬高45度約10分鐘","(B) 休息時，可肩膀朝前，雙手屈曲朝向身體中線並靠近嘴巴","(C) 平時，屈曲髖部及膝蓋，預留四肢活動的空間","(D) 若出現呼吸暫停，可頸部微仰，勿過度屈曲與伸展"],"answer":0,"image":""},{"id":"nr4-111-2-54","subject":"nr4","topic":"兒科-高危險新生兒","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"早產兒若氧氣濃度超過60%，PaO2<60mmHg時，醫囑使用持續性氣道正壓呼吸（CPAP），下列敘述何者不適當？","options":["(A) 適用於可自行呼吸之呼吸窘迫症候群早產兒","(B) 給予4～7 cmH2O壓力","(C) 可增加早產兒肺功能性肺餘容積","(D) 防止吸氣時肺泡塌陷"],"answer":3,"image":""},{"id":"nr4-111-2-55","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"對於高胱胺酸尿症（homocystinuria, HCU）兒童的長期照護，下列何者錯誤？","options":["(A) 禁食母奶，採用豆類配方之特殊奶粉（如3200-K）","(B) 對於維生素B6反應不佳的兒童，需限制含甲硫胺酸食物","(C) 建議按時接受體格與智力發育評估","(D) 早期發現早期治療可以避免近視、水晶體脫垂等眼睛病變"],"answer":3,"image":""},{"id":"nr4-111-2-56","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"小文，2歲6個月，罹患慢性病長達一年，下列有關其壓力反應之敘述，何者最適當？","options":["(A) 身體心像改變","(B) 自主感的建立","(C) 性別角色的建立","(D) 社交隔離的困擾"],"answer":1,"image":""},{"id":"nr4-111-2-57","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"小華，5歲，因其3歲弟弟罹患慢性疾病，需反覆長期住院，下列何者較不是造成小華壓力反應的風險因子？","options":["(A) 小華的性別","(B) 發病前小華與弟弟或父母關係不良","(C) 父母親情緒或行為大幅改變","(D) 害怕會被送到其他地方接受照顧"],"answer":0,"image":""},{"id":"nr4-111-2-58","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"安安，9歲，因白血病復發病況惡化，常主訴身體疼痛，下列處置何者較不適當？","options":["(A) 告訴安安不要焦慮，要放輕鬆，帶她去遊戲室轉移心情","(B) 使用安安可理解的語言與方式，以了解其身體不適的心情","(C) 評估安安的疼痛程度、疼痛性質、疼痛持續時間及範圍","(D) 協助安安採取舒適臥位，依醫囑給予止痛藥並監測成效"],"answer":0,"image":""},{"id":"nr4-111-2-59","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"有關兒童罹患後天免疫缺乏症候群（acquired immune deficiency syndrome）的敘述，下列何者不適當？","options":["(A) 病毒會侵犯輔助T細胞，造成兒童後天的免疫缺乏","(B) 間質性肺炎是愛滋病兒童最常見的臨床症狀","(C) 兒童感染愛滋病毒的潛伏期較成人長","(D) 愛滋病兒童大多是生產時經產道接觸到母親的血液和分泌物而致病"],"answer":2,"image":""},{"id":"nr4-111-2-60","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"小乖，18個月大，因感染腸病毒上吐下瀉多日而入院，原體重為14kg，入院時體重只有12kg，皮膚黏膜乾燥、脈搏淺快、尿很少，其症狀屬於：","options":["(A) 輕度脫水","(B) 中度脫水","(C) 重度脫水","(D) 正常體液流失"],"answer":2,"image":""},{"id":"nr4-111-2-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"有關呼吸道融合病毒（Respiratory Syncytial Virus, RSV）的敘述，下列何者錯誤？","options":["(A) 是一種罕見病毒，罹患RSV嬰幼兒通常會低血氧及肺擴張不全","(B) 吸入性抗病毒藥物利巴韋林（Ribavirin）可用於治療RSV","(C) 使用RSV免疫球蛋白，預防高危險嬰兒感染RSV的風險","(D) RSV可引起呼吸窘迫和肺炎，因此需入院治療"],"answer":0,"image":""},{"id":"nr4-111-2-62","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"有關罹患呼吸系統疾病兒童接受胸腔物理治療之敘述，下列何者最適當？","options":["(A) 胸腔物理治療包括呼吸運動（breathing exercise）及呼吸肌訓練","(B) 為利排痰，最有效的方法為胸部叩擊後接著給予噴霧治療","(C) 飯前及飯後1小時，是進行胸腔物理治療的最佳時間","(D) 當肺部的上、下葉皆須引流時，應以下葉為優先"],"answer":0,"image":""},{"id":"nr4-111-2-63","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"關於兒童罹患黴漿菌性肺炎（mycoplasma pneumonia）照護措施之敘述，下列何者最適當？","options":["(A) 告知家屬該肺炎的傳染性低，不用擔心會有家人間的傳染","(B) 提醒家屬注意兒童常會出現高燒、痰液量多及胸肋膜疼痛的症狀","(C) 指導家屬由於黴漿菌喜侵犯肺泡及細支氣管，故病程進展是突發且快速","(D) 跟家屬說明以Azithromycin治療，療程短且副作用較少"],"answer":3,"image":""},{"id":"nr4-111-2-64","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"小真，6個月大，體重7公斤，剛接受完開心手術入住心臟外科加護病房，有關腎臟衰竭之臨床表徵，下列何者錯誤？","options":["(A) 1小時內尿量排出0.5～2 mL/kg/hr","(B) 意識不清或昏睡","(C) 高血鉀出現心悸現象","(D) 血中尿素氮和血清肌酸酐降低"],"answer":3,"image":""},{"id":"nr4-111-2-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"有關早產兒開放性動脈導管的醫療處置，下列敘述何者錯誤？","options":["(A) 沒有症狀者，可於12週內自動關閉","(B) 給予前列腺素E1(PGE1)是優先的治療方式","(C) 出生體重低於1000 g有心衰竭症狀，宜提早作結紮手術","(D) 可在左側第二肋間聽到連續性的心雜音，成長至幼兒時期，若導管仍未關閉，通常會先考慮導管栓塞術"],"answer":1,"image":""},{"id":"nr4-111-2-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"為了增加法洛氏四重症（TOF）兒童的肺循環血流，以增加其左心充氧血的含量，下列照護處置何者錯誤？","options":["(A) 缺氧發作時予膝胸臥姿","(B) 口服給予Aspirin","(C) 靜脈滴注前列腺素E1(PGE1)","(D) 布萊洛克陶西分流術（Blalock-Taussing shunt）"],"answer":1,"image":""},{"id":"nr4-111-2-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"小蘋，5歲，診斷為缺鐵性貧血，血紅素（Hb）為5.5 g/dL，下列何項身體反應與此檢驗值最不相關？","options":["(A) 常出現發燒症狀","(B) 休息時，心跳100～120次／分鐘","(C) 注意力不集中","(D) 生長發展遲緩"],"answer":0,"image":""},{"id":"nr4-111-2-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"有關肌肉注射鐵劑時的注意事項，下列敘述何者錯誤？","options":["(A) 採Z字型深部肌肉注射","(B) 抽藥之後需要更換針頭","(C) 搓揉注射部位以利吸收","(D) 注射後應停5秒再拔針"],"answer":2,"image":""},{"id":"nr4-111-2-69","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"有關腸病毒的預防與環境消毒，下列何者正確？","options":["(A) 利用75%的酒精消毒玩具可預防腸病毒感染","(B) 接觸腸病毒幼童，可口服3天巨環黴素預防性投藥","(C) 兒童的分泌物或排泄物污染的物品建議使用1,000 ppm的含氯漂白水消毒","(D) 冷凍可殺滅腸病毒"],"answer":2,"image":""},{"id":"nr4-111-2-70","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"小芬，11個月大，初次診斷為單純性熱性痙攣（simple febrile convulsion）住院治療，下列護理措施何者錯誤？","options":["(A) 發作時協助採側臥，維持呼吸道通暢","(B) 教導家屬終生服用抗痙攣藥物的重要性","(C) 提供床欄護墊使用","(D) 通常停止發燒10天後，才執行腦電波檢查"],"answer":1,"image":""},{"id":"nr4-111-2-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"花花，3歲，罹患癌症需住院接受化學藥物治療。目前血液檢查結果為：白血球：1,200/mm3，其中多形核白血球（segmented neutrophi1）：11%、帶狀白血球（band neutrophil）：1%、單核球（monocyte）：2%、淋巴球（lymphocyte）：37%。請問其絕對嗜中性白血球（absolute neutrophi1 count, ANC）數量為何？","options":["(A) 24","(B) 144","(C) 156","(D) 444"],"answer":1,"image":""},{"id":"nr4-111-2-72","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"小莉，因診斷有食道氣管瘻管（tracheo-esophageal fistula）而住加護病房，欲執行鼻胃管放置，下列護理措施之敘述，何者較不適當？","options":["(A) 經鼻插入，長度由鼻尖到耳垂到劍突之長度為準","(B) 可接上空針並反抽，如有胃液，表示鼻胃管位置正確","(C) 灌食前，應以灌食空針反抽，評估是否有殘餘量，以了解消化吸收情形","(D) 鼻胃管灌食後鼓勵採左側臥以預防吸入性肺炎"],"answer":3,"image":""},{"id":"nr4-111-2-73","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"小佳，3歲半女童，因經常泌尿道感染而反覆入院，此次入院準備作靜脈注射腎盂攝影（intravenous pyelogram, IVP）檢查，下列護理指導之敘述，何者不適當？","options":["(A) 檢查目的為觀察上泌尿道結構","(B) 檢查期間，為防止感染宜給予預防性抗生素","(C) 檢查前，宜先確認有無對放射線顯影劑產生過敏","(D) 檢查後，宜讓小佳攝取大量液體"],"answer":1,"image":""},{"id":"nr4-111-2-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"陳小弟，4歲，診斷急性腎絲球性腎炎（acute glomerulonephritis），下列護理指導何者最適當？","options":["(A) 急性期合併水腫時，鼓勵多活動，排出過量體液","(B) 急性期合併少尿時，鼓勵多攝入果汁、湯汁等，增加尿量","(C) 急性期合併水腫時，宜以海苔、蘇打餅、洋芋片等食物，補充熱量","(D) 急性期合併少尿時，避免牛奶、蛋類、香蕉等食物"],"answer":3,"image":""},{"id":"nr4-111-2-75","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"有關兒童因幽門狹窄，需進行幽門切開術（pyloromyotomy），下列何者正確？","options":["(A) 嬰兒需禁食至排氣後，始可給予少量的葡萄糖水或電解質口服液","(B) 若給予葡萄糖水未出現嘔吐，8小時後可開始漸進式給予餵食","(C) 餵食時抬高頭部，餵食後應採左側臥或半坐臥位","(D) 手術後，易造成腸阻塞宜補充脂溶性維生素"],"answer":1,"image":""},{"id":"nr4-111-2-76","subject":"nr4","topic":"兒科-生長發展","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"小明，14歲，最近常抱怨大腿肌肉疼痛，經檢查後確認是生長痛（growing pain），下列護理措施何者不適當？","options":["(A) 建議小明應維持日常活動","(B) 減少參與太多不同種類的運動，適時休息以減緩疼痛","(C) 必要時，可依醫囑給予止痛藥，如Acetaminophen","(D) 若每晚都持續嚴重疼痛，建議尋求醫療診治"],"answer":1,"image":""},{"id":"nr4-111-2-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"有關兒童罹患妥瑞氏症（Tourette’s disorder）的疾病特徵，下列敘述何者正確？","options":["(A) 通常在18歲之前出現抽動病徵","(B) 屬於精神心理疾病，會影響未來智能發展","(C) 不自主的聲語型抽動相當罕見","(D) 動作型抽動最常出現的是聳肩"],"answer":0,"image":""},{"id":"nr4-111-2-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"小強，7歲，罹患癲癇，有長期服用抗癲癇藥，包括Phenytoin(Dilantin)及Valproic acid(Depakine)，有關藥物護理指導，下列敘述何者錯誤？","options":["(A) 指導父母須定時返院監測血中藥物濃度","(B) 當疾病發作被控制時，可暫停服用藥物以降低副作用","(C) Dilantin易造成牙齦增生，須執行良好的口腔護理","(D) 雖有定時服用藥物，仍鼓勵維持正常生活習慣，以預防發作"],"answer":1,"image":""},{"id":"nr4-111-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"有關腦性麻痺（cerebral palsy）兒童常見的健康問題，下列敘述何者較不適當？","options":["(A) 皆合併有智力障礙","(B) 普遍有粗動作發展遲緩","(C) 常會合併有發音困難或語言障礙","(D) 非進行性的神經病變"],"answer":0,"image":""},{"id":"nr4-111-2-80","subject":"nr4","topic":"兒科-意外事故與急症","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"張小弟，5個月大，因不慎跌落床下，診斷為顱內出血，有顱內壓增高（increase intracranial pressure, IICP）現象，有關其護理措施，下列敘述何者較不適當？","options":["(A) 觀察兒童囟門有無緊繃鼓脹現象，每天測量頭圍","(B) 鼓勵父母陪伴，並給予安撫，減少哭泣不安","(C) 給予多喝水，增加體液容積以及腦組織灌流","(D) 保持床頭抬高約30～45度，維持頭部於中線位置，並避免壓迫頸靜脈"],"answer":2,"image":""},{"id":"nr4-112-1-1","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"有關分娩期的支持性照護措施，下列何者較不適當？","options":["(A) 提供待產婦女一致性常規醫療照護","(B) 教導待產婦女及伴侶生產的相關知識","(C) 維持生產環境的燈光昏暗","(D) 允許待產婦女自由選擇下床走動"],"answer":0,"image":""},{"id":"nr4-112-1-2","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"下列何種情況之孕婦最需要協助轉介遺傳諮詢？","options":["(A) 姻親通婚者","(B) 親妹有血友病","(C) 超音波發現胎兒過大","(D) 先生有B型肝炎"],"answer":1,"image":""},{"id":"nr4-112-1-3","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"有關胎兒發育的描述，下列何者正確？","options":["(A) 胎兒最內層的胚胎膜是羊膜，會與子宮的基底蛻膜形成胎盤","(B) 受孕後囊胚會立即植入子宮內膜，稱為著床，通常部位發生在子宮頸內口","(C) 受精後第2～3週由胎盤提供胚胎養分","(D) 黃體退化後，胎盤取代其功能分泌雌性素及黃體素"],"answer":3,"image":""},{"id":"nr4-112-1-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"有關懷孕時因雌性素增加，造成孕期常見的不適，下列敘述何者正確？","options":["(A) 使膀胱鬆弛，產生頻尿","(B) 使腸胃道活動力降低，產生心灼熱感","(C) 使陰道黏膜增生，陰道分泌物會增加","(D) 使平滑肌放鬆，導致孕期容易便秘"],"answer":2,"image":""},{"id":"nr4-112-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"陳女士，懷孕32週，預計採陰道生產。下列何項為最有效的伸展會陰部肌肉之產前運動？","options":["(A) 腰背伸展運動","(B) 腹部強化運動","(C) 蹲踞運動","(D) 抬腿運動"],"answer":2,"image":""},{"id":"nr4-112-1-6","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"蔡女士30歲，懷孕14週，孕前身體質量指數（BMI）30 kg/m2，下列何者為最優先安排的檢查？","options":["(A) 乙型鏈球菌","(B) 血糖相關檢驗","(C) 胎盤功能評估","(D) 無壓力試驗"],"answer":1,"image":""},{"id":"nr4-112-1-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"李女士懷孕14週，產檢時詢問：「我從小就吃素，現在懷孕了，我在飲食上要注意什麼嗎？」下列回應何者較適當？","options":["(A) 素食易缺乏維生素A，可以多攝取深色蔬菜","(B) 素食易缺乏葉酸，可以多攝取綠色蔬菜","(C) 素食易缺乏維生素B12，可以多攝取海苔海藻","(D) 素食易缺乏鈣，可以多攝取牛奶起司"],"answer":2,"image":""},{"id":"nr4-112-1-8","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"懷孕期愛滋血清試驗中，對於初篩連續兩次陽性反應之個案，衛生單位應聯繫孕婦進行下列那項措施？","options":["(A) 以酵素免疫分析法（Enzyme Immunoassay, EIA）及核酸檢驗（Nucleic Acid Test, NAT）再次確認","(B) 以顆粒凝集法（Particle-Agglutination Method, PA）及抗體免疫層析（Immunochromatographic Test）再次確認","(C) 以核酸檢驗（Nucleic Acid Test, NAT）及抗體免疫層析（Immunochromatographic Test）再次確認","(D) 不須再檢測直接給予藥物治療"],"answer":2,"image":""},{"id":"nr4-112-1-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"王女士，因卵巢過度刺激症候群（Ovarian Hyperstimulation Syndrome, OHSS）住院安胎，腹水嚴重相當不舒服，且住院很多事不方便，但會說這是值得的，會努力配合治療。王女士正進行那些懷孕期發展任務（maternal task）？①確保自己及胎兒在懷孕中能安全順利 ②使重要家人接受新生兒 ③學習貢獻自己 ④與胎兒連成一體","options":["(A) ①②","(B) ②③","(C) ①③","(D) ③④"],"answer":2,"image":""},{"id":"nr4-112-1-10","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"有關衛生福利部國民健康署對婦女妊娠期體重增加之建議，下列敘述何者正確？","options":["(A) 孕前身體質量指數（BMI）＜18.5的孕婦，總體重增加應控制在7～11公斤","(B) 孕前身體質量指數（BMI）18.5～24.9的孕婦，總體重增加需11.5～16公斤","(C) 雙胞胎孕婦之建議增加總體重量為單胞胎之2倍","(D) 孕前身體質量指數（BMI）正常的孕婦，第二、三妊娠期體重宜增加0.3公斤／週"],"answer":1,"image":""},{"id":"nr4-112-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"張女士，G2P1，懷孕40週，子宮頸口擴張8公分，變薄90%，如果出現宮縮強且胎頭迅速下降想用力，下列護理措施何者較不恰當？","options":["(A) 請採哈氣，喘息呼吸","(B) 協助側躺姿勢，減輕疼痛","(C) 指導產婦用力，保護會陰","(D) 採跪趴姿勢，減少用力感受"],"answer":2,"image":""},{"id":"nr4-112-1-12","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"陰道分娩過程中，胎盤以暗紅色的粗糙面被牽引出陰道。有關此胎盤娩出的敘述，下列何者正確？ ①希氏法（Schultzemechanism）娩出 ②鄧氏法（Duncanmechanism）娩出 ③較容易發生剝離不完全 ④較少發生剝離不完全","options":["(A) ①③","(B) ②③","(C) ①④","(D) ②④"],"answer":1,"image":""},{"id":"nr4-112-1-13","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"有關待產期間施行陰道內診的敘述，下列何者錯誤？","options":["(A) 過程中須注意無菌原則","(B) 以食指及中指深入陰道內檢查","(C) 於子宮收縮時進行檢查","(D) 產婦採大腿彎曲且外展的姿勢"],"answer":2,"image":""},{"id":"nr4-112-1-14","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"有關胎心率變異性減速的敘述，下列何者正確？","options":["(A) 胎心率在宮縮高峰時開始變慢，宮縮結束後則恢復到基準","(B) 進行陰道內診確認臍帶是否受壓迫，必要時協助左側臥","(C) 因子宮胎盤灌流過度導致胎血負荷過重所致","(D) 為第二產程期間的正常現象，持續觀察即可"],"answer":1,"image":""},{"id":"nr4-112-1-15","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"陳女士因陣痛入院待產，目前子宮頸口開2公分，Oxytocin使用，宮縮每6～7分鐘一次，每次20～30秒，宮縮壓力：40～50 mmHg。主訴陣痛厲害無法忍受，下列措施何者最適當？","options":["(A) 向陳女士解釋，連絡醫師給予腰椎硬膜外麻醉止痛","(B) 簽同意書，並協助醫師準備腰椎硬膜外麻醉止痛之用物","(C) 根據陳女士宮縮壓力情形，給予按摩放鬆技巧以減輕疼痛","(D) 向陳女士解釋，目前產程無法採用腰椎硬膜外麻醉止痛，可調快Oxytocin"],"answer":2,"image":""},{"id":"nr4-112-1-16","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"第一產程活動期的待產婦，每3分鐘宮縮1次，每次持續45秒，個案在宮縮的休息期，胎心率為90 bpm，下列何項護理措施較適當？","options":["(A) 立即通知醫師","(B) 正常，可繼續監測胎心率","(C) 鼓勵個案在每次宮縮時繼續用力向下","(D) 教導個案呼吸技巧"],"answer":0,"image":""},{"id":"nr4-112-1-17","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"有關胎心音監測的敘述，下列何者正確？","options":["(A) 杜卜勒（Doppler）超音波可用來執行連續性監測胎心音","(B) Leopold四段腹查的第三段觸診為確認胎背位置","(C) 持續性的胎心音監測可得知胎心率基準線與週期性變化","(D) 高危險待產婦女與胎兒，在第一產程的潛伏期應每1小時評估一次胎心率"],"answer":2,"image":""},{"id":"nr4-112-1-18","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"剖腹產時，為減少藥物對胎兒的副作用，宜採用何種麻醉方式？","options":["(A) 靜脈注射麻醉劑法","(B) 腰椎硬膜外麻醉法","(C) 陰部阻斷法","(D) 吸入性麻醉法"],"answer":1,"image":""},{"id":"nr4-112-1-19","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"丁女士，使用催產素引產，以每小時9 c.c.靜脈滴注，胎兒監視器顯示變異性減速，此時最優先之處置為何？","options":["(A) 停止催產素","(B) 協助下床活動","(C) 準備剖腹產","(D) 密切觀察，不須特別處理"],"answer":0,"image":""},{"id":"nr4-112-1-20","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"有關母乳中各種營養素對於新生兒成長作用之敘述，下列何者錯誤？","options":["(A) 寡糖可避免致病菌黏附在腸胃道用以避免腸胃道疾病","(B) 中、長鏈不飽和脂肪酸有助於視網膜的發展","(C) 乳鐵蛋白能與鐵結合，避免鐵質被腸道細菌利用","(D) 酪蛋白可加強脂溶性維生素在腸胃道吸收的比例"],"answer":3,"image":""},{"id":"nr4-112-1-21","subject":"nr4","topic":"產科-產後照護","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"黃女士G2P2，大寶剛剛滿2歲，今天預計出院回家，產婦擔心同時照顧2個孩子會心力交瘁，下列何者有關黃女士的親子依附關係出現時，最需要特別關注與持續追蹤？","options":["(A) 大寶睡覺時，抱著新生兒目不轉睛盯著看","(B) 同時以乳房安撫大寶及新生兒","(C) 在新生兒睡覺時，唸書給大寶聽","(D) 除了哺餵新生兒，其他時間都請月嫂照顧"],"answer":3,"image":""},{"id":"nr4-112-1-22","subject":"nr4","topic":"產科-產後照護","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"坐月子期間純母乳哺餵的母親表示：「為什麼寶寶一喝完奶就解便、大便總是稀稀糊糊的？」下列護理指導何者最適當？","options":["(A) 最可能是新生兒對母乳過敏，建議改用水解配方奶","(B) 後奶含豐富乳糖，乳糖刺激新生兒胃結腸反射，而產生帶酸味的稀糊便","(C) 因坐月子期間母親攝取過多高脂食物而影響奶水成分，間接導致稀糊便","(D) 母乳水分含量高，新生兒胃結腸反射明顯，來不及將水分吸收而產生稀糊便"],"answer":3,"image":""},{"id":"nr4-112-1-23","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"有關剖腹產術前及術後之護理措施，下列何者正確？","options":["(A) 手術前4小時禁食固體食物","(B) 皮膚剃毛從肚臍往下至大腿上二分之一","(C) 如採區域性麻醉，術後不必等排氣即可進食","(D) 一般留置導尿管，點滴移除後才移除"],"answer":2,"image":""},{"id":"nr4-112-1-24","subject":"nr4","topic":"產科-產後照護","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"吳女士，G1P1，產後進行親子同室，其先生抱起寶寶，眼神專注凝視寶貝，並輕聲細語說：「我是爸爸，叫爸爸。」下列描述父親與新生兒發展依附之行為，何者最適當？","options":["(A) 肌膚接觸（skin-to-skin contact）","(B) 袋鼠護理（kangaroo care）","(C) 準父親自信（confident of expectant father）","(D) 全神貫注（engorgement）"],"answer":3,"image":""},{"id":"nr4-112-1-25","subject":"nr4","topic":"產科-產後照護","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"王女士，28歲第一胎，產後2個月，月經尚未來，採純母乳哺餵。下列何項避孕措施最不推薦？","options":["(A) 口服避孕藥","(B) 子宮內避孕器","(C) 保險套","(D) 泌乳無月經避孕法"],"answer":0,"image":""},{"id":"nr4-112-1-26","subject":"nr4","topic":"產科-產後照護","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"有關產後泌尿系統的變化，下列何者為正常現象？","options":["(A) 尿液中人類絨毛膜促性腺激素（hCG）於產後1週消失","(B) 蛋白尿持續3週","(C) 血尿持續3週","(D) 產後利尿現象持續6週"],"answer":0,"image":""},{"id":"nr4-112-1-27","subject":"nr4","topic":"產科-產後照護","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"產後3～10天，產婦的注意力集中在母親職責的學習及自己身體功能的恢復，這是符合魯賓（Rubin）提出的那一期？","options":["(A) 調適期（Adaptative Phase）","(B) 接受期（Taking-in Phase）","(C) 緊執期（Taking-hold Phase）","(D) 釋放期（Letting-go Phase）"],"answer":2,"image":""},{"id":"nr4-112-1-28","subject":"nr4","topic":"產科-產後照護","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"有關產婦乳腺炎的評估及照護，下列敘述何者錯誤？","options":["(A) 常發生於產後1週內","(B) 通常發生於單側乳房","(C) 最常見的致病菌為金黃色葡萄球菌","(D) 指導正確的哺餵母乳可預防其發生"],"answer":0,"image":""},{"id":"nr4-112-1-29","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"正常新生兒出生4～6小時內，最主要的能量來源為何？","options":["(A) 葡萄糖","(B) 胺基酸","(C) 脂肪酸","(D) 棕色脂肪"],"answer":0,"image":""},{"id":"nr4-112-1-30","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"有關維持新生兒出生即刻體溫穩定的措施，下列何者不適當？","options":["(A) 將接觸新生兒的布單事先預熱","(B) 擦乾新生兒後進行母嬰肌膚接觸","(C) 使用空調或是加溫設備維持室溫","(D) 新生兒出生後應立即沐浴維持體溫"],"answer":3,"image":""},{"id":"nr4-112-1-31","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"一位懷孕28週妊娠糖尿病孕婦接受胰島素治療，其施打的胰島素劑量隨著妊娠週數的增加也逐漸增加。胰島素的需求量與下列何項荷爾蒙的分泌增加有關？","options":["(A) 泌乳激素（Prolactin）","(B) 人類胎盤泌乳激素（human Placental Lactogen, hPL）","(C) 人類絨毛膜促性腺激素（human Chorionic Gonadotropin, hCG）","(D) 促腎上腺皮質素（Andrenocorticotropic hormone, ACTH）"],"answer":1,"image":""},{"id":"nr4-112-1-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"有關胎盤碎片殘留所致產後出血的敘述，下列何者正確？","options":["(A) 希氏法（Schultze mechanism）娩出胎盤者，較易有胎盤小碎片殘留子宮","(B) 是指分娩第二產程處理欠妥，使得部分胎盤碎片殘留子宮","(C) 胎盤小碎片殘留常是晚期產後出血之主因","(D) 應採雙手壓迫子宮法，促使子宮收縮將胎盤碎片排出"],"answer":2,"image":""},{"id":"nr4-112-1-33","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"當產科急症造成瀰漫性血管內凝血（Disseminated Intravascular Coagulation, DIC）時，下列檢驗數值何者正確？①凝血酶原時間（PT）、部分凝血酶原時間（PTT）延長 ②D-dimer數值下降 ③血小板數值下降 ④纖維蛋白原（fibrinogen）數值上升","options":["(A) ①②","(B) ①③","(C) ②③","(D) ③④"],"answer":1,"image":""},{"id":"nr4-112-1-34","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"張女士，懷孕8週，主訴陰道點狀出血、腹部微痛，超音波檢查子宮頸口未開，可能為下列何種情形？","options":["(A) 迫切性流產（Imminent abortion）","(B) 先兆性流產（Threatened abortion）","(C) 不完全流產（Incomplete abortion）","(D) 完全性流產（Complete abortion）"],"answer":1,"image":""},{"id":"nr4-112-1-35","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"承上題，超音波掃描確認胎兒心跳正常，此時最適當的照護措施為何？","options":["(A) 臥床休息，給予黃體素","(B) 給予安胎藥Yutopar服用","(C) 建議做子宮頸環紮術","(D) 投予抗生素預防感染"],"answer":0,"image":""},{"id":"nr4-112-1-36","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"郭先生的精液分析結果如下：精液量約7 c.c.，精子濃度800萬/mL，射精後42%的精蟲仍具活動力，正常型態的精蟲為50%。有關其結果之敘述，下列何者正確？","options":["(A) 結果一切正常","(B) 精子畸形症","(C) 精液過少症","(D) 精蟲減少症"],"answer":3,"image":""},{"id":"nr4-112-1-37","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"有關絨毛膜癌的敘述，下列何者錯誤？","options":["(A) 約有50%由葡萄胎惡性病變衍生而來","(B) 常見轉移之部位為肺臟","(C) 血清hCG值升高是診斷絨毛膜癌最重要的依據","(D) 以手術治療為主，放射線治療為輔"],"answer":3,"image":""},{"id":"nr4-112-1-38","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"王女士有打噴嚏、咳嗽、大笑所引起無法自主控制膀胱的漏尿，是屬於下列那種尿失禁？","options":["(A) 急迫性尿失禁","(B) 姿勢性尿失禁","(C) 壓力性尿失禁","(D) 滿流性尿失禁"],"answer":2,"image":""},{"id":"nr4-112-1-39","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"有關尖型濕疣（菜花）的敘述，下列何者錯誤？","options":["(A) 由人類乳頭瘤病毒（HPV）16與18型所引起","(B) 感染後約在2星期至8個月內出現症狀","(C) 常發生於生殖器、肛門等部位","(D) 治療方法包含雷射、液態氮、藥物等方法"],"answer":0,"image":""},{"id":"nr4-112-1-40","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"李女士40歲，因子宮内膜癌進行全子宮和雙側輸卵管卵巢切除術，出院前的護理指導，下列何者正確？①第1年每6個月回診一次 ②不可抬過重的物品 ③告知可能的更年期症狀 ④術後半年避免性行為","options":["(A) ①②","(B) ①④","(C) ②③","(D) ③④"],"answer":2,"image":""},{"id":"nr4-112-1-41","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"面對自閉症（Autism）病童住院，下列護理措施何者最適當？","options":["(A) 多與病童溝通互動，以利建立護病關係","(B) 採一對一的照護，且避免過度視聽騷擾","(C) 發現病童有重複固著行為時，要出面制止","(D) 避免病童有暴怒行為，不須事先告知說明"],"answer":1,"image":""},{"id":"nr4-112-1-42","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"以「家庭為中心的照護」應用於加護病房的照顧，下列敘述何者正確？","options":["(A) 鼓勵並支持病童父母或手足有機會時參與共同照顧","(B) 加強管理，嚴格規定父母會客時間，以預防感染","(C) 為減少交互感染之風險，應儘量避免家人探視","(D) 兒童、青少年住院，醫師應以父母作為病情溝通與解釋對象"],"answer":0,"image":""},{"id":"nr4-112-1-43","subject":"nr4","topic":"兒科-生長發展","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"李小妹，2歲8個月，屬於李小妹遊戲發展特點，下列敘述何者正確？","options":["(A) 遊戲過程獨自玩弄玩具，自得其樂，不重視玩伴","(B) 遊戲過程與玩伴互換玩具，但各玩各的，無合作行為","(C) 聯合遊戲過程，缺乏遊戲規則，亦無分工合作行為","(D) 遊戲過程與玩伴合作、競爭，訂立遊戲規則與團體目標"],"answer":1,"image":""},{"id":"nr4-112-1-44","subject":"nr4","topic":"兒科-生長發展","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"針對嬰幼兒生長發展情況之敘述，下列何者錯誤？","options":["(A) 2歲身高約成人身高的一半","(B) 前囟門約1歲半時關閉","(C) 1歲時腎絲球過濾率達成人標準","(D) 觸覺是感覺器官中最早發育的"],"answer":2,"image":""},{"id":"nr4-112-1-45","subject":"nr4","topic":"兒科-意外事故與急症","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"嬰幼兒誤食色彩鮮豔的糖果紙、廣告紙、顏料等，容易引起下列何種物質的中毒，造成中樞神經系統的損傷？","options":["(A) 鉛","(B) 鐵","(C) 銅","(D) 塑化劑"],"answer":0,"image":""},{"id":"nr4-112-1-46","subject":"nr4","topic":"兒科-意外事故與急症","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"有關兒童性虐待的常見表徵，下列敘述何者錯誤？","options":["(A) 外陰部、肛門、嘴部或喉嚨處有撕裂傷瘀傷腫脹","(B) 肢體瘦小、皮下脂肪不足的營養不良現象","(C) 睡眠紊亂、害怕獨處、同儕關係薄弱","(D) 反覆的尿道感染及解尿困難"],"answer":1,"image":""},{"id":"nr4-112-1-47","subject":"nr4","topic":"兒科-生長發展","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"有關兒童氣質評估之敘述，下列何者正確？","options":["(A) 反應閾高的嬰兒，尿布不乾淨就會哭鬧不安","(B) 堅持度高的嬰兒，容易受到外界干擾而影響","(C) 趨避性高的嬰兒，初次接受或拒絕人事物的態度明顯","(D) 反應強度是指引起孩子反應所需最小刺激量"],"answer":2,"image":""},{"id":"nr4-112-1-48","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"有關新生兒篩檢的敘述，下列何者錯誤？","options":["(A) 新生兒出生後須滿48小時才能採檢","(B) 採檢前須熱敷足部3～10分鐘","(C) 以75%酒精棉球消毒穿刺部位","(D) 手執濾紙接取穿刺後流出的第一滴血"],"answer":3,"image":""},{"id":"nr4-112-1-49","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"強強，3歲，因車禍住加護病房，剛住院時一直哭泣，對著護理師不斷地哭著說：「走開，我要媽媽…… 我要媽媽……」。根據兒童早期分離焦慮之反應屬於以下那一個階段？","options":["(A) 失望期","(B) 去依戀期","(C) 關係重建期","(D) 抗議期"],"answer":3,"image":""},{"id":"nr4-112-1-50","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"有關不同年齡層兒童口服用藥，下列敘述何者正確？","options":["(A) 建議嬰兒抱起或協助採半坐臥，每次建議口服量為5 mL","(B) 嬰兒若是服用藥粉，建議將藥粉溶入水中再以餵奶器滴入口中","(C) 幼兒服藥反抗時，建議讓其躺下並壓其下巴張開口以利服藥","(D) 若5歲以下病童選擇吞服藥丸，建議藥丸置舌尖以利吞嚥"],"answer":1,"image":""},{"id":"nr4-112-1-51","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"翔翔，9歲，因妹妹癌末瀕臨死亡住院，以下對翔翔的照護措施何者較不適當？","options":["(A) 安排他在適當時機探望妹妹","(B) 鼓勵他：「你已經是大孩子了，一切要自己忍耐下來」","(C) 請學校老師協助提供他關懷與支持","(D) 將他同時納入護理照護計畫"],"answer":1,"image":""},{"id":"nr4-112-1-52","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"有關FLACC（face, legs, activity, cry and consolability）疼痛量表，下列敘述何者錯誤？","options":["(A) 可用來評估4個月大的嬰兒","(B) 分數越高表示越疼痛","(C) 雙腳持續踢動評估分數為2","(D) 每項評估分數分為1與2二等級"],"answer":3,"image":""},{"id":"nr4-112-1-53","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"有關早產兒經口餵食的發展照護原則，下列敘述何者錯誤？","options":["(A) 早產兒出現安靜清醒期，並出現飢餓暗示行為，例如尋乳行為、吸吮動作即可開始準備","(B) 早產兒出現壓力暗示行為，例如疲倦、嗆奶、呼吸暫停、發紺，需減緩或停止餵食","(C) 對於妊娠週數低及低體重的早產兒，餵食時間應延長至60分鐘以減少壓力","(D) 觀察呼吸及膚色，調整奶瓶位置及流速，視情況暫停餵食並刺激呼吸"],"answer":2,"image":""},{"id":"nr4-112-1-54","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"有關早產兒視網膜病變的高危險群與症狀，下列敘述何者不適當？","options":["(A) 通常出現在出生體重在1,500公克以下","(B) 長期使用呼吸器與高濃度氧氣暴露為危險因子","(C) 第一、二期為輕度病變，會自行好轉，一般不需治療，少有視力障礙","(D) 視網膜完全剝離，可經由鞏膜扣壓術、玻璃體內切除術獲得治癒"],"answer":3,"image":""},{"id":"nr4-112-1-55","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"吳小弟血型為B型，因血型與O型的母親不合而造成溶血，下列敘述何者正確？","options":["(A) 「ABO血型不合」的黃疸會比「Rh因子不合」者嚴重","(B) 「ABO血型不合」通常發生在第二胎以後的新生兒","(C) 有較高機會發生聽力損傷、發展遲緩等後遺症","(D) 吳小弟需要換血，使用血品為B血型"],"answer":2,"image":""},{"id":"nr4-112-1-56","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"有關提供慢性病兒童家庭之持續性及全面性照護的護理措施，下列敘述何者較不適當？","options":["(A) 對父母親的反應及潛在需求，要有敏感度","(B) 善用傾聽技巧，且採用易於理解的語言，提供醫療訊息","(C) 主動提供共享資訊，包含有關社會資源的訊息","(D) 為了讓主要照顧者全面了解，應一次提供疾病照護的所有訊息"],"answer":3,"image":""},{"id":"nr4-112-1-57","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"人類免疫缺乏病毒（Human Immunodeficiency Virus, HIV）帶原的青少年之護理指導，下列敘述何者錯誤？","options":["(A) 指導絕對不可以發生性行為，以免傳染給他人","(B) 家人協助處理切割的傷口時，應戴手套","(C) 提醒感染HIV者不要捐血，以避免傳染疾病","(D) 教導環境設備污染時，以0.05%漂白水擦拭"],"answer":0,"image":""},{"id":"nr4-112-1-58","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"有關瀕死病童的生理變化，下列敘述何者錯誤？","options":["(A) 尿量漸減","(B) 陳施氏呼吸（Cheyne-Stokes respiration）","(C) 視力減退，聽覺最早消失","(D) 心跳慢且弱"],"answer":2,"image":""},{"id":"nr4-112-1-59","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"有關猩紅熱的臨床表徵，下列敘述何者正確？","options":["(A) 突發性高燒，盤尼西林治療24小時內體溫降至正常","(B) 舌頭最初為紅色乳突狀的紅色草莓樣舌，4～5天後轉為白色草莓樣舌","(C) 皮疹最早出現在軀幹、四肢、前額、臉頰","(D) 皮疹為針點狀紅疹，受壓迫時皮疹更明顯"],"answer":0,"image":""},{"id":"nr4-112-1-60","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"有關疱疹病毒的感染，下列何者錯誤？","options":["(A) 嘴唇或嘴部周圍聚集成叢的水泡，常見於第一型疱疹病毒感染","(B) 疱疹性齦口炎是單純性疱疹初次侵犯兒童最常見的型態","(C) 使用Acyclovir可治療疱疹病毒的感染","(D) 疱疹性齦口炎的口腔潰瘍常見口腔的後半部，咽喉與咽喉上方"],"answer":3,"image":""},{"id":"nr4-112-1-61","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"小華，9個月，診斷為雙側中耳炎（Otitis Media），有關中耳炎之臨床表徵，下列敘述何者錯誤？","options":["(A) 頸淋巴結腫大","(B) 抓或拉扯耳朵","(C) 高燒","(D) 吞嚥困難"],"answer":3,"image":""},{"id":"nr4-112-1-62","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"小名，3歲，疑似罹患流行性感冒，有關臨床表徵的敘述，下列何者最不適當？","options":["(A) 發燒和發冷","(B) 喉嚨痛和黏膜乾燥","(C) 畏光和肌肉痠痛","(D) 紅疹和皮膚搔癢"],"answer":3,"image":""},{"id":"nr4-112-1-63","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"下列那種疾病不是由A群β 型溶血性鏈球菌所引起？","options":["(A) 扁桃腺發炎","(B) 急性風濕熱","(C) 哮吼","(D) 急性腎絲球腎炎"],"answer":2,"image":""},{"id":"nr4-112-1-64","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"母親懷孕早期感染下列何種疾病，易導致新生兒罹患先天性心臟病？","options":["(A) 德國麻疹","(B) 鏈球菌感染","(C) 風濕性關節炎","(D) 急性支氣管炎"],"answer":0,"image":""},{"id":"nr4-112-1-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"菲菲，2歲，罹患法洛氏四重症（TetralogyofFallot,TOF），出院後仍需每12小時服用毛地黃（Digoxin）一次，下列護理指導何者錯誤？","options":["(A) 給藥前須完整測量心尖脈1分鐘","(B) 最好是在飯前1小時或飯後2小時給藥","(C) 勿將藥物與果汁混合餵食","(D) 若忘記給藥超過6小時應補給一劑"],"answer":3,"image":""},{"id":"nr4-112-1-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"小宇，10歲，患有主動脈狹窄（Coarctation of the Aorta, COA），入院時可能出現的臨床表徵，下列敘述何者不適當？","options":["(A) 下肢比上肢血壓高20 mmHg","(B) 股動脈搏動微弱","(C) 主訴頭痛、暈眩","(D) 主訴腳部冰冷"],"answer":0,"image":""},{"id":"nr4-112-1-67","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"小美，17歲女性，為A型血友病帶因者，到院做遺傳諮詢，下列敘述何者最適當？","options":["(A) 告知若配偶基因正常，未來每一胎生男嬰有1/2機率為血友病者","(B) 告知若配偶基因正常，則不會生下血友病的孩子","(C) 告知若配偶基因正常，未來生的男嬰不會發生血友病，女嬰則有機率是帶因者","(D) 告知若配偶基因正常，未來若生女嬰皆為帶因者但不會發病"],"answer":0,"image":""},{"id":"nr4-112-1-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"小華，3歲，在一週前發燒後身上突然出現多處紫斑，經醫師診斷為特發性血小板（Idiopathic Thrombocytopenic Purpura, ITP），下列敘述何者錯誤？","options":["(A) 這是一種自體免疫的障礙","(B) 使用類固醇治療","(C) 指導家屬禁止使用阿斯匹靈藥物（Aspirin）","(D) 建議3歲前施行脾臟切除手術"],"answer":3,"image":""},{"id":"nr4-112-1-69","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"小勇，10歲，罹患急性淋巴性白血病，目前接受化學治療中，有關其護理措施之敘述，下列何者錯誤？","options":["(A) L-asparaginase會引起血糖過高，需要監測血糖","(B) Prednisolone會增加感染機會，需採保護性隔離","(C) Vincristine需監測手腳麻刺感和便秘的現象","(D) Mycostatin指導於飯後使用，預防革蘭氏陽性菌感染"],"answer":3,"image":""},{"id":"nr4-112-1-70","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"小軒，6歲，體重20公斤，診斷為尿崩症，有關診斷與護理處置，下列何者錯誤？","options":["(A) 在接受禁水試驗（fluid deprivate test）過程中，體重減少至1公斤時，繼續試驗","(B) 24小時尿液分析之尿比重降低","(C) 當病況穩定後，可經由鼻腔噴霧法給予血管緊縮素，效果可維持8～20小時","(D) 避免過度給予血管緊縮素，造成尿量減少、體液滯留體內以及頭痛等症狀"],"answer":0,"image":""},{"id":"nr4-112-1-71","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"罹患癌症之嬰幼兒，需要接受骨髓穿刺檢查，最常選擇的部位為何？","options":["(A) 胸骨","(B) 股骨","(C) 脛骨","(D) 腰椎"],"answer":2,"image":""},{"id":"nr4-112-1-72","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"有關第1型糖尿病（Type 1 diabetes）之敘述，下列何者正確？①主要是因為自體免疫反應，使產生胰島素的β 細胞受到破壞 ②使用口服降血糖藥物就能治療疾病 ③疾病治療的準則中，血糖監測、藥物、飲食和運動缺一不可 ④好發族群為肥胖之青少年","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":0,"image":""},{"id":"nr4-112-1-73","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"陳小弟，4歲，身體瘦弱，因貧血來院檢查，疑似寄生蟲感染，陳小弟喜歡赤腳到田裡玩泥巴，下列何者是最可能感染的寄生蟲？","options":["(A) 蛔蟲","(B) 蟯蟲","(C) 鉤蟲","(D) 廣東住血吸蟲"],"answer":2,"image":""},{"id":"nr4-112-1-74","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"姍姍，2歲6個月，因為出現水腫、體重增加而入院，診斷為腎病症候群（NephroticSyndrome），有關此疾病的敘述下列何者最適當？","options":["(A) 一種因為A群β 型溶血性鏈球菌感染所導致","(B) 腎絲球受破壞，導致腎絲球膜通透性增加，常出現有蛋白尿","(C) 主要治療以抗生素為主，應指導勿隨意停藥以免產生抗藥性","(D) 容易出現有高血壓及嚴重血尿現象"],"answer":1,"image":""},{"id":"nr4-112-1-75","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"小強，14歲，因慢性腎衰竭進行腹膜透析治療中，有關護理指導的敘述，下列何者較不適當？","options":["(A) 攝取高熱量碳水化合物及脂肪類食物，特別限制蛋白質及鹽的攝取","(B) 多攝取富含鐵質、葉酸食物以及提供維生素D，防止出現貧血現象","(C) 腹膜炎是常見的合併症，病童及家屬須學習透析部位正確消毒方法","(D) 每次透析液約30～50 mL/kg緩慢注入腹內，需停留20分鐘再引流出"],"answer":0,"image":""},{"id":"nr4-112-1-76","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"有關先天性膽道閉鎖的敘述，下列何者正確？","options":["(A) 常出現水溶性維生素缺乏現象","(B) 通常執行膽道切開術後，病童一般預後良好","(C) 若未治療，易出現肝硬化、脾腫大現象","(D) 糞便內經常含有血絲及暗紅色大便"],"answer":2,"image":""},{"id":"nr4-112-1-77","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"有關使用格拉斯哥氏昏迷量表（Glasgow Coma Scale, GCS）評估兒童意識程度，下列敘述何者正確？","options":["(A) 評估嬰幼兒時，不需要父母陪同，避免干擾評估正確性","(B) 評估兒童對於環境刺激的瞳孔、語言和運動反應","(C) 少於或等於7分定義為昏迷狀態","(D) 最高分13分表示正常"],"answer":2,"image":""},{"id":"nr4-112-1-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"有關雷氏症候群（Reye’s syndrome）的臨床表徵，下列敘述何者錯誤？","options":["(A) 肝臟酵素-胺基轉胺酶（AST、ALT）皆升高","(B) 高血糖","(C) 腦水腫","(D) 凝血酶原時間（PT）及部分凝血酶原時間（PTT）延長"],"answer":1,"image":""},{"id":"nr4-112-1-79","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"有關早產兒腦室內出血，下列護理處置之敘述，何者最適當？","options":["(A) 抬高床頭45度以減少顱內壓","(B) 採取集中照護，減少不必要的打擾","(C) 提供具聲光刺激的環境，以增加大腦血流","(D) 提供高張藥物及溶液，以減低大腦血流量"],"answer":1,"image":""},{"id":"nr4-112-1-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"李小妹，診斷為痙攣型腦性麻痺（spastic type of cerebral palsy），有關其臨床表徵，下列敘述何者正確？","options":["(A) 不自主的扭動","(B) 伸展反射增加","(C) 肌腱反射降低","(D) 跨大步伐行走"],"answer":1,"image":""},{"id":"nr4-112-2-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"有關嬰兒死亡率之敘述，下列何者正確？","options":["(A) 一年內未滿4週之嬰兒死亡數÷當年出生活嬰總數×1,000","(B) 一年內未滿42天之嬰兒死亡數÷當年出生活嬰總數×1,000","(C) 一年內未滿6個月之嬰兒死亡數÷當年出生活嬰總數×1,000","(D) 一年內未滿1歲之嬰兒死亡數÷當年出生活嬰總數×1,000"],"answer":3,"image":""},{"id":"nr4-112-2-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"丁女士30歲，G1P0，懷孕20週，至門診產檢。懷孕前身體質量指數（BMI）為20，懷孕後體重增加3公斤，宮底高肚臍上一橫指，詢問「肚子會不會太小？」護理師最合適的回答為何？","options":["(A) 目前體重增加太少，所以肚子比較小，可以每天再增加1份300卡的點心","(B) 目前體重增加太多，肚子不會太小，需要減少一天熱量，有效控制體重","(C) 目前體重增加和肚子大小符合懷孕週數，繼續維持就可以","(D) 目前肚子大小符合週數，但體重增加太少，可以每天再增加1份300卡的點心"],"answer":2,"image":""},{"id":"nr4-112-2-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"趙女士至門診確認懷孕8週，有孕吐現象，詢問有關孕期熱量攝取，下列何者為最適當的回答？","options":["(A) 孕期熱量需求和體重增加是平均分配於三個孕期","(B) 第一孕期常有孕吐，體重增加是三個孕期中最少","(C) 第二孕期熱量主要提供胎兒的生長","(D) 第三孕期熱量主要提供胎盤的生長"],"answer":1,"image":""},{"id":"nr4-112-2-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"有關懷孕期的營養指導，下列何者最適當？","options":["(A) 懷孕前及第一孕期注意葉酸的攝取，可預防胎兒神經管缺損","(B) 懷孕期絕不可喝咖啡、茶、可樂等含咖啡因的飲料","(C) 每日水分的攝取應限制在500～1,000毫升","(D) 第二孕期需特別補充鐵劑及維生素K"],"answer":0,"image":""},{"id":"nr4-112-2-5","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"張女士，40歲，懷孕17週，來院進行羊膜穿刺術，下列敘述何者錯誤？","options":["(A) 告知無需事先喝水漲滿膀胱","(B) 協助平躺並鋪設無菌區域","(C) 可以無需麻醉協助抽取羊水","(D) 此時目的在評估胎兒成熟度"],"answer":3,"image":""},{"id":"nr4-112-2-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"葉女士，懷孕33週，在正常體重增加與胎兒發展的情況下，逐漸膨大的子宮會使她姿勢發生下列何種改變？","options":["(A) 身體重心往後移增加平衡","(B) 腰、背、脊柱向前方凸起","(C) 腹部肌肉張力逐漸增加","(D) 骨盆關節活動性更加緊實"],"answer":1,"image":""},{"id":"nr4-112-2-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"懷孕婦女抱怨陰道白色分泌物（白帶）增加、呈黏稠狀、無臭味，造成會陰部不適感，此種情況最可能原因為？","options":["(A) 陰道上皮細胞發炎","(B) 陰道細胞受到念珠球菌感染","(C) 陰道細胞受到嗜乳酸桿菌作用","(D) 子宮頸黏液塞排出"],"answer":2,"image":""},{"id":"nr4-112-2-8","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"懷孕34週婦女接受高層次超音波檢查，血流超音波檢查結果S/D = 2.4，對此檢查結果的敘述，下列何者正確？","options":["(A) S/D是臍靜脈收縮壓與舒張壓比值","(B) S/D舒張壓變小，表示胎盤血管阻力減少","(C) 第二孕期後，S/D值隨週數增加而增加","(D) S/D = 2.4表示胎盤功能正常"],"answer":3,"image":""},{"id":"nr4-112-2-9","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"婦女在懷孕過程中會主動尋求與生產有關之訊息，定期接受產前檢查，並且經常請教親朋好友生產的情形，這符合下列那項魯賓（Rubin）母性任務發展？","options":["(A) 學習奉獻自己","(B) 促使重要他人接受新生兒","(C) 使自己與胎兒連成一體","(D) 確保自己與胎兒在懷孕期過程安全順利"],"answer":3,"image":""},{"id":"nr4-112-2-10","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"護理師教導孕婦在家每日自行監測胎動，下列何者最適當？","options":["(A) 飯前1小時計算胎動，正常應每小時有5次（或以上）","(B) 清晨醒來臥床1小時計算胎動，正常應每小時有5次（或以上）","(C) 安靜坐或躺，計算胎動發生次數10次時間，正常應在2小時內可達到","(D) 散步1小時過程中，計算胎動發生次數，正常應達10次（或以上）"],"answer":2,"image":""},{"id":"nr4-112-2-11","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"陳女士G1P1，因前置胎盤採剖腹產，有關產後立即性照護，下列何者錯誤？","options":["(A) 至少每4小時監測生命徵象測量一次","(B) 評估傷口出血及惡露量情形","(C) 評估子宮底位置及張力","(D) 每15分鐘評估下肢感覺恢復情形"],"answer":0,"image":""},{"id":"nr4-112-2-12","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"張女士，G1P0，由先生陪同待產，出現哭叫打罵情形，先生已陪產一天，出現疲憊不堪情形，詢問護理師他該怎麼辦，下列回應何者最不恰當？","options":["(A) 接受準爸爸可能有驚慌失措的行為","(B) 提供明確產程進展訊息給準爸爸","(C) 請準爸爸持續陪伴，以避免產婦失控","(D) 讓準爸爸暫時在旁休息，改由其他家人照顧產婦"],"answer":2,"image":""},{"id":"nr4-112-2-13","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"陳女士懷孕39週入院待產，體溫36.5℃、心跳74次／分、呼吸24次／分，血壓120/85mmHg。有關待產時使用腰椎硬膜外麻醉（epidural analgesia）時，麻醉前後注意事項，下列何者錯誤？","options":["(A) 麻醉前30分鐘應提供靜脈留置針及給予0.9%N/S 500～1,000 mL灌注","(B) 麻醉藥注入前20分鐘，應監測母親血壓和胎心音","(C) 麻醉後採左側臥，避免低血壓","(D) 待產婦血壓為86/50 mmHg，需給予naloxone解毒"],"answer":3,"image":""},{"id":"nr4-112-2-14","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"王女士，懷孕41週，觀察其待產期間的胎心率變化。下列何種現象，需要特別處理？","options":["(A) 潛伏期時，不論有無宮縮，都維持在128～148 bpm","(B) 活動期時，10分鐘內，不論有無宮縮，最高為140 bpm，最低為136 bpm","(C) 宮縮開始，加速最高至162 bpm，宮縮結束後回到124 bpm","(D) 產檯上用力期間，逐漸減慢到最低至110 bpm，宮縮結束後回到138 bpm"],"answer":1,"image":""},{"id":"nr4-112-2-15","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"高女士，G2P0，懷孕38週，因規則陣痛且自然破水而入院待產。待產期間沒有接受硬脊膜外麻醉，已入院待產13小時，目前子宮收縮每2～3分鐘一次，持續50秒，子宮頸口擴張8公分，胎兒高度 −1。請問，高女士此時最不可能出現下列何種徵象或行為反應？","options":["(A) 現血量會越來越多","(B) 宮縮間歇時，常閉著眼睛休息","(C) 對於能否撐過生產，越來越沒信心","(D) 非常希望獨處，大叫「請你們離開！」"],"answer":3,"image":""},{"id":"nr4-112-2-16","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"有關初產婦與經產婦於分娩過程的常見變化，下列敘述何者正確？","options":["(A) 初產婦子宮頸先擴張，再變薄","(B) 經產婦子宮頸軟化變薄及擴張，同時進行","(C) 經產婦於分娩前約2週出現腹輕感（lightening）","(D) 初產婦腹輕感往往於分娩啟動時才出現"],"answer":1,"image":""},{"id":"nr4-112-2-17","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"周女士，G1P0，懷孕39週，因破水且子宮頸口開3公分。以臺灣目前臨床實務最常見的電子胎兒監測方式，下列護理師的說明，何者不適當？","options":["(A) 「會先用手觸診腹部，找出聽取胎兒心跳最清楚的位置」","(B) 「等一下妳的腹部上會放有兩條固定帶」","(C) 「放在宮底位置的這個是感應子宮收縮壓力的傳導器」","(D) 「監測宮縮壓力及胎兒心跳的兩個傳導器都會抹上凝膠物質」"],"answer":3,"image":""},{"id":"nr4-112-2-18","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"丁女士主訴無法忍受生產疼痛並接受meperidine（Demerol）注射，給藥後護理師監測其呼吸速率低於每分鐘10次，下列何種藥物能改善此情形？","options":["(A) diazepam（Valium）","(B) hydroxyzine（Vistaril）","(C) promazine（Sparine）","(D) naloxone（Narcan）"],"answer":3,"image":""},{"id":"nr4-112-2-19","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"廖女士，41歲，G4P4，在今天早上6點以陰道分娩第四個女兒，現親子同室中，護理師詢問其他家人何時會來醫院，廖女士眼眶泛紅表示：「他們不會來啦，因為這胎又是女兒」，下列回應何者最適當？","options":["(A) 妳不要難過了，妳更要多與寶寶互動，以免影響日後的親子依附關係建立","(B) 妳是受到產後荷爾蒙劇烈變化的影響，才會情緒低落下，過兩天就會改善","(C) 剛生產完，母親及新生兒都需要足夠的時間休息，通常也不會建議此時家人的探視","(D) 聽起來妳很難過，新生兒的誕生對家庭成員都有影響，妳現在的想法是？"],"answer":3,"image":""},{"id":"nr4-112-2-20","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"有關產褥期身心調適的敘述，下列何者錯誤？","options":["(A) 生殖器官的復舊需要四～六週時間","(B) 又稱為第四孕期；以強化母嬰一體調整與恢復的概念","(C) 子宮頸口一週後會趨近閉合，是一種生理上進行性變化","(D) 子宮體積的減少，與自體溶解有關"],"answer":2,"image":""},{"id":"nr4-112-2-21","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"李女士，產後三週，表示產後至今體重增加5公斤，失眠睡不好，動作遲緩且嗜睡，對任何事物及新生兒照護都缺乏興趣，覺得很有罪惡感，加上自己坐月子缺乏幫手，常常出現想死的念頭。針對李女士的情形，下列評估何者最適當？","options":["(A) 產後荷爾蒙變化的自然現象","(B) 產後情緒低落（Postpartum Blue）","(C) 產後憂鬱（Postpartum Depression）","(D) 產後精神疾患（Postpartum Psychosis）"],"answer":2,"image":""},{"id":"nr4-112-2-22","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"有關乳腺炎用藥治療及哺乳建議，下列何者最適當？","options":["(A) 最常見的致病菌多為金黃色葡萄球菌，必要時給予ampicillin加上持續哺乳最有效","(B) 投與抗盤尼西林黴素時，不建議服藥2小時內哺乳","(C) 可以持續哺乳且用藥後24～48小時，發燒、發紅及硬塊情況通常就會改善","(D) 可以持續哺乳，但為了降低藥物對嬰兒的影響，症狀消失後即可停藥"],"answer":2,"image":""},{"id":"nr4-112-2-23","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"有關初乳的敘述，下列何者不適當？","options":["(A) 蛋白質和礦物質的含量較成熟乳高","(B) 脂肪和醣類的含量較高，少量但熱量足","(C) 水分含量較成熟乳低，適合新生兒的胃容量","(D) 含有豐富促進腸道好菌發展的益菌生"],"answer":1,"image":""},{"id":"nr4-112-2-24","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"提供產後飲食衛教，教導暫時性避免食用含酒精性食物，其最主要原因為何？","options":["(A) 避免影響腸道蠕動","(B) 避免影響傷口癒合","(C) 避免影響惡露排出","(D) 避免影響性生活"],"answer":1,"image":""},{"id":"nr4-112-2-25","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"蔡女士，初產婦，新生兒出生體重3,800公克。採完全哺餵母乳，護理師進行產後兩週之出院後電話關懷時發現，新生兒出生兩週體重為下降至3,700公克。下列何者為最優先的處置？","options":["(A) 肯定個案的堅持母乳哺育，建議增加哺乳的頻率兩天，之後再觀察體重變化","(B) 說明體重下降過多時對嬰兒成長的危險，應立即補充配方奶","(C) 了解個案飲食狀態，建議增加高蛋白高熱量飲食攝取，以強化母乳營養及產量","(D) 鼓勵個案說出自己的感受，告知今日儘快到醫院進行哺乳與新生兒之評估與檢查"],"answer":3,"image":""},{"id":"nr4-112-2-26","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"張女士，剖腹產後第一天，表示整個腹部疼痛，全身疲憊無力，不想動，也不要親子同室。下列何項護理措施最適當？","options":["(A) 告知親子同室是政府推行政策，建議親子同室並由丈夫協助照顧新生兒","(B) 說明是子宮收縮引起疼痛，協助24小時使用束腹帶並建議長期臥床休息","(C) 說明活動的益處，依醫囑給予止痛劑，採漸進式活動","(D) 評估腸蠕動情況，給予腹部按摩及軟便劑，鼓勵多喝水"],"answer":2,"image":""},{"id":"nr4-112-2-27","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"有關產後正常紅惡露（Lochia Rubra）的敘述，下列何者錯誤？","options":["(A) 顏色為深紅色","(B) 產後1～3天出現","(C) 內含上皮細胞、蛻膜碎片","(D) 會出現有大量紅色血塊"],"answer":3,"image":""},{"id":"nr4-112-2-28","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"有關於胎兒與新生兒免疫系統之敘述，下列何者正確？","options":["(A) IgM是唯一可以通過胎盤的抗體","(B) 胎兒無法自行製造IgA，可由初乳而獲得","(C) 出生時新生兒體內之抗體主要為IgA","(D) 當新生兒的IgG值升高，顯示有子宮內感染"],"answer":1,"image":""},{"id":"nr4-112-2-29","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"使用New Ballard Score評估足月兒成熟度與妊娠週數的最佳時間為：","options":["(A) 出生後24小時內","(B) 出生後2～3天內","(C) 出生後3～7天內","(D) 出生後8天至滿月前"],"answer":0,"image":""},{"id":"nr4-112-2-30","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"有關新生兒篩檢的檢體採集方式，下列何者正確？","options":["(A) 早產兒出生週數滿34週即可立即採血","(B) 採血的穿刺部位應選擇避開蹠神經與跟骨部位的足跟兩側","(C) 穿刺後若血流不順可以用力擠壓穿刺處讓血液流出","(D) 穿刺時以45度角將穿刺針刺入採血點"],"answer":1,"image":""},{"id":"nr4-112-2-31","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"江女士為百貨公司化妝品銷貨員，因長期久站，懷孕前左腿即有明顯的靜脈曲張情形，產後會陰傷口腫脹疼痛而不願下床活動，產後第三天她試著下床步行，當她站立伸直左右小腿時，左小腿會感覺疼痛，觸摸也會覺得壓痛。依據上述情況，下列何項判斷及處置較適當？","options":["(A) 為深層血栓靜脈炎，應教導其在左小腿疼痛處多熱敷並按摩","(B) 霍曼氏徵象（Homan’s sign）若為陽性反應，依醫囑給予抗凝血劑，並密切觀察出血情形","(C) 霍夫曼技術（Hoffman’s technique）評估為陽性，應抬高床尾，避免血栓造成肺栓塞","(D) 為深層血栓靜脈炎，鼓勵多下床活動以促進血液回流"],"answer":1,"image":""},{"id":"nr4-112-2-32","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"王女士使用ritodrine（Yutopar）安胎，下列照護何者正確？","options":["(A) 監測高血壓現象","(B) 監測低血糖現象","(C) 需注意胸痛、呼吸困難現象","(D) 發生心搏過速，應立即停藥"],"answer":2,"image":""},{"id":"nr4-112-2-33","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"有關比夏計分法（Bishop’s score）之敘述，下列何者正確？","options":["(A) 比夏計分法之得分愈低，則早產機率愈高","(B) 評估項目為心跳速率、呼吸能力、肌肉張力、皮膚顏色、反射性刺激反應","(C) 每一項目評分為-1、0、1、2、3分五個等級","(D) 過期妊娠婦女催產前，可用此計分法評估子宮頸的成熟度"],"answer":3,"image":""},{"id":"nr4-112-2-34","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"32歲初產婦身高160公分，中午12：00入院時子宮頸變薄50%，擴張為4公分，待產期間僅給予Ringer輸液keep line，但子宮收縮頻率自然變快且強度也增加，10分鐘內平均有5次以上收縮，分娩進展快速於下午14：50娩出1名男嬰，出生體重2,700公克。有關此位初產婦分娩特性的敘述，下列何者最適當？","options":["(A) 急產，產後應評估子宮頸及產道是否有撕裂傷","(B) 分娩快速，胎兒易出現感染及失溫的危險","(C) 產程延滯，是醫療處置不當的結果","(D) 應注意胎兒是否因腦缺氧，刺激交感神經引發心跳加速"],"answer":0,"image":""},{"id":"nr4-112-2-35","subject":"nr4","topic":"產科-產後照護","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"承上題，該產婦在產後觀察期間，觸診其子宮收縮呈堅硬狀，子宮底位置與臍平並置中，膀胱無漲尿，產婦陰道不斷流出鮮紅血性物，半小時內產後棉片就濕透一半，血壓值為100/65 mmHg。下列敘述何者正確？","options":["(A) 為早期產後出血，因產道撕裂傷所致","(B) 為早期產後出血，因子宮收縮乏力所致","(C) 為晚期產後出血，係胎盤碎片殘留子宮","(D) 為晚期產後出血，係異常高張力宮縮"],"answer":0,"image":""},{"id":"nr4-112-2-36","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"女性月經來潮時的衛生清潔措施，下列何者不適當？","options":["(A) 使用清潔液灌洗陰道","(B) 可用中性肥皂或清水清潔會陰部","(C) 採淋浴方式","(D) 穿著寬鬆的棉質內褲"],"answer":0,"image":""},{"id":"nr4-112-2-37","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"有關血清抗穆氏管荷爾蒙（Anti-mullerian Hormone, AMH）檢查之敘述，下列何者錯誤？","options":["(A) 能反映卵子的儲量","(B) 能準確評估卵巢功能","(C) 受月經週期影響，需於月經週期第14天進行檢測","(D) 年輕女性AMH的平均值在2〜4 μg/L"],"answer":2,"image":""},{"id":"nr4-112-2-38","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"有關人工授精之適應症，下列何者錯誤？","options":["(A) 精子無法穿透子宮黏液","(B) 精子稀少者","(C) 選擇接受精子捐贈者","(D) 輸卵管阻塞者"],"answer":3,"image":""},{"id":"nr4-112-2-39","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"有關多囊性卵巢疾病的表徵，下列何者錯誤？","options":["(A) 雄性素分泌過多","(B) 排卵障礙","(C) 胰島素阻抗","(D) 月經次數過多"],"answer":3,"image":""},{"id":"nr4-112-2-40","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"有關子宮肌瘤的術後護理，下列何者正確？","options":["(A) 若有出血情形，須密切觀察與紀錄出血量、性質、顏色","(B) 微創手術後，為避免傷口出血，應臥床24小時","(C) 微創手術後，因恢復時間短，返家可立即恢復性生活","(D) 肌瘤切除術後，返家後可開始運動，如至健身房進行重訓"],"answer":0,"image":""},{"id":"nr4-112-2-41","subject":"nr4","topic":"兒科-意外事故與急症","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"楊小妹，1歲，體重10公斤，有關事故傷害預防之護理指導，下列敘述何者最適當？","options":["(A) 為了提升楊小妹安全意識，應開始利用玩偶及遊戲進行安全教育","(B) 為了預防車禍撞擊，乘車時楊小妹應坐在後座之攜帶式嬰兒床或後向式安全座椅","(C) 為了促進其自主性之發展，應鼓勵母親開始讓楊小妹自己洗澡","(D) 為了補充優質脂肪酸，鼓勵母親開始讓楊小妹進食堅果類食物"],"answer":1,"image":""},{"id":"nr4-112-2-42","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"小澤，8歲，罹患氣喘，有關促進小澤在學校生活適應，下列敘述何者不適當？","options":["(A) 父母應告知學校老師和校護關於小澤的狀況和健康需求","(B) 父母應將小澤需在學校服用的藥物標示清楚及藥物相關資訊","(C) 避免疾病發作，老師需保護和限制小澤參與體育等競賽活動","(D) 徵得小澤和父母的同意下，對班上同學簡潔說明小澤的疾病和注意事項"],"answer":2,"image":""},{"id":"nr4-112-2-43","subject":"nr4","topic":"兒科-意外事故與急症","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"有關預防嬰兒搖晃症候群（Shaken Baby Syndrome）之護理照護措施，下列敘述何者正確？","options":["(A) 避免劇烈搖晃嬰幼兒，是預防脊柱未成形而造成損害","(B) 移動嬰幼兒時，雙手務必適當的支撐背部及腰部","(C) 安全抱持是雙手置於嬰幼兒兩側腋窩或抱起雙臂","(D) 教導照顧者處於憤怒、焦慮時，先調適自身情緒"],"answer":3,"image":""},{"id":"nr4-112-2-44","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"罹患自閉症的學齡期兒童，母親應該如何與之互動最合適？","options":["(A) 多給與刺激性的活動，以增進其認知功能","(B) 鼓勵增加與孩子的身體接觸或碰觸，使其感受到關心","(C) 給予明確且具體的指示，以增進其信任感","(D) 鼓勵多給予意外的驚喜，以增加其生活色彩"],"answer":2,"image":""},{"id":"nr4-112-2-45","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"有關兒童血壓測量，下列敘述何者正確？","options":["(A) 右臂橈動脈區是最常用基準部位","(B) 合適的壓脈帶寬度應可以覆蓋所選肢體的1/2","(C) 小於1歲兒童的正常血壓範圍為100～110/60～75 mmHg","(D) 1歲以上兒童的下肢測量收縮壓會比上肢高約20 mmHg"],"answer":3,"image":""},{"id":"nr4-112-2-46","subject":"nr4","topic":"兒科-生長發展","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"有關兒童氣質的相關敘述，下列何者錯誤？","options":["(A) 氣質無好壞之分，是個人對內在、外在刺激的行為模式","(B) 氣質和父母教養方式有密切關係，在彼此互動下會產生不同的親子關係","(C) 瞭解孩子的氣質，可協助父母發展最適合孩子氣質特點的社會適應模式","(D) 氣質會影響孩子的智力發展與日後的成就"],"answer":3,"image":""},{"id":"nr4-112-2-47","subject":"nr4","topic":"兒科-生長發展","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"有關兒童生理的發展，下列敘述何者正確？","options":["(A) 從出生至1歲的嬰兒，其神經系統及附屬器官生長速度最快","(B) 從出生到3歲快速長高，約3歲時的身高為出生時身長的2倍","(C) 出生時頭圍約30公分，每年增加12～15公分，5歲時可達成人90%","(D) 出生時身體中點為肚臍處，3歲時頭約占身長1/3"],"answer":0,"image":""},{"id":"nr4-112-2-48","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"小桃，8歲，因氣喘發作住院接受治療，主訴：「因為我愛吃冰，然後出去玩沒戴口罩，也沒穿外套，所以就發作了」，下列何者為小桃此階段「疾病概念」發展的特色？","options":["(A) 生病是兩件事情接近，不可思議發生的","(B) 生病是來自外在但存於身體內部的","(C) 生病是來自外在的人、物或行動對兒童身體不好或有傷害的","(D) 生病是外在原因與自己無關的具體現象"],"answer":2,"image":""},{"id":"nr4-112-2-49","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"依據皮亞傑（Piaget）認知發展理論，有關具體運思期兒童對疾病的概念，下列敘述何者最適宜？","options":["(A) 認為生病原因是上天的懲罰","(B) 認為生病原因是器官功能不良","(C) 認為生病原因是接觸生病的人","(D) 能對生病原因提出假設，再進行驗證"],"answer":2,"image":""},{"id":"nr4-112-2-50","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"小偉，2歲，入住加護病房的第二天早晨哭喊著要媽媽，拒絕護理師的安撫，且出現身體攻擊行為。此行為屬於分離焦慮的那一期？","options":["(A) 抗議期","(B) 否認期","(C) 絕望期","(D) 關係重建期"],"answer":0,"image":""},{"id":"nr4-112-2-51","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"林小弟，妊娠31週，出生一週大，目前體重1,868公克，有關林小弟的營養照護，下列敘述何者最正確？","options":["(A) 為滿足口慾，以經口餵食為主，不足部分以靜脈輸液補充","(B) 為避免吸吮耗費身體能量，以全靜脈營養提供所需熱量","(C) 早產兒配方奶熱量高於母乳，建議餵食早產兒配方奶為主","(D) 口胃管灌食時，反抽量大於灌食量一半時，應暫停餵食"],"answer":3,"image":""},{"id":"nr4-112-2-52","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"小凱為26週大的早產兒，有關維持早產兒體溫的照護措施，下列敘述何者不適當？","options":["(A) 毛毯包裹及戴帽子，四肢穿戴手腳套","(B) 保溫箱溫度設定於28～30℃，濕度45～50%","(C) 使用塑膠單或塑膠套覆蓋早產兒的身體","(D) 將早產兒置於預熱過的輻射加溫處理台上，執行醫療處置"],"answer":1,"image":""},{"id":"nr4-112-2-53","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"有關慢性疾病兒童與家庭的照護原則，下列敘述何者不適當？","options":["(A) 家庭須發展出融合病童疾病治療與使家庭生活正常化的策略","(B) 強調慢性疾病對病童的影響和限制，允許對其過度保護","(C) 鼓勵家庭儘量讓病童參與治療及照護相關的決策","(D) 鼓勵家庭成員和病童能與同儕或外界互動"],"answer":1,"image":""},{"id":"nr4-112-2-54","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"小強，13歲大，罹患骨肉瘤（Osteosarcoma），經歷化學治療與手術治療後，癌細胞仍轉移到肺部。當小強在生命末期時，護理師可評估到的生理變化，下列敘述何者正確？","options":["(A) 呼吸呈現深快的庫斯莫爾氏呼吸（Kussmaul’s respiration）","(B) 周邊循環增加，使得四肢末梢脈搏變強","(C) 括約肌控制降低，造成大小便失禁","(D) 痛覺變遲鈍，視力最後消失"],"answer":2,"image":""},{"id":"nr4-112-2-55","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"黃小妹為35週出生的早產兒，罹患高膽紅素血症（Hyperbilirubinemia），有關傳統照光機執行照光治療的護理措施，下列敘述何者錯誤？","options":["(A) 常出現體溫升高、脫水的副作用","(B) 每日採血前須暫停使用照光","(C) 需戴不透光眼罩和貼隔光紙於生殖器部位","(D) 照光的光源與病童皮膚保持30～40公分距離"],"answer":3,"image":""},{"id":"nr4-112-2-56","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"有關評估早產兒的生長發展，下列敘述何者最適當？","options":["(A) 早期應每3個月評估早產兒的生長發展","(B) 早產男嬰睪丸可能尚未下降且陰囊小及無皺褶","(C) 早產兒評估的矯正年齡計算是以其預產期加4週當出生日期","(D) 應用新貝拉德量表（New Ballard Score）定期進行評估生長發展"],"answer":1,"image":""},{"id":"nr4-112-2-57","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"小章，足月兒，出生即確診為後天免疫缺乏症候群（AIDS），若病況穩定需接種疫苗時，下列敘述何者錯誤？","options":["(A) 出生24小時內可接種B型肝炎疫苗（Hep B）第1劑","(B) 出生滿2個月可接種流行性感冒嗜血桿菌疫苗（Hib）","(C) 出生滿5個月可接種卡介苗（Bacillus Calmette-Guérin, BCG）","(D) 出生滿6個月可接種流行性感冒疫苗（Influenza vaccine）"],"answer":2,"image":""},{"id":"nr4-112-2-58","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"小立，6歲，一週前被三斑家蚊叮咬，之後出現發燒、頭痛、嘔吐、痙攣、頸部僵硬的症狀，其抽取腦脊髓液的檢查結果，下列敘述何者正確？","options":["(A) 蛋白質上升","(B) 血小板下降","(C) 球蛋白反應為陰性","(D) 葡萄糖下降"],"answer":0,"image":""},{"id":"nr4-112-2-59","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"有關玫瑰疹（Roseola Infantum）的相關敘述，下列何者正確？","options":["(A) 由第1型人類疱疹病毒感染所致","(B) 常見於學齡前期的兒童","(C) 燒退後發疹最先出現在臉上，為玫瑰紅斑點","(D) 常見合併症為熱性痙攣"],"answer":3,"image":""},{"id":"nr4-112-2-60","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"有關嬰幼兒「呼吸系統特徵」之敘述，下列何者最不適當？","options":["(A) 嬰幼兒耳咽管較長、窄且垂直，致病菌較不易進入中耳","(B) 嬰兒的會厭軟骨較成人所占的比例大，且無彈性","(C) 嬰兒喉頭位置在頸部較高處，較成人易有吸入性肺炎","(D) 嬰兒鼻腔黏膜富含微血管比成人豐富，易受致病原感染"],"answer":0,"image":""},{"id":"nr4-112-2-61","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"傳染力最低的是那種類型的肺炎？","options":["(A) 細菌性肺炎","(B) 病毒性肺炎","(C) 黴漿菌性肺炎","(D) 間質性肺炎"],"answer":0,"image":""},{"id":"nr4-112-2-62","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"有關氧氣帳使用之敘述，下列何者正確？","options":["(A) 維持高濃度氧（40%〜60%），高濕度（40%〜60%）的帳內環境","(B) 提供電動玩具，增加視聽覺刺激，以免病童有被隔離感","(C) 氧氣濃度分析儀放於病童肢體末端，可測得準確的氧濃度","(D) 採集中護理，限制照護者與病童互動，以免帳內氧氣流失"],"answer":0,"image":""},{"id":"nr4-112-2-63","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"小祁，10歲，男童，主訴眼睛發癢、持續打噴嚏但無發燒，診斷為過敏性鼻炎，下列護理措施何者最不適當？","options":["(A) 需長期使用鼻血管收縮噴劑","(B) 勿使用毛毯及絨毛玩具","(C) 提醒小祁咳嗽打噴嚏需用手帕或衛生紙蓋住口鼻的禮節","(D) 依醫囑給予口服Antihistamine緩解過敏性徵兆和症狀"],"answer":0,"image":""},{"id":"nr4-112-2-64","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"曹小妹為足月產新生兒，有關其出生後會出現之循環變化，下列何者正確？","options":["(A) 血氧濃度降低，讓動脈導管收縮而關閉","(B) 臍靜脈出生後立即關閉形成靜脈韌帶","(C) 全身血管阻力增加，肺動脈阻力降低","(D) 卵圓孔自然關閉是因為右心房壓力高於左心房壓力"],"answer":2,"image":""},{"id":"nr4-112-2-65","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"劉小弟，5歲，因心室中膈缺損長期服用毛地黃，入院行右心導管檢查，有關劉小弟之照護措施，何者最正確？","options":["(A) 檢查前禁食4～6小時，毛地黃改靜脈注射給與","(B) 檢查後每15分鐘測量生命徵象，持續4小時","(C) 檢查後維持穿刺肢體平直，須臥床休息","(D) 右心導管最常由股動脈進入右心房"],"answer":2,"image":""},{"id":"nr4-112-2-66","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"邱小弟，4歲，罹患重度主動脈瓣狹窄（Aortic Stenosis, AS），下列敘述何者錯誤？","options":["(A) 易發生充血性心衰竭，需要限制水分攝取","(B) 容易因為活動導致缺氧發作，需進行活動限制","(C) 觀察心跳與末梢循環，提供足夠休息與睡眠","(D) 須執行布萊洛-陶西分流術（Blalock-Taussing Shunt）"],"answer":3,"image":""},{"id":"nr4-112-2-67","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"王小弟因血紅素值4.1 g/dL須輸血治療，下列敘述何者正確？","options":["(A) 過敏反應時，依醫囑於血袋中加入Antihistamine滴注，緩和過敏引發的症狀","(B) 輸血過程中，王小弟抱怨注射部位灼熱感，應立即更換為5%葡萄糖水滴注","(C) 急性溶血反應通常因輸入的血型不合所引起，大多在輸血後2小時出現症狀","(D) 輸血過程中使用溫血器，但溫度不可高於37℃"],"answer":3,"image":""},{"id":"nr4-112-2-68","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"有關血友病（Hemophilia）兒童的居家照護指導，下列敘述何者最為正確？","options":["(A) 若出現皮膚或黏膜表層出血，宜局部加壓並於凝血後給與熱敷","(B) 學齡前期兒童可指導其學習凝血因子之皮下注射","(C) 可使用軟毛牙刷及口腔保健，預防齲齒","(D) 家裡需常備acetaminophen、aspirin、codeine等止痛藥物"],"answer":2,"image":""},{"id":"nr4-112-2-69","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"小美，5歲，罹患白血病，正處於引導緩解期，對於此階段的護理照護指導，下列敘述何者錯誤？","options":["(A) 監測小美的血球計數，接觸前後需要洗手，執行侵入性治療嚴守無菌原則","(B) 依醫囑注射顆粒球生成因子，提高小美的嗜中性白血球數，提升防禦能力","(C) 此階段會採取密集和積極的治療，主要透過人工血管進行化學治療","(D) 若接受脊髓腔內（intrathecal）注射化學藥物後，需鼓勵立即下床活動避免血栓產生"],"answer":3,"image":""},{"id":"nr4-112-2-70","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"初診斷為急性淋巴性白血病童有發生腫瘤溶解症候群（TumorLysisSyndrome）之危機，下列敘述何者錯誤？","options":["(A) 監測血液尿酸值","(B) 針對常見代謝性異常給與相關處置","(C) 限制水分攝取","(D) 給與allopurinol"],"answer":2,"image":""},{"id":"nr4-112-2-71","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"有關苯酮尿症病童之臨床症狀，下列敘述何者正確？","options":["(A) 出生即出現酮酸中毒","(B) 一般症狀包括嘔吐、尿、體汗有霉臭味","(C) 皮膚色澤呈現潮濕紅潤，髮色烏黑","(D) 黃疸、生長遲緩、白內障"],"answer":1,"image":""},{"id":"nr4-112-2-72","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"小芳，17歲，即將準備接受造血幹細胞移植，下列敘述何者錯誤？","options":["(A) 移植前高劑量的化學治療是要破壞骨髓及癌細胞，使植入的幹細胞有生長空間","(B) 急性移植體對抗宿主疾病（GVHD）可能在幹細胞移植後4～6個月之間出現","(C) 移植過程需採保護性隔離並觀察有無副作用","(D) 使用Hickman輸注幹細胞後，約需14～28天才會開始造血"],"answer":1,"image":""},{"id":"nr4-112-2-73","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"下列何者為評估病童「重度脫水」時會有的症狀或徵象？","options":["(A) 頻尿","(B) 哭沒有眼淚","(C) 體重減輕＜5%","(D) 脈搏下降"],"answer":1,"image":""},{"id":"nr4-112-2-74","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"王小弟，6歲，因下腹部疼痛、噁心、嘔吐等現象到急診室求治，懷疑闌尾炎，有關闌尾炎的評估，下列何者最適當？","options":["(A) 柯林氏徵象（Kernig’s sign）","(B) 布魯伯氏徵象（Blumberg’s sign）","(C) 羅氏徵象（Rovsing’s sign）","(D) 墨菲氏徵象（Murphy’s sign）"],"answer":2,"image":""},{"id":"nr4-112-2-75","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"有關病童罹患腸套疊（Intussusception）之治療和護理措施，下列敘述何者正確？","options":["(A) 可採趴睡壓迫腸子促使自動復位","(B) 若需執行外科手術，可以拉扯方式將嵌入腸道復位避免壞死","(C) 鋇劑灌腸是以液體和空氣壓力將嵌入腸子推回原位","(D) 腸套疊治療復位後可立即出院"],"answer":2,"image":""},{"id":"nr4-112-2-76","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"吳小弟，5個月大，持續腹瀉，有關護理指導的敘述，下列何者較不適當？","options":["(A) 以中性溫和肥皂及清水清洗臀部並擦乾","(B) 需泡兩倍濃度的全奶，防止營養不良","(C) 建議可改喝無乳糖配方奶粉","(D) 輕中度腹瀉可給與電解質口服液治療"],"answer":1,"image":""},{"id":"nr4-112-2-77","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"有關肌肉失養症（Muscular Dystrophy）病童之臨床表徵與處置，下列敘述何者不適當？","options":["(A) 症狀乃因缺乏肌縮蛋白（Dystrophin）導致","(B) 病童站立時出現巴羅氏徵象（Barlow’s sign）","(C) 游泳是促進全身肌肉強度最好的運動","(D) 血液檢查CPK、aldolase、AST數值偏高"],"answer":1,"image":""},{"id":"nr4-112-2-78","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"兒童罹患雷氏症候群（Reye’s Syndrome）常會有複雜性合併症產生，有關其病因和症狀，下列敘述何者正確？","options":["(A) 為代謝性腦病變合併胰臟病變的疾病","(B) 可能與使用含阿斯匹靈（aspirin）退燒有關","(C) 血液中氨（ammonia）值下降","(D) 血糖濃度增加"],"answer":1,"image":""},{"id":"nr4-112-2-79","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"小琪，5歲，診斷為中度腦性麻痺（Cerebral Palsy），有咀嚼、吞嚥控制困難問題，有關飲食之居家照顧指導，下列敘述何者錯誤？","options":["(A) 可以三指下顎控制法（three-finger jaw control）協助小琪進食","(B) 儘量將食物置於舌頭前方，避免哽塞","(C) 餵食姿勢應維持頭部正中位置，使肩部前屈","(D) 液態過稀的物質，可用增稠劑以利吞嚥順暢"],"answer":1,"image":""},{"id":"nr4-112-2-80","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"小花，3歲，因腦膜炎（Meningitis）導致顱內壓升高，不會出現下列何種臨床徵象？","options":["(A) 前囟門鼓脹或膨出","(B) 躁動不安","(C) 發燒","(D) 嘔吐"],"answer":0,"image":""},{"id":"nr4-112-3-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第3次第1題","year":112,"session":3,"number":1,"question":"有關婦嬰生命統計，下列何者正確？","options":["(A) 粗出生率為一年內每十萬年中人口之平均活產數","(B) 孕產婦死亡率為每十萬活產嬰兒中，於妊娠期間或妊娠終止後42天內死亡之婦女人數","(C) 新生兒死亡率為每年每十萬活產嬰兒中未滿1歲即死亡之人數","(D) 周產期死亡率為妊娠40週以上之死胎數加上活產後4週內死亡數之和對一年中活產數之比率"],"answer":1,"image":""},{"id":"nr4-112-3-2","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第3次第2題","year":112,"session":3,"number":2,"question":"有關拉梅茲倡議的生產措施，下列敘述何者正確？","options":["(A) 鼓勵分娩時可下床活動及變換姿勢","(B) 鼓勵使用催產素以加速產程之進展","(C) 鼓勵採仰臥姿位以提高產婦的舒適感","(D) 鼓勵使用持續性胎兒監測器以確保胎兒安全"],"answer":0,"image":""},{"id":"nr4-112-3-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第3次第3題","year":112,"session":3,"number":3,"question":"張女士，懷孕30週，主訴近期常感覺頻尿及偶有漏尿十分困擾，下列護理指導何者較不適當？","options":["(A) 教導凱格爾運動，強化骨盆底肌肉","(B) 維持會陰部清潔乾燥，多更換內褲","(C) 白天減少水分攝取，減輕膀胱壓力","(D) 使用托腹帶減輕腹壓，儘量不憋尿"],"answer":2,"image":""},{"id":"nr4-112-3-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第3次第4題","year":112,"session":3,"number":4,"question":"王女士主訴：「我懷孕後都不吃冰了，因擔心對孩子氣管不好」，下列護理師反應何者最適當？","options":["(A) 建議詢問醫師後再決定","(B) 以實證研究資料反駁婦女的行為","(C) 尊重其文化以及飲食的選擇","(D) 提供更多的飲食禁忌訊息"],"answer":2,"image":""},{"id":"nr4-112-3-5","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第3次第5題","year":112,"session":3,"number":5,"question":"有關羊膜穿刺術（amniocentesis）的檢查時機及情況，下列敘述何者正確？","options":["(A) 懷孕12週婦女，曾生育染色體異常","(B) 懷孕16週婦女，先前有習慣性流產","(C) 懷孕16週婦女，罹患慢性高血壓","(D) 懷孕18週婦女，母血唐氏症篩檢危險比值為1/720"],"answer":1,"image":""},{"id":"nr4-112-3-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"112年第3次第6題","year":112,"session":3,"number":6,"question":"素食者在懷孕期較易缺乏下列何項維生素？","options":["(A) 維生素A","(B) 維生素B2","(C) 維生素B12","(D) 維生素K"],"answer":2,"image":""},{"id":"nr4-112-3-7","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第3次第7題","year":112,"session":3,"number":7,"question":"張女士，G1P0，懷孕40週，下列何者是真陣痛的特徵？","options":["(A) 感覺後背痛，但走路會緩解","(B) 宮縮間隔時間逐漸變短，並有規律感","(C) 宮縮時偶肚子變硬，但強度沒有變化","(D) 陣痛一定伴隨破水發生"],"answer":1,"image":""},{"id":"nr4-112-3-8","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第3次第8題","year":112,"session":3,"number":8,"question":"丁女士，G1P0，妊娠39週，常規產檢結果正常。丁女士表示：「最近肚子有下降了，呼吸也更輕鬆了」。預期丁女士伴隨發生的症狀，下列何者可能性最低？","options":["(A) 頻尿情形更為頻繁","(B) 橫膈處的緊繃感減輕","(C) 鼠蹊部疼痛緩解","(D) 分娩大約在2週內發生"],"answer":2,"image":""},{"id":"nr4-112-3-9","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第3次第9題","year":112,"session":3,"number":9,"question":"陳女士，G2P1，陰道內診結果為：「Station：floating」，其代表的意思，下列敘述何者正確？","options":["(A) 胎兒先露部位尚未進入骨盆入口","(B) 胎兒先露部位尚未通過骨盆腔最短徑線的橫切面","(C) 胎兒雙頂徑（BPD）接近坐骨結節，但尚未到達","(D) 胎兒先露部位膨出於母體的會陰部"],"answer":0,"image":""},{"id":"nr4-112-3-10","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第3次第10題","year":112,"session":3,"number":10,"question":"有關潛伏期產程延長且母胎無異常的待產婦照護，下列何者較不適當？","options":["(A) 應立即採行剖腹產","(B) 提供足夠水分及食物","(C) 評估分析可能原因","(D) 經常更換姿勢，以利胎兒轉位下降"],"answer":0,"image":""},{"id":"nr4-112-3-11","subject":"nr4","topic":"產科-待產與分娩","meta":"112年第3次第11題","year":112,"session":3,"number":11,"question":"李女士剖腹產前將進行腰椎硬膜外麻醉，下列措施何者不適當？","options":["(A) 協助產婦採側躺並呈蝦米狀","(B) 麻醉前靜脈輸液1,000 c.c.葡萄糖水","(C) 進行穿刺於L3或L4腰椎間","(D) 藥物注入後密切監測生命徵象"],"answer":1,"image":""},{"id":"nr4-112-3-12","subject":"nr4","topic":"產科-產後照護","meta":"112年第3次第12題","year":112,"session":3,"number":12,"question":"徐女士，G2P1，行子宮下段橫式切開剖腹產（Lower segment Cesarean section），採用脊髓麻醉法，下列術後照護何者錯誤？","options":["(A) 術後導尿管至少留置8小時","(B) 術後採辛式臥位","(C) 給與足夠水分2,500～3,000 c.c.／天","(D) 下一胎可嘗試剖腹產後陰道生產（VBAC）"],"answer":1,"image":""},{"id":"nr4-112-3-13","subject":"nr4","topic":"產科-產後照護","meta":"112年第3次第13題","year":112,"session":3,"number":13,"question":"鄒女士，33歲，為陰道生產之初產婦。選擇在母嬰親善醫院生產並計劃依循衛生福利部國民健康署對嬰幼兒最佳餵養建議，下列敘述何者不適當？","options":["(A) 新生兒即刻照護評估後30分鐘，再開始進行初次母嬰肌膚接觸","(B) 確保在家人協助與陪伴下進行親子同室","(C) 告知觀察到嬰兒有飢餓訊號時就餵母乳，不限餵奶時間或頻率","(D) 鼓勵親自以乳房哺餵新生兒，若有脹奶時進行手擠奶"],"answer":0,"image":""},{"id":"nr4-112-3-14","subject":"nr4","topic":"產科-產後照護","meta":"112年第3次第14題","year":112,"session":3,"number":14,"question":"婦女初次嘗試親餵母乳，向護理師表示：「我的乳頭是平的，還能親餵嗎？」，下列何項護理指導內容最適當？","options":["(A) 乳頭扁平使寶寶不易含乳，請將奶水擠出來瓶餵","(B) 寶寶是吸吮乳房不是乳頭，應先評估乳頭伸展性","(C) 乳頭扁平使寶寶不易含乳，等寶寶大些就會吸了","(D) 寶寶是吸吮乳房不是乳頭，等寶寶大些就會吸了"],"answer":1,"image":""},{"id":"nr4-112-3-15","subject":"nr4","topic":"產科-產後照護","meta":"112年第3次第15題","year":112,"session":3,"number":15,"question":"有關產後情緒變化之敘述，下列何者正確？①產後沮喪婦女可自行復原 ②產後精神病婦女會出現幻聽、幻覺而傷害新生兒 ③重度產後憂鬱婦女具有自殺危險性 ④產後精神病常出現於產後2個月之後","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":0,"image":""},{"id":"nr4-112-3-16","subject":"nr4","topic":"產科-產後照護","meta":"112年第3次第16題","year":112,"session":3,"number":16,"question":"有關產後會陰傷口評估與護理措施，下列敘述何者正確？","options":["(A) 避免會陰傷口裂開，鼓勵採低纖維飲食","(B) 評估會陰傷口時，採平躺打開雙腳較易觀察","(C) 緩解會陰傷口痛，分娩後2小時採溫水坐浴","(D) 評估會陰癒合情形，可採REEDA方法"],"answer":3,"image":""},{"id":"nr4-112-3-17","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第3次第17題","year":112,"session":3,"number":17,"question":"促使新生兒出生後動脈導管功能性關閉的最主要原因為何？","options":["(A) 肺擴張後左心房壓力減少","(B) 肺擴張後血氧分壓上升","(C) 剪斷臍帶後肝臟血液增加","(D) 剪斷臍帶後下腔靜脈血液減少"],"answer":1,"image":""},{"id":"nr4-112-3-18","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第3次第18題","year":112,"session":3,"number":18,"question":"有關新生兒之身體評估方式，下列何者不適當？","options":["(A) 心尖脈最好能在新生兒睡覺時測量，需測30秒","(B) 觸診腹部前應先聽診腹部四象限是否有腸音","(C) 評估新生兒肌力時，宜將手拉直、放鬆，觀察其手臂回彈程度","(D) 頭圍測量應將量尺置於眉毛上方，再繞耳朵頂端至枕骨粗隆凸處一圈"],"answer":0,"image":""},{"id":"nr4-112-3-19","subject":"nr4","topic":"產科-新生兒護理","meta":"112年第3次第19題","year":112,"session":3,"number":19,"question":"下列何種免疫球蛋白胎兒無法自行合成，需於出生後從母乳中獲得？","options":["(A) IgM","(B) IgG","(C) IgA","(D) IgE"],"answer":2,"image":""},{"id":"nr4-112-3-20","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第3次第20題","year":112,"session":3,"number":20,"question":"陳女士，G3P0SA2，前兩胎均在妊娠16～18週左右因無痛性破水自然流產，目前陳女士妊娠16週，產檢發現胎兒發育與週數相符、子宮張力正常、子宮頸長度為2.4公分、擴張2公分。有關產前照護的敘述，下列何者較適當？","options":["(A) 告知產檢狀況一切正常不用擔心，一個月後再回診","(B) 具子宮頸閉鎖不全之高危險因子，建議接受子宮頸環紮術（Cervical cerclage）","(C) 具胎盤早期剝離之高危險因子，建議給口服安胎藥且返家後儘量臥床休息","(D) 具產程遲滯的危險因子，可能前胎流產沾黏導致子宮頸長度較長"],"answer":1,"image":""},{"id":"nr4-112-3-21","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第3次第21題","year":112,"session":3,"number":21,"question":"有關HELLP症候群的敘述，下列何者正確？","options":["(A) H：指紅血球溶血","(B) EL：指胰臟酵素值上升","(C) LP：指血小板少於200,000／mm3","(D) 常發生在第一妊娠期"],"answer":0,"image":""},{"id":"nr4-112-3-22","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第3次第22題","year":112,"session":3,"number":22,"question":"丁女士，妊娠12週，接受第二次產前檢查，發現其紅血球平均容積（MCV）為60 fl。針對丁女士的狀況，下列何者為最優先處置？","options":["(A) 安排丁女士接受基因檢查，以確認其是否為海洋性貧血症","(B) 安排配偶接受基因檢查，以確認其是否為海洋性貧血帶因者","(C) 安排配偶接受紅血球平均容積（MCV）之血液篩檢","(D) 安排丁女士接受絨毛膜取樣，以確認胎兒的基因型式"],"answer":2,"image":""},{"id":"nr4-112-3-23","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"112年第3次第23題","year":112,"session":3,"number":23,"question":"承上題，若配偶亦為海洋性貧血之帶因者，有關胎兒狀況之敘述，下列何者正確？","options":["(A) 胎兒為重症海洋性貧血的罹病率是75%","(B) 重症海洋性貧血遺傳的機率與胎兒性別有關","(C) 若胎兒為乙型海洋性貧血重症者，則其在胎兒時期是正常的","(D) 若胎兒為乙型海洋性貧血重症者，丁女士易發生妊娠高血壓"],"answer":2,"image":""},{"id":"nr4-112-3-24","subject":"nr4","topic":"婦科-婦女健康","meta":"112年第3次第24題","year":112,"session":3,"number":24,"question":"有關人工受精的敘述，下列何者正確？","options":["(A) 建議禁慾1天再取精","(B) 以新鮮精液或將冷凍精液解凍後使用","(C) 精液注入子宮腔後婦女需平躺12小時以利精液留滯","(D) 精液注入子宮腔後的第7天以驗孕試劑確認受孕成功"],"answer":1,"image":""},{"id":"nr4-112-3-25","subject":"nr4","topic":"產科-高危險妊娠","meta":"112年第3次第25題","year":112,"session":3,"number":25,"question":"王女士懷孕12週時產檢血清檢查確診梅毒感染，其掩面哭泣表示：「不知道為什麼自己會得到梅毒，是否要告訴先生？」，下列護理指導，何者不適當？","options":["(A) 詢問王女士性生活史以瞭解是否具多重性伴侶","(B) 衛教梅毒主要傳染途徑為性行為，夫妻均需接受檢查與治療才能避免反覆交互感染","(C) 衛教Penicillin可以治療梅毒的感染，請王女士配合治療","(D) 說明梅毒在懷孕初期不會傳染給胎兒，可等懷孕18週再做產檢抽血確定"],"answer":3,"image":""},{"id":"nr4-112-3-26","subject":"nr4","topic":"兒科-意外事故與急症","meta":"112年第3次第26題","year":112,"session":3,"number":26,"question":"小明，1歲8個月大，體重12公斤，不慎被熱水燙到，導致前胸15%的燒傷，立即送醫後經評估為二度燒傷，關於小明的照護措施，下列何者錯誤？","options":["(A) 在燒傷最初24小時以乳酸林格氏液補充水分及電解質","(B) 輸液的速度需觀察生命徵象、尿量，以適時調整滴速","(C) 提供足夠營養以修復組織細胞，每日熱量需求為1,050 Kcal","(D) 傷口處置包含每天換藥、清洗、水療、清創及植皮等照護"],"answer":2,"image":""},{"id":"nr4-112-3-27","subject":"nr4","topic":"兒科-生長發展","meta":"112年第3次第27題","year":112,"session":3,"number":27,"question":"有關厭食症的相關敘述，下列何者錯誤？","options":["(A) 造成厭食症的可能原因並非單一因素所導致","(B) 可運用行為治療與家庭心理諮商修正不良的飲食行為","(C) 厭食症者害怕體重增加而甘願忍受飢餓或自我催吐","(D) 照護以提供足夠的營養，體重增加速度以每週3～5公斤為理想值"],"answer":3,"image":""},{"id":"nr4-112-3-28","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"112年第3次第28題","year":112,"session":3,"number":28,"question":"有關賦權（empowerment）在兒科護理照護的應用，下列敘述何者錯誤？","options":["(A) 強調醫護人員有權利決定病童照護的選擇","(B) 強調病童及其家人能有能力與行動促進病童的健康","(C) 建立醫護專業人員與家人的夥伴關係，協同照護病童","(D) 強調家人有權利與能力決定家庭成員的健康需求"],"answer":0,"image":""},{"id":"nr4-112-3-29","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第3次第29題","year":112,"session":3,"number":29,"question":"小偉因腦膜炎住院，依醫囑給與小偉藥物治療，醫師醫囑為：Dexamethasone（10 mg/2 mL/vial）7 mg Q8H靜脈滴注，護理師每次給藥應抽多少mL的藥物劑量？","options":["(A) 1.2","(B) 1.4","(C) 1.6","(D) 1.8"],"answer":1,"image":""},{"id":"nr4-112-3-30","subject":"nr4","topic":"兒科-生長發展","meta":"112年第3次第30題","year":112,"session":3,"number":30,"question":"6個月大之嬰兒健檢時，母親詢問護理師：「我孩子頭頂中間摸起來軟軟的，這是正常的嗎？」，下列何項回應最為適當？","options":["(A) 這是前囟門，約於12至18個月大時會完全關閉","(B) 這是前囟門，應該在出生後3個月關閉","(C) 這是後囟門，應該會在最近2個月內關閉","(D) 建議轉診小兒神經外科做進一步檢查"],"answer":0,"image":""},{"id":"nr4-112-3-31","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第3次第31題","year":112,"session":3,"number":31,"question":"有關病童使用Fentanyl貼片的敘述，下列護理指導何者錯誤？","options":["(A) 屬於鴉片類製劑，透過黏膜吸收，會造成呼吸速度變慢","(B) 貼片適合黏貼於平坦處，如前胸、後背、上手臂、大腿","(C) 易產生耐藥性、成癮或便秘等","(D) 貼片使用期限為24小時，使用貼片時需註明起迄時間"],"answer":3,"image":""},{"id":"nr4-112-3-32","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第3次第32題","year":112,"session":3,"number":32,"question":"小玲，2歲6個月，因泌尿道感染住院，有關減輕小玲住院壓力的護理措施，下列敘述何者錯誤？","options":["(A) 容許小玲表達其反抗和生氣的情緒","(B) 不批評且接受其退化性行為","(C) 限制小玲下床自由活動","(D) 儘可能提供小玲選擇的機會"],"answer":2,"image":""},{"id":"nr4-112-3-33","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第3次第33題","year":112,"session":3,"number":33,"question":"汪小弟為29週又5天出生的早產兒，體重1,310公克，有關各系統的生理特徵，下列敘述何者正確？","options":["(A) 免疫力較低，無法經由胎盤獲得IgA","(B) β-尿苷酸酶的量不足，易發生高膽紅素血症","(C) 心室中膈缺損是最常見的心臟血管問題","(D) 中樞神經系統不成熟，易發生呼吸暫停現象"],"answer":3,"image":""},{"id":"nr4-112-3-34","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第3次第34題","year":112,"session":3,"number":34,"question":"有關瀕死兒童家庭的照護敘述，下列何者不適當？","options":["(A) 接納父母的哀傷反應，鼓勵父母說出其想法","(B) 針對父母想獲得的資訊給與正確的資料","(C) 提醒父母避免家中其他幼童參與喪禮的過程","(D) 評估父母和病童對靈性的需求，提供適當的支持與諮詢"],"answer":2,"image":""},{"id":"nr4-112-3-35","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第3次第35題","year":112,"session":3,"number":35,"question":"為促進早產兒的統整化行為，下列護理措施何者不適當？","options":["(A) 提供袋鼠式護理，採皮膚接觸皮膚的方式照顧早產兒","(B) 早產兒清醒時可於保溫箱內播放輕柔音樂","(C) 絕對避免觸摸或抱起早產兒，以免引起驚嚇反射之刺激","(D) 在保溫箱內使用包巾築巢，以提供類似子宮的安全感"],"answer":2,"image":""},{"id":"nr4-112-3-36","subject":"nr4","topic":"兒科-高危險新生兒","meta":"112年第3次第36題","year":112,"session":3,"number":36,"question":"以「斯佛門-安德生計分法」（Silverman Anderson score）評估早產兒呼吸窘迫情況，下列敘述何者正確？","options":["(A) 觀察早產兒呼吸時有無困難情形，滿分為10分","(B) 評估早產兒呼吸情形，分數愈高表示情況愈好","(C) 評估發現早產兒得0分表示嚴重呼吸困難","(D) 評估呼吸時腹部凹陷情形、鼻孔擴張程度及吸氣咕嚕聲"],"answer":0,"image":""},{"id":"nr4-112-3-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第3次第37題","year":112,"session":3,"number":37,"question":"有關腮腺炎之照護措施，下列敘述何者錯誤？","options":["(A) 冷敷或溫敷頸部腫脹處以增加舒適感","(B) 若張口困難則建議以吸管飲用檸檬汁","(C) 服用Acetaminophen可緩解脹痛與高燒","(D) 自腮腺開始腫大，採呼吸道隔離約9天"],"answer":1,"image":""},{"id":"nr4-112-3-38","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第3次第38題","year":112,"session":3,"number":38,"question":"有關氣喘（asthma）之病因及病理變化，下列敘述何者正確？","options":["(A) 呼吸道受刺激造成黏膜水腫導致呼吸困難是因為平滑肌擴張所致","(B) 誘發因子引發呼吸道狹窄、呼吸困難、缺氧，產生呼吸性酸中毒","(C) 呼吸道阻塞使吸氣時間延長而形成吸氣哮鳴音（stridor）","(D) 嚴重發作時呈現臉色潮紅、呼吸次數增快、心跳次數減緩"],"answer":1,"image":""},{"id":"nr4-112-3-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"112年第3次第39題","year":112,"session":3,"number":39,"question":"有關罹患急性會厭炎（acute epiglottitis）病童的臨床表徵，下列何者錯誤？","options":["(A) 身體採坐姿且將身體前傾，用手撐住下巴","(B) 流口水、吞嚥困難","(C) 持續性咳嗽","(D) 呼吸窘迫、發音困難"],"answer":2,"image":""},{"id":"nr4-112-3-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第3次第40題","year":112,"session":3,"number":40,"question":"王小妹疑似心臟病入院檢查，予以抽ASLO（anti-streptolysin O）抗鏈球菌素檢驗，此檢驗主要是診斷下列何者？","options":["(A) 川崎氏症","(B) 法洛氏四重症","(C) 開放性動脈導管","(D) 急性風濕熱"],"answer":3,"image":""},{"id":"nr4-112-3-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第3次第41題","year":112,"session":3,"number":41,"question":"小梨，4歲，診斷為缺鐵性貧血，有關鐵劑（Imferon）注射，下列何者不適當？","options":["(A) 以Z字形深部肌肉注射","(B) 持針以90度插入皮膚","(C) 注入鐵劑後應該立即拔針","(D) 勿揉搓注射部位"],"answer":2,"image":""},{"id":"nr4-112-3-42","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第3次第42題","year":112,"session":3,"number":42,"question":"有關兒童副甲狀腺功能低下症（hypoparathyroidism），下列敘述何者錯誤？","options":["(A) 通常血鈣濃度小於7.0 mg/dL","(B) 手足痙攣為常見症狀","(C) X光檢查發現骨質疏鬆","(D) 避免食用含高磷的食物"],"answer":2,"image":""},{"id":"nr4-112-3-43","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"112年第3次第43題","year":112,"session":3,"number":43,"question":"有關威爾姆氏腫瘤（Wilms tumor）起源於下列那個器官或系統？","options":["(A) 骨骼","(B) 血液","(C) 腎臟","(D) 腦"],"answer":2,"image":""},{"id":"nr4-112-3-44","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"112年第3次第44題","year":112,"session":3,"number":44,"question":"小恩，12歲，接受化學治療出現掉髮，顯得悶悶不樂，不願離開病房與他人互動。有關其護理措施，下列敘述何者錯誤？","options":["(A) 告知小恩掉髮是必然的副作用，且不可逆","(B) 鼓勵小恩表達對掉髮的想法及感受","(C) 與小恩共同討論使用頭巾、假髮等遮蓋掉髮","(D) 介紹與小恩年齡相仿之病友，分享掉髮經驗"],"answer":0,"image":""},{"id":"nr4-112-3-45","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第3次第45題","year":112,"session":3,"number":45,"question":"有關尿道下裂（hypospadias）病童術後之敘述，下列何者最適當？","options":["(A) 術後鼓勵病童常下床活動，可促進傷口癒合速度","(B) 術後數天內尿液由陰莖以外滲漏，為正常現象","(C) 鼓勵病童跨坐可固定傷口減輕疼痛","(D) 將導尿管固定於腹部或腿上以降低拉扯傷口"],"answer":3,"image":""},{"id":"nr4-112-3-46","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第3次第46題","year":112,"session":3,"number":46,"question":"有關輪狀病毒（rotavirus）和諾羅病毒（norovirus）之比較，下列敘述何者錯誤？","options":["(A) 輪狀病毒好發於嬰幼兒，諾羅病毒好發於所有年齡層","(B) 輪狀病毒有疫苗預防，諾羅病毒則無","(C) 輪狀病毒會產生腸毒素，諾羅病毒機轉尚不清楚","(D) 兩者傳染途徑均屬糞口傳染"],"answer":2,"image":""},{"id":"nr4-112-3-47","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第3次第47題","year":112,"session":3,"number":47,"question":"小倩，11歲，有急性腎衰竭病史，因控制不佳，此次入院診斷為慢性腎衰竭，有關其護理照護之敘述，下列何者最不適當？","options":["(A) 觀察身體有無瘀傷、紫斑等現象以預防出血","(B) 皮膚因尿霜堆積，易出現搔癢問題，可給與適當潤膚劑使用","(C) 給與高鉀之飲食指導，如香蕉、橘子，以避免低血鉀導致心律不整現象","(D) 給與含鐵質與葉酸之飲食指導，以避免貧血之發生"],"answer":2,"image":""},{"id":"nr4-112-3-48","subject":"nr4","topic":"兒科-生長發展","meta":"112年第3次第48題","year":112,"session":3,"number":48,"question":"有關發展性髖關節發育不良之護理措施，下列敘述何者錯誤？","options":["(A) 布萊安特氏（Bryant）牽引，是將雙腳與髖關節屈曲45度並向上做牽引","(B) 帕米利克背帶（Pavlik harness）使用目的是維持髖關節屈曲及外展","(C) 開始走路以後，無法用吊帶，可用髖部人字形石膏（spica cast）來治療","(D) 6個月以前為治療發展性髖關節發育不良的黃金時期"],"answer":0,"image":""},{"id":"nr4-112-3-49","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"112年第3次第49題","year":112,"session":3,"number":49,"question":"有關兒童顱內壓增高的臨床表徵及處置，下列敘述何者錯誤？","options":["(A) 早上起床後發生頭痛及噴射狀嘔吐","(B) 會出現呼吸不規則，心搏過緩，血壓升高的Cushing’s triad現象","(C) 顱內壓大於15 mmHg時，即稱為顱內壓增高","(D) 給與全速靜脈輸注Mannitol"],"answer":3,"image":""},{"id":"nr4-112-3-50","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"112年第3次第50題","year":112,"session":3,"number":50,"question":"有關罹患無菌性腦膜炎（aseptic meningitis）病童之腦脊髓液，下列敘述何者正確？","options":["(A) 外觀呈現白濁濃稠","(B) 蛋白質值大幅下降","(C) 腦脊髓壓力正常或稍上升","(D) 葡萄糖值大幅上升"],"answer":2,"image":""},{"id":"nr4-113-1-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"有關孕產婦死亡率之敘述，下列何者正確？","options":["(A) 係指一年內每十萬名活產中，於懷孕期間或懷孕終止42天內之婦女死亡數","(B) 係指一年內每十萬名活產中，於第三妊娠期或懷孕終止7天內之婦女死亡數","(C) 係指一年內每十萬名活產中，於第三妊娠期或懷孕終止30天內之婦女死亡數","(D) 係指一年內每十萬名活產中，於懷孕期間或懷孕終止24小時內之婦女死亡數"],"answer":0,"image":""},{"id":"nr4-113-1-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"有關妊娠期血液檢查之敘述，下列何者正確？","options":["(A) 首次產檢需要篩檢人類免疫缺乏病毒","(B) 第一妊娠期進行母體血液葡萄糖耐受篩檢","(C) 第二妊娠期進行B群鏈球菌篩檢","(D) 第三妊娠期進行德國麻疹抗體濃度價數篩檢"],"answer":0,"image":""},{"id":"nr4-113-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"王先生將成為準父親，有關王先生於配偶孕期之心理變化，下列何者最適當？","options":["(A) 第一孕期最常出現害怕生產的壓力","(B) 第二孕期最擔憂是否能勝任成為父親的角色","(C) 第一孕期常因胎動而感覺與胎兒連成一體","(D) 第二孕期常會想像胎兒模樣及身為父親的形象"],"answer":3,"image":""},{"id":"nr4-113-1-4","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"王女士，32歲，妊娠8週，前一胎因21對染色體異常引產，詢問此次有關唐氏症篩檢之敘述，下列何者最合適？","options":["(A) 建議妊娠16～18週之間，可以接受絨毛膜穿刺，確定胎兒染色體是否正常","(B) 建議妊娠11～12週之間，可以接受羊膜腔穿刺，確定胎兒染色體是否正常","(C) 建議妊娠21～24週之間，可以進行母血唐氏症篩檢，確定胎兒染色體是否正常","(D) 建議妊娠15～20週之間，可以接受頸部透明帶的檢測，確定胎兒染色體是否正常"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第4題一律給分。 (原公告答案 D)"},{"id":"nr4-113-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"有關妊娠期的心臟血管系統生理變化，下列敘述何者錯誤？","options":["(A) 3出現生理性白血球增多症，白血球數量可增加到15,000/mm","(B) 妊娠生理性貧血是因紅血球攜鐵蛋白的能力降低所致","(C) 心輸出量增加30～50%，以供應子宮、胎盤需要血流","(D) 血漿中白蛋白降低，使得水分易滯留在血管間隙形成水腫"],"answer":1,"image":""},{"id":"nr4-113-1-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"有關孕期的營養需求，下列敘述何者錯誤？","options":["(A) 於第三孕期多補充鐵劑","(B) 整個孕期應多補充碘","(C) 磷可參與早期的細胞分裂過程","(D) 鈣質提供胎兒骨骼和牙齒的生長發育"],"answer":2,"image":""},{"id":"nr4-113-1-7","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"葉女士，28歲，G1P0，待產過程中突然自然破水，內診發現子宮頸口開8公分、變薄程度80%、先露部位+1。下列何者為最優先之護理處置？","options":["(A) 提供灌腸","(B) 監測胎心率變化","(C) 提供氧氣","(D) 採平躺增加子宮血流"],"answer":1,"image":""},{"id":"nr4-113-1-8","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"陰道生產過程，下列何種情形表示先露部位胎頭已發生著冠（crowning）？","options":["(A) 當子宮收縮時，胎頭顱頂上出現一圈可見的壓痕","(B) 當子宮收縮時，胎頭出現於陰道口，宮縮間歇時，胎頭縮回陰道內","(C) 當子宮收縮時，陰道口膨出可見胎頭，大小呈卵圓形","(D) 當宮縮間歇時，胎頭出現於陰道口且不會縮回陰道內"],"answer":3,"image":""},{"id":"nr4-113-1-9","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"有關分娩期預防產後出血的措施，下列何者不適當？","options":["(A) 待產婦在進入第二產程前，開始持續靜脈注射methylergometrine（Methergin）","(B) 胎盤娩出後，檢查胎盤以確認胎盤完整娩出","(C) 在新生兒及產婦狀況穩定下，協助親子立即肌膚接觸","(D) 產後於恢復室觀察，每15分鐘監測產婦的血壓及出血量"],"answer":0,"image":""},{"id":"nr4-113-1-10","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"胎兒為頭產式，胎頭呈部分屈曲，其最可能以下列那條徑線通過產道？","options":["(A) 枕下前囟徑（SOB）","(B) 枕額徑（OF）","(C) 枕頦徑（OM）","(D) 頦下前囟徑（SMB）"],"answer":1,"image":""},{"id":"nr4-113-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"劉女士，G1P0，子宮頸開4公分，每3分鐘宮縮一次，無胎頭骨盆不對稱（CPD），使用硬脊膜外麻醉，持續2小時都未見胎頭下降，此時最優先之處置為何？","options":["(A) 評估膀胱的情形","(B) 評估胎頭大小","(C) 給與ritodrine點滴注射，促進子宮收縮","(D) 評估羊水量"],"answer":0,"image":""},{"id":"nr4-113-1-12","subject":"nr4","topic":"產科-產後照護","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"王女士，初產婦，陰道生產，採純母乳哺育，產後6週重返職場的一週後，主訴發燒38℃，右側乳房情況如圖所示，觸診溫熱且有痛感。最可能的診斷是？","options":["(A) 因為剛剛返回工作狀態，所以最可能是壓力性乳腺管阻塞（blocked ducts）","(B) 因為幾乎整個乳房大面積發紅，所以最可能是乳房腫脹（engorgement）","(C) 因為乳頭可見傷口，所以最可能是乳腺炎（mastitis）","(D) 因為乳房3、4點鐘方向有水囊狀感，所以最可能是乳房膿瘍（breast abscess）"],"answer":2,"image":"nr4-113-1-12.jpeg"},{"id":"nr4-113-1-13","subject":"nr4","topic":"產科-產後照護","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"蔡女士，初產婦，因產程遲滯而行剖腹生產，新生兒出生體重3,800公克。產婦計畫要完全哺餵母乳，擔心自己奶水不足，因為從生產至今已兩天，都沒有脹奶的感覺，而且新生兒幾乎是含著乳房入睡，放下來就哭。有關蔡女士對奶量的擔心，下列措施何者不適當？","options":["(A) 評估新生兒兩天的排尿及排便情況","(B) 告訴產婦產程過長及剖腹生產都會延後脹奶出現的時間，這是正常的","(C) 肯定產婦完全母乳哺育的決定，了解這兩天新生兒吃奶及含乳的情況","(D) 了解產婦執行手擠乳的情況，討論增加手擠奶頻率的可行性"],"answer":1,"image":""},{"id":"nr4-113-1-14","subject":"nr4","topic":"產科-產後照護","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"何女士，G1P1，採陰道分娩，無任何產後合併症，產後4小時，觸診子宮底時發現位於臍上一指且偏右，下列何者為首要的護理措施？","options":["(A) 子宮按摩","(B) 下床活動","(C) 多喝開水","(D) 如廁解尿"],"answer":3,"image":""},{"id":"nr4-113-1-15","subject":"nr4","topic":"產科-產後照護","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"有關產後婦女之情緒照顧，下列護理指導何者不適當？","options":["(A) 初產婦出現哭泣不安及缺乏育兒信心為產後憂鬱症，應儘速就醫","(B) 在接受期（taking-in phase），鼓勵產婦陳述生產經驗，接受其感受，必要時可澄清其疑慮","(C) 在緊執期（taking-hold phase），鼓勵參與及學習新生兒照護","(D) 產婦即使進入放手期（letting-go phase），仍可能有不自覺的哀傷情緒"],"answer":0,"image":""},{"id":"nr4-113-1-16","subject":"nr4","topic":"產科-產後照護","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"婦女產後痛（after pain）主要是評估下列那一個器官或組織之健康問題？","options":["(A) 乳房、乳頭疼痛","(B) 會陰、會陰傷口疼痛","(C) 子宮、子宮間歇性收縮不適感","(D) 肛門、痔瘡痛"],"answer":2,"image":""},{"id":"nr4-113-1-17","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"抱起新生兒放入磅秤測量體重，新生兒四肢出現對稱性的外展和伸直，大拇指與食指呈C字形，是下列那種反射表現？","options":["(A) 擁抱反射（moro reflex）","(B) 驚嚇反射（startle reflex）","(C) 手掌抓握反射（palmer grasp reflex）","(D) 退縮反射（withdrawal reflex）"],"answer":0,"image":""},{"id":"nr4-113-1-18","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"方小妹，39週頭產式出生，下列何者新生兒身體評估結果為異常發現？","options":["(A) 胎頭變形（molding）","(B) 結膜下點狀出血","(C) 硬腭小白點（艾柏斯坦小珠Epstein's pearls）","(D) 耳朵上緣位於內外眼眥連線以下"],"answer":3,"image":""},{"id":"nr4-113-1-19","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"下列何者為評估男性新生兒皮膚飽和度的最佳部位？","options":["(A) 陰囊","(B) 四肢末端","(C) 眼瞼","(D) 腹部"],"answer":3,"image":""},{"id":"nr4-113-1-20","subject":"nr4","topic":"產科-產後照護","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"王女士，G1P0，妊娠38週，因早期破水入院待產，待產時宮縮頻率及強度均不好，破水30小時後新生兒才娩出。產後第2天出現下列症狀：體溫38.5～39.5℃、惡露呈紅色有惡臭味、子宮底高度臍平、子宮軟、有頭痛及失眠、下腹部壓痛但無反彈性壓痛。上述王女士的身體狀況，其臨床症狀敘述下列何者正確？","options":["(A) 會陰傷口感染","(B) 子宮內膜炎","(C) 腹膜炎","(D) 泌尿道感染"],"answer":1,"image":""},{"id":"nr4-113-1-21","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"接受子宮頸環紮術（cervical cerclage）之孕婦狀況，下列何者最適合？","options":["(A) 上一胎足月產但此胎妊娠16週，子宮頸口擴張4公分","(B) 前兩次均在妊娠21週時無痛性流產，此胎在16週子宮頸長度3.3公分","(C) 妊娠18週有破水且有規則宮縮痛，內診發現子宮頸口擴張2公分","(D) 前胎31週早產，此胎在28週例行性超音波發現子宮頸長度1公分"],"answer":1,"image":""},{"id":"nr4-113-1-22","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"有關妊娠糖尿病之敘述，下列何者正確？","options":["(A) 妊娠初期胎盤分泌人類胎盤泌乳激素（hPL）增加，產生胰島素拮抗","(B) 容易導致流產及羊水過多","(C) 與糖尿病遺傳史無關","(D) 口服降血糖藥為主要治療方式"],"answer":1,"image":""},{"id":"nr4-113-1-23","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"李女士以oxytocin進行引產，胎心音出現變異性減速，下列處置何者最適當？","options":["(A) 提高oxytocin滴速","(B) 降低oxytocin滴速","(C) 維持原來oxytocin滴速","(D) 停止oxytocin的滴注"],"answer":3,"image":""},{"id":"nr4-113-1-24","subject":"nr4","topic":"婦科-婦女健康","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"有關逆行性射精之敘述，下列何者錯誤？","options":["(A) 常見於脊髓損傷或糖尿病合併神經病變之患者","(B) 可能為腹腔或骨盆腔手術後之併發症","(C) 流至尿道的精液逆流至膀胱","(D) 接受精子捐贈進行人工授精為唯一的治療方式"],"answer":3,"image":""},{"id":"nr4-113-1-25","subject":"nr4","topic":"婦科-婦女健康","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"王女士罹患梅毒，王女士表示先生如果知道了，他會失去先生，不停掩面哭泣，下列護理措施何者最適當？","options":["(A) 告知王女士切勿隱瞞，因先生可能已感染，請他立即連絡先生到院檢查","(B) 衛教將以抗生素進行治療，立即協助施打cefazolin","(C) 告知王女士哭泣無法解決問題，請王女士堅強面對","(D) 傾聽王女士的不安與擔憂，鼓勵其與先生共同面對，接受治療"],"answer":3,"image":""},{"id":"nr4-113-1-26","subject":"nr4","topic":"兒科-意外事故與急症","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"小花因誤食鐵劑而送醫治療，指導小花媽媽之護理措施，下列敘述何者最適當？","options":["(A) 鐵劑通常不會沉積在肝臟或造成肝損傷","(B) 一週後應注意腸胃不適或出血的症狀","(C) 使用活性碳可以幫助鐵劑的吸附","(D) 注射去鐵質劑，尿液會呈深褐／紅橙色"],"answer":3,"image":""},{"id":"nr4-113-1-27","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"小明，16歲，高中一年級，在校成績低落、情緒不穩、易怒、缺課，曾表明想從世界消失。就醫後診斷為青少年憂鬱症。媽媽詢問護理師如何幫助小明時，下列敘述何者錯誤？","options":["(A) 讓小明知道自己生病了，需要治療","(B) 多安排小明的戶外運動","(C) 告知小明不要胡思亂想，應致力於課業成就","(D) 多陪伴小明，避免小明獨處"],"answer":2,"image":""},{"id":"nr4-113-1-28","subject":"nr4","topic":"兒科-生長發展","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"有關滿15個月大幼兒之動作發展，下列敘述何者正確？","options":["(A) 能正確指出身體的一部分","(B) 能重疊6塊積木","(C) 不需扶持可獨自行走","(D) 會自己洗手並擦乾"],"answer":2,"image":""},{"id":"nr4-113-1-29","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"君君，4歲，入院接受靜脈注射和腹部手術，住院期間護理師和君君說話的內容，下列敘述何者最不適當？","options":["(A) 跟你的玩偶說你覺得害怕的事","(B) 打針時跟護理師一起慢慢吸氣吐氣","(C) 切開你的肚子才能把蟲拿出來","(D) 你按著拔針的地方才不會流血"],"answer":2,"image":""},{"id":"nr4-113-1-30","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"護理師給與2歲小廷耳滴藥的照護措施，下列敘述何者錯誤？","options":["(A) 協助病童躺向健側半側臥","(B) 將耳朵往下往後輕拉，使耳道變直","(C) 將耳藥直接滴於鼓膜上","(D) 滴藥後以手指按摩耳部促進藥物吸收"],"answer":2,"image":""},{"id":"nr4-113-1-31","subject":"nr4","topic":"兒科-生長發展","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"當嬰幼兒初次接觸陌生人或新環境，會表現出接受或退縮的態度。此為氣質評估內容中那一個項目？","options":["(A) 反應閾","(B) 適應度","(C) 趨避性","(D) 堅持度"],"answer":2,"image":""},{"id":"nr4-113-1-32","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"小亮，出生後診斷為腭裂（cleft palate），1歲時入院行腭裂修補術，有關術後約束之護理措施，下列敘述何者正確？","options":["(A) 木乃伊約束法","(B) 手臂約束法","(C) 手肘約束法","(D) 背心式約束法"],"answer":2,"image":""},{"id":"nr4-113-1-33","subject":"nr4","topic":"兒科-高危險新生兒","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"有關早產兒發展性照護的敘述，下列何者正確？","options":["(A) 提供父母與早產兒皮膚對皮膚的袋鼠式護理","(B) 執行治療時，固定早產兒雙臂與腿呈伸展姿勢的寧握護理","(C) 採分散護理，以避免早產兒生命徵象不穩定","(D) 保持環境明亮，早產兒戴上遮光眼罩以促進視覺發展"],"answer":0,"image":""},{"id":"nr4-113-1-34","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"小紅，12歲，罹患急性骨髓性白血病，治療後復發，目前處於疾病末期，她向父母發脾氣說：「為什麼生病的人是我，都是你們沒有把我照顧好！」，下列照護措施何者最適合？","options":["(A) 仔細傾聽其話語，鼓勵小紅表達內心的需要","(B) 鼓勵接受目前的治療措施，降低治療造成的疼痛","(C) 鼓勵與同儕聯繫，讓其有歸屬感，並轉移焦點","(D) 說明父母與醫療團隊已經盡最大努力協助治療"],"answer":0,"image":""},{"id":"nr4-113-1-35","subject":"nr4","topic":"兒科-高危險新生兒","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"小敏妊娠週數26週出生，醫師診斷為壞死性腸炎（necrotizing enterocolitis, NEC），有關其護理照護及處置之敘述，下列何者最不適當？","options":["(A) 為防止腸道受損，應避免測量肛溫","(B) 初期觀察小敏是否會出現活動力下降、體溫不穩及呼吸窘迫等症狀","(C) 立即禁食，給與全靜脈營養","(D) 護理評估發現腸蠕動減慢，嘔吐物不含膽汁"],"answer":3,"image":""},{"id":"nr4-113-1-36","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"有關預防造成新生兒猝死之睡眠環境的護理指導，下列敘述何者正確？","options":["(A) 母親與嬰兒同床以方便母乳哺餵","(B) 嬰兒應該仰睡且以枕頭抬高頭部","(C) 嬰兒的枕頭旁擺放絨毛玩具以增加安全感","(D) 嬰兒應該避免穿過多衣服或用衣物包覆頭部"],"answer":3,"image":""},{"id":"nr4-113-1-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"有關腮腺炎（mumps）最常見的合併症，下列敘述何者正確？","options":["(A) 無菌性腦膜炎","(B) 肺炎","(C) 熱性痙攣","(D) 續發性皮膚感染"],"answer":0,"image":""},{"id":"nr4-113-1-38","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"陳小弟，5歲，罹患扁桃腺炎（tonsillitis），接受扁桃腺切除手術（tonsillectomy），下列術後護理何者正確？","options":["(A) 預防肺擴張不全，鼓勵深呼吸、用力咳嗽","(B) 注意觀察是否有吞嚥或清喉嚨次數增加","(C) 局部熱敷或提供熱食，促進傷口血液循環","(D) 提供含維生素C飲料（如檸檬汁），促進傷口癒合"],"answer":1,"image":""},{"id":"nr4-113-1-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"有關嬰幼兒呼吸道特性的敘述，下列何者錯誤?","options":["(A) 耳咽管較短且水平，較易受感染","(B) 舌頭在口腔的比例較大，感染後易出現阻塞","(C) 嬰兒喉頭在頸部較高處，較易出現吸入性肺炎","(D) 嬰幼兒胸腔順應性較成人低"],"answer":3,"image":""},{"id":"nr4-113-1-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"有關川崎氏症病童的治療及其目的，下列敘述何者正確？","options":["(A) 給與阿斯匹靈（aspirin），以促進血小板凝集","(B) 給與免疫球蛋白（IVIG）可有效降低冠狀動脈瘤發生","(C) 給與苯巴比特魯錠（phenobarbital）治療舞蹈症","(D) 給與盤尼西林（penicillin）以預防發炎"],"answer":1,"image":""},{"id":"nr4-113-1-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"有關嬰幼兒缺鐵性貧血（iron deficiency anemia）之敘述，下列何者正確？","options":["(A) 屬體染色體隱性遺傳疾病","(B) 常發生於6～24個月大的足月兒","(C) 紅血球體積比正常紅血球大","(D) 長期貧血可能導致心跳過慢之代償反應"],"answer":1,"image":""},{"id":"nr4-113-1-42","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"小華，6個月，罹患兒童癌症，目前接受化學治療且須治療半年以上，則小華可以接種下列何種疫苗？","options":["(A) 四合一疫苗（Tdap-IPV）","(B) 水痘疫苗","(C) 輪狀病毒疫苗","(D) 麻疹腮腺炎德國麻疹混合疫苗"],"answer":0,"image":""},{"id":"nr4-113-1-43","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"小萍診斷為先天性甲狀腺功能低下症，有關血液檢驗值之敘述，下列何者正確？","options":["(A) 甲狀腺素T4高於正常值、甲狀腺刺激素TSH高於正常值","(B) 甲狀腺素T4高於正常值、甲狀腺刺激素TSH低於正常值","(C) 甲狀腺素T4低於正常值、甲狀腺刺激素TSH低於正常值","(D) 甲狀腺素T4低於正常值、甲狀腺刺激素TSH高於正常值"],"answer":3,"image":""},{"id":"nr4-113-1-44","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"有關性早熟（precocious puberty）的敘述，下列何者正確？","options":["(A) 男孩在12歲以前、女孩在11歲以前出現第二性徵，即為性早熟","(B) 血清中的LH、FSH、estrogen、testosterone皆正常","(C) 中樞性性早熟可給與leuprolide acetate，以抑制促性腺激素釋放荷爾蒙（GnRH）的分泌","(D) 可以腹部斷層掃描確認是否有中樞性性早熟"],"answer":2,"image":""},{"id":"nr4-113-1-45","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"膽道閉鎖（biliary atresia）是嬰兒先天性疾病之一，下列敘述何者錯誤？","options":["(A) 常出現灰白色的大便、暗茶色的尿液","(B) 容易影響脂肪的消化吸收，導致水溶性維生素缺乏","(C) 膽管炎是手術後常見的合併症之一","(D) 提供不需要膽汁消化的中鏈脂肪酸配方奶、高蛋白牛奶為主"],"answer":1,"image":""},{"id":"nr4-113-1-46","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"小強罹患先天性巨結腸症（congential megacolon），有關照護和手術之護理指導敘述，下列何者正確？","options":["(A) 保守療法應採低渣、高熱量、高蛋白飲食","(B) 手術前需採肥皂水進行腸道清潔灌腸","(C) 術後若有造瘻口腫脹情形，則是異常現象，須立即通報醫師","(D) 結腸造口的黏膜並無神經，且會比周圍皮膚低"],"answer":0,"image":""},{"id":"nr4-113-1-47","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"有關兒童急性腹瀉時，下列護理處置何者最適當？","options":["(A) 給與腸道吸附劑（kaolin-pectin），與食物一起服用","(B) 以雞湯取代配方奶","(C) 水分的補充可給與口服葡萄糖電解質水","(D) 配方奶泡濃一些，減少水瀉的次數"],"answer":2,"image":""},{"id":"nr4-113-1-48","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"有關兒童腦神經疾病導致的顱內壓升高（IICP），若無適切介入措施，常會造成兒童生命危險，下列護理措施何者正確？","options":["(A) 可過度換氣讓動脈血中氧氣濃度（PaO2）維持在27～30 mmHg","(B) 應維持病童房間光線明亮，避免病童因頭昏跌倒","(C) 協助抬高床頭約30度，維持頭頸部自然平直","(D) 若有痰液，教導常做深呼吸咳嗽，避免積痰而缺氧"],"answer":2,"image":""},{"id":"nr4-113-1-49","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"小英，6歲，罹患重症肌無力（myasthenia gravis），下列護理措施何者不適當？","options":["(A) 鼓勵加強費力的活動，有助改善肌肉力量","(B) 若出現複視情形，需預防跌倒","(C) 觀察是否有呼吸困難或痰液不易咳出情形","(D) 眼瞼下垂是最早出現的症狀"],"answer":0,"image":""},{"id":"nr4-113-1-50","subject":"nr4","topic":"兒科-意外事故與急症","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"有關熱性痙攣（febrile convulsion）的敘述，下列何者最不適當？","options":["(A) 發燒介於37～38℃之間，且出現單側性的全身性僵直","(B) 為引起幼兒抽筋或痙攣最常見的原因之一","(C) 發燒是誘發因素，其基礎疾病為感染性病原，如上呼吸道感染","(D) 發作時，若出現牙關緊閉，不可強行將兒童嘴巴打開"],"answer":0,"image":""},{"id":"nr4-113-2-1","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"有關以家庭為中心的產科護理模式之敘述，下列何者錯誤？","options":["(A) 待產過程中，鼓勵伴侶全程陪伴","(B) 鼓勵親子同室，減少母嬰分離","(C) 主張待產、生產與產後恢復皆在同一環境","(D) 增加產前基因篩檢次數，減少家族遺傳疾病之發生"],"answer":3,"image":""},{"id":"nr4-113-2-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"孫女士於產檢時，詢問葉酸補充注意事項，下列何者為最適當的護理指導？","options":["(A) 懷孕3個月後開始補充的效果最好","(B) 完全素食者一定要特別注意補充","(C) 可藉由維他命C組合加強吸收","(D) 可經由新鮮深綠色蔬菜及瘦肉獲取"],"answer":3,"image":""},{"id":"nr4-113-2-3","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"有關懷孕期無壓力試驗（Non-stress test, NST）的敘述，下列何者正確？","options":["(A) 建議懷孕26（含）週始能開始測量，才有較準確結果","(B) 測量子宮收縮時胎心率型態的改變","(C) 需持續測量60分鐘以上，才能進行結果判讀","(D) 結果判讀為「反應型者」，可預測一週內胎兒處於健康狀態"],"answer":3,"image":""},{"id":"nr4-113-2-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"有關懷孕內分泌系統的變化，下列敘述何者正確？","options":["(A) 甲狀腺體積比未懷孕時期減少","(B) 鬆弛素大部分是由黃體分泌","(C) 醛固醇分泌量減少，特別是限鈉飲食的孕婦","(D) 第一孕期，hCG的分泌主要是來自胎盤"],"answer":1,"image":""},{"id":"nr4-113-2-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"懷孕24週婦女，表達她很想感受「與胎兒連為一體的情感」，下列護理指導，何者最適當？","options":["(A) 建議尋求良好的產科照顧，隨時了解胎兒發育","(B) 協助其表達對胎動的感受，鼓勵常常對胎兒說話","(C) 請其暫時停止喝咖啡，不熬夜，減少對胎兒傷害","(D) 建議請先生協助做家務，給予孕期支持"],"answer":1,"image":""},{"id":"nr4-113-2-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"接近預產期婦女在家執行「每日胎兒運動紀錄」，當出現下列何種結果需立即到醫院接受診治？","options":["(A) 1小時內記錄到5次胎動","(B) 24小時胎動少於4次","(C) 2小時內有10次胎動","(D) 胎動比前一天相比少了20%"],"answer":1,"image":""},{"id":"nr4-113-2-7","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"李女士，G1P0，子宮收縮每5分鐘一次，每次持續40～60秒，收縮強度為中度，子宮頸口開6公分、變薄程度60%、先露部位0。下列護理措施何者不適當？","options":["(A) 至少每30分鐘測一次胎心率及宮縮情況","(B) 注意待產婦解尿的時間，每2小時評估膀胱排空情形","(C) 擔心隨時生產，所以應禁止待產婦下床","(D) 教導呼吸法協助減輕待產疼痛"],"answer":2,"image":""},{"id":"nr4-113-2-8","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"吳女士，G1P0，懷孕38週，主述：「下面濕濕的，不知道是不是破水了？」。下列何種檢測可以確認破水？","options":["(A) 避開尿或血液，以硝基試紙，檢測流出陰道的液體，試紙呈粉紅色（Nitrazine test）","(B) 避開尿或血液，以硝酸鹽試紙，檢測流出陰道的液體，試紙呈黃綠色（Nitrate water test）","(C) 檢視吳女士墊的衛生棉上，看到清澈淡黃液體並含有羊齒狀的碎片物質（Pad test）","(D) 將流出陰道的液體塗抹於玻片，使用顯微鏡有觀察到羊齒狀結晶（Fern test）"],"answer":3,"image":""},{"id":"nr4-113-2-9","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"葉女士，懷孕39週，因破水入院待產。護理師進行腹部觸診時，在宮底處觸摸到一個較軟，且比較不圓的胎兒部位；在恥骨聯合附近觸摸到一個較硬，似圓形的胎兒部位，接著在肚臍以下的部位聽取到清楚的胎心音。陰道內診時，摸到圓滑且硬的胎兒部位。判斷其胎產式為何？","options":["(A) 頭產式","(B) 臀產式","(C) 面產式","(D) 肩產式"],"answer":0,"image":""},{"id":"nr4-113-2-10","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"安胎婦女使用下列何種藥物可促進胎兒肺部成熟？","options":["(A) Ritodrine","(B) Indomethacin","(C) Betamethasone","(D) Nifedipine"],"answer":2,"image":""},{"id":"nr4-113-2-11","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"原本對生產計畫侃侃而談的待產婦女突然對護理師說：「我想解大便，我如果去廁所會不會把孩子生在馬桶裡？」，下列護理師的回應何者較適宜？","options":["(A) 「我想應該是要生了，我趕緊通知醫師處理。」","(B) 「你有便意感顯示胎頭在往下降，產程有進展了喔！我來幫妳內診評估好嗎？」","(C) 「不用緊張，妳這些擔心都不是真的，不會生在馬桶裡的！」","(D) 「你進來待產時已經有灌腸過，去上廁所應該不會有大便才對。」"],"answer":1,"image":""},{"id":"nr4-113-2-12","subject":"nr4","topic":"產科-產後照護","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"下列何者為阻礙產後婦女子宮復舊的因素？①產程延長 ②正常羊水量之單胞胎 ③漲滿的膀胱 ④純母乳親餵","options":["(A) 僅①③","(B) ①④","(C) ①②③","(D) ②③④"],"answer":0,"image":""},{"id":"nr4-113-2-13","subject":"nr4","topic":"產科-產後照護","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"有關產後情緒低落（postpartum blues）的定義及敘述，下列何者正確？","options":["(A) 會嚴重影響日常的生活功能","(B) 會影響社會功能","(C) 通常可自行復原","(D) 若情緒低落持續一週則診斷為產後憂鬱"],"answer":2,"image":""},{"id":"nr4-113-2-14","subject":"nr4","topic":"產科-產後照護","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"有關乳腺炎（mastitis）的敘述，下列何者錯誤？","options":["(A) 最常見的致病菌為金黃色葡萄球菌（Staphylococcus aureus）","(B) 應該暫停哺乳，避免嬰兒受到感染","(C) 哺乳頻率突然減少時，可能是導因","(D) 婦女可能會發燒到38.4～40℃"],"answer":1,"image":""},{"id":"nr4-113-2-15","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"護理師進入病室時發現新生兒哭泣，產婦表示：「我都等寶寶哭，確定寶寶餓了，然後再餵奶。」下列何項護理指導最適當？","options":["(A) 母乳易消化，固定每2～3小時餵奶可以避免寶寶飢餓","(B) 寶寶有轉頭、舌頭伸出、吸吮動作出現就可以準備餵奶了","(C) 哭是飢餓的徵象，等寶寶大哭後再餵會吃比較多","(D) 如果寶寶哭，要先安撫，讓寶寶先睡，等醒來再餵"],"answer":1,"image":""},{"id":"nr4-113-2-16","subject":"nr4","topic":"婦科-婦女健康","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"下列何種情況適合裝置子宮內避孕器？","options":["(A) 不明原因的陰道出血者","(B) 月經週期不規則者","(C) 月經過多者","(D) 痛經厲害者"],"answer":1,"image":""},{"id":"nr4-113-2-17","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"陳小弟出生第二天，執行親子同室。陳小弟若出現下列何種狀況，護理師應進一步評估？","options":["(A) 整天尿布都沒有濕","(B) 半夜醒來二次","(C) 大便為綠色","(D) 哭的時候沒有眼淚"],"answer":0,"image":""},{"id":"nr4-113-2-18","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"有關新生兒過渡期執行即刻母嬰肌膚接觸的敘述，下列何者為最佳時機及其理由？","options":["(A) 相對不反應期，新生兒較能專注在母親身上","(B) 第一反應期，新生兒清醒且吸吮反射強","(C) 第二反應期，新生兒安靜不哭鬧","(D) 絕對反應期，新生兒能快速回應母親的呼喚"],"answer":1,"image":""},{"id":"nr4-113-2-19","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"有關正確含乳（suckling）的表徵，下列敘述何者不適當？","options":["(A) 嬰兒口腔由下往上不對稱（asymmetric）含住一大口乳房組織","(B) 嬰兒上下唇如魚嘴般，尤其是下唇外翻","(C) 嬰兒嘴巴張得很大且兩頰飽滿","(D) 嬰兒吸吮與吞嚥頻率，平穩地維持1：1，約一秒一次"],"answer":3,"image":""},{"id":"nr4-113-2-20","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"有關羊水栓塞（amniotic fluid embolism）之相關敘述，下列何者錯誤？","options":["(A) 呈現病理性收縮環","(B) 通常發生在分娩時或分娩剛結束","(C) 常發生於羊膜破水後","(D) 易出現心肺功能衰竭和休克"],"answer":0,"image":""},{"id":"nr4-113-2-21","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"初產婦34歲，妊娠38週胎兒發育符合妊娠週數，因破水入院後24小時仍無宮縮，予以評估子宮頸成熟度，發現其子宮頸擴張＜1公分，子宮頸變薄30%，無法觸診到胎兒的先露部位，子宮頸位置在後方且堅硬。依據上述情境，若採Bishop計分法評估，以決定後續相關處置，下列敘述何者較適當？","options":["(A) 得分為6分，適用催生針劑靜脈滴注催產","(B) 子宮頸已成熟，適用前列腺素針劑靜脈滴注催產","(C) 得分為0分，適用前列腺素陰道塞劑促子宮頸成熟","(D) 子宮頸不成熟，可繼續觀察48小時，若無產兆且確定無感染則可返家待產"],"answer":2,"image":""},{"id":"nr4-113-2-22","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"下列那些為重度子癇前症的危險徵候和症狀？①嚴重頭痛 ②視力模糊 ③4小時尿量為400mL ④血清肌酐酸持續下降","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①④"],"answer":0,"image":""},{"id":"nr4-113-2-23","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"林女士，若進行第一階段50gm葡萄糖耐性試驗篩檢妊娠糖尿病，下列那些敘述正確？①建議於懷孕20～22週篩檢 ②建議於懷孕24～28週篩檢 ③篩檢前需禁食，空腹抽血 ④1小時後的血糖值大於140 mg/dL，則需進一步檢查","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":3,"image":""},{"id":"nr4-113-2-24","subject":"nr4","topic":"婦科-婦女健康","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"有關人類乳突病毒（human papillomavirus, HPV）之敘述，下列何者錯誤？","options":["(A) 主要經由性行為而傳染","(B) 免疫力正常的年輕女性感染後通常能夠自行痊癒","(C) HPV 6與11型屬於致癌型","(D) HPV疫苗對於未曾有過性行為或未受到HPV感染者最有效"],"answer":2,"image":""},{"id":"nr4-113-2-25","subject":"nr4","topic":"婦科-婦女健康","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"劉女士卵巢癌分期IIIC，本週接受減積手術，劉女士表示自己不再是完整的女人也擔心影響夫妻間的性生活，下列護理師之回應何者較不恰當？","options":["(A) 告訴劉女士現階段應該全心配合治療，不要負面思考","(B) 鼓勵劉女士與先生溝通，了解彼此的感受與疑慮","(C) 解釋術後可能出現更年期症狀，行房時可加長前戲時間來改善陰道乾澀不適","(D) 徵得同意後介紹卵巢癌病友給劉女士，以促進術後正向調適"],"answer":0,"image":""},{"id":"nr4-113-2-26","subject":"nr4","topic":"兒科-生長發展","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"1歲3個月的幼兒通常可通過動作發展之項目，下列敘述何者較適當？","options":["(A) 能踏動三輪車","(B) 可單腳跳躍","(C) 可獨自行走","(D) 會堆疊九塊積木"],"answer":2,"image":""},{"id":"nr4-113-2-27","subject":"nr4","topic":"兒科-意外事故與急症","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"陳小妹在媽媽的麵店玩耍，不小心撞到端著熱湯的媽媽，左手臂被燙傷，燙傷部分表皮皮膚微紅且出現水泡，當下立即處理何者最適當？","options":["(A) 趕快帶陳小妹去沖冷水至少沖15～30分鐘","(B) 立即去冰箱拿冰塊做局部冰敷","(C) 給予燙傷藥膏塗抹傷口","(D) 用無菌針頭將燒傷水泡戳破"],"answer":0,"image":""},{"id":"nr4-113-2-28","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"有關自閉症（autistic disorder）兒童的照護，下列敘述何者最適當？","options":["(A) 喜歡身體接觸的感覺，多擁抱可增進人際互動","(B) 隨時調整生活常規，培養適應能力","(C) 設計變化多端的環境，增加感官刺激","(D) 隨時維持安全的環境，防範意外或自我傷害"],"answer":3,"image":""},{"id":"nr4-113-2-29","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"奇奇，2歲，因為住院而出現分離焦慮，為了協助奇奇宣洩負向情緒，下列何種治療性遊戲較合適？","options":["(A) 木槌敲紙箱","(B) 使用布偶進行戲劇性遊戲","(C) 把玩聽診器","(D) 玩扮家家酒"],"answer":0,"image":""},{"id":"nr4-113-2-30","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"張小妹，1歲，因發燒入院，護理師欲進行生命徵象測量，有關生命徵象測量相關護理，下列何者最適切？","options":["(A) 壓脈帶的寬度應覆蓋過測量肢體長度的1/2","(B) 觀察腹部起伏測量10秒鐘，並乘以六","(C) 於左鎖骨中線第三～四肋間測量心尖脈","(D) 耳溫測量時，應將耳朵向上向後拉"],"answer":2,"image":""},{"id":"nr4-113-2-31","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"有關厭食症的敘述，下列何者錯誤？","options":["(A) 好發於青少年期，女性多","(B) 厭食症的女性易造成經血過多，經期過短的問題","(C) 病童對身體形象知覺錯誤現象","(D) 運用認知行為治療及心理治療等，修正病童不良飲食行為"],"answer":1,"image":""},{"id":"nr4-113-2-32","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"有關新生兒身體評估結果，下列何者需進一步追蹤評估？","options":["(A) 出生身長45～55公分","(B) 出生頭圍40～42公分","(C) 新生兒兩眼瞳孔間距3.5～4公分","(D) 視力範圍20公分（8英吋）以內"],"answer":1,"image":""},{"id":"nr4-113-2-33","subject":"nr4","topic":"兒科-高危險新生兒","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"劉小弟，30週又2天早產兒，於新生兒加護病房接受治療，強化親子依附關係的行為，下列敘述何者較適當？","options":["(A) 說明醫療團隊專業能力很強，雙親可放心","(B) 避免回答雙親對使用醫療儀器的疑問","(C) 劉小弟病情穩定時，鼓勵雙親參與照顧","(D) 嚴格遵守訪客規定，限制雙親探視以預防感染"],"answer":2,"image":""},{"id":"nr4-113-2-34","subject":"nr4","topic":"兒科-高危險新生兒","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"有關早產兒常發生的問題，下列敘述何者錯誤？","options":["(A) 腦室內出血是因腦室周圍原生質（germinal matrix）部位血管較脆弱易破裂所導致","(B) 視網膜病變是因血氧過低或過高，使不成熟的視網膜血管收縮導致缺血","(C) 壞死性腸炎的主因是腸胃道生理結構與消化功能不成熟","(D) 呼吸窘迫症候群是因缺乏表面張力素造成肺擴張不全"],"answer":2,"image":""},{"id":"nr4-113-2-35","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"有關病童死亡時，支持其家人哀傷的護理措施，下列敘述何者較為適當？","options":["(A) 避免手足探訪，以免擔心害怕","(B) 提醒家庭成員勿表達自己的感情，避免彼此煩惱","(C) 營造讓病童的家人有時間與其獨處","(D) 強調痛苦的悲傷情緒，通常持續不到一年"],"answer":2,"image":""},{"id":"nr4-113-2-36","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"有關高膽紅素血症新生兒的護理措施，下列何者最適當？","options":["(A) 可即早餵食，使膽紅素正常排泄","(B) 應每4小時翻身一次，以增加照光的持續效果","(C) 照光時光源距離皮膚最佳的距離為30～45公分","(D) 出現黃疸時，立即暫停哺餵母乳"],"answer":0,"image":""},{"id":"nr4-113-2-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"有關日本腦炎的症狀與處置，下列敘述何者錯誤？","options":["(A) 傳播媒介為三斑家蚊為主","(B) 黃昏時刻避免至戶外，以防病媒蚊叮咬","(C) 預防感染需要隔離病患的血液和分泌物","(D) 前驅期會出現頭痛、倦怠的症狀"],"answer":2,"image":""},{"id":"nr4-113-2-38","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"為病童執行抽吸（suction）技術時，下列護理處置何者最適當？","options":["(A) 新生兒宜先抽鼻腔再抽口腔","(B) 抽吸前將生理食鹽水滴入氣管內管","(C) 嬰幼兒抽痰壓力應在110～120 mmHg","(D) 早產兒抽吸時間宜在6～8秒"],"answer":3,"image":""},{"id":"nr4-113-2-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"有關細菌性肺炎（bacterial pneumonia）敘述，下列何者正確？","options":["(A) 傳染性高，須採呼吸道隔離","(B) 聽診出現哮鳴音（stridor）","(C) 痰液量多且黏稠","(D) 體溫正常或輕微上升"],"answer":2,"image":""},{"id":"nr4-113-2-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"小光，3個月大，診斷為法洛氏四重畸形，在矯正手術前，依醫囑給與prostaglandin E1（PGE1）的理由，下列敘述何者正確？","options":["(A) 使動脈導管維持開放，增加主動脈的血量","(B) 使動脈導管維持開放，增加肺動脈的血量","(C) 使動脈導管儘早關閉，減少肺動脈的壓力","(D) 使動脈導管儘早關閉，減少主動脈的壓力"],"answer":1,"image":""},{"id":"nr4-113-2-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"下列何者為急性淋巴性白血病最有效之鑑別診斷？","options":["(A) 血液檢查","(B) 骨髓抽吸檢查","(C) 淋巴組織切片檢查","(D) 腦脊髓液檢查"],"answer":1,"image":""},{"id":"nr4-113-2-42","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"有關扁桃腺切除（tonsillectomy）術後飲食之護理指導，下列敘述何者適當？","options":["(A) 可喝西瓜汁或番茄汁","(B) 可喝檸檬汁或柳橙汁","(C) 可吃布丁或冰淇淋","(D) 可喝無糖綠茶及咖啡"],"answer":2,"image":""},{"id":"nr4-113-2-43","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"小琪，女嬰，新生兒篩檢診斷為先天性腎上腺增生症（congenital adrenal hyperplasia, CAH），護理師提供給小琪父母的護理指導，下列敘述何者最不適當？","options":["(A) 教導父母觀察小琪有無脫水情形","(B) 若小琪合併醛固酮不足，應減少飲食的鹽分","(C) 確實監測小琪的身高和體重的變化","(D) 需要按時讓小琪服用皮質醇（cortisone）"],"answer":1,"image":""},{"id":"nr4-113-2-44","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"有關白血病病童接受化學治療期間，依醫囑注射Rasburicase及Allopurinol的目的，下列敘述何者正確？","options":["(A) 預防卡氏肺囊蟲肺炎","(B) 預防腫瘤溶解症候群造成高尿酸血症","(C) 預防中樞神經系統白血病的復發","(D) 治療念珠菌感染引起的鵝口瘡"],"answer":1,"image":""},{"id":"nr4-113-2-45","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"有關病童放置鼻胃管之護理照護，下列敘述何者較適當？","options":["(A) 鼻胃管插入長度為由鼻尖至耳垂之直線距離","(B) 測試放置正確與否，可將鼻胃管末端浸入水中需出現氣泡","(C) 鼻胃管灌食的總量，不需考慮殘餘量","(D) 管灌結束後宜採右側半坐臥或坐姿，頭部抬高30度"],"answer":3,"image":""},{"id":"nr4-113-2-46","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"王小美，5歲，罹患巨結腸症（megacolon），進行腸道無神經節部位切除，有關術後之護理措施與指導，下列敘述何者錯誤？","options":["(A) 定時評估其疼痛型態，必要時依醫囑給與止痛劑","(B) 教導並協助定時翻身，以預防肺炎或肺部擴張不全","(C) 術後觀察肛門狹窄及糞便失禁合併症","(D) 提供高纖飲食以促進早期排便"],"answer":3,"image":""},{"id":"nr4-113-2-47","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"有關疫苗接種對象的敘述，下列何者最適當？","options":["(A) 兒癌病童化療期間不宜接種水痘疫苗","(B) 體重2,000公克以上之新生兒，可接種卡介苗","(C) 靜脈注射免疫球蛋白的兒童需隔4週後才能接種疫苗","(D) 活性疫苗可接種於後天免疫缺乏症候群兒童"],"answer":0,"image":""},{"id":"nr4-113-2-48","subject":"nr4","topic":"兒科-生長發展","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"小妍，14歲，被診斷為脊柱側彎（scoliosis），有關疾病特性和臨床表徵，下列敘述何者錯誤？","options":["(A) 彎腰時，雙側背部呈現明顯的突峰","(B) 站立時二邊肩膀高度不一","(C) 可用Cobb氏量角法評估脊柱側彎的嚴重度","(D) 骨盆傾斜"],"answer":0,"image":""},{"id":"nr4-113-2-49","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"有關嬰幼兒呼吸系統解剖生理特徵，下列何者正確？","options":["(A) 嬰幼兒肺泡數量較少，胸廓較小，因此年齡越小呼吸速率越慢","(B) 嬰幼兒的氣管較成人短，分叉處較高，比成人較易造成吸入性肺炎","(C) 耳咽管較成人短、窄、呈垂直，細菌易進入耳咽管，引發中耳炎","(D) 嬰幼兒肋骨位置較成人呈垂直，胸肋骨支持穩定性較小，採胸式呼吸"],"answer":1,"image":""},{"id":"nr4-113-2-50","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"有關癲癇兒童接受生酮飲食療法，下列敘述何者正確？","options":["(A) 提供高脂肪、高蛋白及低醣飲食","(B) 需要增加液體攝取，有助於酮的生成","(C) 酮（ketones）可製造較多的穩定性神經傳導物質，具有鎮定效果","(D) 多數用於抗癲癇藥物治療效果良好的兒童"],"answer":2,"image":""},{"id":"nr4-113-3-1","subject":"nr4","topic":"婦科-婦女健康","meta":"113年第3次第1題","year":113,"session":3,"number":1,"question":"有關我國目前優生保健法中的人工流產之相關規定與法則，下列敘述何者正確？","options":["(A) 有配偶之婦女若因懷孕或生產將影響其心理健康，而自願實施人工流產者，不須告知配偶，即可實施人工流產","(B) 若符合法令規定之適用對象且無身體異常情形，可以使用Mifepristone-RU486施行人工流產","(C) 16歲以上之未婚婦女依相關規定實施人工流產，不須經過法定代理人同意即可實施","(D) 因配偶之四親等以內之血親患有礙優生之遺傳疾病者，而自願實施人工流產者，須告知配偶，方可實施人工流產"],"answer":1,"image":""},{"id":"nr4-113-3-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第3次第2題","year":113,"session":3,"number":2,"question":"李女士24歲，G1P0，現懷孕32週，產檢皆正常。主訴頻尿但無灼熱感，睡覺平躺時很容易頭暈、心悸。詢問護理師原因，下列回應何者最恰當？","options":["(A) 懷孕頻尿和頭暈很正常，小心一點就可以了","(B) 頻尿是目前常見的症狀，不要憋尿；睡覺頭暈、心悸可能跟姿勢有關，試試側睡","(C) 頻尿是泌尿道感染，要注意會陰部清潔；頭暈、心悸可能是貧血，多吃深綠色蔬菜","(D) 頻尿是泌尿道感染，頭暈是貧血，等會告訴醫師檢查一下"],"answer":1,"image":""},{"id":"nr4-113-3-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第3次第3題","year":113,"session":3,"number":3,"question":"林女士，G1P0，懷孕14週，今天產檢時的主訴如下，下列那一項較不符合目前的生理變化？","options":["(A) 最近常覺得有心悸","(B) 感覺寶寶在睡前活動較多","(C) 噁心嘔吐感好像比較少了","(D) 懷孕前的褲子扣子都扣不上了"],"answer":1,"image":""},{"id":"nr4-113-3-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第3次第4題","year":113,"session":3,"number":4,"question":"王女士，懷孕16週，有關產檢報告結果，下列何者需最優先給予衛教？","options":["(A) 尿糖陰性","(B) 尿蛋白微量","(C) 德國麻疹IgG陰性","(D) B型肝炎HBsAg陰性"],"answer":2,"image":""},{"id":"nr4-113-3-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第3次第5題","year":113,"session":3,"number":5,"question":"阮氏女士，懷孕32週，有關胎動監測之護理指導，下列何者不適當？","options":["(A) 每天同一時間測量，兩小時內至少有10次胎動","(B) 胎動比昨天的次數少一半是不正常","(C) 飯前或空腹時比較容易有明顯胎動","(D) 觀察時雙手可以放在腹部觸摸感受"],"answer":2,"image":""},{"id":"nr4-113-3-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"113年第3次第6題","year":113,"session":3,"number":6,"question":"第三孕期婦女抱怨下肢腫脹，傍晚時鞋子就穿不下，下列護理指導何者不適當？","options":["(A) 可穿舒適軟質包鞋","(B) 穿著及膝彈性襪","(C) 可做足背屈曲運動","(D) 臥床休息時，採左側臥"],"answer":1,"image":""},{"id":"nr4-113-3-7","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第3次第7題","year":113,"session":3,"number":7,"question":"王女士，G1P0，妊娠39週，因規則陣痛入院待產，護理紀錄上寫著「Effacement：50%」，其代表的意思為何？","options":["(A) 子宮頸變薄程度達50%","(B) 胎心音變異性達50%","(C) 胎頭下降進入骨盆腔50%","(D) 胎兒內轉已完成50%"],"answer":0,"image":""},{"id":"nr4-113-3-8","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第3次第8題","year":113,"session":3,"number":8,"question":"潘女士，G1P0，懷孕41週，因規則陣痛而入院待產，胎位為左枕前位（LOA），未接受硬脊膜外麻醉。現因宮縮強且密集，陰道內診發現子宮頸已擴張完全，胎兒高度+2。在此情境下，下列敘述何者不適當？","options":["(A) 臉部顯得潮紅，陰道口看到的現血量增加","(B) 宮縮時，出現不自主向下用力的動作","(C) 胎心音在母體左邊髂骨前上棘與肚臍連線的中點附近最清楚","(D) 胎心率在宮縮開始時變慢，在宮縮高峰時達到最低點，宮縮結束又恢復正常"],"answer":2,"image":""},{"id":"nr4-113-3-9","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第3次第9題","year":113,"session":3,"number":9,"question":"第二產程中所應用的呼吸型式中，能減少因胎兒娩出時所致會陰或產道撕裂傷，下列何項最不適當？","options":["(A) 吹蠟燭呼吸法","(B) 屏氣10秒向下用力","(C) 開聲門用力","(D) 緩慢哈氣呼吸"],"answer":1,"image":""},{"id":"nr4-113-3-10","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第3次第10題","year":113,"session":3,"number":10,"question":"徐女士30歲，G2P1，懷孕35週。因在家感覺子宮規則收縮疼痛，故入院。檢查發現每隔10分鐘宮縮一次，持續30秒，強度40mmHg，內診子宮頸口開4公分，70%變薄，胎位為臀位，主訴有很多水從陰道流出。護理師最優先的照護措施為下列何者？","options":["(A) 立刻通知超音波室","(B) 給予靜脈輸液","(C) 監測胎兒心跳速率","(D) 準備進行催生"],"answer":2,"image":""},{"id":"nr4-113-3-11","subject":"nr4","topic":"婦科-婦女健康","meta":"113年第3次第11題","year":113,"session":3,"number":11,"question":"有關治療子宮內膜異位症的藥物，下列何者錯誤？","options":["(A) 排卵藥","(B) 含黃體素的口服避孕藥","(C) 雄性素衍生荷爾蒙，如：Danazol","(D) 促性腺激素釋放荷爾蒙類似物（GnRH Analogs）"],"answer":0,"image":""},{"id":"nr4-113-3-12","subject":"nr4","topic":"產科-產後照護","meta":"113年第3次第12題","year":113,"session":3,"number":12,"question":"有關產後憂鬱症（postpartum depression）的敘述，下列何者錯誤？","options":["(A) 持續支持並協助順利哺餵母乳有利於改善症狀","(B) 症狀常在產後4週出現，且症狀持續超過2週","(C) 可能與面臨經濟壓力與家事照顧問題有關","(D) 可能與產後動情素、黃體素濃度突然上升有關"],"answer":3,"image":""},{"id":"nr4-113-3-13","subject":"nr4","topic":"產科-產後照護","meta":"113年第3次第13題","year":113,"session":3,"number":13,"question":"有關哺乳期各種避孕法，下列敘述何者錯誤？","options":["(A) 非荷爾蒙作用之避孕措施，不會影響泌乳，可以安全使用","(B) 單一雌性素的荷爾蒙避孕藥不會影響乳汁分泌，適合選用","(C) 雌性素及黃體素之混合型避孕藥，可能減少奶量，不建議使用","(D) 如果不再有生育的計畫，輸精管結紮是永久避孕的首選"],"answer":1,"image":""},{"id":"nr4-113-3-14","subject":"nr4","topic":"產科-產後照護","meta":"113年第3次第14題","year":113,"session":3,"number":14,"question":"吳女士陰道生產，產後第3天表示：「坐著哺乳我的腰很痠」，下列何種產後運動最適合教導？","options":["(A) 凱格爾氏運動（Kegel’s exercise）","(B) 骨盆搖擺運動","(C) 下肢抬腿運動","(D) 仰臥起坐"],"answer":1,"image":""},{"id":"nr4-113-3-15","subject":"nr4","topic":"產科-產後照護","meta":"113年第3次第15題","year":113,"session":3,"number":15,"question":"王女士，初產婦，陰道生產，採純母乳哺育，產後6週重返職場的一週後，因發燒乳房紅腫熱痛求診，診斷為乳腺炎。下列的護理措施何者不適當？","options":["(A) 改善發紅部位的乳房引流","(B) 進行完整的哺乳史評估，並去除可能的導因","(C) 給予症狀照護，包括：餵奶前服用止痛藥，或餵奶後冰敷止痛","(D) 立即協助乳汁培養並立即進行完整抗生素治療"],"answer":3,"image":""},{"id":"nr4-113-3-16","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第3次第16題","year":113,"session":3,"number":16,"question":"有關胎盤早期剝離之敘述，下列何者錯誤？","options":["(A) 需要密切觀察胎心音","(B) 易呈現高張力宮縮","(C) 可能合併症為瀰漫性血管內凝血（DIC）","(D) 為無痛性的陰道出血"],"answer":3,"image":""},{"id":"nr4-113-3-17","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第3次第17題","year":113,"session":3,"number":17,"question":"護理人員使用新貝拉（NewBallardScore）量表，進行四位出生第3小時的新生兒成熟度評估，下列那位新生兒可能為早產兒？","options":["(A) 王小弟，方形窗徵象角度為0°，手臂反彈角度為60°","(B) 林小妹，膝膕間角度為140°，全身胎毛豐富","(C) 黃小弟，圍巾徵象手肘不能越過同側乳房中線，乳暈突起且直徑5 mm","(D) 洪小妹，足底前2/3有皺褶，皮膚乾燥看不見血管"],"answer":1,"image":""},{"id":"nr4-113-3-18","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第3次第18題","year":113,"session":3,"number":18,"question":"有關新生兒篩檢的敘述，下列何者正確？","options":["(A) 採血時間為新生兒出生後滿12小時","(B) 穿刺部位應選擇足跟的外面兩側","(C) 血量不足時，應用力擠壓穿刺部位以利血液流出","(D) 為減少新生兒的疼痛，應使用注射針頭進行採檢"],"answer":1,"image":""},{"id":"nr4-113-3-19","subject":"nr4","topic":"產科-新生兒護理","meta":"113年第3次第19題","year":113,"session":3,"number":19,"question":"下列何項護理措施較無法改善新生兒溢奶的狀況？","options":["(A) 餵食採漸進式奶量增加","(B) 餵食後協助排氣","(C) 餵食後採左側臥","(D) 避免過度餵食"],"answer":2,"image":""},{"id":"nr4-113-3-20","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第3次第20題","year":113,"session":3,"number":20,"question":"下列何種情況易導致待產婦女發生子宮內翻（Uterine Inversion）？①娩出胎盤時過度牽引臍帶 ②過早注射Methergin ③在子宮底施加壓力（fundal pressure） ④胎盤早期剝離","options":["(A) ①②","(B) ①③","(C) ③④","(D) ②④"],"answer":1,"image":""},{"id":"nr4-113-3-21","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第3次第21題","year":113,"session":3,"number":21,"question":"林女士，入院待產，醫師內診時發現臍帶脫垂，下列處置何者錯誤？","options":["(A) 將脫出的臍帶再推回子宮內","(B) 使用無菌生理食鹽水紗布覆蓋","(C) 若子宮頸尚未完全擴張，緊急剖腹生產","(D) 戴無菌手套從陰道將先露部位往上頂"],"answer":0,"image":""},{"id":"nr4-113-3-22","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第3次第22題","year":113,"session":3,"number":22,"question":"待產婦女於生產過程中發生肩難產（shoulder dystocia）時，下列處置何者為宜？①教導待產婦快速屈曲大腿靠向腹部 ②於子宮底施壓 ③加強子宮收縮藥劑量 ④注意胎心音變化","options":["(A) ①③","(B) ②③","(C) ②④","(D) ①④"],"answer":3,"image":""},{"id":"nr4-113-3-23","subject":"nr4","topic":"產科-高危險妊娠","meta":"113年第3次第23題","year":113,"session":3,"number":23,"question":"重度子癇前症孕婦之飲食指導，下列建議何者最適當？","options":["(A) 高蛋白質低鈉飲食","(B) 低蛋白質低鈉飲食","(C) 低蛋白質高鈉飲食","(D) 高蛋白質高鈉飲食"],"answer":0,"image":""},{"id":"nr4-113-3-24","subject":"nr4","topic":"產科-待產與分娩","meta":"113年第3次第24題","year":113,"session":3,"number":24,"question":"護理師從胎兒監測器得知，胎兒心跳100次／分，持續80秒，其型態與宮縮沒有一定關係，此胎心率型態為：","options":["(A) 胎心率正常","(B) 變異性減速","(C) 早發性減速","(D) 晚發性減速"],"answer":1,"image":""},{"id":"nr4-113-3-25","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"113年第3次第25題","year":113,"session":3,"number":25,"question":"毛女士接受人工受精治療後懷孕併多胞胎妊娠，將接受減胎術，毛女士表示很擔心嬰靈會對自己有不好的影響，下列護理師之回應何者最適當？","options":["(A) 嬰靈說法無科學根據，減胎是不得不的決定","(B) 衛教多胞胎的早產風險，告訴毛女士她是以大局為重","(C) 詢問毛女士的宗教信仰，鼓勵毛女士說出對嬰靈的看法","(D) 請毛女士不要胡思亂想，為了腹中胎兒她要往前看"],"answer":2,"image":""},{"id":"nr4-113-3-26","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第3次第26題","year":113,"session":3,"number":26,"question":"合併唇裂（cleft lip）與腭裂（cleft palate）嬰幼兒之手術前護理措施，下列敘述何者最適當？","options":["(A) 餵食時，使用孔洞小的奶嘴，避免吞食過多空氣","(B) 以鼻胃管餵食，避免使用口腔唇舌肌肉，擴大唇裂與腭裂之裂縫","(C) 餵食時，採平躺姿勢，利於吞嚥，避免奶水溢出","(D) 餵食時，餵食器放於口腔內後方或臉頰內側面，避免奶水進鼻腔內"],"answer":3,"image":""},{"id":"nr4-113-3-27","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"113年第3次第27題","year":113,"session":3,"number":27,"question":"關於自閉症兒童的敘述，下列何者錯誤？","options":["(A) 出現孤立的人際互動，缺乏目光接觸","(B) 對環境改變很敏感，須儘量維持一致性","(C) 難以接受改變的僵化思考模式","(D) 用luminal治療疾病，須服用6～8週後效果佳"],"answer":3,"image":""},{"id":"nr4-113-3-28","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第3次第28題","year":113,"session":3,"number":28,"question":"有關成骨不全（osteogenesis imperfecta）的相關敘述，下列何者錯誤？","options":["(A) 藍色鞏膜為典型症狀之一","(B) 可能會喪失聽力","(C) 需要限制任何活動","(D) 四肢極短且彎曲呈弓形、肌肉張力減退"],"answer":2,"image":""},{"id":"nr4-113-3-29","subject":"nr4","topic":"兒科-生長發展","meta":"113年第3次第29題","year":113,"session":3,"number":29,"question":"小華會把樂高分享給小美，兩人會交換玩具，但各玩各的，是屬於兒童遊戲發展那一個階段？","options":["(A) 合作遊戲","(B) 聯合遊戲","(C) 平行遊戲","(D) 旁觀遊戲"],"answer":2,"image":""},{"id":"nr4-113-3-30","subject":"nr4","topic":"兒科-生長發展","meta":"113年第3次第30題","year":113,"session":3,"number":30,"question":"關於9歲學齡期兒童的發展及生長，下列敘述何者最適當？","options":["(A) 喜歡模仿成人行為","(B) 有質量保留的概念","(C) 可以做抽象思考","(D) 對男女生殖器感到好奇"],"answer":1,"image":""},{"id":"nr4-113-3-31","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"113年第3次第31題","year":113,"session":3,"number":31,"question":"一瓶nystatin懸浮液為100,000 units/mL，兒童罹患鵝口瘡需要一天四次服用，每次給予250,000 units，請問應給予幾mL？","options":["(A) 1.5","(B) 2.0","(C) 2.5","(D) 3.0"],"answer":2,"image":""},{"id":"nr4-113-3-32","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"113年第3次第32題","year":113,"session":3,"number":32,"question":"3歲的小杰生病住進了加護病房第4天，小杰顯得安靜、沉默以及對病房的事物不感興趣，其分離焦慮是處於那個時期？","options":["(A) 抗議期（protest）","(B) 失望期（despair）","(C) 去依戀期（detachment）","(D) 過渡期（transition）"],"answer":1,"image":""},{"id":"nr4-113-3-33","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第3次第33題","year":113,"session":3,"number":33,"question":"有關壞死性結腸炎（necrotizing enterocolitis）的敘述，下列何者正確？","options":["(A) 腸黏膜壞死後，以革蘭氏陽性菌最常侵犯腸壁","(B) 常侵犯部位是在幽門附近及小腸近端處","(C) 引起的原因是腸黏膜缺血缺氧","(D) 優先採取的處置是以鼻胃管餵食半奶的嬰兒配方奶"],"answer":2,"image":""},{"id":"nr4-113-3-34","subject":"nr4","topic":"兒科-高危險新生兒","meta":"113年第3次第34題","year":113,"session":3,"number":34,"question":"楊小妹，妊娠週數31週，出生體重1,628公克，有關楊小妹出生後的生理特徵，下列敘述何者錯誤？","options":["(A) 腎小管再吸收功能差，會出現蛋白尿及尿糖","(B) 凝血因子不足與維生素K低下，易出現凝血功能不良","(C) 乳糖消化能力尚未成熟，會有暫時性乳糖吸收不良症","(D) 肺泡表面張力素分泌不足，容易出現持續性肺動脈高壓"],"answer":3,"image":""},{"id":"nr4-113-3-35","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"113年第3次第35題","year":113,"session":3,"number":35,"question":"7歲的小雄，面對爺爺過世，小雄一直吵著媽媽說爺爺在睡覺，要去找爺爺說話。有關和小雄談論死亡的敘述，下列何者不適當？","options":["(A) 鼓勵小雄說出心裡的話和問題","(B) 正確的向小雄描述死亡的狀態和事實","(C) 避免讓小雄參加喪禮","(D) 利用日常經驗或影片認識死亡"],"answer":2,"image":""},{"id":"nr4-113-3-36","subject":"nr4","topic":"兒科-高危險新生兒","meta":"113年第3次第36題","year":113,"session":3,"number":36,"question":"有關新生兒胎便吸入症候群的症狀及處置之敘述，下列何者錯誤？","options":["(A) 皮膚、指甲，或臍帶有胎便沾染痕跡","(B) 可能發生呼吸窘迫的症狀","(C) 羊水有胎便，嬰兒娩出後，立即以甦醒球（ambu bag）加壓刺激呼吸","(D) 動脈血液氣體分析顯示呼吸衰竭，需矯正呼吸性酸中毒"],"answer":2,"image":""},{"id":"nr4-113-3-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"113年第3次第37題","year":113,"session":3,"number":37,"question":"有關嬰兒玫瑰疹（roseola）的評估，下列敘述何者錯誤？","options":["(A) 會出現突然的高燒且持續3～5天左右","(B) 枕下／耳後的淋巴結可能有腫大的情形","(C) 軀幹先出現散發性的玫瑰紅斑點","(D) 發疹期間大約會持續1週以上才消退"],"answer":3,"image":""},{"id":"nr4-113-3-38","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第3次第38題","year":113,"session":3,"number":38,"question":"有關病童接受氧氣治療的照護措施，下列敘述何者最適當？","options":["(A) 以氧氣濃度分析儀上的感應器測量氧氣濃度時，病童的口鼻處為最佳部位","(B) 使用氧氣頭罩時，氧氣流速最好小於3 L/min，避免二氧化碳滯留","(C) 鼻套管管徑較小，氧氣流速宜在10 L/min以上，以免氧氣濃度不足","(D) 使用氧氣帳的目的包括讓病童與他人隔離以避免傳染"],"answer":0,"image":""},{"id":"nr4-113-3-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第3次第39題","year":113,"session":3,"number":39,"question":"10歲的連小妹持續乾咳多日，有輕微發燒，胸部X光檢查發現兩側下肺葉呈現間質性浸潤，痰中的單核白血球上升，且家中的雙胞胎妹妹也曾有類似的症狀，下列何者為連小妹罹患肺炎最可能的致病因子？","options":["(A) 金黃色葡萄球菌","(B) 肺炎鏈球菌","(C) 黴漿菌","(D) b型嗜血桿菌"],"answer":2,"image":""},{"id":"nr4-113-3-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第3次第40題","year":113,"session":3,"number":40,"question":"2歲的王小弟罹患先天性心臟病，以毛地黃（digoxin）治療，一天服用兩次。下列敘述何者正確？","options":["(A) 餐後半小時內服用藥物","(B) 可與牛奶或果汁一起服用","(C) 若忘了服用藥物，六小時內可以補給原劑量","(D) 給藥後需測量心尖脈"],"answer":2,"image":""},{"id":"nr4-113-3-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第3次第41題","year":113,"session":3,"number":41,"question":"6歲的小強因不明原因的貧血而入院，欲進行骨髓抽吸術（bone marrow aspiration），下列處置及護理措施何者錯誤？","options":["(A) 此年紀穿刺部位以近側脛骨優先","(B) 穿刺後傷口應以紗布覆蓋加壓至少15分鐘以防出血","(C) 術前評估小強是否有出血異常或服用凝血相關藥物","(D) 穿刺後1小時內需密切監測生命徵象及傷口出血情形"],"answer":0,"image":""},{"id":"nr4-113-3-42","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第3次第42題","year":113,"session":3,"number":42,"question":"有關預防腫瘤溶解症候群（tumor lysis syndrome）所進行的相關處置，下列敘述何者錯誤？","options":["(A) 持續監測尿糖","(B) 化學治療前大量給水","(C) 依醫囑按時服用allopurinol","(D) 靜脈輸液加入碳酸氫鈉"],"answer":0,"image":""},{"id":"nr4-113-3-43","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"113年第3次第43題","year":113,"session":3,"number":43,"question":"3歲的小萱出現發燒、臉色蒼白、腹痛，經醫師確診為神經母細胞瘤第三期，有關提供父母的護理指導，下列敘述何者不適當？","options":["(A) 神經母細胞瘤出現的症狀與壓迫部位有關","(B) 因腫瘤已超過身體中線，手術已無法完全切除","(C) 需抽血監測兒茶酚胺（catecholamine）以確認是否轉移","(D) 骨髓檢查是要確認小萱骨髓是否受到侵犯"],"answer":2,"image":""},{"id":"nr4-113-3-44","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第3次第44題","year":113,"session":3,"number":44,"question":"有關甲狀腺功能亢進（hyperthyroidism）的照護措施，下列敘述何者最不適當？","options":["(A) 配合病童代謝率增加的需求，可準備高熱量飲食","(B) 不可隨便停藥，以防病童產生甲狀腺危象","(C) 觀察病童體溫過低的症狀和徵象","(D) 病童注意力不集中，宜安排在安靜環境中學習"],"answer":2,"image":""},{"id":"nr4-113-3-45","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第3次第45題","year":113,"session":3,"number":45,"question":"有關乳糜或粥樣瀉（celiac disease）的敘述，下列何者正確？","options":["(A) 是自體免疫疾病，對麩質無法耐受所造成的腸病變","(B) 飲食治療以穀類與麥類為主，並適時補充維生素C","(C) 無腹痛，但解血絲便","(D) 使用廣效型抗生素以減輕腸道發炎情形"],"answer":0,"image":""},{"id":"nr4-113-3-46","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第3次第46題","year":113,"session":3,"number":46,"question":"有關排尿性膀胱尿道攝影（voiding cystoureterography,VCUG）的敘述，下列何者最適當？","options":["(A) 檢查目的為評估病童尿液逆流的嚴重程度","(B) 檢查前應進行小量灌腸以幫助影像判讀","(C) 檢查前鼓勵病童多喝水，有助於攝影的進行","(D) 檢查過程無使用顯影劑，檢查後讓病童自然排尿即可"],"answer":0,"image":""},{"id":"nr4-113-3-47","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"113年第3次第47題","year":113,"session":3,"number":47,"question":"有關人工肛門造瘻口之術後護理指導，下列何者較適當？","options":["(A) 當造瘻口流出大量水樣引流物時，表示功能正常","(B) 術後三週內採低渣飲食，減少腸蠕動","(C) 術後造瘻口一般外觀應呈深黑色且表面乾燥","(D) 乙狀結腸造口糞便多呈液狀"],"answer":1,"image":""},{"id":"nr4-113-3-48","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第3次第48題","year":113,"session":3,"number":48,"question":"7歲的奇奇罹患腦性麻痺，因基底核和錐體外病變，產生不自主運動，且出現無法控制四肢抖動，尤其影響手部的書寫功能，有關奇奇罹患之腦性麻痺的型態，下列何者正確？","options":["(A) 痙攣型（spastic）","(B) 運動失調型（ataxic）","(C) 手足徐動型（athetoid type）","(D) 無張力型（atonic）"],"answer":2,"image":""},{"id":"nr4-113-3-49","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"113年第3次第49題","year":113,"session":3,"number":49,"question":"10歲的曉華罹患頑固型癲癇，醫生建議以生酮飲食治療，下列何者正確？","options":["(A) 高蛋白質、低醣類","(B) 高脂肪、低醣類","(C) 高醣類、高蛋白質","(D) 高纖維質、低脂肪"],"answer":1,"image":""},{"id":"nr4-113-3-50","subject":"nr4","topic":"兒科-生長發展","meta":"113年第3次第50題","year":113,"session":3,"number":50,"question":"有關單側性發展性髖關節發育不良（developmental hip dysplasia, DDH）病童的臨床表徵，下列何者錯誤？","options":["(A) 病童的臀部及大腿皮膚皺褶左右不對稱","(B) 患肢單腿站立時，健肢髖部的高度會向下傾斜","(C) 仰臥，將髖部曲折成90度時，健肢膝部會降低","(D) 患肢腿屈曲做外展運動時，會出現卡嗒（click）聲"],"answer":2,"image":""},{"id":"nr4-114-1-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"有關婦嬰生命統計資料的敘述，下列何者錯誤？","options":["(A) 粗出生率係指一年內每千位人口的平均活產數","(B) 總生育率係指每年每千位育齡婦女合計生育的子女數","(C) 台灣使用總生育率作為衡量人口生育水準的標準","(D) 開發中的國家，其粗出生率往往較低"],"answer":3,"image":""},{"id":"nr4-114-1-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"護理師為妊娠32週的趙女士進行腹部四段式觸診，下列敘述何者最適當？","options":["(A) 檢查前請趙女士喝很多水以漲滿膀胱","(B) 第四段觸診時應面向趙女士以評估胎兒背部","(C) 觸診子宮底型態感覺硬、圓、光滑則為胎兒臀部","(D) 觸診腹部兩側感覺較硬及平滑面為胎兒背部"],"answer":3,"image":""},{"id":"nr4-114-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"陳女士月經週期規律，偶睡前服用鎮靜劑，因月經過期10天，自行購買驗孕棒進行妊娠試驗，下列敘述何者正確？","options":["(A) 太早進行驗孕，驗孕棒結果不準確","(B) 驗孕棒原理是以聯酶法（ELISA）檢測尿液中hCG濃度","(C) 以睡前中段尿液檢測，可得較準確的結果","(D) 服用鎮靜劑可能導致假陰性反應"],"answer":1,"image":""},{"id":"nr4-114-1-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"懷孕32週婦女，當有人經過其身旁時，會不由自主用雙手護住肚子，下列何者最能形容其孕期的母性任務行為？","options":["(A) 確保與他人的社會互動之距離","(B) 確認自己身體外觀的變化","(C) 關注自己身體功能的運作","(D) 關注自己身體界限的完整"],"answer":3,"image":""},{"id":"nr4-114-1-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"懷孕28週婦女，詢問有關懷孕期自我會陰按摩方法，下列護理指導何者不適當？","options":["(A) 可於預產期前6週開始執行","(B) 採一腳跨踩於椅子上進行會陰按摩","(C) 將手指塗抹潤滑油，放入陰道約5公分","(D) 以拇指按壓陰道，向上按壓，並往兩側推"],"answer":3,"image":""},{"id":"nr4-114-1-6","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"下列何項血液檢驗值，可以用來篩檢孕婦是否為海洋性貧血帶因者？","options":["(A) 血色素（Hb）","(B) 平均紅血球體積（MCV）","(C) ++ 鐵離子（Fe）","(D) α-胎兒蛋白（α-AFP）"],"answer":1,"image":""},{"id":"nr4-114-1-7","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"有關待產婦因過度產痛所引起的不良生理變化，下列敘述何者錯誤？","options":["(A) 伴隨產痛的過度換氣，將造成待產婦出現定向感障礙、感覺異常及四肢痙攣","(B) 產痛將增加待產婦自主神經活性，減少胎盤血液灌流，增加胎兒呼吸性酸中毒的危險","(C) 產程過程中激烈產痛，易產生壓力反應，增加抗利尿激素分泌","(D) 待產過程出現過度換氣，增加待產婦呼吸性酸中毒的發生"],"answer":3,"image":""},{"id":"nr4-114-1-8","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"有關吸入性麻醉藥（inhalation anesthesia），下列敘述何者錯誤？","options":["(A) 屬於全身麻醉劑，其中一氧化二氮（N2O），為無色無味氣體，俗稱笑氣","(B) 易影響子宮收縮，造成產程延長及產後大出血，增加生產過程的危險","(C) 為水溶性麻醉劑，容易過胎盤進入胎兒體內，抑制新生兒的神經反射","(D) 需注意麻醉劑量濃度及避免吸入後引起待產婦嘔吐"],"answer":2,"image":""},{"id":"nr4-114-1-9","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"汪女士，生產過程未行會陰切開。胎盤娩出後，檢查發現會陰皮膚及陰道黏膜有撕裂，但未裂至肌肉層。此情況應記錄為會陰部撕裂傷幾度？","options":["(A) 第一度","(B) 第二度","(C) 第三度","(D) 第四度"],"answer":0,"image":""},{"id":"nr4-114-1-10","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"林女士，G1P0，懷孕41週，因自然破水及規則陣痛到院檢查，陰道內診子宮頸已擴張2公分，宮縮時疼痛分數為2分（0-10分量表）故協助辦理住院待產。林女士此時最可能出現下列何種行為反應？","options":["(A) 興奮話多，樂意分享產兆發生過程","(B) 顯得疲累且擔心自己的身體失去控制","(C) 大多閉眼休息，宮縮不適時，儘量維持身體不動","(D) 身心能量都集中在應付宮縮上，常以單字回應問題"],"answer":0,"image":""},{"id":"nr4-114-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"有關生產疼痛理論與緩解措施之敘述，下列何者正確？","options":["(A) 按撫法（effleurage）對強度疼痛的減痛效果明顯","(B) 骶骨重壓法可減輕下背部疼痛","(C) 生產球適合高危險妊娠婦女使用","(D) 按撫法的原理是依據制約理論"],"answer":1,"image":""},{"id":"nr4-114-1-12","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"有關鼓勵孕產家庭與家中新成員－新生兒的依附關係的建立，下列敘述何者錯誤？","options":["(A) 除了兩歲以下的小孩外，鼓勵所有家人共同參與新生兒照護","(B) 產後婦女的身體與心理調適，都可能會影響依附關係之建立","(C) 親子同室有助於家人參與育兒照護工作，也提供新生兒適應日後的生活環境","(D) 鼓勵父親及家人一起參與親子同室，可以儘早接觸及認識新生兒"],"answer":0,"image":""},{"id":"nr4-114-1-13","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"林女士，G1P1，剖腹生產後一週，主訴全身發熱不舒服，身體檢查沒有明顯身體其他部位疼痛情況。若是此發熱不適與子宮復舊有關，下列何者為最可能的子宮復舊評估結果？","options":["(A) 腹部觸診時，約在下腹部，接近恥骨聯合處觸摸到子宮底","(B) 按摩後子宮硬度及大小有如棒球","(C) 觸診子宮時，會有壓迫感，但不會明顯疼痛不適","(D) 子宮底位於肚臍下五橫指，惡露呈暗咖啡色帶有臭味"],"answer":3,"image":""},{"id":"nr4-114-1-14","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"下列何者最適合採用泌乳期無月經法（LAM）作為避孕方法？","options":["(A) 純母乳哺育，嬰兒3個月大，產後第一次月經剛剛結束","(B) 純母乳哺育，嬰兒4個月大，產後月經尚未恢復","(C) 主要以母乳哺育，夜裡偶而添加1～2次配方奶，嬰兒3個月大，產後月經尚未恢復","(D) 混合哺餵，嬰兒3個月大，產後月經尚未恢復"],"answer":1,"image":""},{"id":"nr4-114-1-15","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"有關產後惡露評估，下列敘述何者為正常生理現象？","options":["(A) 產後第2天，惡露呈鮮紅色且無血塊，有惡臭味","(B) 產後第3天，惡露呈深紅色微量血塊，有血腥味","(C) 產後第5天，惡露呈淡乳黃色無血塊，有血腥味","(D) 產後第12天，惡露呈暗棕色無血塊，無血腥味"],"answer":1,"image":""},{"id":"nr4-114-1-16","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"有關哺餵母乳的好處，下列敘述何者正確？","options":["(A) 哺乳可刺激腦下垂體前葉釋放泌乳激素（prolactin）促使子宮收縮","(B) 白天餵奶可以抑制濾泡刺激素（follicle stimulating hormone, FSH）的分泌而避孕","(C) 哺乳期間母親需要增加熱量及其他營養素的攝取，因此體重增加比餵配方奶者多","(D) 哺乳的母親在停經前罹患乳癌或卵巢癌的機率較低"],"answer":3,"image":""},{"id":"nr4-114-1-17","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"有關預防尿布疹的措施，下列何者最適當？","options":["(A) 包裹新的尿布前需使用痱子粉保持皮膚乾爽","(B) 溫水清潔後使用酒精消毒皮膚降低細菌孳生","(C) 大小便後以溫水清洗再用清潔的布拭乾","(D) 改餵配方奶以減少排便次數"],"answer":2,"image":""},{"id":"nr4-114-1-18","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"沐浴前將新生兒置於有磅秤紙的體重計進行體重量測，沐浴後以乾毛巾迅速擦乾其身體，此乃運用下列那些預防體熱喪失的機制？","options":["(A) 對流及蒸發","(B) 傳導及蒸發","(C) 傳導及輻射","(D) 對流及輻射"],"answer":1,"image":""},{"id":"nr4-114-1-19","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"採純母乳哺餵之健康新生兒出生體重為3,900公克，出生第三天體重降為3,700公克，父母非常擔憂該新生兒體重降低的狀況，此時最適合的護理指導為何？","options":["(A) 三天內體重減輕200公克可能與新生兒腸胃道吸收功能不佳有關，需要請醫師檢查","(B) 出生前幾日的體重減輕可能與生理性黃疸有關，應該要立即抽血檢查","(C) 三天內體重減輕200公克與母乳分泌不足有關，教導母親應多喝水與多食用高蛋白食物","(D) 此為正常新生兒生理性體重流失現象，增加哺餵次數體重會慢慢恢復，不必太過擔憂"],"answer":3,"image":""},{"id":"nr4-114-1-20","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"王女士使用催產素引產，胎兒監測器呈現宮縮頻率及持續時間為60\" /1'30\" -2'，宮縮時壓力100 mmHg，子宮頸口一直停留在4公分，胎心音為135～150 bpm，下列何者為最優先處置？","options":["(A) 鼓勵待產婦下床走動","(B) 停止催產素注射","(C) 採右側臥姿勢","(D) 準備緊急剖腹產"],"answer":1,"image":""},{"id":"nr4-114-1-21","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"林女士待產時突然主訴腹部呈撕裂性疼痛，護理師評估腹部有一明顯凹陷，無法測到宮縮和胎心音，此情境最可能為？","options":["(A) 低張性子宮收縮","(B) 早期破水","(C) 子宮破裂","(D) 羊水栓塞"],"answer":2,"image":""},{"id":"nr4-114-1-22","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"有關產後血栓性靜脈炎之敘述，下列何者正確？","options":["(A) 產後血小板及凝血因子數量增加是其主因","(B) 長期服用口服避孕藥婦女較不易發生","(C) 待產期出汗脫水而造成血液濃稠是其主因","(D) 孕期水腫婦女較易發生"],"answer":0,"image":""},{"id":"nr4-114-1-23","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"王女士，30歲，G1P1，有妊娠期糖尿病，有關產後的避孕護理指導，下列何者較為合適？","options":["(A) 子宮內避孕器","(B) 口服避孕藥","(C) 輸卵管結紮","(D) 保險套"],"answer":3,"image":""},{"id":"nr4-114-1-24","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"在已開發國家中會以那些措施預防愛滋病的母子垂直感染？①妊娠期接受完整的抗愛滋病毒藥物治療 ②採剖腹生產 ③新生兒給與預防性口服抗愛滋病毒藥物 ④分娩前母親血中病毒量＜400 copies/mL者方可哺餵母乳","options":["(A) 僅①②","(B) 僅③④","(C) ①②③","(D) ①②④"],"answer":2,"image":""},{"id":"nr4-114-1-25","subject":"nr4","topic":"產科-產後照護","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"吳女士，25歲，罹患淋病（gonorrhea），下列產後護理措施何者適當？","options":["(A) 指導其性生活可以繼續，但頻率要減少","(B) 教導執行自我陰道灌洗技術","(C) 收集子宮頸口分泌物進行細菌培養","(D) 使用2% tetracycline藥膏預防新生兒眼疾發生"],"answer":2,"image":""},{"id":"nr4-114-1-26","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"兒童急救的生命之鏈（pediatric chain of survival）有五個環環相扣的重要程序，第一步驟為何？","options":["(A) 預防傷害發生","(B) 儘早心肺復甦術","(C) 儘早高級醫療照護","(D) 啟動緊急救護系統"],"answer":0,"image":""},{"id":"nr4-114-1-27","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"有關兒童遭受虐待的護理處置，下列敘述何者錯誤？","options":["(A) 儘速將受虐者與施虐者隔離，避免兒童繼續遭受虐待","(B) 受虐者須與父母一起接受問診確認事情發生過程，不能分開會談","(C) 執行醫療照護時，需注意受虐兒童隱私問題","(D) 得知父母親缺乏支持系統，加上經濟壓力，應儘快提供社會資源"],"answer":1,"image":""},{"id":"nr4-114-1-28","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"護理師提供父母親對自閉症兒童的照護指導，下列敘述何者不適當？","options":["(A) 可增加居家環境的改變，刺激其認知學習","(B) 行為症狀會持續至成人期","(C) 使用抗思慮障礙劑或中樞神經活化劑等藥物，以減輕症狀","(D) 多於幼兒期即被發現，宜即早安排接受早期療育"],"answer":0,"image":""},{"id":"nr4-114-1-29","subject":"nr4","topic":"兒科-生長發展","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"10個月大新生兒進行身體檢查仍會有的反射項目，下列何者最為正確？","options":["(A) 驚嚇反射（startle reflex）","(B) 手掌抓握反射（palmar grasp reflex）","(C) 踏步反射（stepping reflex）","(D) 巴賓斯基氏反射（Babinski’s reflex）"],"answer":3,"image":""},{"id":"nr4-114-1-30","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"有關兒童使用眼藥的注意事項，下列敘述何者正確？","options":["(A) 將眼藥膏塗抹於下眼瞼結膜上","(B) 將眼藥水滴於下眼瞼結膜外側","(C) 給藥時請兒童頭後仰且往下看","(D) 醫囑O.D.是指雙眼給藥"],"answer":0,"image":""},{"id":"nr4-114-1-31","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"小婷，14歲，因罹患全身性紅斑性狼瘡（systemic lupus erythematosus, SLE）住院進行脈衝治療（pulse therapy），護理師提供的照護措施，下列何者不適當？","options":["(A) 住院期間，鼓勵其與同儕保持聯繫","(B) 告知疾病和治療對身體外觀影響不大，以減輕其不安","(C) 評估疼痛的程度，避免因隱瞞而疏忽對其疼痛的處理","(D) 注意傾聽並提供支持，避免評論"],"answer":1,"image":""},{"id":"nr4-114-1-32","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"下列何者不屬於FLACC行為疼痛評估量表的向度？","options":["(A) 臉部表情","(B) 活動力","(C) 安撫","(D) 呼吸型態"],"answer":3,"image":""},{"id":"nr4-114-1-33","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"罹患第一型糖尿病兒童的照護趨勢，專業人員運用賦權（empowerment）在以家庭為中心照護的目的，下列何者較適當？","options":["(A) 父母參與孩子的每一項治療與檢查的過程","(B) 父母減少孩子與社區的互動，避免被污名化","(C) 避免談論慢性疾病的存在，促使生活正常化","(D) 專業人員提供諮商輔導，增進父母對治癒有信心"],"answer":0,"image":""},{"id":"nr4-114-1-34","subject":"nr4","topic":"兒科-高危險新生兒","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"吳小妹，妊娠31週又2天出生，出生體重1,698公克，吳太太至新生兒加護中心探視吳小妹，下列護理處置何者錯誤？","options":["(A) 說明早產兒特性及身上的使用設備","(B) 安排及示範吳太太學習早產兒照護技巧","(C) 鼓勵吳太太執行袋鼠護理","(D) 告知吳太太減少觸摸吳小妹，以避免過多刺激及感染"],"answer":3,"image":""},{"id":"nr4-114-1-35","subject":"nr4","topic":"兒科-生長發展","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"依據皮亞傑（Piaget）的認知發展理論，有關3〜5歲學齡前期兒童的死亡概念，下列敘述何者正確？","options":["(A) 不了解死亡，缺乏死亡概念","(B) 死亡如同睡覺，會醒過來","(C) 人死無法復活，唯獨壞人才會死亡","(D) 人死不能復生，人人都會面臨死亡"],"answer":1,"image":""},{"id":"nr4-114-1-36","subject":"nr4","topic":"兒科-高危險新生兒","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"簡小妹為35週出生的早產兒，體重2,400公克，被診斷有高膽紅素血症（hyperbilirubinemia），今抽血所得總膽紅素值（total bilirubin）為26 mg/dL，有關換血治療的護理，下列敘述何者正確？","options":["(A) 換血後2小時由靜脈滴注25% albumin（1 gm/kg），預防核黃疸","(B) 協助醫師放置導管插入臍動脈，或橈動脈、股動脈","(C) 每換200 mL的血液，需注射10％葡萄糖溶液2 mL","(D) 換血後需追蹤總膽紅素值，觀察期間繼續照光治療"],"answer":3,"image":""},{"id":"nr4-114-1-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"小英，6個月，出現輕微發燒、食慾不振、喉嚨痛、耳後及後頸部淋巴結腫大等症狀。他先在臉部出現粉紅色斑丘疹，再漫延至頸部、手臂、軀幹，而後逐漸往下肢發展，但疹子出現3天即消除。小英最可能感染下列何種疾病？","options":["(A) 麻疹（measles）","(B) 德國麻疹（rubella）","(C) 嬰兒玫瑰疹（roseola infantum）","(D) 感染型紅斑（erythema infectiosum）"],"answer":1,"image":""},{"id":"nr4-114-1-38","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"使用氧氣頭罩（O2 hood）之照護措施，下列敘述何者最不適當？","options":["(A) 氧氣流速大於5～6 L/min，可防CO2滯留","(B) 潮濕瓶與蛇行管宜每週更換一次","(C) 避免直接吹到病童臉上以減少體熱喪失","(D) 以生理食鹽水作為噴霧來源效果更好"],"answer":3,"image":""},{"id":"nr4-114-1-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"有關黴漿菌性肺炎（mycoplasma pneumonia）之敘述，下列何者正確？","options":["(A) 常見的呼吸音為肋膜摩擦音","(B) 主要由肺炎雙球菌引起，導致黏膜水腫","(C) 咳嗽明顯常伴有痰音，痰液黏稠、黃綠色且量多","(D) 使用藥物為erythromycin或azithromycin"],"answer":3,"image":""},{"id":"nr4-114-1-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"小強，5歲，長期服用毛地黃（digoxin）之護理指導，下列敘述何者最適當？","options":["(A) 若服藥前測量一分鐘心跳低於90次則暫停服藥一次","(B) 建議與其他食物混合餵食，以利藥物吸收","(C) 若使用利尿劑（Lasix），避免香蕉、深綠色蔬菜等含鉀高之食物","(D) 於服藥時間後4小時發現忘記服藥應補服"],"answer":3,"image":""},{"id":"nr4-114-1-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"有關海洋性貧血兒童使用排鐵劑（deferoxamine）治療，下列敘述何者錯誤？","options":["(A) 排鐵過程尿液會呈現紅色或橘紅色","(B) 適應的年齡為5～7歲，因遵從性會更好","(C) 排鐵過程需補充維他命C","(D) 可以皮下注射，宜在晚間執行"],"answer":1,"image":""},{"id":"nr4-114-1-42","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"有關苯酮尿症（phenylketonuria）之護理指導，下列何者錯誤？","options":["(A) 為體染色體隱性遺傳的疾病，會遺傳給下一代","(B) 禁餵母奶，須餵食低苯胺基丙酸（如：lofenalac）或不含苯丙胺酸（如：phenyl-free）之配方奶","(C) 飲食須富含蛋白質食物，避免產生神經系統後遺症","(D) 不治療會有髮色淡黃、霉臭味尿液、智力不足症狀"],"answer":2,"image":""},{"id":"nr4-114-1-43","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"有關初診斷白血病的臨床表徵，下列敘述何者最適當？","options":["(A) 血壓下降、心律不整","(B) 呼吸困難、臉潮紅","(C) 發燒、疲憊","(D) 腹痛、少尿"],"answer":2,"image":""},{"id":"nr4-114-1-44","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"小雄，3歲，罹患威爾姆氏腫瘤（Wilms tumor）第三期，有關護理照護，下列敘述何者錯誤？","options":["(A) 提醒父母、家人和相關醫療人員，應避免觸診小雄的腹部","(B) 主要治療方式包含腎臟切除術、化學治療以及放射線治療","(C) 3小雄白血球低於1,000 /mm，採取保護性隔離避免感染","(D) 放射線治療主要採全身性治療，避免腫瘤擴散"],"answer":3,"image":""},{"id":"nr4-114-1-45","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"有關急性腎絲球腎炎（acute glomerulonephritis）病童的照護措施，下列敘述何者最適當？","options":["(A) 牛奶及香蕉在少尿期，不需特別限制","(B) 急性期鼓勵多下床活動，減輕水腫","(C) 血尿素氮（BUN）達100 mg/dL，須採高蛋白飲食","(D) 維持正常體液，兒童排尿量須達1～2 mL/kg/hr"],"answer":3,"image":""},{"id":"nr4-114-1-46","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"莉莉，4個月，此次因唇裂（cleft lip）住院，醫師安排進行唇裂修補術，在手術後的照護，下列敘述何者較適當？","options":["(A) 鼓勵採俯臥，以預防呼吸道阻塞","(B) 向家屬解釋病童手術後出現不斷吞嚥動作是術後正常的現象","(C) 術後疼痛哭鬧，給與安撫奶嘴使用以降低疼痛","(D) 須給與適時約束手肘，以避免摩擦臉部影響傷口癒合"],"answer":3,"image":""},{"id":"nr4-114-1-47","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"小敏，8歲，因為長期嚴重便秘而入院檢查，檢查後發現大量大便堆積腸道，欲執行大量灌腸。有關大量灌腸的護理指導，下列敘述何者最不適當？","options":["(A) o大量灌腸溶液的溫度，以30～36C左右較合適","(B) 可以利用遊戲、故事或娃娃模型示範解釋灌腸的目的與步驟","(C) 灌腸中如出現臉色蒼白、冒冷汗、心跳加快應停止，並通知醫師","(D) 協助病童採左側臥，右膝屈曲的姿勢"],"answer":0,"image":""},{"id":"nr4-114-1-48","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"芷妹，9歲，因頭痛、發燒就醫，診斷為病毒性腦膜炎（virus meningitis）入院治療，有關此疾病相關症狀和治療，下列敘述何者錯誤？","options":["(A) 最主要的治療是儘早給與抗生素","(B) 大部分由腸病毒及腮腺炎病毒引起","(C) 腦脊髓液外觀通常清澈","(D) 少有神經功能障礙後遺症"],"answer":0,"image":""},{"id":"nr4-114-1-49","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"張小弟，10歲，診斷為裘馨氏肌失養症（Duchenne muscular dystrophy），有關病因和臨床表徵，下列敘述何者錯誤？","options":["(A) 體染色體隱性遺傳疾病","(B) 蹲下拿東西，無力獨自站起來","(C) 直立時明顯腰椎前彎","(D) 小腿肚（腓腸肌）假性肥大"],"answer":0,"image":""},{"id":"nr4-114-1-50","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"小美，15個月大，從樓梯跌落導致頭部受傷，急診護理師依據兒童適用之葛氏昏迷量表（Glasgow coma scale, GCS）評估其意識程度，結果顯示叫他時會睜眼，雖會哭泣但可安撫，輕觸其手臂會收縮反應，請問小美的昏迷指數為幾分？","options":["(A) 7分","(B) 9分","(C) 12分","(D) 15分"],"answer":2,"image":""},{"id":"nr4-114-2-1","subject":"nr4","topic":"婦科-婦女健康","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"下列何者最能反映當代育齡婦女的平均生育力？","options":["(A) 粗出生率","(B) 總生育率","(C) 周產期生育率","(D) 孕產婦生育率"],"answer":1,"image":""},{"id":"nr4-114-2-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"下列何者為懷孕的確實徵候？","options":["(A) 清晨起床時感到噁心與嘔吐","(B) 觸診時有發現子宮峽部變軟","(C) 超音波檢查看見妊娠囊","(D) hCG妊娠試驗呈陽性"],"answer":2,"image":""},{"id":"nr4-114-2-3","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"下列何者是胎兒第一個有功能的器官？","options":["(A) 心臟","(B) 肺臟","(C) 腎臟","(D) 脾臟"],"answer":0,"image":""},{"id":"nr4-114-2-4","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"懷孕10週婦女，以超音波評估胎兒大小，下列測量部位何者最適當？","options":["(A) 雙頂徑","(B) 胎兒腹圍","(C) 頭臀徑","(D) 股骨長度"],"answer":2,"image":""},{"id":"nr4-114-2-5","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"有關胎兒生長過程的敘述，下列何者正確？","options":["(A) 胎血循環的三個通道使大多數血液避免進入腎臟","(B) 懷孕第12週外生殖器官可以清楚分辨性別","(C) 胎兒唯一可以自行製造的免疫球蛋白是IgM","(D) 妊娠第34週胎兒肺臟開始製造表面張力素，防止肺泡塌陷"],"answer":1,"image":""},{"id":"nr4-114-2-6","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"護理師為32週的李女士執行無壓力試驗（Non-stress test, NST），結果為30分鐘內有5次以上胎動，胎心率基準線由130 bpm上升至150 bpm，伴隨每次胎動，胎心率增加20次，且持續20秒以上，下列何者為其判讀結果？","options":["(A) 反應型；正常","(B) 不反應型；不正常","(C) 陽性；正常","(D) 陰性；不正常"],"answer":0,"image":""},{"id":"nr4-114-2-7","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"王女士，G1P0，已待產13小時，目前子宮頸口開8公分，呼吸急促，每次宮縮時皆以手拍打床面，身體呈現精疲力竭、情緒失控、出汗等現象，下列護理措施何者正確？","options":["(A) 協助王女士開始平躺用力","(B) 以手指伸入陰道促進子宮頸擴張","(C) 請她不要拍打床面以保持情緒穩定","(D) 請王女士跟著手勢調整呼吸"],"answer":3,"image":""},{"id":"nr4-114-2-8","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"王女士，G1P0，懷孕39週，胎位為LOA，目前已進入第二產程，胎頭已著冠。此階段，護理師應將杜卜勒（Doppler）置於王女士腹部何處最有機會聽診到清楚的胎心音？","options":["(A) 肚臍和右側髂骨前上棘連線中間","(B) 肚臍和左側髂骨前上棘連線中間","(C) 恥骨聯合上緣","(D) 肚臍下緣"],"answer":2,"image":""},{"id":"nr4-114-2-9","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"周女士，G1P0，懷孕39週。兩小時前由配偶陪同入院待產，目前腹部上裝著電子胎兒監測器臥床休息中。配偶指著機器上的胎心率紀錄紙，問：「這要怎麼看？」。以臺灣目前最常使用的方式為例，下列的說明內容，何者最不適當？","options":["(A) 上面的這條曲線是代表寶寶的心跳次數","(B) 下面的這條曲線是代表太太子宮收縮的情形","(C) 可監測宮縮時胎兒心率的變化來評估胎兒健康","(D) 機器設定每分鐘跑1公分寬時，每一小格代表1分鐘"],"answer":3,"image":""},{"id":"nr4-114-2-10","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"有關第二產程的產痛來源，下列何者錯誤？","options":["(A) 下段子宮肌肉伸展","(B) 宮縮時子宮肌肉缺氧","(C) 胎兒先露部位壓迫產婦臀部","(D) 會陰肌肉的伸展擴張"],"answer":0,"image":""},{"id":"nr4-114-2-11","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"郭女士，懷孕39週。主訴：「自今天凌晨1點開始陸續出現陣痛，有時半小時，有時20分鐘痛一次，不太規則。大概從半夜3點開始，宮縮變得規則且明顯，大約5分鐘一次」。早上6點因子宮頸口開3公分且3～4分鐘宮縮一次而入院待產。下午3點子宮頸口完全擴張（10公分）。下午4點10分陰道娩出一健康女嬰。下午4點20分胎盤娩出。請問郭女士此次生產第一產程時間應記錄為何？","options":["(A) 12小時00分鐘","(B) 13小時10分鐘","(C) 14小時00分鐘","(D) 15小時20分鐘"],"answer":0,"image":""},{"id":"nr4-114-2-12","subject":"nr4","topic":"產科-產後照護","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"吳女士，G1P1，剖腹產後第2天，詢問：「我肚子脹脹的、不舒服，可以不要下床嗎？」下列護理措施何者最適當？","options":["(A) 收集吳太太不想下床的原因，依醫囑給予止痛藥","(B) 給予漸進式飲食指導，可等待腹脹改善後再下床","(C) 告知吳女士先暫時禁食，待傷口檢查後再行決定是否下床","(D) 進行腸道評估，鼓勵下床活動來緩解腹脹不適"],"answer":3,"image":""},{"id":"nr4-114-2-13","subject":"nr4","topic":"產科-產後照護","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"有關親子同室（rooming-in）的敘述，下列何者錯誤？","options":["(A) 護理師應依不同家庭有不同需求，彈性安排親子同室，以滿足每個家庭的需求","(B) 世界衛生組織建議產後母親與嬰兒不應該分開，每天24小時都應該相處在同一房間","(C) 親子同室是以家庭為中心的一種照護","(D) 執行親子同室主要目的為減輕護理師的負擔"],"answer":3,"image":""},{"id":"nr4-114-2-14","subject":"nr4","topic":"產科-產後照護","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"有關產婦執行凱格爾氏運動（Kegel’s exercise）的護理指導，下列何者錯誤？","options":["(A) 產後第一天開始，可重複多次執行","(B) 可採坐姿、站姿、躺姿進行","(C) 降低膀胱肌肉張力","(D) 預防壓力性尿失禁"],"answer":2,"image":""},{"id":"nr4-114-2-15","subject":"nr4","topic":"產科-產後照護","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"產婦產後第一次下床活動前，下列何者為最優先的護理評估？","options":["(A) 生命徵象","(B) 宮縮情況","(C) 血栓試驗","(D) 惡露性質"],"answer":0,"image":""},{"id":"nr4-114-2-16","subject":"nr4","topic":"產科-產後照護","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"陳女士，產後第三天，早上睡覺起來向護理師表示：「我的乳房變硬，摸起來熱熱的，但不會痛。」下列護理措施何者最適當？","options":["(A) 提供支持性胸衣","(B) 增加哺乳次數","(C) 塗消腫軟膏","(D) 教導牽引乳頭"],"answer":1,"image":""},{"id":"nr4-114-2-17","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"有關新生兒出生後一週內生理性體重減輕的常見原因，下列何者除外？","options":["(A) 無感性水分喪失","(B) 糞便及尿液的排出","(C) 剛出生吸奶量少","(D) 吐奶次數增加"],"answer":3,"image":""},{"id":"nr4-114-2-18","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"有關新生兒頭部評估，下列何者正確？","options":["(A) 頭血腫（cephalohematoma）通常會超過骨縫線，於出生12小時至數天可被吸收","(B) 產瘤（caput succedaneum）為骨膜與頭骨間微血管破裂後血液堆積的結果，不會超過骨縫線","(C) 胎頭變形（molding）為順應產道分娩而形成的頭骨重疊，約出生後數天或數週會恢復","(D) 前囟門呈菱形，約出生後12～18週關閉"],"answer":2,"image":""},{"id":"nr4-114-2-19","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"下列那些新生兒反射在長大後不會消失，持續一生都存在？①眨眼反射（blinking reflex） ②吸吮反射（sucking reflex） ③吞嚥反射（swallowing reflex） ④巴賓斯基反射（Babinski reflex） ⑤作嘔反射（gag reflex） ⑥擁抱反射（moro reflex）","options":["(A) ①③⑤","(B) ①⑤⑥","(C) ②③④","(D) ③④⑥"],"answer":0,"image":""},{"id":"nr4-114-2-20","subject":"nr4","topic":"兒科-高危險新生兒","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"有關妊娠糖尿病母親所產下新生兒的常見合併症，下列何者錯誤？","options":["(A) 低血糖","(B) 高血鈣","(C) 紅血球增多症","(D) 呼吸窘迫症候群"],"answer":1,"image":""},{"id":"nr4-114-2-21","subject":"nr4","topic":"產科-產後照護","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"王女士，產後第4天哺餵母乳中，左小腿出現明顯疼痛，靜脈血管攝影檢測後確診為深層血栓靜脈炎。有關身體評估與臨床處置的敘述，下列何者正確？","options":["(A) 出現呼吸困難、喘、胸痛、臉色蒼白，應懷疑為肺栓塞","(B) 建議多按壓及熱敷疼痛處以改善腿部疼痛","(C) 為降低產後出血，抗凝血劑治療至多兩週","(D) 宜服用Warfarin以避免血栓再度發生"],"answer":0,"image":""},{"id":"nr4-114-2-22","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"林女士第一胎，子宮頸口全開後，即使在無子宮收縮時，也可在會陰部看到胎兒頭髮，此現象稱為：","options":["(A) 胎頭固定","(B) 胎頭下降+2","(C) 著冠","(D) 屈曲"],"answer":2,"image":""},{"id":"nr4-114-2-23","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"有關妊娠高血壓婦女在預防產後大出血之護理措施，下列何者最不適當？","options":["(A) 注射Ergonovine","(B) 子宮按摩","(C) 測宮底位置及宮縮","(D) 監控惡露量與會陰傷口"],"answer":0,"image":""},{"id":"nr4-114-2-24","subject":"nr4","topic":"婦科-婦女健康","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"有關子宮內膜癌婦女接受全子宮切除術及放射線治療之護理，下列敘述何者不適當？","options":["(A) 陰道分泌物會增加，影響性生活","(B) 可使用水性潤滑劑減少陰道乾澀","(C) 鼓勵夫妻一起討論身體狀況的改變","(D) 一般手術後6個月內避免提重物"],"answer":0,"image":""},{"id":"nr4-114-2-25","subject":"nr4","topic":"婦科-婦女健康","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"有關更年期婦女荷爾蒙之變化，下列敘述何者正確？","options":["(A) 濾泡刺激素（FSH）分泌增加","(B) 黃體生成素（LH）分泌減少","(C) 雌性素（Estrogen）分泌增加","(D) 黃體素（Progesterone）分泌增加"],"answer":0,"image":""},{"id":"nr4-114-2-26","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"林同學，專科3年級生，1年前出現情緒低落、無助、悲傷，被診斷為青少年憂鬱症（adolescence’s depression），曾服用Fluoxetine及Paroxetine治療。近日因實習壓力大，導致失眠、企圖自我傷害。醫師表示憂鬱症復發，須接受治療。下列護理指導何者正確？","options":["(A) 藥物產生頭痛副作用時應暫停服用，避免影響實習成績","(B) 提供醣類、奶製品、魚油、蔬菜油及維生素食物","(C) 避免討論憂鬱症議題，減輕個案的不安與羞恥感","(D) 避免外界干擾，影響情緒起伏，儘量提供獨處空間"],"answer":1,"image":""},{"id":"nr4-114-2-27","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"一名1歲嬰兒誤食家用清潔劑，被家長緊急送至急診，經評估其呼吸穩定但持續流口水、咳嗽。下列護理處置何者較適當？","options":["(A) 立即給予大量溫開水催吐，以排出殘餘毒物","(B) 保持呼吸道通暢，持續觀察意識狀態","(C) 給予牛奶中和胃內毒物，以減少腐蝕性","(D) 給予吐根糖漿中和酸鹼"],"answer":1,"image":""},{"id":"nr4-114-2-28","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"當父母詢問是否該讓兒童施打流行性感冒疫苗時，護理師提供疫苗相關的實證依據以協助父母做為施打意願的參考。這是展現下列那一種護理人員角色功能？","options":["(A) 協調者與合作者","(B) 協助恢復兒童健康者","(C) 持續性健康照護提供者","(D) 預防保健照護者"],"answer":3,"image":""},{"id":"nr4-114-2-29","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"醫護人員為未滿1歲兒童執行心肺復甦術，下列敘述何者錯誤？","options":["(A) 按壓深度為胸部前後徑下壓約4公分","(B) 按壓部位兩乳頭連線中央之下方","(C) 壓胸時的速率為每分鐘60～80次","(D) 使用壓額抬下巴的方式暢通呼吸道"],"answer":2,"image":""},{"id":"nr4-114-2-30","subject":"nr4","topic":"兒科-生長發展","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"氣質評估可提供一個更全面了解個體差異的途徑，有關氣質評估之敘述，下列何者正確？","options":["(A) 反應閾低的嬰兒，尿布一點點濕就會哭鬧不安","(B) 反應強度高的嬰兒，容易受到外界干擾而影響","(C) 避性高的嬰兒，初次可以接受人事物的態度較好","(D) 慢吞吞型的孩子通常情緒本質較為正向"],"answer":0,"image":""},{"id":"nr4-114-2-31","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"有關嬰兒安全給藥原則之敘述，下列何者錯誤？","options":["(A) 口服給藥時，應將滴管置於舌頭兩側，以幫助吞嚥","(B) 肌肉注射時，應優先選擇腹臀肌，以免傷及坐骨神經","(C) 給予耳滴劑時，應將耳朵往下往後拉，以拉直耳道","(D) 鼻滴劑使用前，應回溫至室溫再給藥，以免刺激鼻黏膜"],"answer":1,"image":""},{"id":"nr4-114-2-32","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"小芬，6歲，罹患骨髓炎（osteomyelitis），有關護理措施，下列敘述何者不適當？","options":["(A) 指導家屬小芬出院後，需繼續口服抗生素的重要性","(B) 提供進食高熱量、高蛋白及富含維生素C飲食","(C) 評估傷口有無腫脹、發熱及觸痛","(D) 患肢不需固定，鼓勵多活動，以利手術傷口引流"],"answer":3,"image":""},{"id":"nr4-114-2-33","subject":"nr4","topic":"兒科-高危險新生兒","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"當早產兒出現「呼吸暫停」徵象，下列護理措施何者錯誤？","options":["(A) 給予觸覺刺激，例如輕彈足底","(B) 立即給予Ibuprofen以刺激呼吸","(C) 利用心電圖或是血氧機監測呼吸暫停的徵象","(D) 觀察呼吸暫停前後的改變，如膚色和肌肉張力"],"answer":1,"image":""},{"id":"nr4-114-2-34","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"孩子剛死亡，父母哀傷並哭泣。下列護理處置何者較不適當？","options":["(A) 同理父母的傷痛","(B) 根據父母的需求給予照護","(C) 陪伴與共在","(D) 轉移父母喪子的注意力"],"answer":3,"image":""},{"id":"nr4-114-2-35","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"有關早產兒身體外觀的特徵，下列敘述何者錯誤？","options":["(A) 皮膚缺乏皮下脂肪，顯得透明且易看到血管","(B) 耳翼邊緣軟骨未骨化，顯得扁平且易摺疊","(C) 腳底皮膚皺摺比足月兒多且清晰可見","(D) 27～28週時胎毛量最多，幾乎覆蓋整個體表"],"answer":2,"image":""},{"id":"nr4-114-2-36","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"進行腹部觸診時，發現腹脹且右上腹區可以觸摸到像橄欖樣狀腫塊，可判斷是何種疾病？","options":["(A) 糞便填塞","(B) 幽門狹窄","(C) 腸套疊","(D) 巨結腸症"],"answer":1,"image":""},{"id":"nr4-114-2-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"小禹，4歲，罹患腸病毒，現預計出院返家照護，護理師給予父母的居家照護指導，下列何者不適當？","options":["(A) 暫時不要上學，避免受他人感染其他疾病","(B) 糞便要馬上沖入馬桶，避免污染環境","(C) 家中幼兒仍要避免與小禹接觸","(D) 準備柔軟、口感佳的食物給小禹"],"answer":1,"image":""},{"id":"nr4-114-2-38","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"下列何種疫苗在國內常規接種時，主要建議採「皮下注射」？","options":["(A) 水痘疫苗","(B) 卡介苗","(C) B型肝炎疫苗","(D) 五合一疫苗"],"answer":0,"image":""},{"id":"nr4-114-2-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"小櫻，18個月大，因細支氣管炎（bronchiolitis）住院治療，對其疾病的相關敘述，下列何者最適當？","options":["(A) 主要為飛沫及接觸傳染","(B) 易出現吸氣喘鳴音（wheezing）","(C) 常見為肺炎鏈球菌感染","(D) 嚴重時會出現呼吸性鹼中毒"],"answer":0,"image":""},{"id":"nr4-114-2-40","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"王小妹，6個月，因熱性痙攣（febrile seizure）出現全身抽搐，王小妹的母親詢問護理師：「再出現全身抽搐時，該如何處置？」，下列護理指導何者最適當？","options":["(A) 協助採側臥姿勢，以利口腔分泌物流出","(B) 立即進行口對口鼻人工呼吸，避免缺氧","(C) 發作後，立即餵食抗痙攣藥，避免再次發作","(D) 發作時，約束肢體，避免碰撞物品造成傷害"],"answer":0,"image":""},{"id":"nr4-114-2-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"有關先天性心臟病病童的藥物護理，下列敘述何者錯誤？","options":["(A) 使用前列腺素E1（PGE1）需注意呼吸窘迫的問題","(B) 使用Propranolol（Inderal）需注意心跳過慢的問題","(C) 使用Digoxin如果心跳過慢可能是毒性反應","(D) 使用Spironolactone（Aldactone）可能造成血鉀過低"],"answer":3,"image":""},{"id":"nr4-114-2-42","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"小丁進行視力檢查，發現右眼有白色反光（貓眼反射），可能罹患下列何種疾病？","options":["(A) 白內障","(B) 神經母細胞瘤","(C) 結膜色素退化","(D) 視網膜母細胞瘤"],"answer":3,"image":""},{"id":"nr4-114-2-43","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"潘小弟，3歲，因為身體不適至醫院求治，經醫師診斷後確診為血友病，有關臨床表徵的敘述，下列何者正確？","options":["(A) 皮膚出現瘀血，刷牙時牙齦出血","(B) 臉色蒼白，呼吸快速或突然昏倒","(C) 易疲倦、食慾不振，身體易感染","(D) 皮膚出現黃疸現象，肝、脾腫大"],"answer":0,"image":""},{"id":"nr4-114-2-44","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"劉小妹，3歲，罹患急性淋巴性白血病，經過血液常規檢查發現，白血球：2,500/mm3，多型核白血球（segment）：8%，帶狀白血球（band）：10%，其絕對嗜中性白血球（absolut neutrophil count, ANC）是多少？","options":["(A) 300","(B) 350","(C) 400","(D) 450"],"answer":3,"image":""},{"id":"nr4-114-2-45","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"有關骨肉瘤（osterosarcoma）的症狀及治療，下列敘述何者錯誤？","options":["(A) 病童容易出現病理性骨折","(B) 白天疼痛感受較夜晚明顯","(C) 好發於青少年","(D) 惡性骨肉瘤常見於長骨"],"answer":1,"image":""},{"id":"nr4-114-2-46","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"有關新生兒先天性甲狀腺功能低下症（congenital hypothyroidism）的敘述，下列何者錯誤？","options":["(A) 可能與母親服用抗甲狀腺藥物有關","(B) 一出生即明顯可見四肢特別短小","(C) 儘量在2週內提供適量甲狀腺素","(D) 血液中甲狀腺刺激素（TSH）異常增高"],"answer":1,"image":""},{"id":"nr4-114-2-47","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"關於先天性食道閉鎖合併遠端氣管食道瘻管之新生兒術前護理措施，下列何者最適當？","options":["(A) 由鼻管餵食，以提供足夠熱量","(B) 禁止口咽抽吸分泌物，以防刺激嘔吐反射","(C) 頭部抬高45～60度，降低胃液逆流","(D) 避免吸奶嘴，以減少吸入空氣"],"answer":2,"image":""},{"id":"nr4-114-2-48","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"黃小妹，6個月，輪狀病毒（rotavirus）感染引起急性腸胃炎（acute gastroenteritis），體重由住院前8公斤減為現在7.4公斤。下列護理處置何者正確？","options":["(A) 屬於重度脫水，監測囟門、脈搏及尿量等表徵","(B) 輪狀病毒透過飛沫傳染，父母及手足應戴口罩","(C) 接受電解質口服液治療後，鼓勵持續哺餵母奶","(D) 預防再次感染，建議注射2劑輪狀病毒疫苗"],"answer":2,"image":""},{"id":"nr4-114-2-49","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"關於β 型海洋性貧血（thalassemia）為體染色體隱性遺傳疾病，當父親及母親皆為帶因者，下一代罹患海洋性貧血的機率為何？","options":["(A) 二分之一","(B) 四分之一","(C) 四分之三","(D) 百分之百"],"answer":1,"image":""},{"id":"nr4-114-2-50","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"張小弟，9歲，確診為裘馨氏假肥大性肌失養症（Duchenne’s pseudohy-pertrophic muscular dystrophy），有關護理指導，下列何者最不適當？","options":["(A) 鼓勵家屬因應疾病發展彈性調整家中環境","(B) 鼓勵張小弟參與高密度游泳活動，以增強肌肉張力","(C) 每日為張小弟進行胸部物理治療，降低罹患肺炎的風險","(D) 進行飲食計畫，控制體重以減少負荷"],"answer":1,"image":""},{"id":"nr4-114-3-1","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第3次第1題","year":114,"session":3,"number":1,"question":"有關因應少子化的相關政策，下列敘述何者最不適當？","options":["(A) 育兒父母必須輪流申請育嬰留職停薪","(B) 擴大試管嬰兒的補助","(C) 提高產檢補助次數及增加項目","(D) 推動未滿兩歲育兒津貼政策"],"answer":0,"image":""},{"id":"nr4-114-3-2","subject":"nr4","topic":"婦科-婦女健康","meta":"114年第3次第2題","year":114,"session":3,"number":2,"question":"提供新住民婦女產科照護時，下列敘述何者最適當？","options":["(A) 依產科醫師醫囑為主要的護理方式","(B) 不與產科照護原則衝突下，應尊重新住民婦女之文化習俗","(C) 為協助新住民婦女融入本國文化，應採臺灣的照護方式","(D) 因語言溝通不易，以新住民婦女的配偶意見為主"],"answer":1,"image":""},{"id":"nr4-114-3-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第3次第3題","year":114,"session":3,"number":3,"question":"李女士，懷孕28週，主訴有腿部抽筋和背痛的症狀，護理師評估後，發現她僅攝取少量的乳製品，且很少吃綠葉蔬菜。根據她的情況，鈣質攝取不足最可能導致下列那一種健康問題？","options":["(A) 增加孕婦骨質疏鬆的風險，影響胎兒骨骼發育","(B) 可能影響胎兒腦部神經發育，易罹患呆小症","(C) 可能引發孕婦貧血，影響胎兒紅血球生成","(D) 可能出現孕期便秘和食慾不振，影響排便"],"answer":0,"image":""},{"id":"nr4-114-3-4","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第3次第4題","year":114,"session":3,"number":4,"question":"王女士，懷孕36週，第一胎，擔心不知何種情況要前往醫院待產，住家離醫院約20分鐘車程，下列指導何者最適當？","options":["(A) 當你開始感到陣痛並有現血時","(B) 當你開始感到呼吸輕鬆腹輕感","(C) 一般在預產期的前後24小時前往","(D) 出現約5分鐘一次的規則陣痛時"],"answer":3,"image":""},{"id":"nr4-114-3-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第3次第5題","year":114,"session":3,"number":5,"question":"盧女士，G2P1，目前懷孕16週，常常跟大寶說未來可以跟小寶一起溜滑梯，那會很有趣。此為魯賓（Rubin）理論的那一項母性任務？","options":["(A) 確保自己及胎兒安全渡過","(B) 使重要家人接受新生兒","(C) 學習貢獻自己","(D) 讓自己與寶寶連成一體"],"answer":1,"image":""},{"id":"nr4-114-3-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第3次第6題","year":114,"session":3,"number":6,"question":"有關無壓力試驗（NST），下列敘述何者正確？①觀察胎兒心跳型態的變化 ②至少要記錄60分鐘 ③建議第三孕期檢測 ④胎心率加速表示有缺氧情形","options":["(A) ①②","(B) ①③","(C) ②④","(D) ③④"],"answer":1,"image":""},{"id":"nr4-114-3-7","subject":"nr4","topic":"產科-孕期生理與評估","meta":"114年第3次第7題","year":114,"session":3,"number":7,"question":"陳女士，懷孕12週又3天，過去曾經在9週時自然流產一次，家裡有3個孩子，分別是40週出生的女兒1個、35週出生的雙胞胎2個，以孕產史記錄法，其產次應為？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":1,"image":""},{"id":"nr4-114-3-8","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第3次第8題","year":114,"session":3,"number":8,"question":"王女士，G1P0，已待產10小時，子宮頸口擴張6 cm，尚未破水，宮縮頻率為40”/3'-5'，她想要泡澡來緩解產痛，但又擔心安全性。下列護理措施何者錯誤？","options":["(A) 第二產程才可以進行泡澡","(B) 水溫以接近37℃為宜","(C) 水面高度要蓋過腹部","(D) 泡澡時間勿超過1.5小時"],"answer":0,"image":""},{"id":"nr4-114-3-9","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"114年第3次第9題","year":114,"session":3,"number":9,"question":"有關足月胎兒的頭部，下列敘述何者錯誤？","options":["(A) 矢狀縫合連結前後兩個囟門","(B) 冠狀縫合為位於兩個頂骨間的膜性組織","(C) 雙頂徑為胎頭最大橫徑，可以作為子宮內胎兒生長遲滯的指標","(D) 後囟門為三角形，位於兩個頂骨與枕骨的交接處"],"answer":1,"image":""},{"id":"nr4-114-3-10","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第3次第10題","year":114,"session":3,"number":10,"question":"王女士，G1P0，懷孕41週，子宮頸口已開全。護理師等王女士出現想用力的感覺時，開始鼓勵她順著感覺向下用力，並依自己舒適的方式，發出聲音用力。有關護理師教導的這種方式，相較於傳統的閉氣用力，下列敘述何者錯誤？","options":["(A) 第二產程實際用力時間縮短","(B) 不會明顯增加胸腔內壓","(C) 較容易發生會陰撕裂傷","(D) 較不會引發產後的尿失禁"],"answer":2,"image":""},{"id":"nr4-114-3-11","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第3次第11題","year":114,"session":3,"number":11,"question":"有關待產婦採用腰椎硬膜外麻醉，下列敘述何者正確？","options":["(A) 執行前先排空膀胱，採蝦米狀，穿刺入硬脊膜","(B) 常用的藥物有Fentanyl、Bupivacaine（Marcaine）等","(C) 執行注射前需給予D5W 500～1,000 c.c.","(D) 會影響第二產程用力及增加新生兒吸吮能力"],"answer":1,"image":""},{"id":"nr4-114-3-12","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第3次第12題","year":114,"session":3,"number":12,"question":"陳女士，待產3小時，於陰道內診發現其胎兒先露部位到達坐骨棘連線上1公分。下列紀錄何者正確？","options":["(A) station：+1","(B) score：+1","(C) station：−1","(D) score：−1"],"answer":2,"image":""},{"id":"nr4-114-3-13","subject":"nr4","topic":"產科-產後照護","meta":"114年第3次第13題","year":114,"session":3,"number":13,"question":"有關產後泌尿系統評估，下列敘述何者正確？","options":["(A) 產後膀胱漲滿敏感度增加，產生頻尿現象","(B) 產後因體內多餘的細胞外液，產生利尿現象","(C) 子宮內膜復舊的自體溶解，產生輕微酮尿","(D) 陰道分娩過程中膀胱受創，產生輕微蛋白尿"],"answer":1,"image":""},{"id":"nr4-114-3-14","subject":"nr4","topic":"產科-產後照護","meta":"114年第3次第14題","year":114,"session":3,"number":14,"question":"有關母乳哺育，下列敘述何者不適當？","options":["(A) 每次哺乳兩側的乳房都要餵，以免日後大小奶","(B) 母親奶水量過多（over supply）也可能會造成嬰兒拒絕吸奶","(C) 哺乳時嬰兒通常會快速吸幾口後又放開乳房，可刺激啟動排乳反射（Let-Down Reflex）","(D) 嬰兒吃奶時間及頻率常會有變化而非固定模式"],"answer":0,"image":""},{"id":"nr4-114-3-15","subject":"nr4","topic":"產科-產後照護","meta":"114年第3次第15題","year":114,"session":3,"number":15,"question":"根據魯賓（Rubin）產後母親行為態度之研究，下列敘述何者表示產後婦女正處於接受期（Taking-in Phase）？","options":["(A) 是不是多喝水可增加母奶量","(B) 昨晚一直夢到我如何生小孩","(C) 我先生累到聽不到寶寶哭聲","(D) 我的寶寶都不吸吮我的乳房"],"answer":1,"image":""},{"id":"nr4-114-3-16","subject":"nr4","topic":"產科-產後照護","meta":"114年第3次第16題","year":114,"session":3,"number":16,"question":"有關產後憂鬱，下列敘述何者錯誤？","options":["(A) 家庭支持不足或資源不足為危險因子","(B) 通常會影響日常生活及育嬰工作","(C) 症狀包括失眠及罪惡感等","(D) 可能是催產素與泌乳激素濃度突然上升引起"],"answer":3,"image":""},{"id":"nr4-114-3-17","subject":"nr4","topic":"產科-產後照護","meta":"114年第3次第17題","year":114,"session":3,"number":17,"question":"有關產褥期女性生殖系統復舊，下列敘述何者正確？①子宮頸外口可完全恢復原本橢圓形樣貌 ②陰道皺褶約產後3週再出現 ③沒有哺乳婦女排卵和月經重現約產後6～8週 ④胎盤剝離部位之復舊於產後3週內完成","options":["(A) ①②","(B) ①④","(C) ②③","(D) ③④"],"answer":2,"image":""},{"id":"nr4-114-3-18","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第3次第18題","year":114,"session":3,"number":18,"question":"游女士，G1P0，懷孕41週，故至醫院進行催生，子宮頸未開，最常給予引發子宮收縮的藥物為下列何者？","options":["(A) Yutopar®","(B) MgSO","(C) PGE2","(D) Betamethasone 4"],"answer":2,"image":""},{"id":"nr4-114-3-19","subject":"nr4","topic":"產科-新生兒護理","meta":"114年第3次第19題","year":114,"session":3,"number":19,"question":"檢查新生兒是否有髖關節先天發育不良，其檢查方法何者正確？","options":["(A) 評估大腿與臀部皺褶之對稱性，兩側皺褶不對稱為正常現象","(B) 執行歐特藍尼操作法（Ortolani’s maneuver），出現「卡答」聲為正常徵象","(C) 仰臥時，膝關節呈屈曲狀，有髖關節脫臼或異位的患側股骨會較長","(D) 執行巴羅操作法（Barlow’s maneuver），將大腿內收、膝部下壓，股骨頭會在關節囊內滑動，為異常現象"],"answer":3,"image":""},{"id":"nr4-114-3-20","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第3次第20題","year":114,"session":3,"number":20,"question":"有關心臟病孕婦之生產及產後護理措施，下列敘述何者正確？","options":["(A) 一律採剖腹生產來減少心臟負荷","(B) 產後絕對平躺休息以降低心臟負荷","(C) 產後48小時靜脈回流增加，需密切監測心臟功能","(D) 臨床分類為第一級的婦女不建議哺餵母乳"],"answer":2,"image":""},{"id":"nr4-114-3-21","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第3次第21題","year":114,"session":3,"number":21,"question":"楊女士，28歲，G1P0，孕前BMI正常，本次懷孕為同卵雙胞胎，胎位皆為頭位，下列護理指導何者最適當？","options":["(A) 容易出現貧血，需攝取30 mg/day鐵質","(B) 妊娠體重需要增加20～22公斤，以提供足夠營養","(C) 容易罹患妊娠高血壓，需要監測血壓狀況","(D) 於妊娠20週常規施打類固醇以預防早產"],"answer":2,"image":""},{"id":"nr4-114-3-22","subject":"nr4","topic":"產科-高危險妊娠","meta":"114年第3次第22題","year":114,"session":3,"number":22,"question":"有關HELLP症候群，下列敘述何者正確？","options":["(A) 通常發生在第一妊娠期，但要及早終止妊娠","(B) H：血尿","(C) EL：肝臟酵素上升、肝腫大","(D) LP：低血小板計數，少於150,000/mm3"],"answer":2,"image":""},{"id":"nr4-114-3-23","subject":"nr4","topic":"產科-待產與分娩","meta":"114年第3次第23題","year":114,"session":3,"number":23,"question":"產婦產後立即性大出血，必須嚴密監測下列何項情況的發生？","options":["(A) 瀰漫性血管內凝血（DIC）","(B) 後天免疫缺乏症候群（AIDS）","(C) 妊娠誘發性高血壓（PIH）","(D) 子宮內胎兒生長遲緩（IUGR）"],"answer":0,"image":""},{"id":"nr4-114-3-24","subject":"nr4","topic":"婦科-婦女健康","meta":"114年第3次第24題","year":114,"session":3,"number":24,"question":"有關子宮頸抹片檢查，下列敘述何者錯誤？","options":["(A) 檢查前24小時應避免放置陰道塞劑及發生性行為","(B) 避開月經來潮期間及產後至少6週再進行檢查","(C) 採檢後以95%酒精浸泡或噴上固定液再送檢","(D) 不管有無性經驗，30歲以上女性應每年進行一次篩檢"],"answer":3,"image":""},{"id":"nr4-114-3-25","subject":"nr4","topic":"婦科-婦女健康","meta":"114年第3次第25題","year":114,"session":3,"number":25,"question":"有關子宮內膜異位症，下列敘述何者正確？","options":["(A) 子宮內膜異位的範圍只侷限於骨盆腔","(B) 診斷可根據血中雌性素濃度","(C) 藥物治療後，不會再復發","(D) 口服避孕藥可抑制排卵、使異位內膜萎縮"],"answer":3,"image":""},{"id":"nr4-114-3-26","subject":"nr4","topic":"兒科-生長發展","meta":"114年第3次第26題","year":114,"session":3,"number":26,"question":"有關注意力不足過動症（attention deficit hyperactivity disorder, ADHD），下列敘述何者正確？","options":["(A) 孩子12歲以前出現症狀至少3個月","(B) 為腦內神經傳導物質如血清素（serotonin）功能異常所致","(C) 可用處罰矯正兒童的不適當行為以建立其行為規範","(D) 以中樞神經興奮劑如：Ritalin®、Methylphenida、Atomoxetine以增加注意力、減少衝動行為"],"answer":3,"image":""},{"id":"nr4-114-3-27","subject":"nr4","topic":"兒科-生長發展","meta":"114年第3次第27題","year":114,"session":3,"number":27,"question":"罹患自閉症（autism）病童之行為表現，下列敘述何者錯誤？","options":["(A) 喜歡彈性多變的生活型態","(B) 有社交技巧障礙問題","(C) 對某些特殊固定的事物有強烈的依戀","(D) 屬於廣泛性發展遲緩"],"answer":0,"image":""},{"id":"nr4-114-3-28","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第3次第28題","year":114,"session":3,"number":28,"question":"小旭，1歲3個月，阿嬤照顧，護理師予事故傷害之預防指導，下列敘述何者最適當？","options":["(A) 小旭把小珠子塞入鼻孔，請阿嬤立即以手挖鼻孔","(B) 小旭使用兒童安全座椅時，應坐於前座右側","(C) 小旭誤喝了漂白水，請阿嬤立即給予催吐，以防食道受傷害","(D) 小旭洗澡時，請阿嬤先放冷水，再放熱水"],"answer":3,"image":""},{"id":"nr4-114-3-29","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"114年第3次第29題","year":114,"session":3,"number":29,"question":"小華，3歲，住院期間常常鬧脾氣，有關設計治療性遊戲降低其住院反應，下列敘述何者最適當？","options":["(A) 小華喜歡獨自玩玩具，自得其樂，因此不需要安排玩伴","(B) 小華會與玩伴互換玩具，可安排需一起合作完成的遊戲","(C) 小華會進行聯合遊戲，但是缺乏遊戲規則，可選擇不需分工合作的遊戲","(D) 小華喜歡與玩伴進行合作和競爭性遊戲，故需訂立遊戲規則"],"answer":1,"image":""},{"id":"nr4-114-3-30","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第3次第30題","year":114,"session":3,"number":30,"question":"為2歲患有右側中耳炎幼童滴耳藥，下列敘述何者正確？","options":["(A) 將幼童耳廓向上及向後拉，滴入耳藥後協助右側臥10～15分鐘","(B) 將幼童耳廓向上及向後拉，滴入耳藥後協助左側臥10～15分鐘","(C) 將幼童耳廓向下及向後拉，滴入耳藥後協助右側臥10～15分鐘","(D) 將幼童耳廓向下及向後拉，滴入耳藥後協助左側臥10～15分鐘"],"answer":3,"image":""},{"id":"nr4-114-3-31","subject":"nr4","topic":"兒科-生長發展","meta":"114年第3次第31題","year":114,"session":3,"number":31,"question":"有關10歲兒童的繪畫發展特色，下列敘述何者正確？","options":["(A) 用符號或圖示來描繪並說明其意義","(B) 可對事物自然寫實，注意物體間的比例","(C) 開始模仿所見的事物，表現創造性","(D) 無意義的線條筆畫"],"answer":1,"image":""},{"id":"nr4-114-3-32","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"114年第3次第32題","year":114,"session":3,"number":32,"question":"小玲，2歲，因骨折手術住院治療中，當您要進行換藥之疼痛評估時，下列何種疼痛評估工具最為適合？","options":["(A) 嬰幼兒疼痛量表（Neonatal Infant Pain Scale, NIPS）","(B) 視覺類比量表（Visual Analogue Scale, VAS）","(C) 數字量表（Numeric Rating Scale, NRS）","(D) FLACC行為疼痛量表（Face, Legs, Activity, Cry, Consolability, FLACC）"],"answer":3,"image":""},{"id":"nr4-114-3-33","subject":"nr4","topic":"兒科-高危險新生兒","meta":"114年第3次第33題","year":114,"session":3,"number":33,"question":"一位32週的早產兒在餵食過程中出現腹脹、吐奶和血便。下列那一種情況最有可能是早產兒的併發症？","options":["(A) 新生兒黃疸","(B) 壞死性小腸結腸炎（NEC）","(C) 呼吸窘迫症候群（RDS）","(D) 早產兒視網膜病變（ROP）"],"answer":1,"image":""},{"id":"nr4-114-3-34","subject":"nr4","topic":"兒科-高危險新生兒","meta":"114年第3次第34題","year":114,"session":3,"number":34,"question":"有關早產兒呼吸暫停的照護處置，下列敘述何者錯誤？","options":["(A) 餵奶期間若有呼吸暫停須減緩或停止餵食，待膚色恢復粉紅、四肢放鬆等再繼續餵食","(B) 通常以Indomethacin治療，且須監測血中濃度","(C) 為了維持呼吸道通暢，可將其頸部微仰，勿過度屈曲及伸展","(D) 若有呼吸暫停，需給予觸覺刺激，並維持呼吸道通暢"],"answer":1,"image":""},{"id":"nr4-114-3-35","subject":"nr4","topic":"兒科-高危險新生兒","meta":"114年第3次第35題","year":114,"session":3,"number":35,"question":"小敏，出生後診斷胎便吸入症候群（meconium aspiration syndrome），有關護理照護措施，下列敘述何者不適當？","options":["(A) 觀察其呼吸狀態，是否有呼吸窘迫徵象","(B) 追蹤動脈血液氣體分析結果，依醫囑矯正鹼中毒，補充體液","(C) 定期追蹤X光肺部檢查的結果，是否出現氣胸","(D) 若呼吸未改善則考慮插管，並執行氣管內胎便抽吸"],"answer":1,"image":""},{"id":"nr4-114-3-36","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第3次第36題","year":114,"session":3,"number":36,"question":"有關嬰兒玫瑰疹（roseola infantum）在發疹期的敘述，下列何者正確？","options":["(A) 發疹通常伴隨著發燒症狀一起出現","(B) 發疹期通常會持續7天","(C) 疹子從軀幹開始擴散至頸、臉及四肢","(D) 疹子會癢，並常見有色素沉著的現象"],"answer":2,"image":""},{"id":"nr4-114-3-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第3次第37題","year":114,"session":3,"number":37,"question":"在流感好發的季節，一位母親帶著嬰兒來健兒門診詢問護理師，可以接種第一劑流感疫苗的時間，下列何者正確？","options":["(A) 出生滿4個月","(B) 出生滿6個月","(C) 出生滿9個月","(D) 出生滿12個月"],"answer":1,"image":""},{"id":"nr4-114-3-38","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第3次第38題","year":114,"session":3,"number":38,"question":"小芷，因發燒、感冒症狀就診，診斷為黴漿菌肺炎（mycoplasma pneumonia）而入院治療，下列敘述何者最適當？","options":["(A) 主要感染於1～3歲兒童","(B) 輕微發燒，通常＜39℃","(C) 傳染性低，不易傳染給其他家人","(D) 使用Azithromycin治療約10～14天"],"answer":1,"image":""},{"id":"nr4-114-3-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"114年第3次第39題","year":114,"session":3,"number":39,"question":"小玉，2歲，因感冒罹患急性中耳炎（acute otitis media）住院治療，其返家之護理照護，下列敘述何者正確？","options":["(A) 二側鼻孔宜一起擤鼻涕，較易清除分泌物","(B) 執行耳內給藥時，應將耳朵往下往後拉","(C) 若行鼓膜切除引流時，宜臥向健側","(D) 耳朵不痛時，即可停用抗生素，以免產生抗藥性"],"answer":1,"image":""},{"id":"nr4-114-3-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第3次第40題","year":114,"session":3,"number":40,"question":"何小妹，8歲，罹患先天性心臟病，需服用毛地黃，母親詢問服藥注意事項，下列回答何者錯誤？","options":["(A) 多補充含鉀食物，如香蕉、深綠色蔬菜","(B) 每日定時給藥，且空腹時給藥效果最好","(C) 給藥前心尖脈＜70次／分鐘，應暫停服藥","(D) 如忘記服藥大於6小時，仍需補給一劑"],"answer":3,"image":""},{"id":"nr4-114-3-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第3次第41題","year":114,"session":3,"number":41,"question":"陳小妹，出生後診斷大血管轉位（transposition of the great arteries, TGA），醫囑服用前列腺素（Prostaglandin E1），有關此藥的使用目的，下列敘述何者正確？","options":["(A) 增加心肌收縮力","(B) 維持動脈導管開放","(C) 增加下肢靜脈血回流","(D) 降低體循環的氧氣飽和度"],"answer":1,"image":""},{"id":"nr4-114-3-42","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"114年第3次第42題","year":114,"session":3,"number":42,"question":"小傑，8歲，診斷再生不良性貧血（aplastic anemia），因白血球、紅血球及血小板下降而入院接受治療，下列護理何者最適當？","options":["(A) 鼓勵戶外活動，以促進血循並增強肌力","(B) 避免給予粗糙、堅硬的食物，以防口腔黏膜受損","(C) 鼓勵並安排同學前來探訪會客，降低因同儕疏離而產生低自尊","(D) 注意預防發燒，必要時給予Aspirin藥物降溫，以免增加感染機會"],"answer":1,"image":""},{"id":"nr4-114-3-43","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第3次第43題","year":114,"session":3,"number":43,"question":"吳小妹，2個月大，診斷為先天性甲狀腺功能低下（congenital hypothyroidism），下列護理指導何者最適當？","options":["(A) 常出現腹瀉，著重臀部照護預防尿布疹","(B) 減少日曬時間，預防皮膚出現紅斑病變","(C) 常出現體溫過高，應保持低溫的環境","(D) 應留意聽力發展，必要時安排聽力檢查"],"answer":3,"image":""},{"id":"nr4-114-3-44","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第3次第44題","year":114,"session":3,"number":44,"question":"林小妹，國小5年級，罹患第1型糖尿病（type 1 diabetes mellitus），有關糖尿病居家護理指導，下列敘述何者正確？","options":["(A) 注射胰島素後，按摩注射部位，增強胰島素作用","(B) 注射胰島素後60～90分鐘再運動，運動前補充點心","(C) 避免血糖大幅波動，不宜進行游泳、慢跑等有氧運動","(D) 出現皮膚乾燥、腹痛、呼吸快且深，儘速進食甜食"],"answer":1,"image":""},{"id":"nr4-114-3-45","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第3次第45題","year":114,"session":3,"number":45,"question":"當3歲的腦瘤女童出現下列何種徵象時，護理師應進一步評估是否為顱內壓上升？","options":["(A) 心跳過快、血壓下降","(B) 頻尿、尿量多","(C) 頭痛、噴射狀嘔吐","(D) 活動量大、貓哭聲"],"answer":2,"image":""},{"id":"nr4-114-3-46","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"114年第3次第46題","year":114,"session":3,"number":46,"question":"高小弟，8個月，診斷泌尿道感染（urinary tract infection），下列護理指導何者最適當？","options":["(A) 嬰兒泌尿道感染常出現不明發燒、食慾不振、餵食困難等症狀","(B) 給予柑橘類果泥，促進酸化尿液，預防感染復發","(C) 醫囑給予抗生素治療，考量抗生素副作用，症狀消失即可停藥","(D) 依照醫囑完整服用抗生素並完成治療後，無須回診追蹤尿液培養"],"answer":0,"image":""},{"id":"nr4-114-3-47","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第3次第47題","year":114,"session":3,"number":47,"question":"諾羅病毒（norovirus）引起的急性腸胃炎，下列敘述何者正確？","options":["(A) 好發嬰幼兒且多見於夏季","(B) 建議嬰兒儘早接受口服疫苗的接種","(C) 以酒精及乾洗手消毒","(D) 急性期採禁食和補充水分電解質"],"answer":3,"image":""},{"id":"nr4-114-3-48","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第3次第48題","year":114,"session":3,"number":48,"question":"張小弟，8歲，騎單車跌倒導致右側肱骨骨折，上石膏住院治療，下列護理措施何者最適當？","options":["(A) 上石膏肢體出現蒼白、麻痺感，可做等長運動，促進血液循環","(B) 患側未被石膏固定的關節，維持正常關節活動，減輕關節僵直","(C) 石膏表面出現灼熱點或滲出液，屬正常現象，持續觀察即可","(D) 石膏弄濕時，避免水分滲入，儘快以烤燈或吹風機加速乾燥"],"answer":1,"image":""},{"id":"nr4-114-3-49","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"114年第3次第49題","year":114,"session":3,"number":49,"question":"林小妹，15個月大，疑似腦膜炎住院，有關此疾病之敘述下列何者最適當？","options":["(A) 細菌性腦膜炎之脊髓液中蛋白質值明顯升高","(B) 病毒性腦膜炎之脊髓液中葡萄糖值明顯升高","(C) 細菌性腦膜炎症狀較輕，病程數天可改善","(D) 身體評估會有明顯克爾尼格氏徵象（Kernig’s sign）"],"answer":0,"image":""},{"id":"nr4-114-3-50","subject":"nr4","topic":"兒科-意外事故與急症","meta":"114年第3次第50題","year":114,"session":3,"number":50,"question":"小玉，1歲6個月，罹患熱性痙攣，住院中突然痙攣發作，下列護理措施何者最適當？","options":["(A) 約束抽搐肢體，以防肢體受傷","(B) 可強行於口腔放入壓舌板，以防舌頭受傷","(C) 協助側臥使口中分泌物流出","(D) 發作後會造成神經系統損傷"],"answer":2,"image":""},{"id":"nr4-115-1-1","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"有關我國母嬰親善醫院之認證基準，下列敘述何者錯誤？","options":["(A) 提供孕婦哺餵母乳相關衛教及指導","(B) 在醫療需求下，可提供母乳以外的食物或飲料","(C) 施行親子同室，依嬰兒需求哺餵母乳","(D) 嬰兒哭泣時可提供安撫奶嘴"],"answer":3,"image":""},{"id":"nr4-115-1-2","subject":"nr4","topic":"產科-孕期生理與評估","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"有關妊娠期間孕婦血液組成的變化，下列敘述何者正確？","options":["(A) 循環血容量及胎兒需求增加，使血漿蛋白增加","(B) 為避免孕婦血液鬱積，凝血因子Ⅶ、Ⅷ、Ⅸ、Ⅹ會減少","(C) 循環血容量增加，使血比容增加","(D) 懷孕期間因雌性素增加，使白血球會增加"],"answer":3,"image":""},{"id":"nr4-115-1-3","subject":"nr4","topic":"產科-孕期生理與評估","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"張女士，懷孕期頻繁噁心嘔吐的情況很不舒服，下列護理指導何者較不合適？","options":["(A) 與人類絨毛膜促性腺素（hCG）濃度有關，懷孕前三個月症狀最明顯","(B) 儘量避免空腹或是油膩食物對輕微者較有效","(C) 嚴重的懷孕噁心嘔吐通常給與維生素B6治療","(D) 進食後儘快喝水或刷牙，有助於去除噁心感"],"answer":3,"image":""},{"id":"nr4-115-1-4","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"王女士，懷孕28週，產檢時詢問拉梅茲生產準備法，下列回應何者最適當？","options":["(A) 是懷孕初期利用瑜珈運動的技巧，降低生產的疼痛","(B) 運用條件反射訓練，讓準父母對生產有較好的準備","(C) 強調待產婦完全配合伴侶的口令進行呼吸技巧","(D) 是瑞德（Dick-Read）醫師所發展，強調生產時使用預防疼痛的藥物"],"answer":1,"image":""},{"id":"nr4-115-1-5","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"林女士40歲，目前懷孕10週，高興成功懷孕，但也擔心胎兒有染色體問題。有關此期唐氏症遺傳診斷檢查之敘述，下列何者最不適當？","options":["(A) 母血檢測胎兒甲型蛋白、β-hCG、抑制素A（inhibin A）、雌三醇數值","(B) 超音波測量胎兒頸部透明帶厚度","(C) 母血檢測β-hCG、妊娠性血漿蛋白A（PAPP-A）的數值","(D) 可以採絨毛膜取樣術做染色體分析篩檢染色體異常"],"answer":0,"image":""},{"id":"nr4-115-1-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"懷孕30週孕婦抱怨下背痛，可優先教導下列何種運動？","options":["(A) 骨盆底陰道收縮運動","(B) 骨盆搖擺運動","(C) 雙下肢抬舉運動","(D) 盤腿坐式運動"],"answer":1,"image":""},{"id":"nr4-115-1-7","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"張女士，G1P0，懷孕40週入院待產。目前子宮頸擴張4公分，變薄50%，先露部位高度為0，羊膜完整，無特殊異常狀況，胎心率為140 bpm。她詢問：「我可以下床走走嗎？」，護理師最適當的回答是：","options":["(A) 「不可以，只能在床上翻身減輕不舒適」","(B) 「可以，但要注意安全」","(C) 「可以，只能去上廁所」","(D) 「不可以，你下床羊膜容易破裂」"],"answer":1,"image":""},{"id":"nr4-115-1-8","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"吳女士，懷孕40週，規則陣痛入院待產，主述：「清晨1點開始，陸續出現不規則陣痛，清晨3點開始規律宮縮，大約5～6分鐘就痛一次。」下午3點子宮頸口完全擴張（10公分）。下午4點10分自然娩出一健康男嬰。下午4點20分胎盤娩出。吳女士此次生產第二產程歷經多久時間？","options":["(A) 0小時10分鐘","(B) 1小時10分鐘","(C) 1小時20分鐘","(D) 12小時00分鐘"],"answer":1,"image":""},{"id":"nr4-115-1-9","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"有關待產期間使用電子胎心音監測之敘述，下列何者錯誤？","options":["(A) 有助了解宮縮及胎心音的持續性變化","(B) 健康待產婦建議持續的使用","(C) 未破水或子宮頸尚未擴張，皆可運用體外的方法進行監測","(D) 注意調節機器的音量，以免干擾待產婦休息"],"answer":1,"image":""},{"id":"nr4-115-1-10","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"有關生產姿勢，下列敘述何者最不適當？","options":["(A) 多數待產婦表示直立前傾姿勢最不痛","(B) 蹲姿可增寬骨盆出口橫徑","(C) 高血壓待產婦可採半坐臥姿勢生產","(D) 前傾跪姿適合待產婦之胎兒枕後位者"],"answer":2,"image":""},{"id":"nr4-115-1-11","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"原本對環境充滿好奇且多言的待產婦突然對護理師說：「你看我腿一直抖…怎麼會這樣…然後我開始感覺現血量變多，宮縮變密且更痛，我是不是快生了啊？」護理師可由其言語與行為判斷產程可能進入下列何階段？","options":["(A) 臨產期（prelabor phase）","(B) 潛伏期（latent phase）","(C) 活動期（active phase）","(D) 停滯期（protraction phase）"],"answer":2,"image":""},{"id":"nr4-115-1-12","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"陳女士，28歲，G1P1。採用剖腹產分娩並表示渴望與新生兒能有共處時刻，下列處置何者錯誤？","options":["(A) 分娩後於產檯上即可鼓勵與新生兒肌膚接觸","(B) 建議實施24小時親子同室","(C) 當產婦疲憊想休息時，仍應實施親子同室","(D) 護產人員隨時提供母嬰健康照護諮詢"],"answer":2,"image":""},{"id":"nr4-115-1-13","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"蘇女士G3P3，懷孕34週早期破水緊急剖腹生產，產後第9天在家來電主訴：「擠奶30分鐘後，身體移動時陰道感覺有東西流出，發現有如50元硬幣大小的血塊（如圖示），廁所途中仍持續出血，2天前開始喝生化湯」，下列解釋何者最不適當？","options":["(A) 可能有子宮破裂情形，建議儘速到醫院進一步處理","(B) 可能因生化湯與催產素刺激，滯留在子宮的血塊在身體活動時排出","(C) 先以手掌掌根按摩子宮底，同時儘快請護理師評估子宮收縮及惡露","(D) 增加親自餵奶頻率及密切觀察惡露變化，若持續有大量血塊則儘速就醫"],"answer":0,"image":"nr4-115-1-13.jpeg"},{"id":"nr4-115-1-14","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"吳女士，G2P1AA1，因胎位不正施行剖腹產，採硬膜外麻醉（epidural anesthesis），剛從恢復室返回病房，其先生表示：「我太太何時可以開始吃東西？」下列護理指導何者最適當？","options":["(A) 必須等排氣後才可喝溫水，若沒有噁心或嘔吐就可進食","(B) 現在就可開始喝溫水，若沒有噁心或嘔吐就可進食","(C) 先禁食6小時後，聽到腸蠕動聲再開始喝溫水，若沒噁心或嘔吐就可進食","(D) 等肚子餓了再開始喝溫水，若沒有噁心或嘔吐就可進食"],"answer":1,"image":""},{"id":"nr4-115-1-15","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"依據學者Rubin對產後婦女行為表現的觀察，下列何者屬於接受期（taking–in）的行為特色？","options":["(A) 主動關心新生兒的需要","(B) 注意力集中在自己身上","(C) 接受新生兒是一獨立個體","(D) 積極尋求別人的意見"],"answer":1,"image":""},{"id":"nr4-115-1-16","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"黃女士，G1P1，產後第一天，向護理師詢問：「我現在沒有奶水，可以餵奶嗎？」下列護理師的回應何者最適宜？","options":["(A) 你的擔心是多餘的，奶水很快就會開始分泌","(B) 現在你的乳房會分泌初乳，正是寶寶所需要的","(C) 即便沒有奶水，還是要讓寶寶吸吮，不然會哺乳失敗","(D) 你可以等三天後奶水來了，再開始哺餵"],"answer":1,"image":""},{"id":"nr4-115-1-17","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"有關新生兒頭顱血腫（cephalohematoma）的敘述，下列何者錯誤？","options":["(A) 可能引發生理性黃疸","(B) 可能為單側或雙側","(C) 通常與顱頂骨與骨膜間血管破裂有關","(D) 通常於出生當時最明顯，隨後逐漸變小"],"answer":3,"image":""},{"id":"nr4-115-1-18","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"有關正常新生兒的呼吸特徵，下列何者錯誤？","options":["(A) 呼吸速率30～60次／分鐘","(B) 採胸式呼吸","(C) 呼吸不規律","(D) 有時會出現5秒以內的呼吸暫停"],"answer":1,"image":""},{"id":"nr4-115-1-19","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"有關新生兒出生時維生素K缺乏的原因，下列何者錯誤？","options":["(A) 腸道相關的菌落叢不足","(B) 肝臟功能尚未成熟","(C) 維生素K不易從母體經由胎盤進入胎兒體內","(D) 腸道的吸收能力尚未成熟"],"answer":3,"image":""},{"id":"nr4-115-1-20","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"張女士，懷孕32週，突然感到下腹疼痛，陰道流出暗紅色血液，立即就診，下列何者為最有可能的問題？","options":["(A) 前置胎盤（placenta previa）","(B) 胎盤早期剝離（abruptio placenta）","(C) 脅迫性流產（inevitable abortion）","(D) 子癇症（eclampsia）"],"answer":1,"image":""},{"id":"nr4-115-1-21","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"張女士，30歲，G1P0，妊娠16週產檢的血壓量測值為118/75 mmHg，尿蛋白與尿糖測試均為陰性（-）。妊娠28週產檢的血壓值為140/96 mmHg，間隔四小時再測之血壓值145/100 mmHg，尿蛋白與尿糖測試均為陰性（-），依據上述相關症狀的敘述，下列何者為張女士最可能之診斷？","options":["(A) 慢性高血壓（chronic hypertension）","(B) 妊娠高血壓（gestational hypertension）","(C) 子癇前症（preeclampsia）","(D) 白袍高血壓（white coat hypertension）"],"answer":1,"image":""},{"id":"nr4-115-1-22","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"下列何者是發生產後血栓靜脈炎的主要原因？","options":["(A) 纖維蛋白溶解抑制素增加","(B) 多胞胎","(C) 妊娠高血壓","(D) 產後出血"],"answer":0,"image":""},{"id":"nr4-115-1-23","subject":"nr4","topic":"產科-產後照護","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"陰道生產之早期產後出血定義，是以生產後24小時內出血量至少超過多少？","options":["(A) 500 c.c.","(B) 700 c.c.","(C) 1,000 c.c.","(D) 1,300 c.c."],"answer":0,"image":""},{"id":"nr4-115-1-24","subject":"nr4","topic":"婦科-婦女健康","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"進入青春期的17歲少女一直無月經來潮，其可能原因為何？","options":["(A) 甲狀腺機能異常","(B) 骨盆腔感染","(C) 多囊性卵巢症候群","(D) 巧克力囊腫"],"answer":0,"image":""},{"id":"nr4-115-1-25","subject":"nr4","topic":"婦科-婦女健康","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"有關卵巢癌的致病因素，下列敘述何者錯誤？","options":["(A) 年齡越大，其罹病率較高","(B) 初經太晚或停經太早，其罹病率較高","(C) 有卵巢癌與乳癌家族史者，其罹病率較高","(D) 懷孕與母乳哺餵，其罹病率較低"],"answer":1,"image":""},{"id":"nr4-115-1-26","subject":"nr4","topic":"兒科-意外事故與急症","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"小華，2個月大，因被厚棉被蓋住頭部，母親掀開棉被後發現小華呈現無意識，有關其急救措施之敘述，下列何者正確？","options":["(A) 立即給與口對口吹兩口氣","(B) 檢查脈動位置，以橈動脈較合適","(C) 心外按摩位置是兩乳頭連線中央下胸骨處","(D) 單人施救，心外按摩與人工呼吸比率為15：2"],"answer":2,"image":""},{"id":"nr4-115-1-27","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"小妍，16歲，是長期厭食症患者，此次嚴重營養不良而入院治療，有關厭食症的症狀或行為，下列敘述何者最不適當？","options":["(A) 過分操控食物","(B) 自覺體重過重","(C) 嗜睡及腹瀉","(D) 常有停經情形"],"answer":2,"image":""},{"id":"nr4-115-1-28","subject":"nr4","topic":"兒科-生長發展","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"有關兒童各系統生長發展之敘述，下列何者正確？","options":["(A) 2歲時身高約為其成人後身高的一半","(B) 視覺為感覺器官中發育完成最早也最重要","(C) 出生時頭部占身長的二分之一","(D) 出生時腦神經髓鞘尚未發展完成，通常至3歲才完成"],"answer":0,"image":""},{"id":"nr4-115-1-29","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"有關嬰幼兒給藥方式，下列措施何者最適當？","options":["(A) 眼藥水滴於下眼瞼中央的結膜囊內","(B) 小於3歲的兒童將耳翼向上及向後輕拉","(C) 2歲以下兒童肌肉注射宜選擇臀肌","(D) 可將口服藥物與日常食物混合服用"],"answer":0,"image":""},{"id":"nr4-115-1-30","subject":"nr4","topic":"兒科-生長發展","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"有關兒童之健康評估結果，下列敘述何者顯示發展異常？","options":["(A) 出生3個月大仍有生理性斜視","(B) 1.5歲已長齊20顆乳牙","(C) 3至4歲時有膝內翻","(D) 4歲兒童的前囟門已關閉"],"answer":1,"image":""},{"id":"nr4-115-1-31","subject":"nr4","topic":"兒科-生長發展","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"強強，1歲6個月大，第一次接觸托嬰中心的陌生環境及教保員就大哭大鬧，雖然由固定的教保員照顧，但仍需花費較長的時間才能安穩。有關強強的氣質敘述，下列何者正確？","options":["(A) 規律性高","(B) 避性為高","(C) 反應閾高","(D) 堅持度低"],"answer":1,"image":""},{"id":"nr4-115-1-32","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"照護住院兒童時，下列敘述何者錯誤？","options":["(A) 測量嬰兒生命徵象的順序以呼吸開始較佳","(B) 幼兒期在發展自主感，檢查前應讓他決定是否願意接受檢查","(C) 學齡前期兒童非常害怕身體受到傷害，需考量維護其身體完整性的照護","(D) 學齡期兒童接受檢查前應先給予解釋增加其控制感"],"answer":1,"image":""},{"id":"nr4-115-1-33","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"依據皮亞傑（Piaget）理論，有關兒童對疾病概念之發展，兒童能瞭解疾病乃由器官功能不良造成，下列那一個階段正確？","options":["(A) 感覺運思期","(B) 運思前期","(C) 具體運思期","(D) 形式運思期"],"answer":3,"image":""},{"id":"nr4-115-1-34","subject":"nr4","topic":"兒科-高危險新生兒","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"林小妹，27週早產兒，出生體重860公克，出生後胸部X光呈現毛玻璃樣影像，有關呼吸窘迫症候群（respiratory distress syndrome）的醫療處置與護理措施，下列敘述何者正確？","options":["(A) 定期以動脈血液氣體分析或脈衝式血氧定量儀檢查血氧飽和度","(B) 以肌肉注射給與6 mg類固醇（dexamethasone）共4劑，每12小時一次","(C) 沒有自發性呼吸時，需使用氣管內管式持續性呼吸道正壓法（CPAP）治療","(D) 抽吸口鼻分泌物時，維持壓力80～100 mmHg和時間8～10秒"],"answer":0,"image":""},{"id":"nr4-115-1-35","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"小敏，8歲，罹患肌肉失養症（muscular dystrophy），呼吸急促且有喘鳴聲，經門診入院求治，以家庭為中心的護理措施，下列敘述何者最不適當？","options":["(A) 賦權予小敏的家庭成員，鼓勵小敏的家人參與住院期間的照護決策過程","(B) 在住院期間，協助主要照顧者，儘量維持小敏的家庭生活常規","(C) 在住院期間，所有決策及溝通，須保持高度的醫護專業控制","(D) 小敏住院對家人造成壓力，應提供心理情緒支持，讓家人逐漸適應"],"answer":2,"image":""},{"id":"nr4-115-1-36","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"瀕死兒童出現肌肉緊張力降低，下列敘述何者最不適當？","options":["(A) 腸胃道會出現噁心、嘔吐、便秘或腹瀉等症狀","(B) 食慾不佳時可以提供病童少量多餐的方式","(C) 吞嚥困難時仍儘量鼓勵由口進食，訓練肌肉張力","(D) 有尿瀦留而留置導尿管時，需注意預防感染問題"],"answer":2,"image":""},{"id":"nr4-115-1-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"有關腸病毒（enteroviruses infection）護理指導，下列敘述何者最適當？","options":["(A) 與家人吃飯時應避免共餐以預防交互傳染","(B) 目前預防腸病毒最有效的方法為施打疫苗","(C) 返校後即可恢復正常生活不需常洗手","(D) 玩具以酒精消毒可使腸病毒失去活性"],"answer":0,"image":""},{"id":"nr4-115-1-38","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"為5個月大的嬰兒進行呼吸系統的身體檢查與評估時，下列敘述何者最適當？","options":["(A) 使用耳鏡時應將耳廓向上向後拉","(B) 正常的呼吸次數約在30～40次／分","(C) 觀察胸部的起伏，以記錄正確的呼吸次數","(D) 正常的血氧飽和度（SpO2）為70～80%"],"answer":1,"image":""},{"id":"nr4-115-1-39","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"陳小妹，9歲，罹患氣喘，有關尖峰呼氣流速值（peak expiratory flow rate, PEFR）使用的注意事項，下列敘述何者正確？","options":["(A) 數值可以做為監測急性發作嚴重度之依據","(B) 請陳小妹紀錄吹三次後的平均值","(C) 當數值在最佳值的60～80%時表示控制良好","(D) 建議陳小妹在每日規則服藥後進行監測"],"answer":0,"image":""},{"id":"nr4-115-1-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"安撫躁動不安的法洛氏四重畸形病童，經常採取膝胸臥式或蹲姿，有關彎曲腿部的理由，下列敘述何者錯誤？","options":["(A) 減少上肢靜脈的回心血量","(B) 增加肺動脈至肺臟的血量","(C) 增加全身血管的血流阻力","(D) 減少右心低氧濃度的血量"],"answer":0,"image":""},{"id":"nr4-115-1-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"陳小妹，10個月，診斷缺鐵性貧血（iron deficiency anemia），醫囑開立口服鐵劑，下列護理指導何者正確？","options":["(A) 鐵劑與柑橘類果汁一起服用，會促進鐵劑吸收","(B) 鐵劑與制酸劑一起服用，避免腸胃不適","(C) 服用鐵劑後，排出黑色糞便，應立即停藥就醫","(D) 利於餵食，鐵劑可加入牛奶內一起服用"],"answer":0,"image":""},{"id":"nr4-115-1-42","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"小明，16歲，因為走路跛行住院檢查，今確立診斷為骨肉瘤（osteosarcoma），下列敘述何者錯誤？","options":["(A) 常出現局部持續性疼痛，病灶處出現腫塊及病理性骨折","(B) 病童皆需接受截肢手術，需評估失去肢體造成的身體心像紊亂","(C) 骨肉瘤是原發性惡性骨腫瘤，好發於青春期","(D) 多發生於長骨的幹骺端，尤其是下肢，股骨遠端和脛骨近端"],"answer":1,"image":""},{"id":"nr4-115-1-43","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"小彤接受化學治療中，其白血球檢驗值如下：白血球1,000 /µL、成熟嗜中性白血球（segment）26%、不成熟嗜中性白血球（band）2%、淋巴球68%、單核球4%，小彤的絕對嗜中性白血球（Absolutely Neutrophil Count, ANC）值為多少？","options":["(A) 680","(B) 320","(C) 280","(D) 200"],"answer":2,"image":""},{"id":"nr4-115-1-44","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"小均，13歲，診斷為第一型糖尿病，有關胰島素注射的護理指導，下列敘述何者最適當？","options":["(A) 注射部位選擇應以大腿部位為主，吸收效果最佳","(B) 進行劇烈運動，當日注射部位應避免於執行運動的肢體","(C) 注射後應加強按摩注射部位，以加強吸收效果","(D) 先抽中效或長效胰島素，再抽取短效的胰島素"],"answer":1,"image":""},{"id":"nr4-115-1-45","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"有關腸套疊（intussusception）的敘述，下列何者正確？","options":["(A) 右上腹可觸及香腸狀的腫塊","(B) 最常見的型態是接近乙狀結腸崁入直腸內","(C) 急性陣發性腹痛、嘔吐、脂肪便為臨床症狀","(D) 出現腹膜炎、腸穿孔症狀，須立即施行鋇劑灌腸"],"answer":0,"image":""},{"id":"nr4-115-1-46","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"小龍，1歲大，罹患尿道下裂（hypospadias），今入院進行尿道重建手術，剛由手術室返回病房，下列護理措施何者最適當？","options":["(A) 導尿管固定於腹部或腿上避免牽扯傷口","(B) 由於傷口尚未癒合，尿液由陰莖以外區域滲出為一正常反應","(C) 鼓勵小龍跨坐父母身上，促進親子關係","(D) 需限制水分攝取，以減少尿液滲出影響傷口癒合"],"answer":0,"image":""},{"id":"nr4-115-1-47","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"王小弟，8個月，罹患先天性膽道閉鎖，手術後偶有膽道炎發生，有關飲食護理指導的敘述，下列何者正確？","options":["(A) 膽汁缺乏所以需補充水溶性維生素","(B) 採低鈣飲食","(C) 限制蛋白質高的食物，避免肝臟負擔","(D) 採用中鏈脂肪酸的配方奶"],"answer":3,"image":""},{"id":"nr4-115-1-48","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"陳小弟，8歲，罹患癲癇，有關癲癇的照護，下列敘述何者錯誤？","options":["(A) 如突然停用抗癲癇藥，易造成癲癇重積現象（status epilepticus）","(B) 如服用癲能停（Dilantin）須特別注意口腔衛生","(C) 生酮飲食治療主要以低脂肪為主，對穩定神經傳導物質有幫助","(D) 服用帝拔癲（Depakine）期間，需定期監測血中藥物濃度"],"answer":2,"image":""},{"id":"nr4-115-1-49","subject":"nr4","topic":"兒科-意外事故與急症","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"小明，4歲2個月大，右側股骨骨折（right femoral fracture）而住院，有關使用石膏治療產生患肢循環和神經系統的異常現象，下列徵象何者不適當？","options":["(A) 疼痛（pain）","(B) 脈搏減少（pulselessness）","(C) 感覺異常（paresthesia）","(D) 瘀斑（purpura）"],"answer":3,"image":""},{"id":"nr4-115-1-50","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"有關腦性麻痺兒童之敘述，下列何者錯誤？","options":["(A) 長時間的腦部缺氧，是出生前和生產時最常發生的致病原因","(B) 智能障礙為主要發展問題，應於學會溝通後開始接受語言訓練","(C) 屬於非進行式的運動功能障礙","(D) 身體特徵為伸展反射、深層肌腱反射及肌肉張力增加"],"answer":1,"image":""},{"id":"nr4-115-2-1","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"有關以實證為基礎的低風險婦女之生產照護原則，下列何者不適當？","options":["(A) 可進食清淡易消化飲食","(B) 支持自由選擇體位","(C) 非常規灌腸與剃毛","(D) 持續臥床待產"],"answer":3,"image":""},{"id":"nr4-115-2-2","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"李女士，懷孕34週，產檢時超音波檢查顯示胎兒體重偏小，且羊水量較少，但呼吸運動與肌肉張力皆正常，醫生建議她進一步進行胎兒健康評估，下列檢查何者對母嬰的風險較低且適合？","options":["(A) 臍帶血採樣（PUBS）","(B) 無壓力試驗（NST）","(C) 宮縮壓力測試（CST）","(D) 羊膜穿刺檢查（amniocentesis）"],"answer":1,"image":""},{"id":"nr4-115-2-3","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"有關孕期乙型鏈球菌篩檢之敘述，下列何者正確？","options":["(A) 應在第一孕期檢測，以早期治療","(B) 孕婦檢測陽性，通常會出現明顯的感染症狀","(C) 孕婦檢測陽性，在孕期中應立即接受抗生素治療","(D) 孕婦檢測陽性，新生兒經過母體產道，可能併發敗血症"],"answer":3,"image":""},{"id":"nr4-115-2-4","subject":"nr4","topic":"產科-孕期生理與評估","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"趙女士，29歲，曾流產一次，有一個4歲大的兒子（懷孕40週出生），一個剛滿1歲的女兒（懷孕36週出生），現因再次懷孕而到產科門診檢查，病歷記錄趙女士的孕產史為：","options":["(A) G3P2A1","(B) G3P1A1","(C) G4P3A0","(D) G4P2A1"],"answer":3,"image":""},{"id":"nr4-115-2-5","subject":"nr4","topic":"產科-孕期生理與評估","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"下列何者為懷孕的確實徵象？","options":["(A) 掃描到妊娠囊","(B) 妊娠試驗呈陽性","(C) 月經延遲未來","(D) 有妊娠紋、褐斑"],"answer":0,"image":""},{"id":"nr4-115-2-6","subject":"nr4","topic":"產科-孕期生理與評估","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"有關懷孕期婦女常見的心理適應，下列敘述何者最適當？","options":["(A) 第一孕期全神貫注於懷孕的身體變化","(B) 第一孕期開始準備新生兒的用物","(C) 第三孕期因接近生產而情緒趨向穩定","(D) 第二孕期對胎兒有不真實的感覺"],"answer":0,"image":""},{"id":"nr4-115-2-7","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"有關引產之適應症，下列何者錯誤？","options":["(A) 妊娠39週合併妊娠高血壓","(B) 子宮內胎兒死亡","(C) 妊娠40週合併胎位不正","(D) 妊娠41週且胎兒健康"],"answer":2,"image":""},{"id":"nr4-115-2-8","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"影響分娩的因素中，包含母體骨盆及胎頭徑線。下列敘述何者錯誤？","options":["(A) 骨盆腔（pelvic cavity）的特徵是前後徑大於橫徑","(B) 骨盆出口（pelvic outlet）的特徵是前後徑大於橫徑","(C) 顱頂產式最小的前後徑為枕下前囟徑（SOB）","(D) 胎頭的枕額徑（OF）大於枕頦徑（OM）"],"answer":3,"image":""},{"id":"nr4-115-2-9","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"陳女士，G1P0，懷孕39週，胎位為LOA，目前已進入第二產程，胎頭已有撥露（排臨）現象。根據分娩機轉，此時常見的胎位應為？","options":["(A) LOA","(B) OA","(C) ROA","(D) OP"],"answer":1,"image":""},{"id":"nr4-115-2-10","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"監測待產婦胎心速率時，護理師發現胎心監測紀錄在胎動時有胎心率加速10bpm的情形，下列何項處置較適宜？","options":["(A) 胎心率不正常宜儘快通知醫師","(B) 協助待產婦重新擺位以改善上述情形","(C) 測量生命徵象並告知待產婦多臥床休息","(D) 告知待產婦這表示胎兒狀況良好"],"answer":3,"image":""},{"id":"nr4-115-2-11","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"有關第三產程的護理，下列何者錯誤？","options":["(A) 評估新生兒生理狀況","(B) 觀察胎盤剝離的徵象","(C) 觀察惡露量並教導按摩子宮","(D) 協助親子互動及母乳哺餵"],"answer":2,"image":""},{"id":"nr4-115-2-12","subject":"nr4","topic":"產科-產後照護","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"自然產後4小時，協助個案下床解尿後，觸診子宮為堅硬狀，子宮底與肚臍平並且置中。觀察產後棉片每20分鐘就濕透一片，並不斷流出鮮紅色物，當時血壓90/56 mmHg。下列敘述何者最適當？","options":["(A) 懷疑是早期產後出血，需評估是否有產道撕裂傷問題","(B) 子宮收縮不足，應儘快使用子宮收縮劑，避免出血增加","(C) 懷疑是子宮高張力收縮影響，應提供熱敷以降低子宮收縮的張力","(D) 請個案採辛式臥位，讓會陰及肛門清楚露出進行檢查出血部位"],"answer":0,"image":""},{"id":"nr4-115-2-13","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"有關母乳與配方奶成分的比較，下列何者錯誤？","options":["(A) 母乳的乳糖含量較配方奶高","(B) 母乳的鈣鐵濃度較配方奶高","(C) 母乳的不飽和脂肪酸比例較配方奶高","(D) 母乳的乳清蛋白成分較配方奶高"],"answer":1,"image":""},{"id":"nr4-115-2-14","subject":"nr4","topic":"產科-產後照護","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"有關生理性脹奶（fullness）的照護，下列敘述何者最不適當？","options":["(A) 產後即刻不限時間的肌膚接觸能預防生理性脹奶","(B) 產後按嬰兒飢餓訊號哺乳，有助於縮短生理性脹奶期間","(C) 產後第一週減少水分攝入，有助於避免生理性脹奶發生","(D) 必要時於餵奶前熱敷乳房以利排乳反射，減緩生理性脹奶"],"answer":2,"image":""},{"id":"nr4-115-2-15","subject":"nr4","topic":"產科-產後照護","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"蔡女士，G1P1，新生兒出生體重3800公克，產後第二天，都沒有脹奶的感覺，而且新生兒幾乎是含著乳房入睡，放下來就哭。進行哺乳相關資料收集發現，新生兒現在體重3500公克，早上9點剛換過一次尿片，混雜尿尿及大量墨綠色大便。有關產後住院期間的照護建議，下列何者不適當？","options":["(A) 確實觀察一次完整哺乳的過程後，確保新生兒能有效吸吮","(B) 建議產婦執行24小時親子同室，可以依照嬰兒飢餓訊號餵奶","(C) 建議除了哺乳外，產婦就跟著新生兒作息睡覺休息","(D) 由於新生兒體重喪失超過7%，建議在哺乳後再額外補充配方奶"],"answer":3,"image":""},{"id":"nr4-115-2-16","subject":"nr4","topic":"產科-產後照護","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"陳女士，G3P1SA2，採陰道分娩，會陰4度裂傷，出院前詢問：「何時可以恢復性生活？」，下列護理指導何者最適當？","options":["(A) 傷口4度裂傷，宜等到產後6個月後才開始性生活","(B) 只要放輕鬆，彼此想在一起即可以有性生活","(C) 建議惡露停止與會陰傷口癒合之後即可開始性生活","(D) 性生活會影響會陰傷口癒合，故建議禁慾一年"],"answer":2,"image":""},{"id":"nr4-115-2-17","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"有關新生兒的生殖系統，下列何者正確？","options":["(A) 因母體雌性素影響，男、女嬰均可能有暫時性的乳房充盈現象","(B) 出生1週內分泌魔乳，會增加未來乳癌發生率","(C) 女嬰出現假性月經，與母體的人類胎盤泌乳激素（hPL）增加有關","(D) 90%早產兒男嬰出生時睪丸已下降"],"answer":0,"image":""},{"id":"nr4-115-2-18","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"握住新生兒的大腿並輕輕往下施壓，做內收（adduction）動作，檢查股骨頭在關節內是否有滑脫現象，此為新生兒先天性髖關節脫臼的何種徵象測試？","options":["(A) 歐氏徵象（Ortolani’s sign）","(B) 巴氏徵象（Barlow’s sign）","(C) 哈氏徵象（Hart’s sign）","(D) 古爾氏徵象（Gower’s sign）"],"answer":1,"image":""},{"id":"nr4-115-2-19","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"有關心臟病婦女妊娠期生活與飲食之注意事項，下列何者正確？","options":["(A) 增加產前運動頻率以提高體能","(B) 須攝取低蛋白及適量鈉的飲食","(C) 體重增加至少16公斤以維持體力","(D) 妊娠20～24週安排進行高層次胎兒心臟超音波檢查"],"answer":3,"image":""},{"id":"nr4-115-2-20","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"有關胎盤早期剝離的敘述，下列何者正確？","options":["(A) 常見的症狀是毫無預警無痛性的陰道出血","(B) 當出血滲入子宮肌層導致庫菲勒氏子宮（Couvelaire uterus）","(C) 胎盤早期剝離的發生與逆行性感染有關","(D) 因剝離時出血易出現低張性子宮收縮"],"answer":1,"image":""},{"id":"nr4-115-2-21","subject":"nr4","topic":"產科-待產與分娩","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"葉女士，34歲，G1P0，於子宮頸全開後用力2小時，太過疲憊無法用力，準備使用真空吸引。有關真空吸引的使用，下列敘述何者最適當？","options":["(A) 協助將真空吸引的吸杯置於胎兒前囟門","(B) 協助將真空吸引壓力調整為80～100 mmHg","(C) 協助配合子宮收縮時牽引胎頭","(D) 適合胎頭尚未固定的時候執行"],"answer":2,"image":""},{"id":"nr4-115-2-22","subject":"nr4","topic":"產科-高危險妊娠","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"有關高危險妊娠婦女的相關診斷，下列何者胎兒先天性畸形的機率較高？","options":["(A) 妊娠前糖尿病","(B) 妊娠期高血壓","(C) 人類免疫缺乏病毒感染","(D) 心臟病"],"answer":0,"image":""},{"id":"nr4-115-2-23","subject":"nr4","topic":"產科-遺傳諮詢與胎兒發育","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"有關我國目前「人工生殖法」之法規內涵，下列何者錯誤？","options":["(A) 受術者要有婚姻關係","(B) 受術之女性須能以其子宮孕育及生產胎兒","(C) 捐贈人規定男性與女性皆為年齡20～45歲","(D) 捐贈人不能為四親等內之旁系血親"],"answer":2,"image":""},{"id":"nr4-115-2-24","subject":"nr4","topic":"婦科-婦女健康","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"有關子宮頸癌的高危險因子，下列何者最不適當？","options":["(A) 第6、11型人類乳突病毒感染","(B) 免疫功能受抑制的高危險群","(C) 吸菸者","(D) 性對象複雜者"],"answer":0,"image":""},{"id":"nr4-115-2-25","subject":"nr4","topic":"婦科-婦女健康","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"鄭女士，因子宮脫垂入院治療，下列敘述何者正確？","options":["(A) 大笑時感覺有東西掉到陰道，為第一度子宮脫垂","(B) 發生原因是先天性骨盆結構無力造成","(C) 只能採手術方式治療","(D) 宜教導增強骨盆底肌肉運動"],"answer":3,"image":""},{"id":"nr4-115-2-26","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"有關兒童及青少年憂鬱症的飲食治療建議，下列敘述何者最適當？","options":["(A) 全穀類食物可提升血清素，穩定情緒","(B) 飲食中應避免深海魚油，可能加重情緒不穩定","(C) 避免牛奶與火雞肉，容易造成情緒上的波動","(D) 蔬菜油含低量的丙亞麻酸，能減少情緒波動"],"answer":0,"image":""},{"id":"nr4-115-2-27","subject":"nr4","topic":"兒科-意外事故與急症","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"有關兒童誤食毒物的處理，下列何者最不適當？","options":["(A) 誤食鐵劑需快速檢查血中鐵濃度並使用活性碳幫助鐵劑的吸附","(B) 誤食鹼水不可催吐，發生2小時內可給予牛奶中和並立即送醫治療","(C) 誤食乙醯胺酚（acetaminophen）4小時內可使用活性碳吸附劑延緩藥物吸收","(D) 誤食含鉛糖果紙可用螯合劑治療，如：EDTA（calcium disodium edetate）排除鉛毒素"],"answer":0,"image":""},{"id":"nr4-115-2-28","subject":"nr4","topic":"兒科-意外事故與急症","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"下列何者不屬於兒童疏忽的行為表現？","options":["(A) 醫院安排慢性病童回診時間，家屬經常拖延且未帶病童回診","(B) 已達國小就學年齡，因家長工作經常性調動，沒有讓學童上學","(C) 兒童常常遭受家中長輩的言語威脅、藐視與辱罵","(D) 經常讓6歲以下的兒童獨自一人在家"],"answer":2,"image":""},{"id":"nr4-115-2-29","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"小羽，2歲，住加護病房一段時間，對護理師安撫由拒絕轉為接受，對父母離開，也由以往哭喊行為，轉為不在意。依據Bowlby與Roberson分離焦慮分期為那一期？","options":["(A) 抗議期（protest phase）","(B) 失望期（despair phase）","(C) 去依戀期（detachment phase）","(D) 羞恥懷疑期（shame and doubt phase）"],"answer":2,"image":""},{"id":"nr4-115-2-30","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"王小弟，足月產，疑似左鎖骨骨折，有關其照護，下列敘述何者最適當？","options":["(A) 採平躺或右側臥姿勢，勿趴睡","(B) 以石膏固定，須注意末梢循環","(C) 給予左手被動運動，避免攣縮","(D) 維持肩部外展、外旋之姿勢"],"answer":0,"image":""},{"id":"nr4-115-2-31","subject":"nr4","topic":"兒科-生長發展","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"有關健康兒童各階段已完成發展的動作敘述，下列何者較不適當？","options":["(A) 8個月嬰兒獨坐得很穩且會單手抓握玩具","(B) 18個月幼兒不需扶持獨自行走及能倒退走路","(C) 2歲兒童會自己穿襪子、拉上及解開拉鍊","(D) 4歲兒童可自行上下樓梯"],"answer":2,"image":""},{"id":"nr4-115-2-32","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"依照艾瑞克森（Erikson）心理社會發展理論，那一個年齡層兒童會將住院或生病病因詮釋為對他的懲罰而產生罪惡感？","options":["(A) 幼兒期","(B) 學齡前期","(C) 學齡期","(D) 青少年期"],"answer":1,"image":""},{"id":"nr4-115-2-33","subject":"nr4","topic":"兒科-兒童評估與溝通","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"評估嬰兒術後疼痛，下列量表何者最適宜？","options":["(A) 數字量表（numetric rating scale）","(B) 臉譜量表（faces rating scale）","(C) FLACC行為疼痛評估量表","(D) 視覺類比量表（visual analog scale）"],"answer":2,"image":""},{"id":"nr4-115-2-34","subject":"nr4","topic":"產科-新生兒護理","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"黃太太產後到嬰兒室探視因病理性黃疸接受照光治療的黃小弟，下列敘述何者正確？","options":["(A) 黃小弟接受照光時，教導黃太太使用嬰兒油進行按摩","(B) 關燈、移除黃小弟的眼罩，讓黃太太與黃小弟互動","(C) 幫黃小弟換尿布並說明因照光治療會解出黃色糊便","(D) 跟黃太太說明每四小時視需要更換黃小弟姿勢"],"answer":1,"image":""},{"id":"nr4-115-2-35","subject":"nr4","topic":"兒科-住院兒童與家庭","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"有關慢性病兒童，提供以家庭為中心之照顧，下列敘述何者較不適當？","options":["(A) 鼓勵父母幫助病童執行處置，以表達對孩子的關愛","(B) 對病童的日常作息宜正常化，減少因疾病而改變","(C) 父母對病童及其他子女管教態度需一視同仁","(D) 提供病童疾病訊息，鼓勵其參與照顧活動"],"answer":0,"image":""},{"id":"nr4-115-2-36","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"有關傳染病病童的症狀及其護理措施，下列敘述何者正確？","options":["(A) 玫瑰疹會使病童發癢，為避免抓傷，宜修剪其指甲","(B) 猩紅熱引發科氏斑點（Koplik’s spots），需口腔護理","(C) 腮腺炎病童會出現草莓舌，宜提供其涼且軟的食物","(D) 麻疹病童容易畏光，宜將房間的光線調整為較昏暗"],"answer":3,"image":""},{"id":"nr4-115-2-37","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"有關卡介苗建議接種時間，下列敘述何者正確？","options":["(A) 出生滿1～4個月","(B) 出生滿5～8個月","(C) 出生滿9～12個月","(D) 出生滿13～16個月"],"answer":1,"image":""},{"id":"nr4-115-2-38","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"王小弟，8歲，罹患氣喘住院治療後病情已穩定，有關護理師提供居家照護指導，下列何者錯誤？","options":["(A) 運動前20分鐘可吸入Cromolyn sodium預防氣喘發作","(B) 尖峰呼氣流量值若為理想值的75%，已達黃燈區，則可考慮減藥","(C) 每週以55℃以上的熱水洗床單、被套和枕巾","(D) 吸入型類固醇使用後要漱口避免黴菌感染"],"answer":1,"image":""},{"id":"nr4-115-2-39","subject":"nr4","topic":"兒科-感染免疫與傳染病","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"有關流行性感冒與一般感冒之差異，下列敘述何者錯誤？","options":["(A) 流行性感冒與一般感冒都可施打疫苗以預防","(B) 流行性感冒之傳染力通常較一般感冒為高","(C) 兩者皆為飛沫及接觸傳染","(D) 流行性感冒較一般感冒有明顯的全身症狀"],"answer":0,"image":""},{"id":"nr4-115-2-40","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"關於先天性心臟病病童一般術後的護理處置，下列敘述何者錯誤？","options":["(A) 排尿量維持4～5 mL/kg/hour","(B) 注意疲倦、呼吸急促等心臟負荷徵象，避免過度活動，定期心臟超音波檢查","(C) 持續評估周邊組織灌流情況，及動脈與靜脈的壓力變化","(D) 若有胸腔引流管引流量持續三小時超過3 mL/kg/hour，須立即通知醫師"],"answer":0,"image":""},{"id":"nr4-115-2-41","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"12歲病童，診斷為風濕性心臟病（rheumatic heart disease），下列症狀何者較不會出現？","options":["(A) 皮下結節","(B) 邊緣性紅斑","(C) 結膜炎","(D) 心雜音"],"answer":2,"image":""},{"id":"nr4-115-2-42","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"小力，4歲，診斷為重度β 型海洋性貧血，居家使用注射型排鐵劑（desferal），下列敘述何者不適當？","options":["(A) 若長期輸血會導致皮膚呈現青銅色","(B) 可搭配服用維生素C，以增加排鐵的效果","(C) 居家以皮下注射以減少血鐵質沉著現象","(D) 若尿液顏色呈現橘紅色為出血現象，應儘快回診"],"answer":3,"image":""},{"id":"nr4-115-2-43","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"罹患血友病病童，有關其護理指導，下列敘述何者錯誤？","options":["(A) 宜儘量避免靜脈注射與肌肉注射等侵入性治療","(B) 關節血腫時，給予局部熱敷以促進血循","(C) 定期接受牙齒檢查，避免牙齦出血","(D) 儘量勿進行躲避球、籃球等易衝撞的活動"],"answer":1,"image":""},{"id":"nr4-115-2-44","subject":"nr4","topic":"兒科-心血管血液腫瘤","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"小美，3歲，罹患癌症需接受化學藥物治療，住院抽血檢查結果，絕對嗜中性白血球（absoluteneutrophil count, ANC）數目為400/mm3，下列護理措施何者正確？","options":["(A) 教導父母ANC是評估血球回升的重要指標","(B) 教導父母ANC低下可能出現自發性出血，需限制活動","(C) 教導父母ANC的正常值會隨著年齡不同而改變","(D) 教導父母和小美採嚴格保護性隔離措施"],"answer":3,"image":""},{"id":"nr4-115-2-45","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"患有第1型糖尿病的病人，突然出現口渴、頻繁排尿及呼吸加快的情況，醫療團隊應首先懷疑的是那一種急性併發症？","options":["(A) 低血糖症","(B) 糖尿病酮酸中毒","(C) 高滲透壓高血糖狀態","(D) 呼吸性酸中毒"],"answer":1,"image":""},{"id":"nr4-115-2-46","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"小金，5個月大，罹患甲狀腺功能低下症，目前接受L-thyroxine治療，有關小金的居家照護，下列敘述何者錯誤？","options":["(A) 飲用適量鮮榨果汁，預防便秘","(B) 適度照射陽光，幫助骨骼成長","(C) 監測是否出現甲狀腺毒性反應","(D) 餵食適量的全蛋，預防發生貧血"],"answer":[0,3],"image":"","answer_note":"更正:第46題答Ａ或Ｄ或AD者均給分。"},{"id":"nr4-115-2-47","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"小志，6個月，男嬰，半夜突然大哭，雙腳屈膝、臉色蒼白、嘔吐物中含膽汁，數分鐘後緩解，20分鐘後又再次出現上述症狀。檢查尿布，發現大便中含血與黏膜。根據上述症狀，小志可能有什麼健康問題？","options":["(A) 胃食道逆流","(B) 腸套疊","(C) 幽門狹窄","(D) 巨結腸症"],"answer":1,"image":""},{"id":"nr4-115-2-48","subject":"nr4","topic":"兒科-呼吸消化疾病","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"有關小兒急性腸胃炎（acute gastroenteritis）臨床表徵之敘述，下列何者錯誤？","options":["(A) 感染諾羅病毒（norovirus）腸胃炎，較少有嘔吐症狀","(B) 病原性大腸桿菌症狀（pathogenic E.coli）為綠色水樣便且伴有血液及黏膜","(C) 輪狀病毒（rotavirus）感染常併有上呼吸道感染","(D) 沙門氏菌（Salmonella）感染的大便含有血絲"],"answer":0,"image":""},{"id":"nr4-115-2-49","subject":"nr4","topic":"兒科-神經內分泌腎泌尿","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"蘇小妹，3歲，開顱手術後第2天，有關評估顱內壓上升的症狀，下列何項評估不適當？","options":["(A) 前囟門膨出","(B) 血壓上升","(C) 意識改變","(D) 呼吸變慢"],"answer":0,"image":""},{"id":"nr4-115-2-50","subject":"nr4","topic":"兒科-意外事故與急症","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"小富，17歲，因左側股骨骨折須以石膏固定，有關小富所需要的護理，下列敘述何者正確？","options":["(A) 評估患肢是否有疼痛、蒼白、麻痺、感覺異常","(B) 若不慎弄濕石膏，可立即以吹風機熱風吹乾","(C) 石膏固定的肌肉可做等張運動","(D) 若患肢循環差，可於石膏上方使用烤燈"],"answer":0,"image":""}];
